let _workCaseOpenLock = { id: "", until: 0 };
let _workCaseOpenInFlight = 0;
let _workCaseOpenGeneration = 0;
const WORK_OPEN_AUTH_TIMEOUT_MS = 15000;
const WORK_OPEN_RESOLVE_TIMEOUT_MS = 60000;
const WORK_OPEN_ENRICH_TIMEOUT_MS = 15000;
const WORK_OPEN_POST_RENDER_TIMEOUT_MS = 8000;

function setWorkCaseOpenLock(requestId, ttlMs = 120000) {
  const id = String(requestId || "").trim();
  if (!id) return;
  _workCaseOpenLock = { id, until: Date.now() + ttlMs };
  if (typeof globalThis !== "undefined") {
    globalThis._workCaseOpenLock = _workCaseOpenLock;
    globalThis._workCaseOpenInFlight = _workCaseOpenInFlight;
  }
  setWorkSelectedRequestId(id);
}

function clearWorkCaseOpenLock() {
  _workCaseOpenLock = { id: "", until: 0 };
  if (typeof globalThis !== "undefined") globalThis._workCaseOpenLock = _workCaseOpenLock;
}

function isWorkCaseOpenIntentActive() {
  return (
    isWorkCaseDetailOpen() ||
    _workCaseOpenInFlight > 0 ||
    (Boolean(_workCaseOpenLock.id) && Date.now() < _workCaseOpenLock.until)
  );
}

function getPreferredWorkRequestId() {
  if (_workCaseOpenLock.id && Date.now() < _workCaseOpenLock.until) {
    return _workCaseOpenLock.id;
  }
  // 詳細表示中はロック期限切れでも「今開いている案件」を優先（同期で先頭＝キャンセルへ飛ばない）
  if (typeof isWorkCaseDetailOpen === "function" && isWorkCaseDetailOpen()) {
    const selectId = String(document.getElementById("workRequestSelect")?.value || "").trim();
    if (selectId) return selectId;
  }
  return getWorkSelectedRequestId();
}

/** 一覧行から requestId / rowId / id のいずれかで案件を探す */
function findVisibleWorkRowByAnyId(rows, anyId) {
  const id = String(anyId || "").trim();
  if (!id || !Array.isArray(rows) || !rows.length) return null;
  return (
    rows.find(
      (r) =>
        r.requestId === id || r.rowId === id || String(r.id || "") === id
    ) || null
  );
}
const DELIVERY_STORAGE_BUCKET = "record-workspace";

/** UI translation — use t("key") or t("key", { name: "..." }) for all new user-facing strings */
function t(key, vars) {
  if (typeof window !== "undefined" && window.WavrickI18n) {
    return window.WavrickI18n.t(key, vars);
  }
  return key;
}

function getScriptLanguagesApi() {
  return typeof window !== "undefined" && window.WavrickScriptLanguages
    ? window.WavrickScriptLanguages
    : null;
}

function getYtScriptLanguage() {
  const SL = getScriptLanguagesApi();
  const raw = document.getElementById("ytScriptLanguage")?.value || "ja";
  return SL ? SL.normalizeScriptLanguageCode(raw) : raw || "ja";
}

function readSupportedLanguagesFromForm(formOrRoot, name = "supportedLanguages") {
  const SL = getScriptLanguagesApi();
  if (SL) return SL.readLanguageCheckboxes(formOrRoot, name);
  const scope = formOrRoot?.querySelectorAll ? formOrRoot : document;
  const codes = [...scope.querySelectorAll(`input[name="${name}"]:checked`)].map((el) => el.value);
  return codes.length ? codes : ["ja"];
}

function formatScriptLanguageDisplay(code) {
  const SL = getScriptLanguagesApi();
  return SL ? SL.formatScriptLanguageLabel(code, t) : String(code || "ja");
}

function getRoleDisplayLabel(role) {
  if (role === "voice") return t("login.role_voice");
  if (role === "admin") return t("login.role_admin");
  return t("login.role_customer");
}

function translateWorkflowStatus(status) {
  const map = {
    募集中: "workflow.status.recruiting",
    選定中: "workflow.status.selecting",
    進行中: "workflow.status.in_progress",
    納品: "workflow.status.delivered",
    検収: "workflow.status.review",
    完了: "workflow.status.completed",
    キャンセル: "workflow.status.cancelled"
  };
  const key = map[status];
  return key ? t(key) : status || t("nav.recruiting");
}

function refreshAllLocalizedDynamicUi() {
  if (globalThis.WavrickI18n?.renderMobileLangDrawer) {
    WavrickI18n.renderMobileLangDrawer();
  }
  if (globalThis.WavrickPrelaunchGate?.refreshVisibleGateOverlays) {
    WavrickPrelaunchGate.refreshVisibleGateOverlays();
  }
  syncMainNav();
  syncAccountPageUi();
  syncYtPageAuthUi();
  syncWorkRoleVisibility(getCurrentSession());
  applyProductionUiGates();
  renderTalents();
  syncYtDraftStatusUi();
  if (recruitmentsPageCases.length && document.getElementById("recruitmentsGrid")) {
    renderRecruitmentsList(recruitmentsPageCases);
  }
  if (
    recruitmentsCurrentRequestId &&
    document.getElementById("page-recruitments")?.classList.contains("active")
  ) {
    showRecruitmentDetail(recruitmentsCurrentRequestId);
  }
  if (document.getElementById("page-yt")?.classList.contains("active")) {
    renderYtCastSlots();
  }
  if (document.getElementById("page-login")?.classList.contains("active")) {
    const bindLoginRender = window._wavrickRenderLoginSession;
    if (typeof bindLoginRender === "function") bindLoginRender();
  }
  const session = getCurrentSession();
  if (
    session?.role === "voice" &&
    (document.getElementById("page-account")?.classList.contains("active") ||
      document.getElementById("page-portfolio")?.classList.contains("active"))
  ) {
    populateVoiceMypageProfileForm(session);
  }
}

function renderScriptLanguageMetaHtml(code, labelKey = "yt.script_language_label") {
  const label = formatScriptLanguageDisplay(code);
  return `<span class="script-language-meta">${escapeHtml(t(labelKey))}: <strong>${escapeHtml(label)}</strong></span>`;
}

function renderTalentLanguagesHtml(profile) {
  const SL = getScriptLanguagesApi();
  if (!SL) return "";
  const badges = SL.renderLanguageBadgesHtml(profile?.supportedLanguages || "ja");
  if (!badges) return "";
  return `<div class="talent-languages-row"><span class="talent-languages-label">${escapeHtml(t("talent.languages_label"))}</span>${badges}</div>`;
}

function initScriptLanguageUi() {
  const SL = getScriptLanguagesApi();
  if (!SL) return;
  const voiceGroup = document.getElementById("voiceSupportedLanguages");
  if (voiceGroup && !voiceGroup.dataset.filled) {
    voiceGroup.innerHTML = SL.renderLanguageCheckboxesHtml({
      name: "supportedLanguages",
      defaultCodes: ["ja"],
      idPrefix: "voiceLang"
    });
    voiceGroup.dataset.filled = "1";
  }
  const editGroup = document.getElementById("voiceEditSupportedLanguages");
  if (editGroup && !editGroup.dataset.filled) {
    editGroup.innerHTML = SL.renderLanguageCheckboxesHtml({
      name: "voiceEditSupportedLanguages",
      defaultCodes: ["ja"],
      idPrefix: "voiceEditLang"
    });
    editGroup.dataset.filled = "1";
  }
  const ytSelect = document.getElementById("ytScriptLanguage");
  if (ytSelect && !ytSelect.dataset.filled) {
    ytSelect.innerHTML = SL.renderScriptLanguageSelectOptions(ytSelect.value || "ja");
    ytSelect.dataset.filled = "1";
  }
  if (globalThis.WavrickI18n?.applySubtree) {
    const voiceForm = document.getElementById("voiceForm");
    const editForm = document.getElementById("voiceEditProfileForm");
    const ytForm = document.getElementById("ytForm");
    if (voiceForm) WavrickI18n.applySubtree(voiceForm);
    if (editForm) WavrickI18n.applySubtree(editForm);
    if (ytForm) WavrickI18n.applySubtree(ytForm);
  }
  if (typeof _wavrickSaveFormState === "function") {
    document.querySelectorAll(".language-checkboxes").forEach((el) => {
      if (el.dataset.autosaveBound === "1") return;
      el.dataset.autosaveBound = "1";
      el.addEventListener("change", _wavrickSaveFormState);
    });
  }
}

