function generateRequestId() {
  return `req_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

function getCloudApi() {
  return typeof window !== "undefined" && window.WavrickCloud ? window.WavrickCloud : null;
}

function getCurrentSession() {
  try {
    const session = JSON.parse(localStorage.getItem("wavrick_session") || "null");
    if (!session || typeof session !== "object") return null;
    // Legacy sessions used `name` instead of `displayName`.
    if (!session.displayName && session.name) {
      session.displayName = session.name;
    }
    return session;
  } catch {
    return null;
  }
}

/** @param {unknown} roles @param {string} [primaryRole] */
function normalizeSessionRoles(roles, primaryRole) {
  const out = [];
  const add = (value) => {
    const role = String(value || "").trim();
    if (role !== "admin" && role !== "customer" && role !== "voice") return;
    if (!out.includes(role)) out.push(role);
  };
  if (Array.isArray(roles)) roles.forEach(add);
  add(primaryRole);
  return out;
}

function getSessionRoles(session) {
  if (!session) return [];
  const roles = normalizeSessionRoles(session.roles, session.role);
  return roles.length ? roles : [];
}

function sessionHasRole(session, role) {
  return getSessionRoles(session).includes(String(role || "").trim());
}

function isPrelaunchLockEnabled() {
  return (window.WAVRICK_CONFIG || {}).prelaunchLock === true;
}

function isPrelaunchBypassed() {
  if (window.WavrickPrelaunchGate?.isBypassed) {
    return window.WavrickPrelaunchGate.isBypassed();
  }
  if (!isPrelaunchLockEnabled()) return true;
  const session = getCurrentSession();
  return session?.role === "admin" || Boolean(session?.prelaunchAccess);
}

async function userHasPrelaunchAccess(email) {
  if (!isSupabaseEnabled() || !email) return false;
  const normalized = (email || "").toLowerCase().trim();
  const { data, error } = await supabaseClient
    .from(TABLES.prelaunchAccess)
    .select("id")
    .ilike("email", normalized)
    .limit(1);
  return !error && Array.isArray(data) && data.length > 0;
}

async function applyPrelaunchAccessToSession() {
  const session = getCurrentSession();
  if (!session?.email || session.role === "admin") return;
  const has = await userHasPrelaunchAccess(session.email);
  if (has !== Boolean(session.prelaunchAccess)) {
    session.prelaunchAccess = has;
    localStorage.setItem("wavrick_session", JSON.stringify(session));
  }
}

async function fetchRemotePrelaunchAccessRows() {
  if (!isSupabaseEnabled()) return [];
  const { data, error } = await supabaseClient
    .from(TABLES.prelaunchAccess)
    .select("*")
    .order("created_at", { ascending: false });
  if (error) {
    console.warn("[wavrick] prelaunch_access fetch failed", error);
    return [];
  }
  return Array.isArray(data) ? data : [];
}

async function syncCanonicalDisplayName(email, displayName, source = "profile_save") {
  const normalized = (email || "").toLowerCase().trim();
  const name = String(displayName || "").trim();
  if (!normalized.includes("@") || !name || !isSupabaseEnabled()) return;
  initSupabaseClient();
  if (!supabaseClient?.rpc) return;
  try {
    await supabaseClient.rpc("upsert_wavrick_display_name", {
      p_email: normalized,
      p_display_name: name,
      p_source: source
    });
  } catch (error) {
    console.warn("[wavrick] syncCanonicalDisplayName failed", normalized, error);
  }
}

async function grantPrelaunchAccess(email, displayName) {
  if (!isSupabaseEnabled()) return { ok: false, reason: "supabase_not_enabled" };
  const normalized = (email || "").toLowerCase().trim();
  if (!normalized.includes("@")) return { ok: false, reason: "invalid_email" };
  const { data: existing } = await supabaseClient
    .from(TABLES.prelaunchAccess)
    .select("id")
    .ilike("email", normalized)
    .limit(1);
  if (!Array.isArray(existing) || !existing.length) {
    const { error } = await supabaseClient.from(TABLES.prelaunchAccess).insert({
      email: normalized,
      display_name: (displayName || "").trim() || null,
      note: "prelaunch"
    });
    if (error) return { ok: false, error };
  }
  const session = getCurrentSession();
  if (session?.email === normalized) {
    session.prelaunchAccess = true;
    localStorage.setItem("wavrick_session", JSON.stringify(session));
  }
  return { ok: true };
}

async function revokePrelaunchAccess(email) {
  if (!isSupabaseEnabled()) return { ok: false, reason: "supabase_not_enabled" };
  const normalized = (email || "").toLowerCase().trim();
  const { error } = await supabaseClient
    .from(TABLES.prelaunchAccess)
    .delete()
    .ilike("email", normalized);
  if (error) return { ok: false, error };
  const session = getCurrentSession();
  if (session?.email === normalized) {
    delete session.prelaunchAccess;
    localStorage.setItem("wavrick_session", JSON.stringify(session));
  }
  return { ok: true };
}

function applyPrelaunchGateToPage(pageName) {
  const pageId = pageMap[pageName];
  const pageEl = pageId ? document.getElementById(pageId) : null;
  if (!pageEl || !window.WavrickPrelaunchGate) return;
  window.WavrickPrelaunchGate.applyPageGate(pageName, pageEl, () => {
    syncMainNav();
    showPage(pageName, { skipHistory: true });
  });
}

function isPageLockedForPrelaunch(pageName) {
  return window.WavrickPrelaunchGate?.isPageLocked?.(pageName) === true;
}

/** ロック中ページへ自動遷移しない（トップを常に開けるようにする） */
/** Guest-only auth screens — logged-in users must not re-enter these (duplicate login risk). */
const GUEST_AUTH_PAGE_NAMES = new Set(["login", "password-reset", "customer-signup", "voice"]);

function isGuestAuthPageName(pageName) {
  return GUEST_AUTH_PAGE_NAMES.has(String(pageName || ""));
}

function resolveLoggedInAwayFromGuestAuthPage(pageName, session) {
  const name = String(pageName || "");
  if (!session?.email || !isGuestAuthPageName(name)) return name;
  // Real password-recovery email callback may keep a leftover local session.
  if (name === "password-reset" && typeof isPasswordRecoveryReturnUrl === "function") {
    try {
      if (isPasswordRecoveryReturnUrl()) return name;
    } catch {
      /* fall through */
    }
  }
  // Bounce to mypage (not login-success landing) to avoid surprise jumps / re-auth loops.
  if (session.role === "admin") return "admin";
  return "account";
}

function resolveAutoNavigationPageName(pageName) {
  let name = pageName && pageMap[pageName] ? pageName : "home";
  if (name === "home") return "home";
  if (isPageLockedForPrelaunch(name) && !isPrelaunchBypassed()) return "home";
  name = resolveLoggedInAwayFromGuestAuthPage(name, getCurrentSession());
  return name && pageMap[name] ? name : "home";
}

function isCustomerLoggedIn() {
  const session = getCurrentSession();
  return Boolean(session && (session.role === "customer" || session.role === "admin"));
}

/** 顧客向けの声優ブロック・表示フィルターは顧客ロールのみ（運営は全件表示） */
function shouldApplyCustomerTalentFilters() {
  return getCurrentSession()?.role === "customer";
}

function findCustomerAccountByEmail(email) {
  const normalized = (email || "").toLowerCase().trim();
  if (!normalized) return null;
  const rows = JSON.parse(localStorage.getItem("wavrick_customer_accounts") || "[]");
  return (
    rows.find((row) => (row.email || "").toLowerCase().trim() === normalized) || null
  );
}

function persistCustomerSession(account, email, options = {}) {
  const normalized = (email || account?.email || "").toLowerCase().trim();
  const displayName =
    account?.name || account?.displayName || account?.displayname || normalized;
  const prev = getCurrentSession();
  const roles = normalizeSessionRoles(
    options.roles || (prev?.email === normalized ? prev.roles : null),
    "customer"
  );
  const accountCreatedAt =
    account?.createdAt ||
    account?.created_at ||
    (prev?.email === normalized && prev.accountCreatedAt) ||
    null;
  const sessionPayload = {
    role: "customer",
    roleLabel: "顧客",
    email: normalized,
    displayName,
    roles,
    suspendedAt: account?.suspendedAt || null,
    suspendedReason: account?.suspendedReason || "",
    accountCreatedAt: accountCreatedAt || null,
    createdAt: new Date().toISOString()
  };
  if (roles.includes("voice")) {
    sessionPayload.talentId =
      (prev?.email === normalized && prev.talentId) ||
      resolveVoiceTalentIdForSession({ role: "voice", email: normalized, roles }) ||
      `voice:${normalized}`;
  }
  localStorage.setItem("wavrick_session", JSON.stringify(sessionPayload));
  syncMainNav();
  return sessionPayload;
}

function persistVoiceSession(account, email, options = {}) {
  const normalized = (email || account?.email || "").toLowerCase().trim();
  const displayName =
    account?.displayName ||
    account?.displayname ||
    `${account?.lastName || ""} ${account?.firstName || ""}`.trim() ||
    normalized;
  const prev = getCurrentSession();
  const roles = normalizeSessionRoles(
    options.roles || (prev?.email === normalized ? prev.roles : null),
    "voice"
  );
  const accountCreatedAt =
    account?.createdAt ||
    account?.created_at ||
    (prev?.email === normalized && prev.accountCreatedAt) ||
    null;
  const sessionPayload = {
    role: "voice",
    roleLabel: "声優",
    email: normalized,
    displayName,
    roles,
    talentId:
      resolveVoiceTalentIdForSession({ role: "voice", email: normalized, roles }) ||
      `voice:${normalized}`,
    suspendedAt: account?.suspendedAt || null,
    suspendedReason: account?.suspendedReason || "",
    accountCreatedAt: accountCreatedAt || null,
    createdAt: new Date().toISOString()
  };
  localStorage.setItem("wavrick_session", JSON.stringify(sessionPayload));
  syncMainNav();
  return sessionPayload;
}

async function attachRestrictionToSession(role, email, account) {
  const fields =
    typeof loadAccountRestrictionFields === "function"
      ? await loadAccountRestrictionFields(role, email)
      : { suspendedAt: account?.suspendedAt || null, suspendedReason: account?.suspendedReason || "" };
  if (fields.bannedAt) return { banned: true };
  const session = getCurrentSession();
  if (!session || session.role !== role) return { banned: false };
  session.suspendedAt = fields.suspendedAt || account?.suspendedAt || null;
  session.suspendedReason = fields.suspendedReason || account?.suspendedReason || "";
  localStorage.setItem("wavrick_session", JSON.stringify(session));
  if (session.suspendedAt && role === "voice") {
    setVoiceIsActive(false);
  }
  globalThis.WavrickAccountRestriction?.syncAccountRestrictionUi?.();
  return { banned: false, session };
}

/** 上部ナビ: 未ログイン＝声優登録・ログイン・依頼する / ログイン後はロール別 */
/** Work list filter driven by header nav: "all" | "active" | "completed" */
let _workListFilter = "all";

function getWorkListFilter() {
  return _workListFilter === "active" || _workListFilter === "completed" ? _workListFilter : "all";
}

function setWorkListFilter(filter) {
  const next = filter === "active" || filter === "completed" ? filter : "all";
  _workListFilter = next;
  try {
    sessionStorage.setItem("wavrick_work_list_filter", next);
  } catch {
    /* ignore */
  }
  const subtitle = document.getElementById("workPageSubtitle");
  if (subtitle) {
    if (next === "active") subtitle.textContent = t("nav.work_active");
    else if (next === "completed") subtitle.textContent = t("nav.work_done");
    else subtitle.textContent = t("work.subtitle");
  }
}

function isWorkCaseCompletedStatus(status, wf) {
  const s = String(wf?.status || status || "").trim();
  return s === "完了" || s === "キャンセル";
}

function applyWorkListFilterToRows(rows) {
  const filter = getWorkListFilter();
  if (filter === "all" || !Array.isArray(rows)) return rows || [];
  return rows.filter((request) => {
    const wf = getWorkflowForRequest(request.requestId, request.status, request);
    const done = isWorkCaseCompletedStatus(request.status, wf);
    return filter === "completed" ? done : !done;
  });
}

function closeNavUserMenu() {
  const menu = document.getElementById("navUserMenu");
  const btn = document.getElementById("navUserMenuBtn");
  const dropdown = document.getElementById("navUserDropdown");
  if (!menu) return;
  menu.classList.remove("nav-user-open");
  btn?.setAttribute("aria-expanded", "false");
  if (dropdown) dropdown.hidden = true;
}

function syncNavThemeToggleUi() {
  const theme = globalThis.WavrickTheme?.getTheme?.() || document.documentElement.getAttribute("data-theme") || "light";
  const btn = document.getElementById("navThemeToggle");
  if (!btn) return;
  const isDark = theme === "dark";
  btn.setAttribute("aria-pressed", isDark ? "true" : "false");
  btn.setAttribute(
    "aria-label",
    isDark ? t("nav.theme_to_light") || "ライトモードへ" : t("nav.theme_to_dark") || "ダークモードへ"
  );
}

function syncNavActiveLinks() {
  const page = getWavrickActivePageName();
  const filter = getWorkListFilter();
  const adminTab =
    typeof _adminActiveTab !== "undefined" && _adminActiveTab ? _adminActiveTab : "analytics";

  document.querySelectorAll("#mainNavMenu .nav-link[data-go], #mainNavMenu a.nav-link").forEach((link) => {
    link.classList.remove("is-active");
  });

  const mark = (id) => document.querySelector(`#${id} .nav-link, #${id} a`)?.classList.add("is-active");

  if (page === "work") {
    if (filter === "completed") mark("navWorkDoneItem");
    else if (filter === "active") mark("navWorkActiveItem");
    else mark("navWorkItem");
  } else if (page === "recruitments") {
    mark("navRecruitmentsItem");
  } else if (page === "admin") {
    if (adminTab === "customers" || adminTab === "voices") mark("navAdminUsersItem");
    else if (adminTab === "requests" || adminTab === "workflows") mark("navAdminCasesItem");
    else if (adminTab === "finance" || adminTab === "operations") mark("navAdminFinanceItem");
    else if (adminTab === "cloud") {
      /* settings lives in user menu */
    } else mark("navAdminDashItem");
  } else if (page === "account") {
    mark("navAccountItem");
  }
}

function focusAccountNavSection(focusKey) {
  const map = {
    payment: "accountPaymentSection"
  };
  const id = map[focusKey];
  if (!id) return;
  window.setTimeout(() => {
    document.getElementById(id)?.scrollIntoView({ behavior: "smooth", block: "start" });
  }, 120);
}

function syncMainNav() {
  const session = getCurrentSession();
  const role = session?.role || "";
  const loggedIn = Boolean(session);
  const navRole = role === "voice" || role === "customer" || role === "admin" ? role : "guest";
  const mainNav = document.getElementById("mainNav");
  mainNav?.setAttribute("data-nav-role", navRole);

  const hide = (el, on = true) => el?.classList.toggle("hidden", on);
  const show = (el) => hide(el, false);

  const navVoice = document.getElementById("navVoiceItem");
  const navHome = document.getElementById("navHomeItem");
  const navLogin = document.getElementById("navLoginItem");
  const navWork = document.getElementById("navWorkItem");
  const navAccount = document.getElementById("navAccountItem");
  const navRecord = document.getElementById("navRecordItem");
  const navAdmin = document.getElementById("navAdminItem");
  const navYt = document.getElementById("navYtItem");
  const navRecruitments = document.getElementById("navRecruitmentsItem");
  const navVoiceStatus = document.getElementById("navVoiceStatus");
  const navNewRequest = document.getElementById("navNewRequestItem");
  const navWorkActive = document.getElementById("navWorkActiveItem");
  const navWorkDone = document.getElementById("navWorkDoneItem");
  const navAdminDash = document.getElementById("navAdminDashItem");
  const navAdminUsers = document.getElementById("navAdminUsersItem");
  const navAdminCases = document.getElementById("navAdminCasesItem");
  const navAdminFinance = document.getElementById("navAdminFinanceItem");
  const navVoiceWorkTemp = document.getElementById("navVoiceWorkTempItem");
  const navGuestCta = document.getElementById("navGuestCta");
  const navLoginLink = document.getElementById("navLoginLink");
  const navLang = document.getElementById("navLangSwitcher");
  const navUserMenu = document.getElementById("navUserMenu");
  const navUserBtn = document.getElementById("navUserMenuBtn");
  const logoAdminSuffix = document.getElementById("logoAdminSuffix");
  const navAnnounceWrap = document.getElementById("navAnnounceWrap");

  [
    navVoice,
    navHome,
    navLogin,
    navWork,
    navAccount,
    navRecord,
    navAdmin,
    navYt,
    navRecruitments,
    navVoiceStatus,
    navNewRequest,
    navWorkActive,
    navWorkDone,
    navAdminDash,
    navAdminUsers,
    navAdminCases,
    navAdminFinance
  ].forEach((el) => hide(el, true));

  hide(navVoiceWorkTemp, isProductionSite());
  hide(navGuestCta, true);
  hide(navLoginLink, true);
  hide(navUserMenu, true);
  hide(logoAdminSuffix, true);
  logoAdminSuffix?.setAttribute("aria-hidden", "true");
  navLang?.classList.toggle("hidden", false);
  navUserBtn?.classList.remove("is-admin");
  closeNavUserMenu();

  document.querySelectorAll("#navUserDropdown [data-nav-user]").forEach((item) => {
    const roles = String(item.getAttribute("data-nav-user") || "")
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);
    item.classList.toggle("hidden", !roles.includes(navRole));
  });

  if (navRole === "guest") {
    show(navLogin);
    show(navYt);
    hide(navGuestCta, false);
    hide(navLoginLink, false);
    hide(navAnnounceWrap, true);
    reorderMainNavItems(["voiceWorkTemp", "login", "yt"]);
  } else if (navRole === "customer") {
    show(navNewRequest);
    show(navWorkActive);
    show(navWorkDone);
    hide(navUserMenu, false);
    hide(navAnnounceWrap, false);
    reorderMainNavItems(["newRequest", "workActive", "workDone"]);
  } else if (navRole === "voice") {
    show(navRecruitments);
    show(navWorkActive);
    show(navRecord);
    hide(navUserMenu, false);
    hide(navAnnounceWrap, false);
    reorderMainNavItems(["voiceWorkTemp", "recruitments", "workActive", "record"]);
  } else if (navRole === "admin") {
    show(navAdminDash);
    show(navAdminUsers);
    show(navAdminCases);
    show(navAdminFinance);
    hide(navUserMenu, false);
    hide(navAnnounceWrap, false);
    hide(logoAdminSuffix, false);
    logoAdminSuffix?.setAttribute("aria-hidden", "false");
    navUserBtn?.classList.add("is-admin");
    reorderMainNavItems(["adminDash", "adminUsers", "adminCases", "adminFinance"]);
  }

  syncNavThemeToggleUi();
  syncNavActiveLinks();
  syncNavDrawerUserActions(navRole);
  globalThis.WavrickAnnouncements?.syncVisibility?.();
  void globalThis.WavrickAnnouncements?.refresh?.();
}

function syncNavDrawerUserActions(navRole) {
  const host = document.getElementById("navDrawerUserActions");
  if (!host) return;
  if (navRole === "guest") {
    host.classList.add("hidden");
    host.innerHTML = "";
    return;
  }
  const dropdown = document.getElementById("navUserDropdown");
  if (!dropdown) {
    host.classList.add("hidden");
    return;
  }
  const items = [...dropdown.querySelectorAll("[data-nav-user], #navLogoutBtn")].filter((el) => {
    if (el.id === "navLogoutBtn") return true;
    const roles = String(el.getAttribute("data-nav-user") || "")
      .split(",")
      .map((s) => s.trim());
    return roles.includes(navRole) && !el.classList.contains("hidden");
  });
  host.innerHTML = "";
  items.forEach((el) => {
    const clone = el.cloneNode(true);
    clone.removeAttribute("id");
    if (el.id === "navLogoutBtn") {
      clone.dataset.navLogoutClone = "1";
    }
    host.appendChild(clone);
  });
  host.classList.toggle("hidden", items.length === 0);
  if (host.dataset.bound !== "1") {
    host.dataset.bound = "1";
    host.addEventListener("click", (e) => {
      const logout = e.target.closest("[data-nav-logout-clone]");
      if (logout) {
        e.preventDefault();
        if (typeof window.wavrickCloseMobileNav === "function") {
          window.wavrickCloseMobileNav(true);
        }
        showConfirmModal(
          t("logout.confirm_title"),
          t("logout.confirm_message"),
          async () => {
            await performWavrickLogout({ redirectTo: "home" });
            showToast(t("logout.success_toast"), "info");
          },
          { confirmLabel: t("login.logout") || t("nav.logout") }
        );
        return;
      }
      const bugReport = e.target.closest("[data-open-bug-report]");
      if (bugReport) {
        e.preventDefault();
        if (typeof window.wavrickCloseMobileNav === "function") {
          window.wavrickCloseMobileNav(true);
        }
        openBugReportModal();
        return;
      }
      const link = e.target.closest("[data-go]");
      if (!link) return;
      e.preventDefault();
      if (typeof window.wavrickCloseMobileNav === "function") {
        window.wavrickCloseMobileNav(true);
      }
      const target = link.getAttribute("data-go");
      const adminTab = link.getAttribute("data-admin-tab");
      const accountFocus = link.getAttribute("data-account-focus");
      if (target === "work") setWorkListFilter("all");
      showPage(target);
      if (target === "admin" && adminTab && typeof switchAdminTab === "function") {
        switchAdminTab(adminTab);
      }
      if (target === "account" && accountFocus) {
        focusAccountNavSection(accountFocus);
      }
      syncNavActiveLinks();
    });
  }
}

function reorderMainNavItems(visibleOrder) {
  const navUl = document.getElementById("mainNavMenu");
  if (!navUl) return;
  const keys = [
    "voiceWorkTemp",
    "home",
    "voiceStatus",
    "voice",
    "login",
    "newRequest",
    "workActive",
    "workDone",
    "recruitments",
    "work",
    "account",
    "record",
    "adminDash",
    "adminUsers",
    "adminCases",
    "adminFinance",
    "admin",
    "yt"
  ];
  const map = {
    voiceWorkTemp: document.getElementById("navVoiceWorkTempItem"),
    home: document.getElementById("navHomeItem"),
    voiceStatus: document.getElementById("navVoiceStatus"),
    voice: document.getElementById("navVoiceItem"),
    login: document.getElementById("navLoginItem"),
    newRequest: document.getElementById("navNewRequestItem"),
    workActive: document.getElementById("navWorkActiveItem"),
    workDone: document.getElementById("navWorkDoneItem"),
    recruitments: document.getElementById("navRecruitmentsItem"),
    work: document.getElementById("navWorkItem"),
    account: document.getElementById("navAccountItem"),
    record: document.getElementById("navRecordItem"),
    adminDash: document.getElementById("navAdminDashItem"),
    adminUsers: document.getElementById("navAdminUsersItem"),
    adminCases: document.getElementById("navAdminCasesItem"),
    adminFinance: document.getElementById("navAdminFinanceItem"),
    admin: document.getElementById("navAdminItem"),
    yt: document.getElementById("navYtItem")
  };
  for (const key of visibleOrder) {
    const el = map[key];
    if (el) navUl.appendChild(el);
  }
  for (const key of keys) {
    if (!visibleOrder.includes(key)) {
      const el = map[key];
      if (el) navUl.appendChild(el);
    }
  }
}

function bindNavChrome() {
  if (document.documentElement.dataset.navChromeBound === "1") return;
  document.documentElement.dataset.navChromeBound = "1";

  try {
    const stored = sessionStorage.getItem("wavrick_work_list_filter");
    if (stored === "active" || stored === "completed" || stored === "all") {
      _workListFilter = stored;
    }
  } catch {
    /* ignore */
  }

  document.getElementById("navThemeToggle")?.addEventListener("click", (e) => {
    e.stopPropagation();
    const current = globalThis.WavrickTheme?.getTheme?.() || "light";
    const next = current === "dark" ? "light" : "dark";
    globalThis.WavrickTheme?.setTheme?.(next);
    syncNavThemeToggleUi();
  });

  window.addEventListener("wavrick:themechange", () => syncNavThemeToggleUi());

  const userMenu = document.getElementById("navUserMenu");
  const userBtn = document.getElementById("navUserMenuBtn");
  const userDropdown = document.getElementById("navUserDropdown");
  userBtn?.addEventListener("click", (e) => {
    e.preventDefault();
    e.stopPropagation();
    const open = !userMenu?.classList.contains("nav-user-open");
    if (open) {
      userMenu?.classList.add("nav-user-open");
      userBtn.setAttribute("aria-expanded", "true");
      if (userDropdown) userDropdown.hidden = false;
    } else {
      closeNavUserMenu();
    }
  });

  document.addEventListener("click", (e) => {
    if (!userMenu?.contains(e.target)) closeNavUserMenu();
  });

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") closeNavUserMenu();
  });

  userDropdown?.addEventListener("click", (e) => {
    const bugItem = e.target.closest("#navBugReportBtn, [data-open-bug-report]");
    if (bugItem) {
      e.preventDefault();
      closeNavUserMenu();
      openBugReportModal();
      return;
    }
    const item = e.target.closest("[data-go], #navLogoutBtn");
    if (!item) return;
    if (item.id === "navLogoutBtn") {
      e.preventDefault();
      closeNavUserMenu();
      showConfirmModal(
        t("logout.confirm_title"),
        t("logout.confirm_message"),
        async () => {
          await performWavrickLogout({ redirectTo: "home" });
          showToast(t("logout.success_toast"), "info");
        },
        { confirmLabel: t("login.logout") || t("nav.logout") }
      );
      return;
    }
    e.preventDefault();
    const target = item.getAttribute("data-go");
    const adminTab = item.getAttribute("data-admin-tab");
    const accountFocus = item.getAttribute("data-account-focus");
    closeNavUserMenu();
    if (typeof window.wavrickCloseMobileNav === "function") {
      window.wavrickCloseMobileNav(true);
    }
    if (target) showPage(target);
    if (target === "admin" && adminTab && typeof switchAdminTab === "function") {
      switchAdminTab(adminTab);
    }
    if (target === "account" && accountFocus) {
      focusAccountNavSection(accountFocus);
    }
    syncNavActiveLinks();
  });

}

function isBugReportModalOpen() {
  const modal = document.getElementById("bugReportModal");
  if (!modal) return false;
  return !modal.hidden && !modal.classList.contains("hidden");
}

function openBugReportModal() {
  const modal = document.getElementById("bugReportModal");
  if (!modal) return;
  const msg = document.getElementById("bugReportModalMessage");
  if (msg) {
    msg.textContent = "";
    msg.className = "message";
  }
  modal.classList.remove("hidden");
  modal.hidden = false;
  modal.setAttribute("aria-hidden", "false");
  queueMicrotask(() => document.getElementById("bugReportText")?.focus?.());
}

function closeBugReportModal() {
  const modal = document.getElementById("bugReportModal");
  if (!modal) return;
  modal.classList.add("hidden");
  modal.hidden = true;
  modal.setAttribute("aria-hidden", "true");
}

function bindBugReportModal() {
  const modal = document.getElementById("bugReportModal");
  const textEl = document.getElementById("bugReportText");
  const sendBtn = document.getElementById("bugReportSendBtn");
  if (!modal || !textEl || !sendBtn) return;
  if (modal.dataset.bugUiBound === "1") return;
  modal.dataset.bugUiBound = "1";

  modal.querySelectorAll("[data-close-bug-report-modal]").forEach((el) => {
    el.addEventListener("click", (e) => {
      e.preventDefault();
      closeBugReportModal();
    });
  });

  document.addEventListener("keydown", (e) => {
    if (e.key !== "Escape" || !isBugReportModalOpen()) return;
    e.preventDefault();
    closeBugReportModal();
  });

  if (!window.WavrickBugReport?.bindBugReportPanel) {
    console.warn("[bug-report] WavrickBugReport is not loaded");
    return;
  }

  window.WavrickBugReport.bindBugReportPanel({
    textEl,
    sendBtn,
    pageSource: "index",
    getPageSource: () => {
      try {
        const page =
          typeof getWavrickActivePageName === "function" ? String(getWavrickActivePageName() || "").trim() : "";
        return page ? `index:${page}` : "index";
      } catch {
        return "index";
      }
    },
    confirmFn: (message) => window.confirm(message),
    onStatus: (msg, level) => {
      const el = document.getElementById("bugReportModalMessage");
      if (el) {
        el.textContent = msg || "";
        el.className = `message ${level === "ok" ? "ok" : level === "err" ? "err" : ""}`.trim();
      }
      if (typeof showToast === "function") {
        const toastType = level === "ok" ? "success" : level === "err" ? "error" : "info";
        showToast(msg, toastType, level === "err" ? 5000 : 3500);
      }
      if (level === "ok") closeBugReportModal();
    }
  });
}

function collectYtRequestDataFromForm(form) {
  const session = getCurrentSession();
  if (!session || session.role !== "customer") {
    return { ok: false, message: "依頼するには顧客としてログインしてください。" };
  }
  const data = Object.fromEntries(new FormData(form).entries());
  const profile = findCustomerAccountByEmail(session.email);
  data.name = profile?.name || session.displayName || "顧客";
  data.email = session.email;
  data.channelUrl = profile?.channelUrl || "";
  data.videoChannelUrl = data.channelUrl || data.videoUrl || "";
  return { ok: true, data, session };
}

function syncYtPageAuthUi() {
  const gate = document.getElementById("ytCustomerGate");
  const app = document.getElementById("ytCustomerApp");
  const loggedInAs = document.getElementById("ytLoggedInAs");
  const subtitle = document.querySelector("#page-yt .form-subtitle");
  const loggedIn = isCustomerLoggedIn();
  const session = getCurrentSession();

  if (gate) gate.classList.toggle("hidden", loggedIn);
  if (app) app.classList.toggle("hidden", !loggedIn);
  if (subtitle) {
    subtitle.textContent = loggedIn ? t("yt.subtitle_logged_in") : t("yt.subtitle_guest");
  }
  if (loggedInAs && session) {
    loggedInAs.textContent = t("yt.logged_in_as", {
      name: session.displayName || session.email
    });
  }
  refreshYtProvisionalPayButton();
  refreshYtChannelUi();
  syncYtChannelTestBypassUi();
  syncYtDraftStatusUi();
}

function getCustomerAccountApi() {
  return typeof window !== "undefined" && window.WavrickCustomerAccount
    ? window.WavrickCustomerAccount
    : null;
}

function getTalentFavoritesApi() {
  return typeof window !== "undefined" && window.WavrickTalentFavorites
    ? window.WavrickTalentFavorites
    : null;
}

function getTalentBlocksApi() {
  return typeof window !== "undefined" && window.WavrickTalentBlocks ? window.WavrickTalentBlocks : null;
}

function isTalentBlockedForCustomer(profile, customerEmail) {
  const B = getTalentBlocksApi();
  const email = (customerEmail || getCustomerEmailForFavorites() || "").toLowerCase().trim();
  if (!B || !email || !profile) return false;
  return B.isBlockedBetween(email, getTalentId(profile));
}

function filterProfilesVisibleToCustomer(profiles, customerEmail) {
  const email = (customerEmail || getCustomerEmailForFavorites() || "").toLowerCase().trim();
  if (!email) return profiles;
  const B = getTalentBlocksApi();
  if (!B) return profiles;
  return (profiles || []).filter((p) => !B.isBlockedBetween(email, getTalentId(p)));
}

function loadVoiceProfilesForCustomerView() {
  if (!shouldApplyCustomerTalentFilters()) return loadVoiceProfiles();
  return filterProfilesVisibleToCustomer(loadVoiceProfiles());
}

function getAccountHistoryApi() {
  return typeof window !== "undefined" && window.WavrickAccountHistory
    ? window.WavrickAccountHistory
    : null;
}

function getCustomerEmailForFavorites() {
  const session = getCurrentSession();
  if (!session || session.role !== "customer") return "";
  return (session.email || "").toLowerCase().trim();
}

function getCustomerChannels() {
  const session = getCurrentSession();
  const CA = getCustomerAccountApi();
  if (!session || session.role !== "customer" || !CA) return [];
  return CA.getChannelsForEmail(session.email);
}

function isAdminSession() {
  return getCurrentSession()?.role === "admin";
}

/** 運営によるテスト依頼（決済スキップ可＝仮決済 UI 対象） */
function isAdminTestRequest(request, session = null) {
  const s = session || getCurrentSession();
  if (s?.role === "admin") return true;
  const proof = String(request?.identityProofText || "");
  // 「ADR キャスティング確定」は顧客通常依頼にも付くため、運営印のみを見る
  if (/運営|ADRテスト/.test(proof)) return true;
  if (
    String(request?.sourceMode || "").toLowerCase() === "adr" &&
    String(request?.createdByRole || "").trim() === "admin"
  ) {
    return true;
  }
  return false;
}

/** 運営テスト／仮決済ルート（本番 Stripe 決済とは別扱い） */
function isOpsTestCase(request, wf = null, session = null) {
  const s = session || getCurrentSession();
  if (s?.role === "admin") return true;
  if (isAdminTestRequest(request, s)) return true;
  if (wf?.opsTest === true) return true;
  const mode = String(wf?.paymentMode || "").trim();
  if (mode === "provisional_test") return true;
  const pi = String(wf?.stripePaymentIntentId || "").trim();
  if (pi.startsWith("pi_test_")) return true;
  try {
    if (localStorage.getItem("wavrick_ops_test_unlock") === "1") return true;
  } catch {
    /* ignore */
  }
  const rid = String(request?.requestId || wf?.requestId || "").trim();
  if (rid && globalThis.WavrickAdrApi?.readBrowserProject?.(rid)) return true;
  return false;
}

/**
 * 決済完了か（制作開始・納品ゲート用）。
 * 全員受諾やフェーズだけでは true にしない — 仮決済ボタン / Stripe 本決済の実績のみ。
 */
function isWorkflowPaymentCleared(wf, request = null, session = null) {
  if (!wf) return false;
  const ps = String(wf.paymentStatus || wf.paymentstatus || "unpaid")
    .toLowerCase()
    .trim();
  if (ps === "paid" || ps === "paid_provisional") return true;
  // 本番 Stripe PaymentIntent のみ（pi_test_* は paymentStatus 必須）
  const pi = String(wf.stripePaymentIntentId || "").trim();
  if (/^pi_[A-Za-z0-9]+$/.test(pi) && !pi.startsWith("pi_test_")) return true;
  // 運営仮決済: paymentStatus 欠落や別名分裂でも制作開始済みなら納品解禁
  const mode = String(wf.paymentMode || "").trim();
  const phase = String(wf.transactionPhase || "").trim();
  const provisionalAt = wf.provisionalPaidAt || wf.provisionalPaymentAt || null;
  if (
    (mode === "provisional_test" || wf.opsTest === true || pi.startsWith("pi_test_")) &&
    (phase === "in_production" || phase === "paid_provisional" || provisionalAt)
  ) {
    return true;
  }
  return false;
}

function isWorkflowCancelled(wf) {
  const Tx = getTransactionApi();
  if (Tx?.isWorkflowCancelled) return Tx.isWorkflowCancelled(wf);
  if (!wf) return false;
  if (String(wf.status || "").trim() === "キャンセル") return true;
  if (String(wf.transactionPhase || "").trim() === "cancelled") return true;
  const pay = String(wf.paymentStatus || wf.paymentstatus || "")
    .toLowerCase()
    .trim();
  return pay === "cancelled";
}

function cancelledCaseMessage() {
  const msg = t("work.case_cancelled");
  return msg && msg !== "work.case_cancelled" ? msg : "この案件はキャンセルされました";
}

function cancelledStatusLabel() {
  const msg = t("work.status_cancelled");
  return msg && msg !== "work.status_cancelled" ? msg : "キャンセル済み";
}

function isRecordingUnlocked(wf, request, session = null) {
  const Tx = getTransactionApi();
  if (isWorkflowCancelled(wf)) return false;
  // 運営テスト専用ルート: 担当声優が受諾済みなら収録解禁（本決済不要）
  if (isOpsTestCase(request, wf, session)) {
    const talentId =
      session?.role === "voice" ? resolveVoiceTalentIdForSession(session) : "";
    if (talentId) {
      const mine = (wf?.castAcceptance || []).find((s) =>
        talentIdsEqual(s?.talentId, talentId)
      );
      if (mine && String(mine.status || "") === (Tx?.SLOT_STATUS?.accepted || "accepted")) {
        return true;
      }
    }
    if (Tx?.allSlotsAccepted?.(wf?.castAcceptance || [])) return true;
    // 仮決済済み / 制作中も解禁
    if (isWorkflowPaymentCleared(wf, request, session)) return true;
    return false;
  }
  // 本番: 声優は「自分が受諾済み」なら収録ページを開ける（納品は別途決済ゲート）
  if (session?.role === "voice") {
    const talentId = resolveVoiceTalentIdForSession(session);
    if (!talentId) return false;
    const mine = (wf?.castAcceptance || []).find((s) => talentIdsEqual(s?.talentId, talentId));
    return Boolean(
      mine && String(mine.status || "") === (Tx?.SLOT_STATUS?.accepted || "accepted")
    );
  }
  // 顧客・運営: 決済済み、または受諾が進んでいる案件を開ける
  if (isWorkflowPaymentCleared(wf, request, session)) return true;
  if (Tx?.allSlotsAccepted?.(wf?.castAcceptance || [])) return true;
  const anyAccepted = (wf?.castAcceptance || []).some(
    (s) => String(s?.status || "") === (Tx?.SLOT_STATUS?.accepted || "accepted")
  );
  return anyAccepted;
}

/** Promise wrapper for showConfirmModal */
function confirmModalAsync(title, message, options = {}) {
  return new Promise((resolve) => {
    showConfirmModal(title, message, () => resolve(true), {
      ...options,
      onCancel: () => {
        options?.onCancel?.();
        resolve(false);
      }
    });
  });
}

if (typeof window !== "undefined") {
  window.isWorkflowPaymentCleared = isWorkflowPaymentCleared;
  window.isRecordingUnlocked = isRecordingUnlocked;
  window.confirmModalAsync = confirmModalAsync;
}

/** 運営向け仮決済（初回）— Stripe を通さず決済プロセスを完了扱いにする */
function applyAdminProvisionalPayment(wf, request) {
  const Tx = getTransactionApi();
  if (!Tx || !wf || !request || !isAdminTestRequest(request)) return wf;
  if (!Tx.allSlotsAccepted(wf.castAcceptance || [])) return wf;
  const now = new Date().toISOString();
  const testPi = `pi_test_admin_initial_${Date.now()}`;
  wf.paymentStatus = "paid_provisional";
  wf.paymentMode = "provisional_test";
  wf.opsTest = true;
  wf.transactionPhase = Tx.TRANSACTION_PHASE.in_production;
  wf.provisionalPaidAt = wf.provisionalPaidAt || now;
  wf.provisionalPaymentAt = now;
  wf.stripePaymentIntentId = wf.stripePaymentIntentId || testPi;
  if (REQUEST_STATUS_FLOW.indexOf(wf.status) < REQUEST_STATUS_FLOW.indexOf("進行中")) {
    wf.status = "進行中";
  }
  // 直後に paid 扱いで制作開始（仮決済完了）
  wf.paymentStatus = "paid";
  return wf;
}

/** 運営向け仮決済（リテイク） */
function applyAdminProvisionalRetakePayment(wf, request, feeUsd) {
  if (!wf || !request || !isAdminTestRequest(request)) return wf;
  const now = new Date().toISOString();
  const fee = Number(feeUsd);
  if (Number.isFinite(fee) && fee > 0) wf.retakeFeeUsd = fee;
  wf.retakePaymentStatus = "paid";
  wf.retakePaymentMode = "provisional_test";
  wf.provisionalRetakePaymentAt = now;
  wf.stripeRetakePaymentIntentId = `pi_test_admin_retake_${Date.now()}`;
  return wf;
}

/** @deprecated use applyAdminProvisionalPayment */
function applyAdminTestPaymentBypass(wf, request) {
  return applyAdminProvisionalPayment(wf, request);
}

/** 運営はチャンネル登録・一致なしで依頼可能。顧客はローカルのテスト回避のみ */
function isYtChannelCheckBypassed() {
  if (isAdminSession()) return true;
  if (isProductionSite()) return false;
  if (!isCustomerLoggedIn()) return false;
  try {
    return localStorage.getItem(YT_CHANNEL_CHECK_BYPASS_KEY) === "1";
  } catch {
    return false;
  }
}

function setYtChannelCheckBypassed(enabled) {
  try {
    if (enabled) localStorage.setItem(YT_CHANNEL_CHECK_BYPASS_KEY, "1");
    else localStorage.removeItem(YT_CHANNEL_CHECK_BYPASS_KEY);
  } catch {
    /* ignore */
  }
  syncYtChannelTestBypassUi();
  refreshYtChannelUi();
}

function syncYtChannelTestBypassUi() {
  const box = document.getElementById("ytChannelTestBypass");
  const checkbox = document.getElementById("ytChannelBypassCheck");
  if (!box) return;
  const show =
    !isProductionSite() &&
    !isAdminSession() &&
    isCustomerLoggedIn() &&
    getYtSourceMode() === "youtube";
  box.classList.toggle("hidden", !show);
  if (checkbox) {
    try {
      checkbox.checked =
        !isAdminSession() && localStorage.getItem(YT_CHANNEL_CHECK_BYPASS_KEY) === "1";
    } catch {
      checkbox.checked = false;
    }
  }
}

function registerYoutubeOAuthHandler(handler) {
  if (typeof handler === "function") wavrickYoutubeOAuthHandlers.push(handler);
}

function clearYoutubeOAuthPending() {
  const p = wavrickYoutubeOAuthPending;
  if (!p) return;
  if (p.timer) window.clearInterval(p.timer);
  if (p.storagePoll) window.clearInterval(p.storagePoll);
  wavrickYoutubeOAuthPending = null;
}

function deliverYoutubeOAuthResult(d) {
  if (!d || d.type !== "WAVRICK_YT_OAUTH") return false;
  for (const handler of wavrickYoutubeOAuthHandlers) {
    try {
      if (handler(d)) return true;
    } catch (_) {
      /* continue */
    }
  }
  const pending = wavrickYoutubeOAuthPending;
  if (!pending?.onResult) return false;
  const msgKey = channelKeyFromOAuthMessage(d);
  if (
    pending.channelKey &&
    d.ok &&
    d.channelId &&
    msgKey &&
    !channelKeysMatch(msgKey, pending.channelKey)
  ) {
    return false;
  }
  try {
    sessionStorage.removeItem(WAVRICK_YT_OAUTH_STORAGE_KEY);
  } catch (_) {
    /* ignore */
  }
  const onResult = pending.onResult;
  const btn = pending.btn;
  const idleLabel = pending.idleLabel;
  clearYoutubeOAuthPending();
  onResult(d, { btn, idleLabel });
  return true;
}

function tryConsumeYoutubeOAuthFromStorageGlobal() {
  let raw = "";
  try {
    raw = sessionStorage.getItem(WAVRICK_YT_OAUTH_STORAGE_KEY) || "";
  } catch (_) {
    return false;
  }
  if (!raw) return false;
  let wrapped = null;
  try {
    wrapped = JSON.parse(raw);
  } catch (_) {
    return false;
  }
  const ts = wrapped?.ts;
  const d = wrapped?.data;
  if (!d || d.type !== "WAVRICK_YT_OAUTH") return false;
  if (typeof ts === "number" && Date.now() - ts > 120_000) {
    try {
      sessionStorage.removeItem(WAVRICK_YT_OAUTH_STORAGE_KEY);
    } catch (_) {
      /* ignore */
    }
    return false;
  }
  return deliverYoutubeOAuthResult(d);
}

function initYoutubeOAuthBridge() {
  if (window.__wavrickYtOAuthMessageBound) return;
  window.__wavrickYtOAuthMessageBound = true;
  window.addEventListener("message", (event) => {
    const localOrigin = window.location.origin;
    const supabaseOrigin = getSupabaseOriginForPostMessage();
    if (event.origin !== localOrigin && (!supabaseOrigin || event.origin !== supabaseOrigin)) return;
    deliverYoutubeOAuthResult(event.data);
  });
  window.addEventListener("focus", () => tryConsumeYoutubeOAuthFromStorageGlobal());
}

function startYoutubeOAuthPopup({ channelKey, linkAll, btn, idleLabel, onResult }) {
  if (!isSupabaseEnabled() && !initSupabaseClient()) {
    return { ok: false, message: "Google 認証には Supabase 接続と Edge Function（youtube-oauth-*）が必要です。" };
  }
  const parentBase = getWavrickAppBase();
  if (!parentBase || parentBase === "null") {
    return { ok: false, message: "http(s) の URL で開いてください（file:// では利用できません）。" };
  }
  if (window.location.protocol === "file:") {
    return {
      ok: false,
      message: "file:// では OAuth できません。./scripts/start-dev-server.sh で起動してください。"
    };
  }
  const startUrl = buildYoutubeOAuthStartUrl(channelKey || "", parentBase, { linkAll });
  if (!startUrl) {
    return { ok: false, message: "OAuth URL を組み立てられませんでした。" };
  }
  if (btn) {
    btn.disabled = true;
    btn.textContent = linkAll ? "Google を開いています…" : wavrickI18n("yt_channel_opening");
  }
  const popup = window.open(startUrl, "wavrick_yt_oauth", "width=560,height=720");
  if (!popup) {
    if (btn) {
      btn.disabled = false;
      btn.textContent = idleLabel || wavrickI18n("yt_channel_btn");
    }
    return { ok: false, message: "ポップアップがブロックされました。許可してから再度お試しください。" };
  }
  if (btn) btn.textContent = wavrickI18n("yt_channel_wait");
  clearYoutubeOAuthPending();
  wavrickYoutubeOAuthPending = {
    channelKey: channelKey || "",
    linkAll: Boolean(linkAll),
    btn,
    idleLabel: idleLabel || "",
    onResult,
    storagePoll: window.setInterval(() => tryConsumeYoutubeOAuthFromStorageGlobal(), 350),
    timer: window.setInterval(() => {
      if (!popup.closed) {
        tryConsumeYoutubeOAuthFromStorageGlobal();
        return;
      }
      tryConsumeYoutubeOAuthFromStorageGlobal();
      const p = wavrickYoutubeOAuthPending;
      if (p?.btn === btn && btn) {
        btn.disabled = false;
        btn.textContent = p.idleLabel || wavrickI18n("yt_channel_btn");
      }
      clearYoutubeOAuthPending();
    }, 600)
  };
  return { ok: true };
}

function getYtSourceMode() {
  const checked = document.querySelector('input[name="ytSourceMode"]:checked');
  return checked?.value === "audio" ? "audio" : "youtube";
}

function ytFormNeedsValidVideoUrl() {
  return getYtSourceMode() !== "audio";
}

function syncYtSourceModeUi() {
  const mode = getYtSourceMode();
  const ytBlock = document.getElementById("ytYoutubeBlock");
  const audioBlock = document.getElementById("ytAudioBlock");
  const videoField = document.getElementById("ytVideoUrl");
  if (ytBlock) ytBlock.classList.toggle("hidden", mode === "audio");
  if (audioBlock) audioBlock.classList.toggle("hidden", mode !== "audio");
  if (videoField) videoField.required = mode === "youtube";
  const mismatch = document.getElementById("ytChannelMismatch");
  if (mismatch && mode === "audio") mismatch.classList.add("hidden");
  if (mode === "youtube") refreshYtChannelUi();
  syncYtChannelTestBypassUi();
}

function refreshYtChannelUi() {
  const banner = document.getElementById("ytChannelBanner");
  const mismatch = document.getElementById("ytChannelMismatch");
  if (!banner) return;
  if (!isCustomerLoggedIn() || getYtSourceMode() !== "youtube") {
    banner.classList.add("hidden");
    if (mismatch) mismatch.classList.add("hidden");
    return;
  }
  const channels = getCustomerChannels();
  const CA = getCustomerAccountApi();
  if (!channels.length && !isYtChannelCheckBypassed()) {
    banner.classList.remove("hidden");
    banner.innerHTML =
      'YouTube 利用にはチャンネル登録が必要です。<button type="button" class="link-btn" data-go="account">マイページでチャンネルを追加</button>';
    banner.querySelector("[data-go]")?.addEventListener("click", (e) => {
      e.preventDefault();
      showPage("account");
    });
    return;
  }
  banner.classList.remove("hidden");
  if (isAdminSession()) {
    banner.textContent =
      "運営ログイン: チャンネル登録・チャンネル一致なしで依頼できます。";
  } else if (isYtChannelCheckBypassed()) {
    banner.textContent =
      "テストモード: チャンネル不一致ロックは無効です（登録チャンネルと動画が違っても進められます）。";
  } else {
    const labels = channels.map((c) => (CA ? CA.channelEntryLabel(c) : c.channelId)).join("、");
    banner.textContent = `登録チャンネル（${channels.length}件）: ${labels}`;
  }
  if (mismatch) mismatch.classList.add("hidden");
}

function purgeLocalAccountData(email, role) {
  const normalized = (email || "").toLowerCase().trim();
  if (!normalized) return;
  const dropFrom = (key) => {
    try {
      const rows = JSON.parse(localStorage.getItem(key) || "[]");
      if (!Array.isArray(rows)) return;
      const next = rows.filter((row) => (row.email || "").toLowerCase().trim() !== normalized);
      localStorage.setItem(key, JSON.stringify(next));
    } catch {
      /* ignore */
    }
  };
  if (role === "customer") {
    dropFrom("wavrick_customer_accounts");
    dropFrom("wavrick_youtube_requests");
  } else if (role === "voice") {
    dropFrom("wavrick_voice_accounts");
    dropFrom("wavrick_voice_profiles");
  }
  try {
    sessionStorage.removeItem("wavrick_admin_dashboard_cache_v1");
  } catch {
    /* ignore */
  }
}

async function performWavrickLogout(options = {}) {
  cancelDeferredLocalSessionClear();
  clearPasswordRecoveryFlag();
  const session = getCurrentSession();
  if (session?.email) {
    await flushNotificationReadStateBeforeLogout(session.email);
  }
  localStorage.removeItem("wavrick_session");
  if (typeof clearAdminDashboardCache === "function") clearAdminDashboardCache();
  window.WavrickAdminMfa?.clearMfaToken?.();
  window.WavrickAdminGate?.clearGate?.();
  globalThis.WavrickAuthGate?.reset?.("logout");
  globalThis.WavrickAuthGate?.notifySignedOut?.("logout");
  // Stop realtime / side listeners before clearing JWT so they don't race re-login.
  window.dispatchEvent(new Event("wavrick-logout"));
  // Must await: fire-and-forget signOut races signInWithPassword (auth lock is disabled).
  if (isSupabaseEnabled()) {
    await signOutWavrickSupabase({ scope: "local" });
  }
  syncMainNav();
  syncYtPageAuthUi();
  syncAccountPageUi();
  if (options.loginMessage) {
    setMessage("loginMessage", options.loginMessage, "ok");
  }
  const redirect = options.redirectTo;
  if (redirect && pageMap[redirect]) showPage(redirect);
}

function syncAccountPageUi() {
  const gate = document.getElementById("accountCustomerGate");
  const app = document.getElementById("accountCustomerApp");
  const voiceApp = document.getElementById("accountVoiceApp");
  const adminApp = document.getElementById("accountAdminApp");
  const logoutCard = document.getElementById("accountLogoutCard");
  const dangerZone = document.getElementById("accountDangerZone");
  const loggedInAs = document.getElementById("accountLoggedInAs");
  const loggedInAsVoice = document.getElementById("accountLoggedInAsVoice");
  const loggedInAsAdmin = document.getElementById("accountLoggedInAsAdmin");
  const portfolioGate = document.getElementById("portfolioVoiceGate");
  const portfolioApp = document.getElementById("portfolioVoiceApp");
  const rewardsGate = document.getElementById("rewardsVoiceGate");
  const rewardsApp = document.getElementById("rewardsVoiceApp");
  const session = getCurrentSession();
  const isCustomer = isCustomerLoggedIn();
  const isVoice = session?.role === "voice";
  const isAdmin = session?.role === "admin";
  const loggedIn = isCustomer || isVoice || isAdmin;

  if (logoutCard) logoutCard.classList.toggle("hidden", !loggedIn);
  if (dangerZone) dangerZone.classList.toggle("hidden", !(isCustomer || isVoice));
  const accountTitle = document.querySelector("#page-account .form-header h2");
  const accountSubtitle = document.querySelector("#page-account > .form-subtitle");
  if (accountTitle) {
    accountTitle.textContent = isVoice
      ? t("account.title_voice")
      : isAdmin
        ? t("account.title_admin")
        : t("account.title");
  }
  if (accountSubtitle) {
    accountSubtitle.textContent = isVoice
      ? t("account.subtitle_voice_mypage")
      : isAdmin
        ? t("account.subtitle_admin")
        : t("account.subtitle");
  }
  if (gate) gate.classList.toggle("hidden", isCustomer || isVoice || isAdmin);
  if (app) app.classList.toggle("hidden", !isCustomer);
  if (voiceApp) voiceApp.classList.toggle("hidden", !isVoice);
  if (adminApp) adminApp.classList.toggle("hidden", !isAdmin);
  const securityCard = document.getElementById("accountSecurityCard");
  if (securityCard) securityCard.classList.toggle("hidden", !(isCustomer || isVoice));
  globalThis.WavrickEmailNotify?.showAccountCard?.(isCustomer || isVoice);
  const magicHint = document.getElementById("accountSecurityCurrentPasswordHint");
  if (magicHint) magicHint.classList.toggle("hidden", !isCustomer);
  if ((isCustomer || isVoice) && session) {
    populateAccountSecurityEmail(session);
  }
  if (portfolioGate) portfolioGate.classList.toggle("hidden", isVoice);
  if (portfolioApp) portfolioApp.classList.toggle("hidden", !isVoice);
  if (rewardsGate) rewardsGate.classList.toggle("hidden", isVoice);
  if (rewardsApp) rewardsApp.classList.toggle("hidden", !isVoice);
  if (loggedInAs && session && isCustomer) {
    loggedInAs.textContent = t("yt.logged_in_as", { name: session.displayName || session.email });
  }
  if (loggedInAsVoice && session && isVoice) {
    loggedInAsVoice.textContent = t("account.logged_in_voice", {
      name: session.displayName || session.email
    });

    syncVoiceRecruitToggleUi(session);

    const mypageStats = document.getElementById("voiceMypageStats");
    if (mypageStats) {
      const TS = globalThis.WavrickTalentStats;
      const talentId = resolveVoiceTalentIdForSession(session);
      mypageStats.innerHTML = TS ? TS.renderDetailedStatsHtml(TS.getTalentStats(talentId)) : "";
    }
    populateVoiceMypageProfileForm(session);
    // Safety net: confirmation-email login must complete cloud profile/account.
    void maybeCompleteVoiceRegistrationForCurrentSession("account-page").then((result) => {
      if (result?.ok && !result?.skipped && !result?.already) {
        populateVoiceMypageProfileForm(getCurrentSession());
        syncMainNav();
      }
    });
    void ensureVoiceCloudProfileSynced();
    globalThis.WavrickStripeConnect?.mountMypageCard?.();
    if (globalThis.WavrickStripeConnect?.isEnabled?.()) {
      void globalThis.WavrickStripeConnect.refreshIdentityStatus().then(() => {
        globalThis.WavrickStripeConnect?.mountMypageCard?.();
        syncVoiceRecruitToggleUi(getCurrentSession());
      });
    }
  }
  if (loggedInAsAdmin && session && isAdmin) {
    loggedInAsAdmin.textContent = t("account.logged_in_admin", {
      name: session.displayName || session.email
    });
  }
  if (isCustomer) {
    const session = getCurrentSession();
    const Cloud = getCloudApi();
    if (session?.email && Cloud?.hydrateUserCloudData && isSupabaseEnabled()) {
      void (async () => {
        const Gate = globalThis.WavrickAuthGate;
        if (Gate) {
          const auth = await Gate.ensureCloudAuth(8000);
          if (!auth.ok) return;
        } else {
          await ensureSupabaseAuthForLocalSession();
        }
        await Cloud.hydrateUserCloudData(session.email, { role: "customer" });
        renderAccountChannelList();
        renderAccountFavoriteTalents();
        renderAccountBlockedTalents();
        renderTalents();
      })();
    } else {
      renderAccountChannelList();
      renderAccountFavoriteTalents();
      renderAccountBlockedTalents();
    }
    void renderAccountCaseHistory();
  }
  if (isCustomer || isVoice) {
    // Lock mypage immediately from session, then confirm against server/DB
    globalThis.WavrickAccountRestriction?.syncAccountRestrictionUi?.();
    void globalThis.WavrickAccountRestriction?.ensureRestrictionUi?.().then((next) => {
      if (isVoice && next) syncVoiceRecruitToggleUi(next);
    });
  } else {
    globalThis.WavrickAccountRestriction?.syncAccountRestrictionUi?.();
  }
  if (isVoice) {
    const session = getCurrentSession();
    const Cloud = getCloudApi();
    const talentId = resolveVoiceTalentIdForSession(session);
    if (session?.email && Cloud?.hydrateUserCloudData && isSupabaseEnabled()) {
      void (async () => {
        const Gate = globalThis.WavrickAuthGate;
        if (Gate) {
          const auth = await Gate.ensureCloudAuth(8000);
          if (!auth.ok) return;
        } else {
          await ensureSupabaseAuthForLocalSession();
        }
        await Cloud.hydrateUserCloudData(session.email, { role: "voice", talentId });
        renderAccountBlockedCustomers();
      })();
    } else {
      renderAccountBlockedCustomers();
    }
    void renderAccountCaseHistory();
  }
}

function renderAccountFavoriteTalents() {
  const list = document.getElementById("accountFavoriteTalents");
  const empty = document.getElementById("accountFavoriteEmpty");
  const F = getTalentFavoritesApi();
  const email = getCustomerEmailForFavorites();
  if (!list || !F || !email) return;

  const favorites = F.getFavoritesForEmail(email).filter((fav) => {
    const profile = resolveVoiceProfileByTalentId(fav.talentId);
    return profile && !isTalentBlockedForCustomer(profile, email);
  });
  list.innerHTML = "";
  if (empty) empty.classList.toggle("hidden", favorites.length > 0);
  if (!favorites.length) return;

  for (const fav of favorites) {
    const profile = resolveVoiceProfileByTalentId(fav.talentId);
    const { name, meta } = profile
      ? getTalentDisplayMeta(profile)
      : { name: fav.displayName || fav.talentId, meta: "プロフィール未読込" };
    const li = document.createElement("li");
    li.className = "account-favorite-item";
    li.innerHTML = `
      <button type="button" class="account-favorite-main" data-open-favorite-talent="${escapeAttr(fav.talentId)}">
        ${profile ? renderTalentAvatarHtml(profile, "talent-avatar talent-avatar--sm") : renderDefaultVoiceAvatarHtml("talent-avatar talent-avatar--sm")}
        <span class="account-favorite-text">
          <span class="account-favorite-name">${escapeHtml(name)}</span>
          <span class="account-favorite-meta">${escapeHtml(meta)}</span>
        </span>
      </button>
      <button type="button" class="btn-ghost btn-sm account-favorite-remove" data-remove-favorite-talent="${escapeAttr(fav.talentId)}" aria-label="${escapeHtml(name)}をお気に入りから削除">削除</button>
    `;
    list.appendChild(li);
  }

  if (list.dataset.bound !== "1") {
    list.dataset.bound = "1";
    list.addEventListener("click", (event) => {
      const openBtn = event.target.closest("[data-open-favorite-talent]");
      if (openBtn) {
        const tid = openBtn.getAttribute("data-open-favorite-talent");
        const profile = resolveVoiceProfileByTalentId(tid);
        if (profile) openTalentProfileModal(profile);
        else setMessage("accountMessage", "声優プロフィールを読み込めませんでした。", "err");
        return;
      }
      const removeBtn = event.target.closest("[data-remove-favorite-talent]");
      if (!removeBtn) return;
      const tid = removeBtn.getAttribute("data-remove-favorite-talent");
      const Fapi = getTalentFavoritesApi();
      const customerEmail = getCustomerEmailForFavorites();
      if (!Fapi || !customerEmail || !tid) return;
      Fapi.removeFavorite(customerEmail, tid);
      renderAccountFavoriteTalents();
      syncTalentModalFavoriteBtn();
      renderYtCastSlots();
      setMessage("accountMessage", "お気に入りから削除しました。", "ok");
    });
  }
}

function renderAccountBlockedTalents() {
  const list = document.getElementById("accountBlockedTalents");
  const empty = document.getElementById("accountBlockedTalentsEmpty");
  const B = getTalentBlocksApi();
  const email = getCustomerEmailForFavorites();
  if (!list || !B || !email) return;

  const blocks = B.getCustomerBlockedTalents(email);
  list.innerHTML = "";
  if (empty) empty.classList.toggle("hidden", blocks.length > 0);
  if (!blocks.length) return;

  for (const row of blocks) {
    const profile = resolveVoiceProfileByTalentId(row.blockedId);
    const { name, meta } = profile
      ? getTalentDisplayMeta(profile)
      : { name: row.displayName || row.blockedId, meta: "プロフィール未読込" };
    const li = document.createElement("li");
    li.className = "account-block-item";
    li.innerHTML = `
      <div class="account-block-text">
        <span class="account-block-name">${escapeHtml(name)}</span>
        <span class="account-block-meta">${escapeHtml(meta)}</span>
      </div>
      <button type="button" class="btn-ghost btn-sm" data-unblock-talent="${escapeAttr(row.blockedId)}" aria-label="${escapeHtml(name)}のブロックを解除">解除</button>
    `;
    list.appendChild(li);
  }

  if (list.dataset.bound !== "1") {
    list.dataset.bound = "1";
    list.addEventListener("click", (event) => {
      const btn = event.target.closest("[data-unblock-talent]");
      if (!btn) return;
      const tid = btn.getAttribute("data-unblock-talent");
      const Blocks = getTalentBlocksApi();
      const customerEmail = getCustomerEmailForFavorites();
      if (!Blocks || !customerEmail || !tid) return;
      Blocks.removeCustomerBlock(customerEmail, tid);
      renderAccountBlockedTalents();
      syncTalentModalBlockBtn();
      renderTalents();
      renderYtCastSlots();
      setMessage("accountMessage", "ブロックを解除しました。", "ok");
    });
  }
}

function renderAccountBlockedCustomers() {
  const list = document.getElementById("accountBlockedCustomers");
  const empty = document.getElementById("accountBlockedCustomersEmpty");
  const B = getTalentBlocksApi();
  const session = getCurrentSession();
  const talentId = session?.role === "voice" ? resolveVoiceTalentIdForSession(session) : "";
  if (!list || !B || !talentId) return;

  const blocks = B.getVoiceBlockedCustomers(talentId);
  list.innerHTML = "";
  if (empty) empty.classList.toggle("hidden", blocks.length > 0);
  if (!blocks.length) return;

  for (const row of blocks) {
    const label = row.displayName || row.blockedId;
    const li = document.createElement("li");
    li.className = "account-block-item";
    li.innerHTML = `
      <div class="account-block-text">
        <span class="account-block-name">${escapeHtml(label)}</span>
        <span class="account-block-meta">${escapeHtml(row.blockedId)}</span>
      </div>
      <button type="button" class="btn-ghost btn-sm" data-unblock-customer="${escapeAttr(row.blockedId)}" aria-label="${escapeHtml(label)}のブロックを解除">解除</button>
    `;
    list.appendChild(li);
  }

  if (list.dataset.bound !== "1") {
    list.dataset.bound = "1";
    list.addEventListener("click", (event) => {
      const btn = event.target.closest("[data-unblock-customer]");
      if (!btn) return;
      const customerEmail = btn.getAttribute("data-unblock-customer");
      const Blocks = getTalentBlocksApi();
      const tid = resolveVoiceTalentIdForSession(getCurrentSession());
      if (!Blocks || !tid || !customerEmail) return;
      Blocks.removeVoiceBlock(tid, customerEmail);
      renderAccountBlockedCustomers();
      setMessage("accountMessage", "ブロックを解除しました。", "ok");
    });
  }
}

function getAccountHistoryDom() {
  const session = getCurrentSession();
  if (session?.role === "voice") {
    return {
      list: document.getElementById("accountCaseHistoryList"),
      empty: document.getElementById("accountCaseHistoryEmpty"),
      refresh: document.getElementById("accountHistoryRefreshBtn")
    };
  }
  if (session?.role === "customer") {
    return {
      list: document.getElementById("accountCaseHistoryListCustomer"),
      empty: document.getElementById("accountCaseHistoryEmptyCustomer"),
      refresh: document.getElementById("accountHistoryRefreshBtnCustomer")
    };
  }
  return null;
}

function getAccountHistoryHelpers() {
  const P = getPricingApi();
  return {
    escapeHtml,
    escapeAttr,
    formatDateTime,
    formatUsd: (amount) => (P ? P.formatUsd(amount) : `$${amount}`),
    renderDeliveryItemHtml,
    renderTalentAvatarHtml,
    renderDefaultVoiceAvatarHtml,
    getTalentDisplayMeta,
    resolveVoiceProfile: resolveVoiceProfileByTalentId,
    openTalentProfile: openTalentProfileModal
  };
}

async function renderAccountCaseHistory() {
  const dom = getAccountHistoryDom();
  const AH = getAccountHistoryApi();
  const session = getCurrentSession();
  if (!dom?.list || !AH || !session) return;
  if (session.role !== "customer" && session.role !== "voice") return;

  dom.list.innerHTML = `<p class="section-desc">読み込み中…</p>`;
  if (dom.empty) dom.empty.classList.add("hidden");

  if (isSupabaseEnabled()) {
    try {
      await hydrateAllCloudData();
    } catch (_) {
      /* local fallback */
    }
  }

  const rows = await getVisibleRequestsForCurrentSession();
  const sorted = AH.sortCasesByDate(rows);
  const talentId = session.role === "voice" ? resolveVoiceTalentIdForSession(session) : "";
  const helpers = getAccountHistoryHelpers();

  const items = sorted.map((request) => {
    const wf = getWorkflowForRequest(request.requestId, request.status);
    const castSlots = getWorkflowCastSlots(request, wf);
    const voiceSpeakerSlots =
      session.role === "voice" ? getVoiceSpeakerSlotsForRequest(request, talentId) : [];
    return AH.buildCaseViewModel({
      request,
      wf,
      role: session.role,
      talentId,
      helpers,
      castSlots,
      voiceSpeakerSlots
    });
  });

  if (!items.length) {
    dom.list.innerHTML = "";
    if (dom.empty) dom.empty.classList.remove("hidden");
    return;
  }

  if (dom.empty) dom.empty.classList.add("hidden");
  dom.list.innerHTML = AH.renderHistoryListHtml(items, helpers);
}

function bindAccountCaseHistory() {
  const bindRefresh = (btn) => {
    if (!btn || btn.dataset.bound === "1") return;
    btn.dataset.bound = "1";
    btn.addEventListener("click", () => {
      void renderAccountCaseHistory();
    });
  };
  bindRefresh(document.getElementById("accountHistoryRefreshBtn"));
  bindRefresh(document.getElementById("accountHistoryRefreshBtnCustomer"));

  const bindList = (listEl) => {
    if (!listEl || listEl.dataset.bound === "1") return;
    listEl.dataset.bound = "1";
    listEl.addEventListener("click", (event) => {
      const toggleBtn = event.target.closest("[data-toggle-account-case]");
      if (toggleBtn) {
        const rid = toggleBtn.getAttribute("data-toggle-account-case");
        const detail = document.getElementById(`account-case-detail-${rid}`);
        if (!detail) return;
        const open = detail.classList.contains("hidden");
        listEl.querySelectorAll(".account-case-detail").forEach((node) => node.classList.add("hidden"));
        listEl.querySelectorAll("[data-toggle-account-case]").forEach((node) => {
          node.setAttribute("aria-expanded", "false");
          node.closest(".account-case-card")?.classList.remove("account-case-card--open");
        });
        if (open) {
          detail.classList.remove("hidden");
          toggleBtn.setAttribute("aria-expanded", "true");
          toggleBtn.closest(".account-case-card")?.classList.add("account-case-card--open");
          globalThis.WavrickNavBack?.push?.(() => {
            detail.classList.add("hidden");
            toggleBtn.setAttribute("aria-expanded", "false");
            toggleBtn.closest(".account-case-card")?.classList.remove("account-case-card--open");
          });
          globalThis.WavrickNavBack?.bindSwipeBack?.(detail, () => {
            globalThis.WavrickNavBack?.pop?.();
          });
        }
        return;
      }

      const workBtn = event.target.closest("[data-open-work-case]");
      if (workBtn) {
        const rid = workBtn.getAttribute("data-open-work-case");
        if (!rid) return;
        void openWorkCaseById(rid);
        return;
      }

      const blockCustomerBtn = event.target.closest("[data-block-customer-email]");
      if (blockCustomerBtn) {
        const customerEmail = blockCustomerBtn.getAttribute("data-block-customer-email");
        const customerName = blockCustomerBtn.getAttribute("data-block-customer-name") || customerEmail;
        const B = getTalentBlocksApi();
        const tid = resolveVoiceTalentIdForSession(getCurrentSession());
        if (!B || !tid || !customerEmail) return;
        const result = B.addVoiceBlock(tid, { customerEmail, displayName: customerName });
        if (!result.ok) return;
        renderAccountBlockedCustomers();
        blockCustomerBtn.textContent = "ブロック済み";
        blockCustomerBtn.disabled = true;
        setMessage("accountMessage", `${customerName} をブロックしました。`, "ok");
        return;
      }

      const talentBtn = event.target.closest("[data-open-history-talent]");
      if (talentBtn) {
        const tid = talentBtn.getAttribute("data-open-history-talent");
        const profile = resolveVoiceProfileByTalentId(tid);
        if (profile) openTalentProfileModal(profile);
      }
    });
  };

  bindList(document.getElementById("accountCaseHistoryList"));
  bindList(document.getElementById("accountCaseHistoryListCustomer"));
}

function renderAccountChannelList() {
  const list = document.getElementById("accountChannelList");
  const empty = document.getElementById("accountChannelEmpty");
  const session = getCurrentSession();
  const CA = getCustomerAccountApi();
  if (!list || !session || !CA) return;
  const channels = getCustomerChannels();
  list.innerHTML = "";
  if (empty) empty.classList.toggle("hidden", channels.length > 0);
  for (const ch of channels) {
    const li = document.createElement("li");
    const left = document.createElement("div");
    const label = document.createElement("div");
    label.className = "channel-label";
    label.textContent = CA.channelEntryLabel(ch);
    const meta = document.createElement("div");
    meta.className = "channel-meta";
    meta.textContent = ch.channelId || ch.channelKey || "";
    left.append(label, meta);
    const removeBtn = document.createElement("button");
    removeBtn.type = "button";
    removeBtn.className = "btn-ghost";
    removeBtn.textContent = "削除";
    removeBtn.addEventListener("click", () => {
      CA.removeChannelForEmail(session.email, ch.channelId);
      renderAccountChannelList();
      refreshYtChannelUi();
      setMessage("accountMessage", "チャンネルを削除しました。", "ok");
    });
    li.append(left, removeBtn);
    list.appendChild(li);
  }
}

async function formatCustomerAudioUploadError(error) {
  const msg = String(error?.message || error || "").trim();
  if (!msg) return "音声のアップロードに失敗しました。";
  if (/Failed to fetch|NetworkError|load failed|network request failed/i.test(msg)) {
    return "音声ストレージに接続できませんでした。ネットワークまたはログイン状態を確認し、再試行してください。";
  }
  if (/row-level security|RLS|not allowed|unauthorized|401|403|jwt|auth/i.test(msg)) {
    return "音声アップロードの権限がありません。再ログインしてから試してください。";
  }
  if (/payload|too large|maximum|entity too large|size/i.test(msg)) {
    return "ファイルが大きすぎます（上限 約24MB）。短い音声か圧縮したファイルで再試行してください。";
  }
  if (/Bucket not found|not found/i.test(msg)) {
    return "アップロード用ストレージ（customer-uploads）が見つかりません。運営に連絡してください。";
  }
  return `音声のアップロードに失敗しました（${msg}）。`;
}

async function uploadCustomerAudioWithFallback(file) {
  const CA = getCustomerAccountApi();
  if (!CA) throw new Error("顧客アカウントモジュールを読み込めません。");
  if (!file) throw new Error("音声ファイルを選択してください。");
  const maxBytes = Number(CA.MAX_AUDIO_BYTES) || 24 * 1024 * 1024;
  if (file.size > maxBytes) {
    throw new Error(`ファイルが大きすぎます（上限 ${Math.round(maxBytes / 1024 / 1024)}MB）。`);
  }

  const session = getCurrentSession();
  const local =
    typeof isLocalWavrickDevHost === "function" ? isLocalWavrickDevHost() : false;

  if (isSupabaseEnabled() && supabaseClient && session?.email) {
    const Gate = globalThis.WavrickAuthGate;
    if (Gate?.ensureCloudAuth) {
      const auth = await Gate.ensureCloudAuth(8000);
      if (!auth?.ok && !local) {
        throw new Error(
          "ログインのクラウド認証が完了していません。再ログインしてから音声をアップロードしてください。"
        );
      }
    }
    try {
      let uid = "";
      try {
        const { data: userData } = await supabaseClient.auth.getUser();
        uid = String(userData?.user?.id || "").trim();
      } catch {
        uid = "";
      }
      if (!uid && !local) {
        throw new Error(
          "Supabase ログインが必要です。一度ログアウトして再ログインしてください。"
        );
      }
      const safeName =
        (file.name || "upload").replace(/[^\w.-]+/g, "_").slice(0, 80) || "upload.bin";
      const folder = uid || encodeURIComponent(String(session.email).toLowerCase());
      const path = `${folder}/${Date.now()}_${safeName}`;
      const { error } = await supabaseClient.storage
        .from(CUSTOMER_UPLOAD_BUCKET)
        .upload(path, file, {
          upsert: false,
          contentType: file.type || "application/octet-stream"
        });
      if (!error) {
        const { data: pub } = supabaseClient.storage
          .from(CUSTOMER_UPLOAD_BUCKET)
          .getPublicUrl(path);
        const url = String(pub?.publicUrl || "").trim();
        if (!url) throw new Error("アップロード先 URL を取得できませんでした。");
        return {
          ok: true,
          url,
          storagePath: path,
          fileName: file.name,
          byteLength: file.size
        };
      }
      if (!local) throw new Error(await formatCustomerAudioUploadError(error));
      console.warn("[uploadCustomerAudio] storage failed, trying local /api/", error);
    } catch (err) {
      if (!local) {
        const raw = err instanceof Error ? err.message : String(err);
        if (
          /再ログイン|接続できません|権限がありません|大きすぎます|見つかりません|ログインが必要/.test(
            raw
          )
        ) {
          throw err instanceof Error ? err : new Error(raw);
        }
        throw new Error(await formatCustomerAudioUploadError(err));
      }
      console.warn("[uploadCustomerAudio] storage threw, trying local /api/", err);
    }
  } else if (!local) {
    if (!session?.email) throw new Error("音声アップロードにはログインが必要です。");
    throw new Error("Supabase に接続できません。ページを再読み込みしてください。");
  }

  try {
    return await CA.uploadCustomerAudio(file);
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    if (/Failed to fetch|NetworkError|load failed/i.test(msg)) {
      throw new Error(
        local
          ? "ローカル開発サーバ (8889) の音声アップロード API に接続できません。./scripts/start-dev-server.sh を起動してください。"
          : await formatCustomerAudioUploadError(err)
      );
    }
    throw err instanceof Error ? err : new Error(String(err));
  }
}

function bindAccountPage() {
  const logoutBtn = document.getElementById("accountLogoutButton");
  if (logoutBtn && logoutBtn.dataset.bound !== "1") {
    logoutBtn.dataset.bound = "1";
    logoutBtn.addEventListener("click", () => {
      showConfirmModal(
        t("logout.confirm_title"),
        t("logout.confirm_message"),
        async () => {
          await performWavrickLogout({ redirectTo: "login" });
          showToast(t("logout.success_toast"), "info");
        },
        { confirmLabel: t("login.logout") }
      );
    });
  }

  const deleteBtn = document.getElementById("accountDeleteButton");
  if (deleteBtn && deleteBtn.dataset.bound !== "1") {
    deleteBtn.dataset.bound = "1";
    deleteBtn.addEventListener("click", () => {
      const session = getCurrentSession();
      if (!session || (session.role !== "customer" && session.role !== "voice")) return;
      if (!window.WavrickAccountIdentity?.deleteMyAccount) {
        setMessage("accountDeleteMessage", t("account.delete_unavailable"), "err");
        return;
      }
      showConfirmModal(
        t("account.delete_confirm_title"),
        t("account.delete_confirm_message"),
        async () => {
          deleteBtn.disabled = true;
          setMessage("accountDeleteMessage", t("account.delete_working"), null);
          const result = await WavrickAccountIdentity.deleteMyAccount(session.role);
          deleteBtn.disabled = false;
          if (!result.ok) {
            const detail = String(result.reason || result.detail || "").trim();
            const msg = detail
              ? `${t("account.delete_failed")} (${detail})`
              : t("account.delete_failed");
            setMessage("accountDeleteMessage", msg, "err");
            return;
          }
          purgeLocalAccountData(session.email, session.role);
          await performWavrickLogout({ redirectTo: "home" });
          showToast(t("account.delete_done"), "info");
        },
        { confirmLabel: t("account.delete_btn") }
      );
    });
  }

  const oauthBtn = document.getElementById("accountChannelOAuthBtn");
  const linkAllBtn = document.getElementById("accountLinkAllOAuthBtn");
  if (!oauthBtn && !linkAllBtn) return;

  if (oauthBtn) {
    oauthBtn.addEventListener("click", () => {
      setMessage("accountMessage", "");
      if (!isCustomerLoggedIn()) {
        setMessage("accountMessage", "先にログインしてください。", "err");
        return;
      }
      const field = document.getElementById("accountChannelUrl");
      const key = normalizeYoutubeChannelKey(field ? field.value : "");
      if (!key) {
        setMessage("accountMessage", "チャンネル URL または @ハンドルを入力してください。", "err");
        return;
      }
      const session = getCurrentSession();
      const CA = getCustomerAccountApi();
      const idle = oauthBtn.textContent;
      const started = startYoutubeOAuthPopup({
        channelKey: key,
        linkAll: false,
        btn: oauthBtn,
        idleLabel: idle,
        onResult: (d) => {
          oauthBtn.disabled = false;
          oauthBtn.textContent = idle;
          if (!d.ok) {
            const errText = d.code ? youtubeOAuthMessageFromCode(d.code) : wavrickI18n("yt_oauth_fail");
            setMessage("accountMessage", errText + (d.detail ? ` (${d.detail})` : ""), "err");
            return;
          }
          if (CA && session?.email && d.channelId) {
            const msgKey = channelKeyFromOAuthMessage(d) || key;
            CA.addChannelsForEmail(session.email, [
              { channelId: d.channelId, channelKey: msgKey || `channel:${d.channelId}` }
            ]);
            renderAccountChannelList();
            refreshYtChannelUi();
          }
          setMessage("accountMessage", wavrickI18n("yt_oauth_success"), "ok");
        }
      });
      if (!started.ok) setMessage("accountMessage", started.message, "err");
    });
  }

  if (linkAllBtn) {
    linkAllBtn.addEventListener("click", () => {
      setMessage("accountMessage", "");
      if (!isCustomerLoggedIn()) {
        setMessage("accountMessage", "先にログインしてください。", "err");
        return;
      }
      const session = getCurrentSession();
      const CA = getCustomerAccountApi();
      const idle = linkAllBtn.textContent;
      const started = startYoutubeOAuthPopup({
        channelKey: "",
        linkAll: true,
        btn: linkAllBtn,
        idleLabel: idle,
        onResult: (d) => {
          linkAllBtn.disabled = false;
          linkAllBtn.textContent = idle;
          if (!d.ok) {
            const errText = d.code ? youtubeOAuthMessageFromCode(d.code) : wavrickI18n("yt_oauth_fail");
            setMessage("accountMessage", errText + (d.detail ? ` (${d.detail})` : ""), "err");
            return;
          }
          const ids = Array.isArray(d.channelIds) ? d.channelIds : d.channelId ? [d.channelId] : [];
          if (CA && session?.email && ids.length) {
            CA.addChannelsForEmail(
              session.email,
              ids.map((id) => ({ channelId: id, channelKey: `channel:${id}` }))
            );
            renderAccountChannelList();
            refreshYtChannelUi();
          }
          setMessage(
            "accountMessage",
            ids.length ? `${ids.length} 件のチャンネルを登録しました。` : wavrickI18n("yt_oauth_success"),
            "ok"
          );
        }
      });
      if (!started.ok) setMessage("accountMessage", started.message, "err");
    });
  }
}

