function getWorkflows() {
  return JSON.parse(localStorage.getItem("wavrick_request_workflows") || "{}");
}

/** Drop inlined base64 audio from local cache — cloud `url` / storagePath remain. */
function stripHeavyWorkflowForLocalStorage(wf) {
  if (!wf || typeof wf !== "object") return wf;
  const Sync = globalThis.WavrickWorkflowSync;
  if (typeof Sync?.stripHeavyWorkflowForLocalStorage === "function") {
    return Sync.stripHeavyWorkflowForLocalStorage(wf);
  }
  const next = { ...wf };
  if (Array.isArray(next.deliveries)) {
    next.deliveries = stripDeliveryAudioForCloud(next.deliveries);
  }
  return next;
}

function compactWorkflowsMapForLocalStorage(workflows) {
  const out = {};
  for (const [key, wf] of Object.entries(workflows || {})) {
    out[key] = stripHeavyWorkflowForLocalStorage(wf);
  }
  return out;
}

/**
 * Persist workflows without blowing localStorage (~5MB). On QuotaExceeded:
 * strip base64 → drop oldest non-paid shells → clear key and store compact map.
 */
function persistWorkflowsLocalStorage(workflows) {
  const key = "wavrick_request_workflows";
  let payload = compactWorkflowsMapForLocalStorage(workflows);
  const tryWrite = (map) => {
    localStorage.setItem(key, JSON.stringify(map));
    return true;
  };
  try {
    return tryWrite(payload);
  } catch (error) {
    if (error?.name !== "QuotaExceededError" && !/quota/i.test(String(error?.message || ""))) {
      throw error;
    }
    console.warn("[wavrick] workflow localStorage quota exceeded — compacting");
  }

  // Drop bulky delivery payloads entirely if still too large (keep metadata counts).
  payload = Object.fromEntries(
    Object.entries(payload).map(([id, wf]) => {
      const slim = { ...wf };
      if (Array.isArray(slim.deliveries) && slim.deliveries.length) {
        slim.deliveries = slim.deliveries.map((d) => ({
          id: d?.id || "",
          url: d?.url || "",
          note: d?.note || "",
          createdAt: d?.createdAt || "",
          kind: d?.kind || "url",
          fileName: d?.fileName || "",
          submittedBy: d?.submittedBy || "",
          submitterEmail: d?.submitterEmail || "",
          storagePath: d?.storagePath || "",
          audioDataUrl: "",
          cueTakes: Array.isArray(d?.cueTakes)
            ? d.cueTakes.map((t) => ({
                cueId: t?.cueId || "",
                speakerId: t?.speakerId || "",
                speakerIndex: Number(t?.speakerIndex) || 0,
                talentId: t?.talentId || "",
                fileName: t?.fileName || "",
                url: t?.url || "",
                storagePath: t?.storagePath || "",
                audioDataUrl: "",
                startSec: Number(t?.startSec) || 0,
                endSec: Number(t?.endSec) || 0
              }))
            : []
        }));
      }
      if (Array.isArray(slim.messages) && slim.messages.length > 40) {
        slim.messages = slim.messages.slice(-40);
      }
      return [id, slim];
    })
  );
  try {
    return tryWrite(payload);
  } catch (error) {
    if (error?.name !== "QuotaExceededError" && !/quota/i.test(String(error?.message || ""))) {
      throw error;
    }
  }

  // Keep newest / paid workflows only.
  const ranked = Object.entries(payload).sort((a, b) => {
    const score = (wf) =>
      (isWorkflowPaymentCleared(wf) ? 1e15 : 0) + (new Date(wf?.updatedAt || 0).getTime() || 0);
    return score(b[1]) - score(a[1]);
  });
  for (const keep of [40, 20, 10, 5, 1]) {
    const trimmed = Object.fromEntries(ranked.slice(0, keep));
    try {
      try {
        localStorage.removeItem(key);
      } catch {
        /* ignore */
      }
      return tryWrite(trimmed);
    } catch (error) {
      if (error?.name !== "QuotaExceededError" && !/quota/i.test(String(error?.message || ""))) {
        throw error;
      }
    }
  }

  try {
    localStorage.removeItem(key);
  } catch {
    /* ignore */
  }
  console.warn("[wavrick] could not persist workflows locally (quota); continuing with memory only");
  return false;
}

/** youtube_requests.requestid と DB id(UUID) / workflow.requestid の食い違いを吸収 */
function listRequestWorkflowAliasKeys(requestOrId) {
  const Sync = globalThis.WavrickWorkflowSync;
  if (Sync?.listAliasKeys) {
    const keys = Sync.listAliasKeys(requestOrId);
    if (keys.length) return keys;
  }
  const keys = [];
  const push = (v) => {
    const id = String(v || "").trim();
    if (id && !keys.includes(id)) keys.push(id);
  };
  if (typeof requestOrId === "string") {
    push(requestOrId);
  } else if (requestOrId && typeof requestOrId === "object") {
    push(requestOrId.requestId);
    push(requestOrId.rowId);
    push(requestOrId.id);
  }
  return keys;
}

const WORKFLOW_PHASE_RANK = {
  cancelled: -1,
  draft: 0,
  casting: 1,
  awaiting_acceptance: 2,
  quoted: 3,
  paid_provisional: 4,
  in_production: 5
};

function workflowPhaseRank(phase) {
  return WORKFLOW_PHASE_RANK[String(phase || "")] ?? 0;
}

function workflowUpdatedAtMs(wf) {
  const t = new Date(wf?.updatedAt || 0).getTime();
  return Number.isFinite(t) ? t : 0;
}

function workflowRichnessScore(wf) {
  if (!wf) return -1;
  let score = 0;
  if (isWorkflowPaymentCleared(wf)) score += 1000;
  score += workflowPhaseRank(wf.transactionPhase) * 100;
  const slots = Array.isArray(wf.castAcceptance) ? wf.castAcceptance : [];
  score += slots.length * 10;
  score += slots.filter((s) => String(s?.status || "") === "accepted").length * 50;
  // updatedAt is primary for merge — keep a small tie-breaker only
  score += workflowUpdatedAtMs(wf) / 1e12;
  return score;
}

function mergeWorkflowListById(aList, bList) {
  const map = new Map();
  const push = (item) => {
    if (!item || typeof item !== "object") return;
    const id = String(item.id || item.deliveryId || item.messageId || "").trim();
    const key = id || `anon_${map.size}_${JSON.stringify(item).slice(0, 48)}`;
    const prev = map.get(key);
    if (!prev) {
      map.set(key, item);
      return;
    }
    const prevTs = new Date(prev.updatedAt || prev.createdAt || 0).getTime() || 0;
    const nextTs = new Date(item.updatedAt || item.createdAt || 0).getTime() || 0;
    map.set(key, nextTs >= prevTs ? { ...prev, ...item } : { ...item, ...prev });
  };
  (Array.isArray(aList) ? aList : []).forEach(push);
  (Array.isArray(bList) ? bList : []).forEach(push);
  return [...map.values()];
}

/** requestId / rowId エイリアス間で決済・フェーズ・キャスト情報を統合 */
function mergeWorkflowPair(a, b) {
  const Sync = globalThis.WavrickWorkflowSync;
  if (Sync?.mergeWorkflowPair) return Sync.mergeWorkflowPair(a, b);
  if (!a) return b ? { ...b } : null;
  if (!b) return { ...a };

  const aTs = workflowUpdatedAtMs(a);
  const bTs = workflowUpdatedAtMs(b);
  const newer = aTs >= bTs ? a : b;
  const older = newer === a ? b : a;
  const merged = { ...older, ...newer };

  if (isWorkflowPaymentCleared(older) && !isWorkflowPaymentCleared(newer)) {
    merged.paymentStatus = older.paymentStatus;
    merged.paymentMode = older.paymentMode;
    merged.provisionalPaidAt = older.provisionalPaidAt || merged.provisionalPaidAt;
    merged.provisionalPaymentAt = older.provisionalPaymentAt || merged.provisionalPaymentAt;
    merged.stripePaymentIntentId = older.stripePaymentIntentId || merged.stripePaymentIntentId;
  }
  if (Array.isArray(newer.castAcceptance)) merged.castAcceptance = newer.castAcceptance;
  else if (Array.isArray(older.castAcceptance)) merged.castAcceptance = older.castAcceptance;

  merged.deliveries = mergeWorkflowListById(older.deliveries, newer.deliveries);
  merged.messages = mergeWorkflowListById(older.messages, newer.messages);
  merged.partialRetakes = mergeWorkflowListById(older.partialRetakes, newer.partialRetakes);
  if (newer.cancelNegotiation || older.cancelNegotiation) {
    const Sync = globalThis.WavrickWorkflowSync;
    merged.cancelNegotiation =
      typeof Sync?.mergeCancelNegotiation === "function"
        ? Sync.mergeCancelNegotiation(older.cancelNegotiation, newer.cancelNegotiation)
        : newer.cancelNegotiation || older.cancelNegotiation || null;
  }

  if (isWorkflowPaymentCleared(merged) === false && isWorkflowPaymentCleared(older)) {
    merged.paymentStatus = older.paymentStatus;
    merged.paymentMode = older.paymentMode || merged.paymentMode;
    merged.provisionalPaidAt = older.provisionalPaidAt || merged.provisionalPaidAt;
    merged.provisionalPaymentAt = older.provisionalPaymentAt || merged.provisionalPaymentAt;
    merged.stripePaymentIntentId = older.stripePaymentIntentId || merged.stripePaymentIntentId;
    if (workflowPhaseRank(older.transactionPhase) > workflowPhaseRank(merged.transactionPhase)) {
      merged.transactionPhase = older.transactionPhase;
    }
  }

  const maxTs = Math.max(aTs, bTs);
  merged.updatedAt =
    maxTs > 0
      ? new Date(maxTs).toISOString()
      : newer.updatedAt || older.updatedAt || new Date().toISOString();
  return merged;
}

function syncWorkflowAliasesIntoStore(requests) {
  const workflows = getWorkflows();
  const rows =
    Array.isArray(requests) && requests.length
      ? requests
      : (() => {
          try {
            return JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]");
          } catch {
            return [];
          }
        })();
  let changed = false;
  for (const req of rows) {
    const rid = String(req?.requestId || "").trim();
    const rowId = String(req?.rowId || req?.id || "").trim();
    if (!rid || !rowId || rid === rowId) continue;
    const a = workflows[rid];
    const b = workflows[rowId];
    const merged = mergeWorkflowPair(a, b);
    if (!merged) continue;
    const nextRid = { ...merged, requestId: rid };
    const nextRow = { ...merged, requestId: rowId };
    const ridChanged = JSON.stringify(workflows[rid]) !== JSON.stringify(nextRid);
    const rowChanged = JSON.stringify(workflows[rowId]) !== JSON.stringify(nextRow);
    if (ridChanged || rowChanged || !a || !b) {
      workflows[rid] = nextRid;
      workflows[rowId] = nextRow;
      changed = true;
    }
  }
  if (changed) {
    persistWorkflowsLocalStorage(workflows);
  }
  return workflows;
}

function findStoredWorkflow(requestOrId) {
  const workflows = syncWorkflowAliasesIntoStore(
    typeof requestOrId === "object" ? [requestOrId] : null
  );
  const keys = listRequestWorkflowAliasKeys(requestOrId);
  let best = null;
  let bestKey = keys[0] || "";
  for (const key of keys) {
    const wf = workflows[key];
    if (!wf) continue;
    if (!best || workflowRichnessScore(wf) >= workflowRichnessScore(best)) {
      best = mergeWorkflowPair(best, wf);
      bestKey = key;
    }
  }
  return { workflows, key: bestKey, wf: best };
}

function saveWorkflows(payload, syncRequestId) {
  persistWorkflowsLocalStorage(payload);
  if (globalThis.WavrickTalentStats) globalThis.WavrickTalentStats.invalidateCache();
  if (syncRequestId && isSupabaseEnabled()) {
    const wf = payload[syncRequestId];
    if (wf?.requestId) {
      // リモート通知の所有者は persistWorkflow。ここではローカル描画だけ。
      paintWorkdataUpdated({ requestId: syncRequestId });
      void upsertWorkflowRemoteSafe(wf, syncRequestId, {
        forcePaymentFields: isWorkflowPaymentCleared(wf)
      });
    }
  }
}

function saveWorkflowAliases(request, wf, { syncRemote = true } = {}) {
  const workflows = getWorkflows();
  const keys = listRequestWorkflowAliasKeys(request);
  const synced = maybeAdvanceTransactionPhase({ ...wf }, request) || wf;
  const next = { ...synced, updatedAt: synced.updatedAt || wf.updatedAt || new Date().toISOString() };
  for (const key of keys) {
    workflows[key] = { ...next, requestId: key };
  }
  // remote の requestid は UUID 側のことがあるため、両方へ同期を試す
  persistWorkflowsLocalStorage(workflows);
  if (globalThis.WavrickTalentStats) globalThis.WavrickTalentStats.invalidateCache();
  if (syncRemote && isSupabaseEnabled()) {
    // リモート通知の所有者は persistWorkflow。ここではローカル描画だけ。
    paintWorkdataUpdated({ requestId: next.requestId || keys[0] || "" });
    void upsertWorkflowRemoteSafe(next, request);
  }
  return workflows;
}

/** 取得なしで案件画面を再描画する（persist 後の二重 signal を避ける）。 */
function paintWorkdataUpdated(detail = {}) {
  try {
    window.dispatchEvent(
      new CustomEvent("wavrick-workdata-updated", {
        detail: { silent: true, ...(detail && typeof detail === "object" ? detail : {}) }
      })
    );
  } catch {
    /* ignore */
  }
}

function signalWorkdataChangedSafe(detail = {}) {
  paintWorkdataUpdated(detail);
  try {
    void globalThis.WavrickWorkdataRealtime?.signalWorkdataChanged?.(detail);
  } catch (err) {
    console.warn("[wavrick] signalWorkdataChanged failed", err);
  }
}

function isNotifyDebugEnabled() {
  try {
    return localStorage.getItem("wavrick_notify_debug") === "1";
  } catch {
    return false;
  }
}

function notifyTrace(step, data) {
  const tag = String(step || "");
  const noisy = !tag.includes("fail") && !tag.includes("skip") && !tag.includes("warn");
  if (noisy && !isNotifyDebugEnabled()) return;
  if (data === undefined) {
    console.info("[wavrick-notify]", tag);
    return;
  }
  console.info("[wavrick-notify]", tag, data);
}

function notificationsStorageEmail(email) {
  return String(email || getCurrentSession()?.email || "")
    .toLowerCase()
    .trim();
}

function notificationsLocalKey(email) {
  const normalized = notificationsStorageEmail(email);
  return normalized ? `wavrick_notifications:v1:${normalized}` : "wavrick_notifications";
}

function readNotificationsJson(key) {
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return null;
  }
}

function saveNotificationsForEmail(email, rows) {
  const key = notificationsLocalKey(email);
  localStorage.setItem(key, JSON.stringify(Array.isArray(rows) ? rows : []));
}

function migrateLegacyNotificationsForAdmin(email) {
  const normalized = notificationsStorageEmail(email);
  if (!normalized || getCurrentSession()?.role !== "admin") return null;
  const key = notificationsLocalKey(normalized);
  if (localStorage.getItem(key)) return null;
  const legacy = readNotificationsJson("wavrick_notifications");
  if (!legacy?.length) return null;
  saveNotificationsForEmail(normalized, legacy);
  return legacy;
}

function getNotifications() {
  const email = notificationsStorageEmail();
  if (!email) {
    return readNotificationsJson("wavrick_notifications") || [];
  }
  const key = notificationsLocalKey(email);
  if (localStorage.getItem(key) !== null) {
    return readNotificationsJson(key) || [];
  }
  const migrated = migrateLegacyNotificationsForAdmin(email);
  if (migrated) return migrated;
  return [];
}

function saveNotifications(rows) {
  const email = notificationsStorageEmail();
  if (!email) {
    localStorage.setItem("wavrick_notifications", JSON.stringify(rows));
    return;
  }
  saveNotificationsForEmail(email, rows);
}

const NOTIFICATION_USER_RETENTION_MAX = 150;
const PRUNED_NOTIFICATION_IDS_KEY = "wavrick_announcements_pruned_ids";
const ANNOUNCEMENT_READ_IDS_KEY = "wavrick_announcements_read_ids";
const NOTIFICATION_READ_STATE_FETCH_MAX = 500;
const NOTIFICATION_READ_SYNC_QUEUE_KEY = "wavrick_notification_read_sync_queue";
const NOTIFICATION_READ_BATCH_CHUNK = 80;
const NOTIFICATION_GLOBAL_STORAGE_MAX = 2000;
/** Locally authored rows waiting for first successful cloud write */
const NOTIFICATION_CLOUD_PENDING_KEY = "wavrick_ntf_cloud_pending";
/** Rows that hit permanent RLS/permission errors — never retry automatically */
const NOTIFICATION_CLOUD_BLOCKED_KEY = "wavrick_ntf_cloud_blocked";
const NOTIFICATION_CLOUD_ID_SET_MAX = 400;

function getReadSyncQueueMap() {
  try {
    return JSON.parse(localStorage.getItem(NOTIFICATION_READ_SYNC_QUEUE_KEY) || "{}");
  } catch {
    return {};
  }
}

function saveReadSyncQueueMap(map) {
  try {
    localStorage.setItem(NOTIFICATION_READ_SYNC_QUEUE_KEY, JSON.stringify(map));
  } catch {
    /* ignore */
  }
}

function enqueueNotificationReadSync(email, ids) {
  const normalized = String(email || "")
    .toLowerCase()
    .trim();
  if (!normalized || !ids?.length) return;
  const map = getReadSyncQueueMap();
  const pending = new Set(Array.isArray(map[normalized]) ? map[normalized] : []);
  for (const rawId of ids) {
    const id = String(rawId || "").trim();
    if (id) pending.add(id);
  }
  map[normalized] = [...pending].slice(-500);
  saveReadSyncQueueMap(map);
}

function dequeueNotificationReadSync(email, ids) {
  const normalized = String(email || "")
    .toLowerCase()
    .trim();
  if (!normalized) return;
  const remove = new Set((ids || []).map((id) => String(id || "").trim()).filter(Boolean));
  if (!remove.size) return;
  const map = getReadSyncQueueMap();
  const prev = Array.isArray(map[normalized]) ? map[normalized] : [];
  const next = prev.filter((id) => !remove.has(id));
  if (next.length) map[normalized] = next;
  else delete map[normalized];
  saveReadSyncQueueMap(map);
}

function getQueuedReadSyncIds(email) {
  const normalized = String(email || "")
    .toLowerCase()
    .trim();
  if (!normalized) return [];
  const map = getReadSyncQueueMap();
  return Array.isArray(map[normalized]) ? map[normalized] : [];
}

function getAnnouncementReadMap(email) {
  const normalized = String(email || "")
    .toLowerCase()
    .trim();
  if (!normalized) return {};
  try {
    const map = JSON.parse(localStorage.getItem(ANNOUNCEMENT_READ_IDS_KEY) || "{}");
    const entry = map[normalized];
    return entry && typeof entry === "object" ? entry : {};
  } catch {
    return {};
  }
}

function saveAnnouncementReadMap(email, readMap) {
  const normalized = String(email || "")
    .toLowerCase()
    .trim();
  if (!normalized) return;
  try {
    const map = JSON.parse(localStorage.getItem(ANNOUNCEMENT_READ_IDS_KEY) || "{}");
    const ids = Object.keys(readMap || {});
    const trimmed = {};
    for (const id of ids.slice(-500)) trimmed[id] = true;
    map[normalized] = trimmed;
    localStorage.setItem(ANNOUNCEMENT_READ_IDS_KEY, JSON.stringify(map));
  } catch {
    /* ignore */
  }
}

function mergeAnnouncementReadIds(email, notificationIds) {
  const normalized = String(email || "")
    .toLowerCase()
    .trim();
  if (!normalized || !notificationIds?.length) return false;
  const readMap = getAnnouncementReadMap(normalized);
  let changed = false;
  for (const rawId of notificationIds) {
    const id = String(rawId || "").trim();
    if (!id || readMap[id]) continue;
    readMap[id] = true;
    changed = true;
  }
  if (changed) saveAnnouncementReadMap(normalized, readMap);
  return changed;
}

async function persistNotificationReadRemote(email, notificationId) {
  const normalized = String(email || "")
    .toLowerCase()
    .trim();
  const id = String(notificationId || "").trim();
  if (!normalized || !id || !isSupabaseEnabled()) return false;
  await recoverSupabaseAuthSession({ retries: 1, waitMs: 4000 });
  if (!(await hasValidSupabaseAuthSession())) return false;
  initSupabaseClient();
  if (!supabaseClient) return false;
  const payload = {
    email: normalized,
    notification_id: id,
    read_at: new Date().toISOString()
  };
  const result = await upsertRemote(TABLES.notificationReadState, payload, "email,notification_id");
  if (!result.ok) {
    notifyTrace("read:persist-fail", { id, error: result.error });
    enqueueNotificationReadSync(normalized, [id]);
    return false;
  }
  dequeueNotificationReadSync(normalized, [id]);
  notifyTrace("read:persist-ok", { id });
  return true;
}

async function persistNotificationReadRemoteBatch(email, notificationIds) {
  const normalized = String(email || "")
    .toLowerCase()
    .trim();
  const ids = [...new Set((notificationIds || []).map((id) => String(id || "").trim()).filter(Boolean))];
  if (!normalized || !ids.length) return false;
  if (!isSupabaseEnabled()) return false;
  await recoverSupabaseAuthSession({ retries: 1, waitMs: 4000 });
  if (!(await hasValidSupabaseAuthSession())) return false;
  initSupabaseClient();
  if (!supabaseClient) return false;
  const readAt = new Date().toISOString();
  const payload = ids.map((id) => ({
    email: normalized,
    notification_id: id,
    read_at: readAt
  }));
  const { error } = await supabaseClient
    .from(TABLES.notificationReadState)
    .upsert(payload, { onConflict: "email,notification_id" });
  if (error) {
    notifyTrace("read:batch-fail", { count: ids.length, error });
    enqueueNotificationReadSync(normalized, ids);
    return false;
  }
  dequeueNotificationReadSync(normalized, ids);
  notifyTrace("read:batch-ok", { count: ids.length });
  return true;
}

async function persistNotificationReadRemoteBatchInChunks(email, notificationIds) {
  const ids = [...new Set((notificationIds || []).map((id) => String(id || "").trim()).filter(Boolean))];
  if (!ids.length) return true;
  let allOk = true;
  for (let i = 0; i < ids.length; i += NOTIFICATION_READ_BATCH_CHUNK) {
    const chunk = ids.slice(i, i + NOTIFICATION_READ_BATCH_CHUNK);
    const ok = await persistNotificationReadRemoteBatch(email, chunk);
    if (!ok) allOk = false;
  }
  return allOk;
}

async function fetchRemoteNotificationReadIds(email) {
  const normalized = String(email || "")
    .toLowerCase()
    .trim();
  if (!normalized || !isSupabaseEnabled()) return null;
  initSupabaseClient();
  if (!supabaseClient) return null;
  await recoverSupabaseAuthSession({ retries: 2, waitMs: 5000 });
  if (!(await hasValidSupabaseAuthSession())) return null;
  const collected = [];
  const pageSize = 500;
  let from = 0;
  while (collected.length < NOTIFICATION_READ_STATE_FETCH_MAX) {
    const to = from + pageSize - 1;
    const { data, error } = await supabaseClient
      .from(TABLES.notificationReadState)
      .select("notification_id")
      .eq("email", normalized)
      .order("read_at", { ascending: false })
      .range(from, to);
    if (error) {
      notifyTrace("read:fetch-fail", { error, from });
      return collected.length ? collected : null;
    }
    const page = Array.isArray(data)
      ? data.map((row) => String(row.notification_id || "").trim()).filter(Boolean)
      : [];
    if (!page.length) break;
    collected.push(...page);
    if (page.length < pageSize) break;
    from += pageSize;
  }
  return [...new Set(collected)].slice(0, NOTIFICATION_READ_STATE_FETCH_MAX);
}

let reconcileNotificationReadStateInFlight = null;

/** Logout-only: push local read ids with a short timeout — never block sign-out on full reconcile. */
async function flushNotificationReadStateBeforeLogout(email, timeoutMs = 2500) {
  const normalized = String(email || "")
    .toLowerCase()
    .trim();
  if (!normalized || !isSupabaseEnabled()) return;

  const work = async () => {
    await recoverSupabaseAuthSession({ retries: 0, waitMs: 1200 });
    if (!(await hasValidSupabaseAuthSession())) return;
    const localIds = Object.keys(getAnnouncementReadMap(normalized));
    const queuedIds = getQueuedReadSyncIds(normalized);
    const toPush = [...new Set([...localIds, ...queuedIds])];
    if (!toPush.length) return;
    await persistNotificationReadRemoteBatchInChunks(normalized, toPush);
  };

  try {
    await Promise.race([work(), new Promise((resolve) => setTimeout(resolve, timeoutMs))]);
  } catch {
    /* ignore — logout must proceed */
  }
}

const NOTIFICATION_READ_RECONCILE_MIN_GAP_MS = 60_000;
let _notificationReadReconcileAt = 0;

/** Pull remote read ids, push only missing locals + retry queue — keeps devices in sync. */
async function reconcileNotificationReadState(force = false) {
  const email = getCurrentSession()?.email;
  if (!email || !isSupabaseEnabled()) return false;
  if (reconcileNotificationReadStateInFlight) return reconcileNotificationReadStateInFlight;
  if (
    !force &&
    _notificationReadReconcileAt &&
    Date.now() - _notificationReadReconcileAt < NOTIFICATION_READ_RECONCILE_MIN_GAP_MS
  ) {
    notifyTrace("read:reconcile-skip", { reason: "cooldown" });
    return false;
  }

  reconcileNotificationReadStateInFlight = Promise.race([
    (async () => {
    const normalized = String(email).toLowerCase().trim();
    await recoverSupabaseAuthSession({ retries: 1, waitMs: 4000 });
    if (!(await hasValidSupabaseAuthSession())) {
      notifyTrace("read:reconcile-skip", { reason: "no-jwt" });
      return false;
    }

    let changed = false;
    const remotePull = await fetchRemoteNotificationReadIds(normalized);
    const remoteSet = new Set(
      Array.isArray(remotePull) ? remotePull.map((id) => String(id || "").trim()).filter(Boolean) : []
    );
    if (remotePull === null) {
      notifyTrace("read:reconcile-pull-fail", {});
    } else {
      changed = mergeAnnouncementReadIds(normalized, remotePull) || changed;
    }

    const localIds = Object.keys(getAnnouncementReadMap(normalized));
    const queuedIds = getQueuedReadSyncIds(normalized);
    // リモートに無いものだけ送る。毎回フル upsert すると Disk IO を食い潰す。
    // pull 失敗時はキュー分だけ再送し、既知のローカル全体は書かない。
    const candidates = remotePull === null ? queuedIds : [...new Set([...localIds, ...queuedIds])];
    const toPush = candidates.filter((id) => id && !remoteSet.has(id));
    if (toPush.length) {
      await persistNotificationReadRemoteBatchInChunks(normalized, toPush);
      const remotePull2 = await fetchRemoteNotificationReadIds(normalized);
      if (remotePull2) {
        changed = mergeAnnouncementReadIds(normalized, remotePull2) || changed;
      }
    }

    _notificationReadReconcileAt = Date.now();
    if (changed || force) {
      window.dispatchEvent(new CustomEvent("wavrick-announcements-changed"));
    }
    notifyTrace("read:reconcile", {
      remoteCount: remotePull?.length ?? 0,
      localCount: localIds.length,
      queuedCount: queuedIds.length,
      pushedCount: toPush.length,
      changed,
      force
    });
    return changed || force;
  })(),
    new Promise((resolve) => {
      setTimeout(() => {
        notifyTrace("read:reconcile-timeout", {});
        resolve(false);
      }, 28000);
    })
  ]).finally(() => {
    reconcileNotificationReadStateInFlight = null;
  });

  return reconcileNotificationReadStateInFlight;
}

async function syncNotificationReadStateFromRemote(force = false) {
  return reconcileNotificationReadState(force);
}

async function markNotificationReadSynced(email, notificationId) {
  const normalized = String(email || "")
    .toLowerCase()
    .trim();
  const id = String(notificationId || "").trim();
  if (!normalized || !id) return false;
  mergeAnnouncementReadIds(normalized, [id]);
  return persistNotificationReadRemote(normalized, id);
}

function isImportantNotification(n) {
  if (String(n?.text || "").startsWith("[account_suspended]")) return true;
  return normalizeAnnouncementCategory(n?.category) === "important";
}

function isUserOwnedNotificationRow(n, email) {
  const me = String(email || "").toLowerCase().trim();
  const emails = normalizeNotificationEmails(n?.targetEmails);
  if (emails.length) return emails.includes(me);
  const rid = String(n?.requestId || "").trim().toLowerCase();
  if (rid.startsWith("acct:")) return rid.slice(5) === me;
  return false;
}

function getPrunedNotificationIds(email) {
  const normalized = String(email || "").toLowerCase().trim();
  if (!normalized) return {};
  try {
    const map = JSON.parse(localStorage.getItem(PRUNED_NOTIFICATION_IDS_KEY) || "{}");
    const entry = map[normalized];
    return entry && typeof entry === "object" ? entry : {};
  } catch {
    return {};
  }
}

function addPrunedNotificationIds(email, ids) {
  const normalized = String(email || "").toLowerCase().trim();
  if (!normalized || !ids?.length) return;
  try {
    const map = JSON.parse(localStorage.getItem(PRUNED_NOTIFICATION_IDS_KEY) || "{}");
    const prev = map[normalized] && typeof map[normalized] === "object" ? map[normalized] : {};
    for (const id of ids) {
      const key = String(id || "").trim();
      if (key) prev[key] = true;
    }
    const keys = Object.keys(prev);
    const trimmed = {};
    for (const key of keys.slice(-500)) trimmed[key] = true;
    map[normalized] = trimmed;
    localStorage.setItem(PRUNED_NOTIFICATION_IDS_KEY, JSON.stringify(map));
  } catch {
    /* ignore */
  }
}

function isNotificationPrunedForUser(email, notificationId) {
  const id = String(notificationId || "").trim();
  if (!id) return false;
  return Boolean(getPrunedNotificationIds(email)[id]);
}

function isAccountScopedNotificationId(rid) {
  return String(rid || "").toLowerCase().startsWith("acct:");
}

function notificationMatchesTargetRole(n, session) {
  const target = n.targetRole || n.target_role || "all";
  if (target === "all") return true;
  if (session?.role === "admin" && target === "admin") return true;
  return sessionHasRole(session, target);
}

function getAccountNotificationsSinceMs(session) {
  if (!session || session.role === "admin") return null;
  const raw = session.accountCreatedAt || session.account_created_at || "";
  const t = Date.parse(String(raw || ""));
  if (!Number.isFinite(t)) return null;
  return t - 2 * 60 * 1000;
}

function isNotificationAfterAccountSince(n, session) {
  if (!session || session.role === "admin") return true;
  const me = String(session.email || "")
    .toLowerCase()
    .trim();
  // Welcome / identity / account-scoped auto-sends must never be hidden by a stale
  // local accountCreatedAt (common right after email-confirm signup).
  if (me) {
    const rid = String(n?.requestId || n?.requestid || "")
      .toLowerCase()
      .trim();
    if (rid === `acct:${me}`) return true;
    const emails = normalizeNotificationEmails(n?.targetEmails || n?.target_emails);
    if (emails.includes(me) && (n?.adminSent || n?.kind === "admin" || String(n?.batchId || n?.batch_id || "").startsWith("auto_"))) {
      return true;
    }
  }
  const since = getAccountNotificationsSinceMs(session);
  if (since == null) return true;
  const created = Date.parse(n?.createdAt || n?.created_at || 0);
  if (!Number.isFinite(created)) return true;
  return created >= since;
}

function pruneLocalNotificationsBeforeAccountSince(session) {
  if (!session?.email || session.role === "admin") return false;
  if (getAccountNotificationsSinceMs(session) == null) return false;
  const rows = getNotifications();
  const next = rows.filter((n) => isNotificationAfterAccountSince(n, session));
  if (next.length === rows.length) return false;
  saveNotifications(next);
  return true;
}

function isNotificationRelevantForSession(n, session, requestIds) {
  if (!session?.email) return false;
  const me = String(session.email || "")
    .toLowerCase()
    .trim();
  if (isNotificationPrunedForUser(me, n.id)) return false;
  if (!isNotificationAfterAccountSince(n, session)) return false;

  const rid = String(n.requestId || "").trim();
  // 取引を離れた声優には、その案件のお知らせを出さない（了承依頼の迷子防止）
  if (
    rid &&
    !isAccountScopedNotificationId(rid) &&
    sessionHasRole(session, "voice")
  ) {
    const talentId = resolveVoiceTalentIdForSession(
      session.role === "voice" ? session : { ...session, role: "voice" }
    );
    const req = typeof findLocalRequestById === "function" ? findLocalRequestById(rid) : null;
    if (talentId && req && voiceHasDeclinedRequest(req, talentId)) {
      return false;
    }
  }

  const emails = normalizeNotificationEmails(n.targetEmails || n.target_emails);
  if (emails.length) return emails.includes(me);
  if (!notificationMatchesTargetRole(n, session)) return false;

  if (!rid) return true;
  if (isAccountScopedNotificationId(rid)) {
    return rid.slice(5).toLowerCase().trim() === me;
  }
  if (session.role === "admin") return true;
  if (requestIds === null) return true;
  return requestIds instanceof Set ? requestIds.has(rid) : false;
}

async function deleteNotificationsRemote(ids) {
  const list = [...new Set((ids || []).map((id) => String(id || "").trim()).filter(Boolean))];
  if (!list.length || !isSupabaseEnabled()) return;
  // DELETE on notifications_public is admin-only; regular users prune locally instead.
  if (!sessionHasRole(getCurrentSession(), "admin")) return;
  initSupabaseClient();
  if (!supabaseClient) return;
  for (const id of list) {
    await supabaseClient.from(TABLES.notifications).delete().eq("id", id);
  }
}

async function enforceNotificationRetentionForSession(session, requestIds) {
  if (!session?.email) return;
  const email = session.email.toLowerCase().trim();
  let ids = requestIds;
  if (ids === undefined) {
    if (session.role === "admin") {
      ids = null;
    } else if (typeof getVisibleRequestsForCurrentSession === "function") {
      const rows = await getVisibleRequestsForCurrentSession();
      ids = new Set(rows.map((r) => r.requestId).filter(Boolean));
    } else {
      ids = new Set();
    }
  }

  const all = getNotifications();
  const relevant = all.filter((n) => isNotificationRelevantForSession(n, session, ids));
  const regular = relevant
    .filter((n) => !isImportantNotification(n))
    .sort((a, b) => new Date(a.createdAt || 0) - new Date(b.createdAt || 0));

  if (regular.length <= NOTIFICATION_USER_RETENTION_MAX) return;

  const excess = regular.slice(0, regular.length - NOTIFICATION_USER_RETENTION_MAX);
  const toDeleteGlobal = [];
  const toPruneLocal = [];

  const isAdmin = sessionHasRole(session, "admin");
  for (const n of excess) {
    if (isAdmin && isUserOwnedNotificationRow(n, email)) toDeleteGlobal.push(n.id);
    else toPruneLocal.push(n.id);
  }

  // Pruned ids persist per user, so a re-fetch will not resurrect them on other devices.
  if (toPruneLocal.length) {
    addPrunedNotificationIds(email, toPruneLocal);
    const pruneSet = new Set(toPruneLocal);
    saveNotifications(all.filter((n) => !pruneSet.has(n.id)));
  }
  if (toDeleteGlobal.length) {
    const removeSet = new Set(toDeleteGlobal);
    saveNotifications(getNotifications().filter((n) => !removeSet.has(n.id)));
    void deleteNotificationsRemote(toDeleteGlobal);
  }
  if (toPruneLocal.length || toDeleteGlobal.length) {
    window.dispatchEvent(new CustomEvent("wavrick-announcements-changed"));
  }
}

function trimNotificationsGlobalStorage(rows) {
  if (!Array.isArray(rows) || rows.length <= NOTIFICATION_GLOBAL_STORAGE_MAX) return rows;
  return [...rows]
    .sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0))
    .slice(0, NOTIFICATION_GLOBAL_STORAGE_MAX);
}

function getRequestDedupeKey(row) {
  return `${(row.email || "").toLowerCase().trim()}|${(row.videoUrl || "").trim()}`;
}

function parseCastMetaFromScript(script) {
  const raw = String(script || "");
  const match = raw.match(/---\s*WAVRICK_CAST\s*---\s*([\s\S]*?)\s*---/i);
  if (!match) return null;
  try {
    const parsed = JSON.parse(match[1].trim());
    if (parsed && Array.isArray(parsed.castSlots)) return parsed;
  } catch {
    /* ignore */
  }
  return null;
}

function getVoiceProfilesMerged() {
  const localProfiles = filterProfilesForDisplay(
    JSON.parse(localStorage.getItem("wavrick_voice_profiles") || "[]")
  );
  return [
    ...getMockTalentsForDisplay(),
    ...localProfiles,
    ...filterProfilesForDisplay(remoteVoiceProfiles)
  ];
}

function resolveVoiceTalentIdForSession(session) {
  if (!session) return "";
  if (session.role !== "voice" && !sessionHasRole(session, "voice")) return "";
  if (session.talentId) return String(session.talentId);
  const email = (session.email || "").toLowerCase().trim();
  if (email) {
    const profiles = getVoiceProfilesMerged();
    const profile = profiles.find((p) => (p.email || "").toLowerCase().trim() === email);
    if (profile) return getTalentId(profile);
    return `voice:${email}`;
  }
  const selected = JSON.parse(localStorage.getItem("wavrick_selected_talent") || "null");
  if (selected?.talentId) return String(selected.talentId);
  return "";
}

function getVoiceIsActive(session) {
  if (!session || session.role !== "voice") return true;
  if (session.isActive === true) return true;
  if (session.isActive === false) return false;
  const email = (session.email || "").toLowerCase().trim();
  const talentId = resolveVoiceTalentIdForSession(session);
  const profiles = getVoiceProfilesMerged();
  const profile =
    (talentId ? profiles.find((p) => getTalentId(p) === talentId) : null) ||
    (email ? profiles.find((p) => (p.email || "").toLowerCase().trim() === email) : null);
  if (profile) return profile.isActive === true;
  return false;
}

function getVoiceProfileForSession(session) {
  if (!session || session.role !== "voice") return null;
  const email = (session.email || "").toLowerCase().trim();
  const talentId = resolveVoiceTalentIdForSession(session);
  const profiles = getVoiceProfilesMerged();
  return (
    (talentId ? profiles.find((p) => getTalentId(p) === talentId) : null) ||
    (email ? profiles.find((p) => (p.email || "").toLowerCase().trim() === email) : null) ||
    null
  );
}

function isCurrentVoiceIdentityVerified(session) {
  const profile = getVoiceProfileForSession(session);
  if (globalThis.WavrickStripeConnect?.isProfileVerified) {
    return WavrickStripeConnect.isProfileVerified(profile);
  }
  return profile?.stripeIdentityVerified === true;
}

function syncVoiceRecruitToggleUi(session) {
  if (!session || session.role !== "voice") return;
  const toggle = document.getElementById("voiceActiveToggle");
  const statusText = document.getElementById("voiceActiveStatusText");
  const toggleCard = document.getElementById("voiceActiveToggleCard");
  const Restriction = globalThis.WavrickAccountRestriction;
  const suspended = Restriction?.isSessionSuspended?.(session);
  const active = suspended ? false : getVoiceIsActive(session);
  const verified = isCurrentVoiceIdentityVerified(session);
  const canToggle = verified && !suspended;

  if (toggle) {
    toggle.checked = active;
    toggle.disabled = !canToggle;
    toggle.setAttribute("aria-disabled", canToggle ? "false" : "true");
    if (toggle.dataset.bound !== "1") {
      toggle.dataset.bound = "1";
      toggle.addEventListener("change", () => {
        const current = getCurrentSession();
        if (
          Restriction?.isSessionSuspended?.(current) ||
          !isCurrentVoiceIdentityVerified(current)
        ) {
          toggle.checked = getVoiceIsActive(current);
          syncVoiceRecruitToggleUi(current);
          return;
        }
        setVoiceIsActive(toggle.checked);
        syncVoiceRecruitToggleUi(getCurrentSession());
        syncMainNav();
      });
    }
  }
  if (statusText) {
    statusText.textContent = active
      ? t("account.voice_status_recruiting")
      : t("account.voice_status_offline");
    statusText.className = active
      ? "voice-active-status-text voice-active-status-text--on"
      : "voice-active-status-text voice-active-status-text--off";
  }
  if (toggleCard) {
    toggleCard.classList.toggle("voice-active-toggle-card--locked", !canToggle);
    let lockHint = document.getElementById("voiceActiveToggleLockHint");
    // 本人確認未完了の案内は直下の本人確認カード側で出す。制限中のみここに表示する。
    if (suspended) {
      if (!lockHint) {
        lockHint = document.createElement("p");
        lockHint.id = "voiceActiveToggleLockHint";
        lockHint.className = "voice-active-toggle-lock-hint";
        toggleCard.appendChild(lockHint);
      }
      lockHint.textContent = t("account.voice_recruit_locked_suspended");
      lockHint.hidden = false;
    } else if (lockHint) {
      lockHint.hidden = true;
    }
  }
}

function setVoiceIsActive(active) {
  const session = getCurrentSession();
  if (!session || session.role !== "voice") return;
  const Restriction = globalThis.WavrickAccountRestriction;
  if (active && Restriction?.isSessionSuspended?.(session)) return;
  if (active && !isCurrentVoiceIdentityVerified(session)) return;
  const email = (session.email || "").toLowerCase().trim();
  if (!email) return;

  session.isActive = active;
  localStorage.setItem("wavrick_session", JSON.stringify(session));

  const profiles = JSON.parse(localStorage.getItem("wavrick_voice_profiles") || "[]");
  const idx = profiles.findIndex((p) => (p.email || "").toLowerCase().trim() === email);
  if (idx >= 0) {
    profiles[idx].isActive = active;
    localStorage.setItem("wavrick_voice_profiles", JSON.stringify(profiles));
  }

  if (isMockDataEnabled()) {
    for (const m of mockTalents) {
      if ((m.email || "").toLowerCase().trim() === email) {
        m.isActive = active;
      }
    }
  }

  if (isSupabaseEnabled() && supabaseClient) {
    supabaseClient
      .from(TABLES.voiceProfiles)
      .update({ is_active: active })
      .ilike("email", email)
      .then(({ error }) => {
        if (error) console.warn("[wavrick] setVoiceIsActive remote update failed", error);
      });
  }

  syncMainNav();
  renderTalents();
}

function isProfileActive(profile) {
  return profile?.isActive === true;
}

function parseSelectedTalentIds(value) {
  return String(value || "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
}

function getTransactionApi() {
  return globalThis.WavrickTransaction || null;
}

function getWorkflowCastSlots(request, wf) {
  if (wf?.castAcceptance?.length) return wf.castAcceptance;
  return getCastSlotsForRequest(request);
}

/** この案件で声優が「受けない」を選んだか（お知らせからの再オープン判定用） */
function voiceHasDeclinedRequest(request, talentId) {
  if (!talentId || !request) return false;
  const wf = getWorkflowForRequest(request.requestId, request.status, request);
  const slots = getWorkflowCastSlots(request, wf);
  const Tx = getTransactionApi();
  if (Tx?.talentDeclinedThisJob) {
    return Tx.talentDeclinedThisJob(slots, talentId);
  }
  const declined = Tx?.SLOT_STATUS?.declined || "declined";
  const declinedByTalent = Tx?.APP_STATUS?.declined_by_talent || "declined_by_talent";
  return slots.some((s) => {
    if (!s) return false;
    if ((s.declinedTalentIds || []).some((id) => talentIdsEqual(id, talentId))) return true;
    if (talentIdsEqual(s?.talentId, talentId) && String(s?.status || "") === String(declined)) {
      return true;
    }
    return (s.applications || []).some(
      (a) =>
        talentIdsEqual(a?.talentId, talentId) &&
        String(a?.status || "") === String(declinedByTalent)
    );
  });
}

/** 話者枠に talentId が載っているか（応募のみ・通知のみ・辞退済みは含めない） */
function requestHasSpeakerAccountForVoice(request, talentId) {
  if (!talentId || !request) return false;
  const wf = getWorkflowForRequest(request.requestId, request.status, request);
  const slots = getWorkflowCastSlots(request, wf);
  const Tx = getTransactionApi();
  // 辞退済みは案件管理・詳細とも触れない
  if (voiceHasDeclinedRequest(request, talentId)) return false;
  const declined = Tx?.SLOT_STATUS?.declined || "declined";
  const pending = Tx?.SLOT_STATUS?.pending_acceptance || "pending_acceptance";
  const selected = Tx?.APP_STATUS?.selected || "selected";
  const isActiveCastSlot = (s) =>
    talentIdsEqual(s?.talentId, talentId) && String(s?.status || "") !== String(declined);
  // cast_acceptance があるときはそれを正とする（辞退後は案件管理から消す）
  if (Array.isArray(wf?.castAcceptance) && wf.castAcceptance.length) {
    if (slots.some(isActiveCastSlot)) return true;
    // 依頼済み・未回答: talentId 未同期でも選定済み応募なら案件管理に出す
    return slots.some(
      (s) =>
        String(s?.status || "") === String(pending) &&
        (s.applications || []).some(
          (a) =>
            talentIdsEqual(a?.talentId, talentId) &&
            String(a?.status || "") === String(selected)
        )
    );
  }
  if (slots.some(isActiveCastSlot)) return true;
  const ids = parseSelectedTalentIds(request.selectedTalentId);
  if (ids.some((id) => talentIdsEqual(id, talentId))) return true;
  if (Array.isArray(request.castSlots) && request.castSlots.some((s) => talentIdsEqual(s?.talentId, talentId))) {
    return true;
  }
  const cast = parseCastMetaFromScript(request.script);
  if (cast?.castSlots?.some((s) => talentIdsEqual(s?.talentId, talentId))) return true;
  return false;
}

/** 応募関与を含む（収録以外の広い判定用）。案件管理の一覧には使わない */
function requestAssignedToVoice(request, talentId) {
  if (!talentId) return false;
  const wf = getWorkflowForRequest(request.requestId, request.status, request);
  const Tx = getTransactionApi();
  if (wf?.castAcceptance?.length && Tx) {
    if (Tx.voiceIsInvolvedInCase(wf.castAcceptance, talentId)) return true;
  }
  return requestHasSpeakerAccountForVoice(request, talentId);
}

function requestHasOpenRecruitmentForVoice(request, talentId) {
  const wf = getWorkflowForRequest(request.requestId, request.status, request);
  const Tx = getTransactionApi();
  if (!wf?.castAcceptance?.length || !Tx) return false;
  const customerEmail = (request?.email || "").toLowerCase().trim();
  const B = getTalentBlocksApi();
  if (customerEmail && B?.isBlockedBetween(customerEmail, talentId)) return false;
  return Tx.getOpenRecruitSlots(wf.castAcceptance).some((slot) =>
    Tx.canTalentApplyToSlot(slot, talentId)
  );
}

function getVoiceSpeakerSlotsForRequest(request, talentId) {
  const wf = getWorkflowForRequest(request.requestId, request.status, request);
  const slots = getWorkflowCastSlots(request, wf);
  if (!slots.length) return [];
  const direct = slots.filter((s) => talentIdsEqual(s.talentId, talentId));
  if (direct.length) return direct;
  const Tx = getTransactionApi();
  const pending = Tx?.SLOT_STATUS?.pending_acceptance || "pending_acceptance";
  const selected = Tx?.APP_STATUS?.selected || "selected";
  return slots.filter(
    (slot) =>
      String(slot?.status || "") === String(pending) &&
      (slot?.applications || []).some(
        (application) =>
          talentIdsEqual(application?.talentId, talentId) &&
          String(application?.status || "") === String(selected)
      )
  );
}

function unwrapRemoteFetchRows(result) {
  if (Array.isArray(result)) return result;
  if (result && result.ok === true && Array.isArray(result.rows)) return result.rows;
  return null;
}

async function getMergedYoutubeRequests(options = {}) {
  const local = JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]");
  if (options.localOnly || !isSupabaseEnabled()) {
    return mergeYoutubeRequestRows(local, []).sort((a, b) => requestRowTimestamp(b) - requestRowTimestamp(a));
  }
  const remoteResult = await fetchRemoteYoutubeRequests();
  const remoteRows = unwrapRemoteFetchRows(remoteResult);
  // Auth/fetch failure: keep local only — never treat as "cloud returned empty".
  return mergeYoutubeRequestRows(local, remoteRows || []).sort(
    (a, b) => requestRowTimestamp(b) - requestRowTimestamp(a)
  );
}

function getWorkSelectedRequestId() {
  return sessionStorage.getItem(WORK_SELECTED_REQUEST_KEY) || localStorage.getItem(WORK_SELECTED_REQUEST_KEY) || "";
}

function setWorkSelectedRequestId(requestId) {
  if (!requestId) return;
  sessionStorage.setItem(WORK_SELECTED_REQUEST_KEY, requestId);
  localStorage.setItem(WORK_SELECTED_REQUEST_KEY, requestId);
  const session = getCurrentSession();
  const Cloud = getCloudApi();
  if (!session?.email || !Cloud) return;
  // hydrate より先にローカル prefs を更新し、古い workSelectedRequestId で上書きされないようにする
  if (typeof Cloud.patchLocalPreferences === "function") {
    Cloud.patchLocalPreferences(session.email, {
      workSelectedRequestId: requestId,
      _cloudUpdatedAt: new Date().toISOString()
    });
  }
  if (typeof Cloud.scheduleSaveUserPreferences === "function") {
    Cloud.scheduleSaveUserPreferences(session.email, { workSelectedRequestId: requestId });
  }
}

function requestRowTimestamp(row) {
  return new Date(row?.updatedAt || row?.createdAt || 0).getTime();
}

function mergeYoutubeRequestFields(prev, next) {
  const merged = { ...(prev || {}), ...(next || {}) };
  const preferPrev = (key) => {
    const n = merged[key];
    const p = prev?.[key];
    if (Array.isArray(n) && n.length) return;
    if (n != null && n !== "") return;
    if (p == null || p === "") return;
    merged[key] = p;
  };
  preferPrev("script");
  preferPrev("videoUrl");
  preferPrev("rawAudioUrl");
  preferPrev("cleanedAudioUrl");
  preferPrev("transcriptPlain");
  preferPrev("whisperDurationSec");
  preferPrev("transcribeJobId");
  preferPrev("speakerCount");
  preferPrev("sourceMode");
  preferPrev("confirmedDeliverables");
  preferPrev("quoteBreakdown");
  // rowId (youtube_requests.id) は空文字で上書きしない。欠けると UUID 側 workflow を見失う。
  {
    const candidates = [merged.rowId, next?.rowId, prev?.rowId, merged.id, next?.id, prev?.id];
    const uuid = candidates
      .map((v) => String(v || "").trim())
      .find((v) => isWorkflowAliasUuid(v));
    if (uuid) {
      merged.rowId = uuid;
      if (!merged.id) merged.id = uuid;
    } else {
      preferPrev("rowId");
    }
  }
  preferPrev("email");
  preferPrev("name");
  if (Array.isArray(prev?.castSlots) && prev.castSlots.length) {
    if (!Array.isArray(merged.castSlots) || !merged.castSlots.length) {
      merged.castSlots = prev.castSlots;
    }
  }
  if (Array.isArray(prev?.whisperSegments) && prev.whisperSegments.length) {
    if (!Array.isArray(merged.whisperSegments) || !merged.whisperSegments.length) {
      merged.whisperSegments = prev.whisperSegments;
    }
  }
  const prevMap = normalizeScriptsBySpeakerMap(prev?.scriptsBySpeaker);
  const nextMap = normalizeScriptsBySpeakerMap(merged.scriptsBySpeaker);
  if (Object.keys(prevMap).length) {
    merged.scriptsBySpeaker =
      Object.keys(nextMap).length > Object.keys(prevMap).length
        ? { ...prevMap, ...nextMap }
        : { ...nextMap, ...prevMap };
  }
  return merged;
}

function mergeYoutubeRequestRows(localRows, remoteRows) {
  const map = new Map();
  const touch = (row) => {
    if (!row || typeof row !== "object") return;
    const requestId = row.requestId || generateRequestId();
    const key = requestId;
    const normalized = { ...row, requestId };
    const prev = map.get(key);
    if (!prev) {
      map.set(key, normalized);
      return;
    }
    const newer =
      requestRowTimestamp(normalized) >= requestRowTimestamp(prev) ? normalized : prev;
    const older = newer === normalized ? prev : normalized;
    map.set(key, mergeYoutubeRequestFields(older, newer));
  };
  for (const row of Array.isArray(localRows) ? localRows : []) touch(row);
  for (const row of Array.isArray(remoteRows) ? remoteRows : []) touch(row);
  return [...map.values()].sort((a, b) => requestRowTimestamp(b) - requestRowTimestamp(a));
}

function upsertLocalYoutubeRequests(rows) {
  const merged = mergeYoutubeRequestRows(rows, []);
  localStorage.setItem("wavrick_youtube_requests", JSON.stringify(merged));
  return merged;
}

function upsertLocalYoutubeRequest(row) {
  const local = JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]");
  const merged = mergeYoutubeRequestRows(local, [row]);
  localStorage.setItem("wavrick_youtube_requests", JSON.stringify(merged));
  return row;
}

async function persistYoutubeRequestToCloud(row) {
  if (!row?.requestId) return { ok: false, reason: "no_request_id" };
  const requestId = String(row.requestId || "").trim();
  const Cloud = globalThis.WavrickYoutubeRequestCloud;
  if (Cloud?.isPermanentlyFailed?.(requestId)) {
    return { ok: false, permanent: true, reason: "permanently_failed" };
  }
  const payload = {
    ...row,
    updatedAt: row.updatedAt || row.createdAt || new Date().toISOString()
  };
  upsertLocalYoutubeRequest(payload);
  if (Cloud?.persistRequest) {
    if (!isSupabaseEnabled()) {
      return allowLocalOnlyPersistence()
        ? { ok: true, localOnly: true }
        : { ok: false, reason: "cloud_required" };
    }
    return Cloud.persistRequest(payload);
  }
  if (!isSupabaseEnabled()) {
    return allowLocalOnlyPersistence()
      ? { ok: true, localOnly: true }
      : { ok: false, reason: "cloud_required" };
  }
  return upsertRemote(
    TABLES.youtubeRequests,
    mapYoutubeRequestToRemote(payload),
    "requestid"
  );
}

async function pushLocalYtDraftsToCloud(email) {
  const D = getYtDraftsApi();
  if (!D || !isSupabaseEnabled() || !email) return;
  const normalized = String(email).toLowerCase().trim();
  for (const draft of D.listLocal(normalized)) {
    if (!draft?.draftId) continue;
    await D.upsertRemote(supabaseClient, draft);
  }
}

async function hydrateAccountRecords(session) {
  if (!session?.email || !isSupabaseEnabled()) return;
  const email = session.email.toLowerCase().trim();

  if (session.role === "customer" || session.role === "admin") {
    const remote = await findRemoteAccount("customer", email);
    if (remote) {
      upsertLocalByEmail("wavrick_customer_accounts", mapCustomerAccountFromRemote(remote));
    }
  }

  if (session.role === "voice" || session.role === "admin") {
    const remote = await findRemoteAccount("voice", email);
    if (remote) {
      upsertLocalByEmail("wavrick_voice_accounts", mapVoiceAccountFromRemote(remote));
    }
    const profiles = await fetchRemoteVoiceProfiles();
    const mine = profiles.find((p) => (p.email || "").toLowerCase().trim() === email);
    if (mine) {
      const local = JSON.parse(localStorage.getItem("wavrick_voice_profiles") || "[]");
      const idx = local.findIndex((p) => (p.email || "").toLowerCase().trim() === email);
      const next = idx >= 0 ? { ...local[idx], ...mine } : mine;
      if (idx >= 0) local[idx] = next;
      else local.push(next);
      localStorage.setItem("wavrick_voice_profiles", JSON.stringify(local));
    }
  }
}

async function pushAccountRecordsToCloud(session) {
  if (!session?.email || !isSupabaseEnabled()) return;
  const email = session.email.toLowerCase().trim();

  if (session.role === "customer") {
    const account = findCustomerAccountByEmail(email);
    if (account) {
      const existing = await findRemoteAccount("customer", email);
      const remotePayload = mapCustomerAccountToRemote(account);
      if (existing) {
        await supabaseClient.from(TABLES.customerAccounts).update(remotePayload).ilike("email", email);
      } else {
        const result = await insertRemote(TABLES.customerAccounts, remotePayload);
        if (!result.ok && isPgDuplicateError(result.error)) {
          await supabaseClient.from(TABLES.customerAccounts).update(remotePayload).ilike("email", email);
        }
      }
    }
  }

  if (session.role === "voice") {
    const accounts = JSON.parse(localStorage.getItem("wavrick_voice_accounts") || "[]");
    const account = accounts.find((row) => (row.email || "").toLowerCase().trim() === email);
    if (account) {
      const existing = await findRemoteAccount("voice", email);
      const remotePayload = mapVoiceAccountToRemote(account);
      if (existing) {
        await supabaseClient.from(TABLES.voiceAccounts).update(remotePayload).ilike("email", email);
      } else {
        const result = await insertRemote(TABLES.voiceAccounts, remotePayload);
        if (!result.ok && isPgDuplicateError(result.error)) {
          await supabaseClient.from(TABLES.voiceAccounts).update(remotePayload).ilike("email", email);
        }
      }
    }
    await pushVoiceProfileToCloud(email);
  }
}

async function pushLocalWorkDataToCloud(session, options = {}) {
  if (!isSupabaseEnabled() || !session?.email) return;
  const email = session.email.toLowerCase().trim();
  const localRequests = JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]");
  const skipWorkflows = Boolean(options.skipWorkflows);
  const Cloud = globalThis.WavrickYoutubeRequestCloud;

  if (session.role === "customer" || session.role === "admin") {
    for (const row of localRequests) {
      if (!row?.requestId) continue;
      const requestId = String(row.requestId || "").trim();
      if (Cloud?.isPermanentlyFailed?.(requestId)) continue;
      const rowEmail = String(row.email || "").toLowerCase().trim();
      // Customers only push their own rows. Admin may push any (RLS still enforces).
      if (session.role === "customer") {
        if (rowEmail && rowEmail !== email) continue;
        if (!rowEmail) {
          // Fill owner email before persist so RLS insert check can pass.
          row.email = email;
        }
      }
      const result = await persistYoutubeRequestToCloud(row);
      if (result?.permanent) {
        console.warn("[wavrick] skip permanent youtube persist fail", requestId, result.reason);
      }
    }
  }

  if (skipWorkflows) {
    await pushLocalNotificationsToCloud(session);
    await pushAccountRecordsToCloud(session);
    if (session.role === "customer") {
      await pushLocalYtDraftsToCloud(session.email);
    }
    return;
  }

  const workflows = getWorkflows();
  const pushedCases = new Set();
  for (const wf of Object.values(workflows)) {
    if (!wf?.requestId) continue;
    const req =
      localRequests.find(
        (r) =>
          r.requestId === wf.requestId ||
          r.rowId === wf.requestId ||
          String(r.id || "") === wf.requestId
      ) || null;
    if (session.role === "customer") {
      if (req && (req.email || "").toLowerCase().trim() !== email) continue;
      if (!req) continue;
    }
    if (session.role === "voice") {
      // 声優の定期 sync で workflow 全体を upsert すると、顧客決済済み状態を unpaid で上書きする。
      // 声優の cast 更新は saveWorkflowAliases / patchRemoteWorkflowCastFields 経由のみ。
      continue;
    }
    const caseKey = String(req?.requestId || wf.requestId || "").trim();
    if (!caseKey || pushedCases.has(caseKey)) continue;
    pushedCases.add(caseKey);
    const merged = getWorkflowForRequest(caseKey, req?.status, req || undefined);
    await upsertWorkflowRemoteSafe(merged, req || caseKey);
  }

  await pushLocalNotificationsToCloud(session);

  await pushAccountRecordsToCloud(session);
  if (session.role === "customer") {
    await pushLocalYtDraftsToCloud(session.email);
  }
}

function isRlsOrPermissionError(error) {
  if (!error) return false;
  const code = String(error.code || error.status || "");
  const msg = String(error.message || error.error_description || error || "").toLowerCase();
  return (
    code === "42501" ||
    code === "PGRST301" ||
    msg.includes("row-level security") ||
    msg.includes("permission denied") ||
    msg.includes("42501")
  );
}

function loadNotificationCloudIdSet(key) {
  try {
    const raw = localStorage.getItem(key);
    const list = raw ? JSON.parse(raw) : [];
    return new Set(Array.isArray(list) ? list.map(String).filter(Boolean) : []);
  } catch {
    return new Set();
  }
}

function saveNotificationCloudIdSet(key, idSet) {
  try {
    const list = [...idSet].slice(-NOTIFICATION_CLOUD_ID_SET_MAX);
    localStorage.setItem(key, JSON.stringify(list));
  } catch {
    /* ignore quota */
  }
}

function markNotificationCloudPending(id) {
  const nid = String(id || "").trim();
  if (!nid) return;
  const blocked = loadNotificationCloudIdSet(NOTIFICATION_CLOUD_BLOCKED_KEY);
  if (blocked.has(nid)) return;
  const pending = loadNotificationCloudIdSet(NOTIFICATION_CLOUD_PENDING_KEY);
  pending.add(nid);
  saveNotificationCloudIdSet(NOTIFICATION_CLOUD_PENDING_KEY, pending);
}

function markNotificationCloudOk(id) {
  const nid = String(id || "").trim();
  if (!nid) return;
  const pending = loadNotificationCloudIdSet(NOTIFICATION_CLOUD_PENDING_KEY);
  if (pending.delete(nid)) {
    saveNotificationCloudIdSet(NOTIFICATION_CLOUD_PENDING_KEY, pending);
  }
}

function markNotificationCloudBlocked(id) {
  const nid = String(id || "").trim();
  if (!nid) return;
  const pending = loadNotificationCloudIdSet(NOTIFICATION_CLOUD_PENDING_KEY);
  if (pending.delete(nid)) {
    saveNotificationCloudIdSet(NOTIFICATION_CLOUD_PENDING_KEY, pending);
  }
  const blocked = loadNotificationCloudIdSet(NOTIFICATION_CLOUD_BLOCKED_KEY);
  blocked.add(nid);
  saveNotificationCloudIdSet(NOTIFICATION_CLOUD_BLOCKED_KEY, blocked);
}

/**
 * Re-upload only notifications this session authored and that are still pending.
 * Received rows (admin announcements, other users' targets) are read-only —
 * pushing them back is rejected by RLS (UPDATE is admin-only) and used to
 * spam notifications_public on every cloud refresh.
 */
async function pushLocalNotificationsToCloud(session) {
  if (!isSupabaseEnabled() || !session?.email) return;
  const isAdmin = sessionHasRole(session, "admin") || session.role === "admin";
  const pending = loadNotificationCloudIdSet(NOTIFICATION_CLOUD_PENDING_KEY);
  const blocked = loadNotificationCloudIdSet(NOTIFICATION_CLOUD_BLOCKED_KEY);
  if (!pending.size) return;
  const rows = getNotifications().filter((n) => {
    if (!n?.id || !pending.has(n.id) || blocked.has(n.id)) return false;
    if (isAdmin) return true;
    if (n.adminSent || n.kind === "admin") return false;
    return Boolean(String(n.requestId || "").trim());
  });
  for (const n of rows) {
    const result = await upsertRemote(TABLES.notifications, mapNotificationToRemote(n), "id");
    if (result.ok) {
      markNotificationCloudOk(n.id);
    } else if (isRlsOrPermissionError(result.error)) {
      markNotificationCloudBlocked(n.id);
      notifyTrace("push-local:rls-block", { id: n.id, error: result.error });
    }
  }
}

async function refreshTalentStatsFromRemote(profiles) {
  const TS = globalThis.WavrickTalentStats;
  if (!TS?.refreshFromRemote || !isSupabaseEnabled()) return false;
  initSupabaseClient();
  const Gate = globalThis.WavrickAuthGate;
  if (Gate?.ensureCloudAuth) {
    const auth = await Gate.ensureCloudAuth(8000);
    if (!auth.ok && !auth.guest) return false;
  } else if (!(await hasValidSupabaseAuthSession())) {
    return false;
  }
  const list = profiles || loadVoiceProfiles();
  const ids = list.map((p) => getTalentId(p)).filter(Boolean);
  if (!ids.length) return false;
  return TS.refreshFromRemote(ids);
}

function refreshTalentStatsUi() {
  renderTalents({ skipStatsRefresh: true });
  const session = getCurrentSession();
  if (session?.role === "voice") {
    const mypageStats = document.getElementById("voiceMypageStats");
    if (mypageStats) {
      const TS = globalThis.WavrickTalentStats;
      const talentId = resolveVoiceTalentIdForSession(session);
      mypageStats.innerHTML = TS ? TS.renderDetailedStatsHtml(TS.getTalentStats(talentId)) : "";
    }
  }
  if (talentModalProfile) openTalentProfileModal(talentModalProfile);
}

const ALIAS_HEAL_COOLDOWN_MS = 6 * 60 * 60 * 1000;
const ALIAS_HEAL_AT_KEY = "wavrick_alias_heal_at";

/**
 * 分裂した別名行（UUID 側に決済、req_* 側に納品 など）の修復。
 * 全案件ぶんの単発 SELECT を撃つので、ログイン直後など明示的な呼び出しだけに限定する。
 */
async function healWorkflowAliasPairs(requests = null, options = {}) {
  const Sync = globalThis.WavrickWorkflowSync;
  const session = getCurrentSession();
  if (!Sync?.healAliasPairs || !session?.email || !isSupabaseEnabled()) {
    return { ok: false, healed: 0, reason: "unavailable" };
  }
  if (!options.force) {
    const last = Number(localStorage.getItem(ALIAS_HEAL_AT_KEY) || 0);
    if (Number.isFinite(last) && Date.now() - last < ALIAS_HEAL_COOLDOWN_MS) {
      return { ok: true, healed: 0, reason: "cooldown" };
    }
  }
  try {
    localStorage.setItem(ALIAS_HEAL_AT_KEY, String(Date.now()));
  } catch {
    /* ignore */
  }
  try {
    const rows = Array.isArray(requests) ? requests : getLocalYoutubeRequests();
    const heal = await Sync.healAliasPairs(rows, { client: supabaseClient, skipAuth: true });
    if (!(heal?.healed > 0)) return { ok: true, healed: 0 };
    console.info("[wavrick] healed workflow alias pairs", heal.healed, options.reason || "");
    const refreshed = await fetchRemoteWorkflows();
    if (refreshed?.ok) {
      const localWf = getWorkflows();
      for (const wf of refreshed.rows || []) {
        if (!wf.requestId) continue;
        localWf[wf.requestId] = mergeWorkflowPair(localWf[wf.requestId], wf) || wf;
      }
      persistWorkflowsLocalStorage(localWf);
      syncWorkflowAliasesIntoStore(rows);
    }
    return { ok: true, healed: heal.healed };
  } catch (err) {
    console.warn("[wavrick] workflow alias heal failed", err);
    return { ok: false, healed: 0, error: err };
  }
}

async function hydrateRemoteWorkData(options = {}) {
  if (!isSupabaseEnabled()) return { ok: false, reason: "disabled" };

  const session = getCurrentSession();
  const Gate = globalThis.WavrickAuthGate;
  if (session?.email) {
    if (Gate) {
      const auth = await Gate.ensureCloudAuth(options.authWaitMs || 8000);
      if (!auth.ok) {
        console.warn("[wavrick] hydrateRemoteWorkData skipped — auth not ready", auth.reason);
        return { ok: false, reason: auth.reason || "no_jwt", auth };
      }
    } else {
      const hasJwt = await ensureSupabaseAuthForLocalSession();
      if (!hasJwt) {
        console.warn("[wavrick] hydrateRemoteWorkData skipped — no JWT");
        return { ok: false, reason: "no_jwt" };
      }
    }
  }

  const requestsResult = await fetchRemoteYoutubeRequests();
  let workflowsResult = await fetchRemoteWorkflows();
  const requestsOk = Boolean(requestsResult?.ok);
  let workflowsOk = Boolean(workflowsResult?.ok);

  if (!requestsOk && !workflowsOk) {
    console.warn("[wavrick] hydrateRemoteWorkData fetch failed", {
      requests: requestsResult?.reason,
      workflows: workflowsResult?.reason
    });
    return {
      ok: false,
      reason: requestsResult?.reason || workflowsResult?.reason || "fetch_failed",
      requestsResult,
      workflowsResult
    };
  }

  let mergedRequests = JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]");
  if (requestsOk) {
    const local = mergedRequests;
    mergedRequests = mergeYoutubeRequestRows(local, requestsResult.rows || []);
    localStorage.setItem("wavrick_youtube_requests", JSON.stringify(mergedRequests));
  }

  // Voice visibility depends on castAcceptance in workflows — retry once if empty after requests landed.
  if (
    session?.role === "voice" &&
    workflowsOk &&
    Array.isArray(workflowsResult.rows) &&
    workflowsResult.rows.length === 0 &&
    requestsOk &&
    (requestsResult.rows || []).length > 0
  ) {
    await cloudSyncDelay(450);
    const retry = await fetchRemoteWorkflows();
    if (retry?.ok && Array.isArray(retry.rows) && retry.rows.length > 0) {
      workflowsResult = retry;
      workflowsOk = true;
    }
  }

  if (workflowsOk) {
    const localWf = getWorkflows();
    for (const wf of workflowsResult.rows || []) {
      if (!wf.requestId) continue;
      const prev = localWf[wf.requestId];
      let merged = mergeWorkflowPair(prev, wf) || wf;
      // 運営裁定済みを顧客端末の古い pending/disputed 表示が飲み込むのを防ぐ
      merged = preferRemoteResolvedCancel(merged, wf);
      localWf[wf.requestId] = merged;
    }
    persistWorkflowsLocalStorage(localWf);
  }
  syncWorkflowAliasesIntoStore(mergedRequests);

  // 別名行の修復は案件数 × 別名数だけ単発 SELECT を撃つ。定期 hydrate では回さない。
  if (options.healAliases) {
    await healWorkflowAliasPairs(mergedRequests, { reason: options.reason || "explicit" });
  }

  const remoteNotifications = await fetchRemoteNotifications();
  if (Array.isArray(remoteNotifications)) {
    mergeRemoteNotificationsIntoLocal(remoteNotifications);
    if (session?.email) {
      for (const n of remoteNotifications) {
        if (!n?.read || !n?.id) continue;
        if (isUserOwnedNotificationRow(n, session.email)) {
          mergeAnnouncementReadIds(session.email, [n.id]);
        }
      }
    }
  }
  await syncNotificationReadStateFromRemote();

  await refreshTalentStatsFromRemote();
  return {
    ok: true,
    requestCount: requestsOk ? (requestsResult.rows || []).length : null,
    workflowCount: workflowsOk ? (workflowsResult.rows || []).length : null
  };
}

async function hydrateAllCloudData() {
  if (!isSupabaseEnabled()) return { ok: false, reason: "disabled" };
  const session = getCurrentSession();
  const Gate = globalThis.WavrickAuthGate;
  let hasJwt = false;
  if (session?.email) {
    if (Gate) {
      const auth = await Gate.ensureCloudAuth(8000);
      hasJwt = Boolean(auth.ok);
      if (!hasJwt) {
        console.warn("[wavrick] local session without Supabase JWT — authenticated cloud sync skipped", auth.reason);
        return { ok: false, reason: auth.reason || "no_jwt" };
      }
    } else {
      hasJwt = await ensureSupabaseAuthForLocalSession();
      if (!hasJwt) {
        console.warn("[wavrick] local session without Supabase JWT — authenticated cloud sync skipped");
        return { ok: false, reason: "no_jwt" };
      }
    }
  } else {
    hasJwt = await hasValidSupabaseAuthSession();
  }

  const Cloud = getCloudApi();
  if (session?.email && hasJwt && Cloud?.hydrateUserCloudData) {
    const role =
      session.role === "voice"
        ? "voice"
        : session.role === "customer"
          ? "customer"
          : session.role === "admin"
            ? "admin"
            : "";
    const talentId = session.role === "voice" ? resolveVoiceTalentIdForSession(session) : "";
    await Cloud.hydrateUserCloudData(session.email, { role, talentId });
  }

  if (hasJwt) {
    // ブートストラップ時のみ別名修復を通す（クールダウン付き）。定期 hydrate では回さない。
    const work = await hydrateRemoteWorkData({ skipAuthWait: true, healAliases: true, reason: "bootstrap" });
    await hydrateAccountRecords(session);
    // Never re-upsert all workflows after every pull — stale local can poison the cloud.
    // Explicit saves already upsert; here only push requests/notifications/account.
    if (session) await pushLocalWorkDataToCloud(session, { skipWorkflows: true });
    return { ok: work?.ok !== false, work };
  }
  return { ok: true, guest: true };
}

async function pushVoiceProfileToCloud(email) {
  if (!isSupabaseEnabled() || !email) return;
  const normalized = email.toLowerCase().trim();
  const profiles = JSON.parse(localStorage.getItem("wavrick_voice_profiles") || "[]");
  let profile = profiles.find((p) => (p.email || "").toLowerCase().trim() === normalized);
  const pendingMedia = await loadVoicePendingMedia(normalized);
  if (pendingMedia) {
    profile = mergeVoiceProfileWithPendingMedia(profile || pendingMedia, pendingMedia);
  }
  if (!profile) return;
  const mediaUpload = await uploadVoiceProfileMediaForCloud(profile);
  if (mediaUpload.ok && mediaUpload.profile) {
    profile = mediaUpload.profile;
    upsertLocalVoiceProfile(sanitizeVoiceProfileForLocalStorage(profile));
  }
  const result = await upsertVoiceProfileRemote(profile);
  if (!result.ok && !result.skipped) {
    console.warn("[wavrick] pushVoiceProfileToCloud failed", result.reason || result.error);
  }
}

async function completeVoiceRegistration(voiceDataForSave, options = {}) {
  let mergedProfile = voiceDataForSave;
  const hasInlineMedia =
    voiceDataForSave?._avatarBlob instanceof Blob ||
    (Array.isArray(voiceDataForSave?.voiceSamples)
      ? voiceDataForSave.voiceSamples
      : parseVoiceSamplesFromStorage(voiceDataForSave?.voiceSamples ?? voiceDataForSave?.voiceSamplesJson)
    ).some((sample) => sample?.localFile instanceof Blob);
  if (!options.skipPendingMedia && !hasInlineMedia) {
    const pendingMedia = await loadVoicePendingMedia(voiceDataForSave.email);
    if (pendingMedia) {
      mergedProfile = mergeVoiceProfileWithPendingMedia(voiceDataForSave, pendingMedia);
    }
  }
  if (mergedProfile.isActive !== true) {
    mergedProfile = { ...mergedProfile, isActive: false };
  }

  let remoteProfileResult = { ok: false, skipped: true };
  let remoteAccountResult = { ok: false, skipped: true };
  if (!isSupabaseEnabled()) {
    upsertLocalVoiceProfile(sanitizeVoiceProfileForLocalStorage(mergedProfile));
    upsertLocalByEmail("wavrick_voice_accounts", {
      role: "voice",
      email: mergedProfile.email,
      displayName: mergedProfile.displayName
    });
    return { remoteProfileResult, remoteAccountResult, mergedProfile };
  }

  const authSession = await getSupabaseAuthSessionForVoiceSave(options.session || null);
  if (!authSession?.user?.email) {
    upsertLocalVoiceProfile(sanitizeVoiceProfileForLocalStorage(mergedProfile));
    upsertLocalByEmail("wavrick_voice_accounts", {
      role: "voice",
      email: mergedProfile.email,
      displayName: mergedProfile.displayName
    });
    return {
      remoteProfileResult: { ok: false, skipped: false, reason: "no_auth_session" },
      remoteAccountResult: { ok: false, skipped: false },
      mergedProfile
    };
  }

  const authEmail = authSession.user.email.toLowerCase().trim();
  const profileEmail = (mergedProfile.email || "").toLowerCase().trim();
  if (authEmail !== profileEmail) {
    return {
      remoteProfileResult: {
        ok: false,
        skipped: false,
        reason: "auth_email_mismatch",
        error: { message: "ログイン中のアカウントと登録メールが一致しません。" }
      },
      remoteAccountResult: { ok: false, skipped: false },
      mergedProfile
    };
  }

  const profileWithMedia = mergedProfile;
  let mediaUpload = await uploadVoiceProfileMediaForCloud(mergedProfile, { session: authSession });
  // Email-confirm JWT is often not Storage-ready on the first try — retry once.
  if (
    !mediaUpload.ok &&
    getVoiceProfileStorageApi()?.profileHasUploadableMedia(mergedProfile)
  ) {
    console.warn(
      "[wavrick] voice media upload failed — refreshing auth and retrying once",
      mediaUpload.error || mediaUpload.reason
    );
    await cloudSyncDelay(500);
    try {
      const { data: refreshed } = await supabaseClient.auth.refreshSession();
      if (refreshed?.session) {
        await ensureSupabaseClientUsesSession(refreshed.session);
        mediaUpload = await uploadVoiceProfileMediaForCloud(mergedProfile, {
          session: refreshed.session
        });
      }
    } catch (retryErr) {
      console.warn("[wavrick] voice media upload retry failed", retryErr);
    }
  }

  let mediaUploadDeferred = false;
  if (mediaUpload.ok && mediaUpload.profile) {
    mergedProfile = mediaUpload.profile;
  } else if (getVoiceProfileStorageApi()?.profileHasUploadableMedia(profileWithMedia)) {
    console.warn(
      "[wavrick] voice media upload failed; saving profile text now, keeping pending media for retry",
      mediaUpload.error || mediaUpload.reason
    );
    mediaUploadDeferred = true;
    // Keep blobs in IndexedDB — only strip for the remote text upsert payload.
    mergedProfile = sanitizeVoiceProfileForLocalStorage(profileWithMedia);
    try {
      await saveVoicePendingMedia(profileEmail, profileWithMedia);
    } catch (pendingErr) {
      console.warn("[wavrick] re-save pending voice media failed", pendingErr);
    }
  }

  upsertLocalVoiceProfile(sanitizeVoiceProfileForLocalStorage(mergedProfile));
  upsertLocalByEmail("wavrick_voice_accounts", {
    role: "voice",
    email: mergedProfile.email,
    displayName: mergedProfile.displayName
  });

  const email = profileEmail;
  remoteProfileResult = await upsertVoiceProfileRemote(mergedProfile);

  // First save right after email-confirm often hits RLS before JWT email is ready.
  if (!remoteProfileResult.ok && isVoiceProfileRlsError(remoteProfileResult.error)) {
    console.warn("[wavrick] voice profile save RLS — refreshing auth and retrying once");
    await cloudSyncDelay(400);
    try {
      const { data: refreshed } = await supabaseClient.auth.refreshSession();
      if (refreshed?.session) {
        await ensureSupabaseClientUsesSession(refreshed.session);
      }
    } catch {
      /* ignore */
    }
    const retriedSession = await getSupabaseAuthSessionForVoiceSave(null);
    if (retriedSession?.user?.email) {
      remoteProfileResult = await upsertVoiceProfileRemote(mergedProfile);
    }
  }

  const existingAccount = await withTimeout(findRemoteAccount("voice", email), 20000, "voice_account_lookup");
  let voiceAccountCreated = false;
  if (existingAccount) {
    remoteAccountResult = { ok: true };
  } else {
    remoteAccountResult = await insertRemote(
      TABLES.voiceAccounts,
      mapVoiceAccountToRemote({
        email: mergedProfile.email,
        displayName: mergedProfile.displayName
      })
    );
    if (remoteAccountResult.ok) {
      voiceAccountCreated = true;
    } else if (isPgDuplicateError(remoteAccountResult.error)) {
      remoteAccountResult = { ok: true };
    }
  }

  if (remoteProfileResult.ok) {
    // NEVER wipe pending media when upload was deferred — that made avatars/samples disappear.
    if (!mediaUploadDeferred) {
      await clearVoicePendingMedia(email);
      void clearVoiceSignupPendingFromCloud(email);
    } else {
      console.warn("[wavrick] keeping pending voice media for post-login retry", email);
    }
    void syncCanonicalDisplayName(mergedProfile.email, mergedProfile.displayName, "profile_save");
    // Welcome on first cloud registration only (immediate save / confirm / retry).
    // Finish-auth paths also call dispatchSignupWelcome; server dedupes.
    if (remoteProfileResult.created === true || voiceAccountCreated) {
      void dispatchSignupWelcome(
        "voice",
        email,
        mergedProfile.displayName || email.split("@")[0]
      );
    }
  } else {
    console.warn("[wavrick] voice profile remote save failed", remoteProfileResult.error);
  }
  return { remoteProfileResult, remoteAccountResult, mergedProfile, mediaUploadDeferred };
}

async function restoreSessionFromSupabaseAuth() {
  if (!isSupabaseEnabled()) return false;
  const { data, error } = await supabaseClient.auth.getSession();
  if (error || !data?.session?.user?.email) return false;

  const user = data.session.user;
  const email = user.email.toLowerCase().trim();
  const existing = getCurrentSession();
  if (existing?.email === email && existing?.role) return true;

  const { data: adminRows } = await supabaseClient
    .from(TABLES.adminUsers)
    .select("*")
    .ilike("email", email)
    .limit(1);
  if (Array.isArray(adminRows) && adminRows.length) {
    const row = adminRows[0];
    localStorage.setItem(
      "wavrick_session",
      JSON.stringify({
        role: "admin",
        roleLabel: "運営",
        email,
        displayName: row.displayname || row.display_name || "WAVRICK運営",
        prelaunchAccess: true,
        createdAt: new Date().toISOString()
      })
    );
    syncMainNav();
    return true;
  }

  const voiceRow = await findRemoteAccount("voice", email);
  if (voiceRow) {
    if (await rejectBannedLogin("voice", email)) return false;
    const account = mapVoiceAccountFromRemote(voiceRow);
    persistVoiceSession(account, email);
    await attachRestrictionToSession("voice", email, account);
    await applyPrelaunchAccessToSession();
    return true;
  }

  const { data: profileRows } = await supabaseClient
    .from(TABLES.voiceProfiles)
    .select("email, displayname, display_name, is_banned, banned_at")
    .ilike("email", email)
    .limit(1);
  if (Array.isArray(profileRows) && profileRows.length) {
    const row = profileRows[0];
    if (row.is_banned || row.banned_at) return false;
    if (await rejectBannedLogin("voice", email)) return false;
    await ensureVoiceAccountRecord({
      email,
      displayName: row.displayname || row.display_name || user.user_metadata?.displayName || email.split("@")[0]
    });
    const account = {
      email,
      displayName: row.displayname || row.display_name || user.user_metadata?.displayName || email.split("@")[0]
    };
    persistVoiceSession(account, email);
    await attachRestrictionToSession("voice", email, account);
    await applyPrelaunchAccessToSession();
    return true;
  }

  const customerRow = await findRemoteAccount("customer", email);
  const meta = user.user_metadata || {};
  if (customerRow || meta.role === "customer") {
    if (await rejectBannedLogin("customer", email)) return false;
    const account =
      (customerRow ? mapCustomerAccountFromRemote(customerRow) : null) ||
      findCustomerAccountByEmail(email) ||
      customerAccountFromAuthUser(user, email);
    await ensureCustomerAccountRecord(account);
    persistCustomerSession(account, email);
    await attachRestrictionToSession("customer", email, account);
    await applyPrelaunchAccessToSession();
    return true;
  }

  if (meta.role === "voice") {
    if (await rejectBannedLogin("voice", email)) return false;
    const account = {
      email,
      displayName: meta.displayName || email.split("@")[0]
    };
    persistVoiceSession(account, email);
    await attachRestrictionToSession("voice", email, account);
    await applyPrelaunchAccessToSession();
    return true;
  }

  return false;
}

function normalizeNotificationEmails(list) {
  if (!Array.isArray(list)) return [];
  return [
    ...new Set(
      list
        .map((email) => String(email || "").toLowerCase().trim())
        .filter(Boolean)
    )
  ];
}

function normalizeAnnouncementCategory(value) {
  const cat = String(value || "").toLowerCase().trim();
  if (cat === "maintenance" || cat === "important" || cat === "case" || cat === "system" || cat === "other") {
    return cat;
  }
  return "other";
}

function pushNotification(text, requestId, options = {}) {
  const kind = options.kind || "system";
  const targetRole = options.targetRole || "all";
  const targetEmails = normalizeNotificationEmails(options.targetEmails);
  const category = normalizeAnnouncementCategory(options.category);
  const batchId = String(options.batchId || "").trim();
  const targetMode = String(options.targetMode || "role").trim() || "role";
  const rows = getNotifications();
  const item = {
    id: options.id || `ntf_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
    text,
    requestId: requestId || "",
    kind,
    targetRole,
    targetEmails,
    category,
    batchId,
    targetMode,
    adminSent: Boolean(options.adminSent),
    read: false,
    createdAt: options.createdAt || new Date().toISOString()
  };
  rows.unshift(item);
  saveNotifications(trimNotificationsGlobalStorage(rows));
  markNotificationCloudPending(item.id);
  if (isSupabaseEnabled()) {
    void persistNotificationRemote(item).then((ok) => {
      // 失敗時に broadcast（realtime.messages INSERT）しない — RLS エラーの連鎖を防ぐ
      if (ok) void globalThis.WavrickNotificationRealtime?.signalNotificationsChanged?.();
    });
  } else {
    void globalThis.WavrickNotificationRealtime?.signalNotificationsChanged?.();
  }
  void enforceNotificationRetentionForSession(getCurrentSession(), undefined);
  window.dispatchEvent(new CustomEvent("wavrick-announcements-changed"));
  return item;
}

async function persistNotificationRemote(item) {
  if (!isSupabaseEnabled()) return false;
  if (item?.id) markNotificationCloudPending(item.id);
  await recoverSupabaseAuthSession({ retries: 2, waitMs: 5000 });
  const hasJwt = await hasValidSupabaseAuthSession();
  if (!hasJwt) {
    notifyTrace("persist:skip-no-jwt", {
      id: item?.id,
      text: String(item?.text || "").slice(0, 80)
    });
    return false;
  }
  const payload = mapNotificationToRemote(item);
  notifyTrace("persist:start", {
    id: item?.id,
    text: String(item?.text || "").slice(0, 80),
    targetRole: item?.targetRole,
    targetEmails: item?.targetEmails
  });
  let result = await upsertRemote(TABLES.notifications, payload, "id");
  if (result.ok) {
    markNotificationCloudOk(item?.id);
    notifyTrace("persist:ok", { id: item?.id });
    return true;
  }
  notifyTrace("persist:upsert-fail", { id: item?.id, error: result.error });
  // RLS はスキーマ差異ではない — legacy フォールバックを連打しない
  if (isRlsOrPermissionError(result.error)) {
    markNotificationCloudBlocked(item?.id);
    notifyTrace("persist:rls-block", { id: item?.id, error: result.error });
    return false;
  }
  // Older schemas: keep per-user privacy via acct:email when target_emails is unsupported.
  const legacy = { ...payload };
  const emails = normalizeNotificationEmails(payload.target_emails);
  if (emails.length === 1 && !String(legacy.requestid || "").startsWith("acct:")) {
    legacy.requestid = `acct:${emails[0]}`;
  }
  delete legacy.category;
  delete legacy.target_emails;
  delete legacy.batch_id;
  delete legacy.target_mode;
  result = await upsertRemote(TABLES.notifications, legacy, "id");
  if (result.ok) {
    markNotificationCloudOk(item?.id);
    notifyTrace("persist:ok-legacy", { id: item?.id });
    return true;
  }
  notifyTrace("persist:legacy-fail", { id: item?.id, error: result.error });
  if (isRlsOrPermissionError(result.error)) {
    markNotificationCloudBlocked(item?.id);
    return false;
  }
  delete legacy.target_role;
  delete legacy.admin_sent;
  result = await upsertRemote(TABLES.notifications, legacy, "id");
  if (result.ok) {
    markNotificationCloudOk(item?.id);
    return true;
  }
  notifyTrace("persist:fail", { id: item?.id, error: result.error });
  if (isRlsOrPermissionError(result.error)) {
    markNotificationCloudBlocked(item?.id);
  }
  return false;
}

function pushAdminAnnouncement(text, options = {}) {
  const category = normalizeAnnouncementCategory(options.category);
  const targetRole = options.targetRole || "all";
  const requestId = String(options.requestId || "").trim();
  const targetMode = String(options.targetMode || "role").trim() || "role";
  const targetEmails = normalizeNotificationEmails(options.targetEmails);
  const batchId =
    String(options.batchId || "").trim() ||
    `batch_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  const createdAt = new Date().toISOString();
  const stamp = Date.now();

  const buildItem = (emails, role) => ({
    id: `ntf_${stamp}_${Math.random().toString(36).slice(2, 9)}`,
    text,
    requestId,
    kind: "admin",
    targetRole: role,
    targetEmails: emails,
    category,
    batchId,
    targetMode,
    adminSent: true,
    read: false,
    createdAt
  });

  // One row per recipient so co-recipients never appear in another user's payload.
  const items = targetEmails.length
    ? targetEmails.map((email) => buildItem([email], "all"))
    : [buildItem([], targetRole)];

  const rows = getNotifications();
  for (const item of items) {
    rows.unshift(item);
    markNotificationCloudPending(item.id);
  }
  saveNotifications(trimNotificationsGlobalStorage(rows));
  void enforceNotificationRetentionForSession(getCurrentSession(), undefined);
  window.dispatchEvent(new CustomEvent("wavrick-announcements-changed"));
  return { batchId, items };
}

async function publishAdminAnnouncement(text, options = {}) {
  const result = pushAdminAnnouncement(text, options);
  if (!isSupabaseEnabled() || !result.items?.length) {
    return { ...result, cloudOk: true };
  }
  const results = await Promise.all(result.items.map((item) => persistNotificationRemote(item)));
  const cloudOk = results.every(Boolean);
  notifyTrace(cloudOk ? "publish:ok" : "publish:fail", {
    text: String(text || "").slice(0, 80),
    itemCount: result.items.length,
    cloudOk
  });
  if (!cloudOk) {
    console.warn(
      "[wavrick] publishAdminAnnouncement: cloud save failed for some recipients — other devices may not receive until retried"
    );
    return { ...result, cloudOk };
  }
  void globalThis.WavrickNotificationRealtime?.signalNotificationsChanged?.();
  return { ...result, cloudOk };
}

async function deleteAdminAnnouncementBatch(batchId, notificationId) {
  const batch = String(batchId || "").trim();
  const id = String(notificationId || "").trim();
  const rows = getNotifications();
  const toRemove = rows.filter((n) => {
    if (batch && String(n.batchId || "").trim() === batch) return true;
    if (id && n.id === id) return true;
    return false;
  });
  if (!toRemove.length) return { ok: false, reason: "not_found" };
  const removeIds = new Set(toRemove.map((n) => n.id));
  saveNotifications(rows.filter((n) => !removeIds.has(n.id)));
  if (isSupabaseEnabled()) {
    initSupabaseClient();
    if (supabaseClient) {
      if (batch) {
        const { error } = await supabaseClient.from(TABLES.notifications).delete().eq("batch_id", batch);
        if (error) {
          for (const row of toRemove) {
            await supabaseClient.from(TABLES.notifications).delete().eq("id", row.id);
          }
        }
      } else {
        for (const row of toRemove) {
          await supabaseClient.from(TABLES.notifications).delete().eq("id", row.id);
        }
      }
    }
  }
  window.dispatchEvent(new CustomEvent("wavrick-announcements-changed"));
  void globalThis.WavrickNotificationRealtime?.signalNotificationsChanged?.();
  return { ok: true, removed: toRemove.length };
}

