/** 本番サイト（Hostinger）か。ローカル開発では false のまま */
function isProductionSite() {
  const cfg = window.WAVRICK_CONFIG || {};
  if (cfg.production === true) return true;
  const host = (location.hostname || "").toLowerCase();
  return host === "wavrick.com" || host === "www.wavrick.com";
}

function applyProductionUiGates() {
  if (!isProductionSite()) return;
  document.querySelectorAll(".site-footer-mvp").forEach((el) => el.classList.add("hidden"));
  document.getElementById("ytChannelTestBypass")?.classList.add("hidden");
  document.getElementById("navVoiceWorkTempItem")?.classList.add("hidden");
  document.getElementById("page-voice-work-temp")?.classList.add("hidden");
  const talentsSub = document.getElementById("talentsPageSubtitle");
  if (talentsSub) {
    talentsSub.textContent = t("talents.subtitle_live");
  }
  if (!isSupabaseEnabled()) {
    console.error(
      "[wavrick] production requires Supabase. Check WAVRICK_CONFIG.supabaseUrl / supabaseAnonKey."
    );
  }
}

/** 本番ではクラウド必須。ローカル開発のみ localStorage 単独保存を許可する */
function allowLocalOnlyPersistence() {
  return !isProductionSite();
}

const MOCK_STATS_SEED_KEY = "wavrick_mock_stats_seeded_v4";
const MOCK_DATA_FLAG_KEY = "wavrick_mock_data_enabled";

/** デモ声優・モック実績を表示するか（本番では常に off。ローカル開発のみ ?mock=1） */
function isMockDataEnabled() {
  if (isProductionSite()) return false;
  try {
    const params = new URLSearchParams(window.location.search);
    if (params.get("mock") === "1") {
      localStorage.setItem(MOCK_DATA_FLAG_KEY, "1");
      return true;
    }
    if (params.get("mock") === "0") {
      localStorage.removeItem(MOCK_DATA_FLAG_KEY);
      return false;
    }
  } catch {
    /* ignore */
  }
  return localStorage.getItem(MOCK_DATA_FLAG_KEY) === "1";
}

function getMockTalentsForDisplay() {
  return isMockDataEnabled() ? mockTalents : [];
}

function isDemoTalentEmail(email) {
  return String(email || "").toLowerCase().includes("@example.com");
}

/** 本番では @example.com のデモ登録（Supabase / localStorage 同期分も除外） */
function filterProfilesForDisplay(profiles) {
  const list = Array.isArray(profiles) ? profiles : [];
  const withoutBanned = list.filter((p) => !p?.isBanned && !p?.bannedAt);
  if (isMockDataEnabled()) return withoutBanned;
  return withoutBanned.filter((p) => !isDemoTalentEmail(p.email));
}

/** モック off 時に注入済みの mock_req_* ワークフローを削除 */
function purgeMockWorkflowDataIfDisabled() {
  if (isMockDataEnabled()) return;
  const workflows = JSON.parse(localStorage.getItem("wavrick_request_workflows") || "{}");
  let changed = false;
  for (const id of Object.keys(workflows)) {
    if (String(id).startsWith("mock_req_")) {
      delete workflows[id];
      changed = true;
    }
  }
  if (changed) {
    persistWorkflowsLocalStorage(workflows);
    if (globalThis.WavrickTalentStats) globalThis.WavrickTalentStats.invalidateCache();
    if (globalThis.WavrickTalentStats?.clearRemoteCache) globalThis.WavrickTalentStats.clearRemoteCache();
  }
  for (const legacyKey of [
    "wavrick_mock_stats_seeded_v2",
    "wavrick_mock_stats_seeded_v3",
    MOCK_STATS_SEED_KEY
  ]) {
    localStorage.removeItem(legacyKey);
  }
}

