function getPricingApi() {
  return globalThis.WavrickPricing || null;
}

function resolveVoiceProfileByTalentId(talentId) {
  if (!talentId) return null;
  const fromActive = loadVoiceProfiles().find((p) => getTalentId(p) === talentId);
  if (fromActive) return fromActive;
  // Include banned tombstones so history can show「退会済みユーザーとの取引」
  const localAll = JSON.parse(localStorage.getItem("wavrick_voice_profiles") || "[]");
  const tombstones = [...(remoteVoiceProfiles || []), ...localAll];
  return tombstones.find((p) => getTalentId(p) === talentId) || null;
}

function formatParticipantDisplayName(name, talentId) {
  const Restriction = globalThis.WavrickAccountRestriction;
  const profile = talentId ? resolveVoiceProfileByTalentId(talentId) : null;
  if (Restriction?.displayNameForParticipant) {
    return Restriction.displayNameForParticipant(name, profile);
  }
  if (profile?.isBanned || profile?.bannedAt) return t("account.withdrawn_user_trade");
  const n = String(name || "").trim();
  if (n === "退会済みユーザー") return t("account.withdrawn_user_trade");
  return n || t("account.withdrawn_user_trade");
}

function renderTalentPricingHtml(profile) {
  const P = getPricingApi();
  if (!P) return "";
  const lines = P.formatVoicePricingLines(profile);
  return `<div class="talent-pricing">
    <span class="talent-price-tag">${escapeHtml(lines.perMinute)}</span>
    <span class="talent-price-tag">${escapeHtml(lines.minimum)}</span>
    <span class="talent-price-tag">${escapeHtml(lines.retake)}</span>
  </div>`;
}

function getTalentId(profile) {
  const email = (profile.email || "").toLowerCase().trim();
  if (email) return `voice:${email}`;
  const name = (profile.displayName || "").toLowerCase().trim();
  if (name) return `mock:${name}`;
  return `mock:${Math.random().toString(16).slice(2)}`;
}

function parseGenres(genresString) {
  return (genresString || "")
    .split(",")
    .map((x) => x.trim())
    .filter(Boolean);
}

function computeGenreOverlapScore(profile, desiredGenres) {
  const pGenres = parseGenres(profile.genres).map((g) => g.toLowerCase());
  const dGenres = parseGenres(desiredGenres).map((g) => g.toLowerCase());
  if (!dGenres.length) return 0;
  const set = new Set(pGenres);
  let score = 0;
  for (const dg of dGenres) if (set.has(dg)) score += 1;
  return score;
}

let _suppressHistoryPush = false;

let _wavrickActivePageName = "home";

function getWavrickActivePageName() {
  const hashPage = (window.location.hash || "").replace(/^#/, "");
  if (hashPage && pageMap[hashPage]) return hashPage;
  if (_wavrickActivePageName && pageMap[_wavrickActivePageName]) return _wavrickActivePageName;
  const stored = sessionStorage.getItem("wavrick_active_page");
  if (stored && pageMap[stored]) return stored;
  return "home";
}

function buildWavrickHistoryState(pageName) {
  const name = pageName && pageMap[pageName] ? pageName : getWavrickActivePageName();
  return { wavrickPage: name };
}

function showPage(name, options) {
  // Discard overlays without history.back — otherwise back races with this navigation
  // and the newly opened page (e.g. 案件管理 after cast select) snaps closed.
  if (typeof globalThis.WavrickAnnouncements?.discardForNavigation === "function") {
    globalThis.WavrickAnnouncements.discardForNavigation();
  } else {
    globalThis.WavrickAnnouncements?.closePanel?.(true);
  }
  if (typeof window.wavrickCloseMobileNav === "function") {
    window.wavrickCloseMobileNav(true);
  }
  globalThis.WavrickNavBack?.discardStack?.();

  // v3 ADR: 「依頼する」はスタンドアロンの音声抽出→話者分けフローへ
  if (name === "yt") {
    window.location.href = "./adr-request.html";
    return;
  }

  // TEMP(応急): 【仮】声優の案件 → 案件管理（話者1受諾想定）— ローカル開発のみ
  if (name === "voice-work-temp") {
    if (!isProductionSite()) {
      try {
        globalThis.WavrickTempVoiceWorkStub?.applyTempVoiceWorkAssumption?.();
      } catch {
        /* ignore */
      }
    }
    name = "work";
  }

  // Logged-in users must not open login / signup / password-reset (except real recovery links).
  {
    const redirected = resolveLoggedInAwayFromGuestAuthPage(name, getCurrentSession());
    if (redirected !== name) {
      name = redirected;
    }
  }

  if (name !== "recruitments") {
    showRecruitmentsListView();
  }
  if (name !== "work") {
    clearWorkCaseOpenLock();
    showWorkMainView();
    showWorkCaseListView({ skipNavBack: true, scrollTop: false, instant: true, clearOpenLock: true });
  }
  const pushHistory = !(options && options.skipHistory);
  if (_wavrickActivePageName === "yt" && name !== "yt" && isCustomerLoggedIn()) {
    _wavrickSaveFormState();
  }
  if (name === "admin") {
    const session = JSON.parse(localStorage.getItem("wavrick_session") || "null");
    if (!session || session.role !== "admin") {
      const fallback = session?.email ? getPostLoginPageName(session) : "login";
      if (fallback === "login") {
        setMessage("loginMessage", "運営ダッシュボードは運営ログイン後に利用できます。", "err");
      }
      name = fallback;
    } else {
      const gateCached = window.WavrickAdminGate?.readGateState?.();
      if (!gateCached) {
        void window.WavrickAdminGate?.requireAdminGate?.().then((gate) => {
          if (gate && !gate.allowed) {
            const sess = getCurrentSession();
            setMessage(
              sess?.email ? "accountMessage" : "loginMessage",
              window.WavrickAdminGate?.formatBlockedMessage?.(gate) ||
                "運営ダッシュボードへのアクセスが拒否されました。",
              "err"
            );
            showPage(sess?.email ? getPostLoginPageName(sess) : "login", { skipHistory: true });
          }
        });
      }
    }
  }
  if (
    (name === "portfolio" || name === "rewards") &&
    globalThis.WavrickAccountRestriction?.isSessionSuspended?.(getCurrentSession())
  ) {
    name = "account";
  }
  const pageId = pageMap[name];
  if (!pageId) return;
  document.querySelectorAll(".page").forEach((page) => page.classList.remove("active"));
  const target = document.getElementById(pageId);
  if (target) target.classList.add("active");
  window.scrollTo({ top: 0, behavior: "instant" });
  if (name === "login" && !getCurrentSession()?.email) {
    void prepareLoginPageAuth();
  }
  if (name === "password-reset") {
    window.WavrickPasswordReset?.bind?.();
    try {
      if (sessionStorage.getItem("wavrick_password_recovery") === "1") {
        window.WavrickPasswordReset?.showMode?.("update");
      } else {
        window.WavrickPasswordReset?.showMode?.("request");
      }
    } catch {
      window.WavrickPasswordReset?.showMode?.("request");
    }
  }
  if (name === "admin") {
    closeAdminDetailModal();
    if (_wavrickCloudBootstrapDone) {
      if (adminDataState.dataReady && !options?.force) {
        renderAdminDashboard();
      } else {
        void ensureAdminDashboardReady({
          reason: "show-page",
          force: true
        });
      }
    } else if (
      typeof hydrateAdminDashboardFromCache === "function" &&
      (adminDataState.dataReady || hydrateAdminDashboardFromCache())
    ) {
      // bootstrap 完了前でも前回キャッシュがあれば即描画（bootstrap 完了後に最新化される）
      renderAdminDashboard();
    } else {
      setAdminDashboardLoading(true);
    }
  }
  window.WavrickAnalytics?.trackPage?.(name);
  syncNavActiveLinks();
  if (name === "work" || name === "recruitments") {
    startWorkPagePolling();
  } else {
    stopWorkPagePolling();
  }
  if (name === "work") {
    // TEMP(応急): 募集話者1受諾済み案件を開いた想定 — ローカル開発のみ
    const tempStubEnabled =
      !isProductionSite() && globalThis.WavrickTempVoiceWorkStub?.isEnabled?.();
    if (tempStubEnabled) {
      try {
        globalThis.WavrickTempVoiceWorkStub.applyTempVoiceWorkAssumption();
        if (typeof renderSession === "function") renderSession();
        if (typeof syncMainNav === "function") syncMainNav();
        window.dispatchEvent(new Event("wavrick-workdata-updated"));
        setMessage(
          "workMessage",
          "【仮】募集中の案件の話者1として受諾し、その案件を開いた想定で表示しています。",
          "ok"
        );
      } catch (stubErr) {
        console.warn("[wavrick] temp voice work stub failed", stubErr);
      }
    }
    // init の運営相当パス（defer）中は競合 hydrate しない
    if (options?.skipCloudHydrate || _wavrickDeferWorkCloudLoad) {
      setMessage("workMessage", "クラウドと同期しています…", null);
    } else {
      void (async () => {
        try {
          setMessage("workMessage", "クラウドと同期しています…", null);
          if (isSupabaseEnabled() && getCurrentSession()?.email) {
            await forceRestoreSupabaseSession({ waitMs: 5000 });
          }
          const result = await hydrateAllCloudData();
          window.dispatchEvent(new Event("wavrick-workdata-updated"));
          if (tempStubEnabled) {
            setMessage(
              "workMessage",
              "【仮】募集中の案件の話者1として受諾し、その案件を開いた想定で表示しています。",
              "ok"
            );
          } else if (result?.ok === false && getCurrentSession()?.email) {
            const jwtOk = await hasValidSupabaseAuthSession();
            if (!jwtOk) {
              setMessage(
                "workMessage",
                "クラウド同期用のログインが切れているため案件を取得できません。一度ログアウトして再ログインしてください。",
                "err"
              );
            }
          }
        } catch (err) {
          console.warn("[wavrick] work hydrate skipped", err);
          window.dispatchEvent(new Event("wavrick-workdata-updated"));
        }
      })();
    }
  }
  if (name === "recruitments") {
    if (options?.skipCloudHydrate || _wavrickDeferRecruitmentsCloudLoad) {
      setRecruitmentsMessage("クラウドと同期しています…", "");
    } else {
      void (async () => {
        try {
          setRecruitmentsMessage("クラウドと同期しています…", "");
          if (isSupabaseEnabled() && getCurrentSession()?.email) {
            await forceRestoreSupabaseSession({ waitMs: 5000 });
          }
          await refreshRecruitmentsPage();
        } catch (err) {
          console.warn("[wavrick] recruitments refresh skipped", err);
          setRecruitmentsMessage("募集案件の取得に失敗しました。", "err");
        }
      })();
    }
  }
  if (name === "yt") {
    syncYtPageAuthUi();
    if (isCustomerLoggedIn()) {
      _wavrickRestoreFormState();
      _wavrickRestorePipelineState();
      renderYtSpeakerPicker();
      renderYtSpeakerNames();
      if (ytTranscriptPlain) {
        renderYtTranscriptAssignView({ forceValue: true });
        scheduleRepaintYtTranscriptAssignEditor();
        updateYtAssignSummary();
      }
      updateYtAssignHint();
      syncYtTranscriptUndoButtons();
      syncYtSourceModeUi();
      syncYtDraftStatusUi();
    }
  }
  if (name === "account" || name === "portfolio" || name === "rewards") {
    syncAccountPageUi();
    if (!isCustomerLoggedIn() && name === "account") {
      /* gate only */
    }
  }
  if ((name === "talents" || name === "home") && isSupabaseEnabled()) {
    void refreshRemoteVoiceProfiles();
  } else if (name === "talents") {
    renderTalents();
  }
  window.scrollTo({ top: 0, behavior: "smooth" });

  if (pushHistory && !_suppressHistoryPush) {
    const newHash = "#" + name;
    if (window.location.hash !== newHash) {
      history.pushState({ wavrickPage: name }, "", newHash);
    }
  }
  sessionStorage.setItem("wavrick_active_page", name);
  _wavrickActivePageName = name;
  applyPrelaunchGateToPage(name);
}

function bindNavigation() {
  if (document.documentElement.dataset.navGoBound !== "1") {
    document.documentElement.dataset.navGoBound = "1";
    document.addEventListener("click", (event) => {
      const node = event.target.closest("[data-go]");
      if (!node) return;
      // Standalone / external navigations keep native href behavior.
      if (node.matches('a[href="./adr-request.html"], a[href="./record-workspace.html"]')) return;
      if (node.closest("#navUserDropdown")) return; // handled in bindNavChrome
      event.preventDefault();
      const target = node.getAttribute("data-go");
      const workFilter = node.getAttribute("data-work-filter");
      const adminTab = node.getAttribute("data-admin-tab");
      const accountFocus = node.getAttribute("data-account-focus");
      if (workFilter) setWorkListFilter(workFilter);
      else if (target === "work") setWorkListFilter("all");
      showPage(target);
      if (target === "admin" && adminTab && typeof switchAdminTab === "function") {
        switchAdminTab(adminTab);
      }
      if (target === "account" && accountFocus) {
        focusAccountNavSection(accountFocus);
      }
      if (target === "work") {
        window.dispatchEvent(new Event("wavrick-workdata-updated"));
      }
      syncNavActiveLinks();
    });
  }

  document.querySelectorAll('nav a[href="#how"]').forEach((node) => {
    node.addEventListener("click", (event) => {
      event.preventDefault();
      showPage("home");
      window.setTimeout(() => {
        const section = document.getElementById("how");
        if (section) section.scrollIntoView({ behavior: "smooth", block: "start" });
      }, 80);
    });
  });

  window.addEventListener("popstate", (e) => {
    if (globalThis.WavrickAnnouncements?.tryHandlePopstate?.()) {
      return;
    }
    if (typeof window.wavrickTryHandleMobileNavPopstate === "function" && window.wavrickTryHandleMobileNavPopstate()) {
      return;
    }
    if (globalThis.WavrickNavBack?.handlePopstate?.()) {
      return;
    }
    // Orphan overlay history (discarded on navigate) — fall through to page resolve.
    _suppressHistoryPush = true;
    const statePage = e.state && e.state.wavrickPage;
    const hashPage = (window.location.hash || "").replace(/^#/, "");
    const storedPage = sessionStorage.getItem("wavrick_active_page");
    const target =
      (statePage && pageMap[statePage] ? statePage : null) ||
      (hashPage && pageMap[hashPage] ? hashPage : null) ||
      (storedPage && pageMap[storedPage] ? storedPage : null) ||
      "home";
    showPage(target, { skipHistory: true });
    _suppressHistoryPush = false;
  });

  window.addEventListener("pageshow", (e) => {
    if (!e.persisted) return;
    _wavrickRestoreFormState();
    _wavrickRestorePipelineState();
    const hashPage = (window.location.hash || "").replace(/^#/, "");
    const lastPage = sessionStorage.getItem("wavrick_active_page");
    const preferred = hashPage && pageMap[hashPage] ? hashPage : lastPage;
    const target = resolveAutoNavigationPageName(preferred);
    if (target && pageMap[target]) {
      _suppressHistoryPush = true;
      showPage(target, { skipHistory: true });
      _suppressHistoryPush = false;
    }
  });
}

// ─── フォームオートセーブ＆復元 ───
const _FORM_AUTOSAVE_KEY = "wavrick_form_autosave";
const _FORM_FIELDS_TO_SAVE = [
  "voiceDisplayName", "voiceEmail",
  "customerSignupName", "customerSignupEmail",
  "ytVideoUrl", "ytDeadline", "ytScriptLanguage", "ytSpeakerCount",
  "ytScript",
  "ytOmakaseGender", "ytOmakaseBudget", "ytOmakaseGenres",
  "accountChannelUrl"
];

function _wavrickDraftStorageEmail() {
  const session = getCurrentSession();
  if (!session || session.role !== "customer") return "";
  return (session.email || "").toLowerCase().trim();
}

function _wavrickFormAutosaveLocalKey() {
  const email = _wavrickDraftStorageEmail();
  return email ? `wavrick_form_autosave:${email}` : "";
}

function _wavrickPipelineLocalKey() {
  const email = _wavrickDraftStorageEmail();
  return email ? `wavrick_yt_pipeline_state:${email}` : "";
}

function getYtDraftsApi() {
  return typeof window !== "undefined" && window.WavrickYtDrafts ? window.WavrickYtDrafts : null;
}

function _wavrickSaveFormState() {
  try {
    const data = {};
    for (const id of _FORM_FIELDS_TO_SAVE) {
      const el = document.getElementById(id);
      if (el && el.value) data[id] = el.value;
    }
    const radioYtSource = document.querySelector('input[name="ytSourceMode"]:checked');
    if (radioYtSource) data._ytSourceMode = radioYtSource.value;
    const json = JSON.stringify(data);
    sessionStorage.setItem(_FORM_AUTOSAVE_KEY, json);
    const localKey = _wavrickFormAutosaveLocalKey();
    if (localKey) localStorage.setItem(localKey, json);
    const email = _wavrickDraftStorageEmail();
    const Cloud = getCloudApi();
    if (email && Cloud?.scheduleSaveUserPreferences && isCustomerLoggedIn()) {
      Cloud.scheduleSaveUserPreferences(email, { ytFormAutosave: data });
    }
    _wavrickSavePipelineState();
  } catch (e) { /* quota exceeded — ignore */ }
}

function _wavrickRestoreFormState() {
  try {
    let raw = sessionStorage.getItem(_FORM_AUTOSAVE_KEY);
    if (!raw) {
      const localKey = _wavrickFormAutosaveLocalKey();
      if (localKey) raw = localStorage.getItem(localKey);
    }
    if (!raw) return;
    const data = JSON.parse(raw);
    for (const id of _FORM_FIELDS_TO_SAVE) {
      if (data[id] == null) continue;
      const el = document.getElementById(id);
      if (el) el.value = data[id];
    }
    if (data._ytSourceMode) {
      const radio = document.querySelector(`input[name="ytSourceMode"][value="${data._ytSourceMode}"]`);
      if (radio) { radio.checked = true; radio.dispatchEvent(new Event("change", { bubbles: true })); }
    }
  } catch (e) { /* ignore */ }
}

const _YT_PIPELINE_STATE_KEY = "wavrick_yt_pipeline_state";

function _wavrickElVisible(id) {
  const el = document.getElementById(id);
  return Boolean(el && !el.classList.contains("hidden"));
}

function _wavrickSetElVisible(id, visible) {
  const el = document.getElementById(id);
  if (!el) return;
  el.classList.toggle("hidden", !visible);
}

function _wavrickSavePipelineState() {
  try {
    flushTextareaEdit();
    const speakerCount = getYtSpeakerCount();
    const payload = {
      ytTranscriptPlain,
      ytTranscriptPlainAtWhisper,
      ytTranscribeJobId,
      ytWhisperSegments,
      ytWhisperDurationSec,
      ytAssignRanges,
      ytAssignRangeHistory,
      ytAssignRangeSeq,
      ytActiveSpeaker,
      ytAssignClickMode,
      ytAssignPreviewFocusSpeaker,
      speakerCount,
      castSlots: loadYtCastSlots(speakerCount),
      ytScriptTimecodedFull,
      ytScriptsBySpeaker,
      ytReconcileDraftFull,
      ytReconcileAdlibSegments,
      ytReconcileAdlibSpans,
      ytReconcileReady,
      ytSpeakerColors: { ...ytSpeakerColors },
      ui: {
        pipelineAfterTranscribe: _wavrickElVisible("pipelineAfterTranscribe"),
        lineAssign: _wavrickElVisible("ytLineAssignSection"),
        castSlots: _wavrickElVisible("ytCastSlotsSection"),
        scriptPreview: _wavrickElVisible("scriptPreview"),
        reconcilePreview: _wavrickElVisible("ytReconcilePreview"),
        generateScript: _wavrickElVisible("generateScriptButton"),
        quotePreview: _wavrickElVisible("ytQuotePreview")
      },
      savedAt: Date.now()
    };
    const json = JSON.stringify(payload);
    sessionStorage.setItem(_YT_PIPELINE_STATE_KEY, json);
    const localKey = _wavrickPipelineLocalKey();
    if (localKey) localStorage.setItem(localKey, json);
    const email = _wavrickDraftStorageEmail();
    const Cloud = getCloudApi();
    if (email && Cloud?.scheduleSaveUserPreferences && isCustomerLoggedIn()) {
      Cloud.scheduleSaveUserPreferences(email, { ytPipelineState: payload });
    }
  } catch (e) { /* quota — ignore */ }
}

function _wavrickApplyPipelineState(saved) {
  if (!saved || typeof saved !== "object") return false;
  const hasData =
    saved.ytTranscriptPlain ||
    saved.ytTranscribeJobId ||
    (Array.isArray(saved.ytWhisperSegments) && saved.ytWhisperSegments.length) ||
    (Array.isArray(saved.ytAssignRanges) && saved.ytAssignRanges.length) ||
    (Array.isArray(saved.castSlots) && saved.castSlots.length);
  if (!hasData) return false;

  ytTranscriptPlain = String(saved.ytTranscriptPlain || "");
  ytTranscriptPlainAtWhisper = String(saved.ytTranscriptPlainAtWhisper || "");
  ensureYtWhisperBaselinePlain();
  ytTranscribeJobId = String(saved.ytTranscribeJobId || "");
  ytWhisperSegments = Array.isArray(saved.ytWhisperSegments) ? saved.ytWhisperSegments : [];
  ytWhisperDurationSec = Number(saved.ytWhisperDurationSec) || 0;
  ytAssignRanges = Array.isArray(saved.ytAssignRanges) ? saved.ytAssignRanges : [];
  ytAssignRangeHistory = Array.isArray(saved.ytAssignRangeHistory) ? saved.ytAssignRangeHistory : [];
  ytAssignRangeSeq = Number(saved.ytAssignRangeSeq) || 0;
  ytActiveSpeaker = Number(saved.ytActiveSpeaker) || 1;
  ytAssignClickMode = Boolean(saved.ytAssignClickMode);
  ytAssignAnchor = null;
  ytAssignPreviewFocusSpeaker = Number(saved.ytAssignPreviewFocusSpeaker) || 0;

  if (Array.isArray(saved.castSlots) && saved.castSlots.length) {
    const count = Number(saved.speakerCount) || saved.castSlots.length;
    const scEl = document.getElementById("ytSpeakerCount");
    if (scEl && count) scEl.value = String(count);
    saveYtCastSlots(saved.castSlots, count);
  }
  if (saved.ytSpeakerColors && typeof saved.ytSpeakerColors === "object") {
    const count = Number(saved.speakerCount) || getYtSpeakerCount();
    ytSpeakerColors = normalizeYtSpeakerColors(saved.ytSpeakerColors, count);
    saveYtSpeakerColors(count);
  } else {
    loadYtSpeakerColors(Number(saved.speakerCount) || getYtSpeakerCount());
  }
  ytLastSpeakerCount = Number(saved.speakerCount) || getYtSpeakerCount();
  if (String(saved.ytScriptTimecodedFull || "").trim()) {
    ytScriptTimecodedFull = String(saved.ytScriptTimecodedFull).trim();
  }
  if (saved.ytScriptsBySpeaker && typeof saved.ytScriptsBySpeaker === "object") {
    ytScriptsBySpeaker = normalizeScriptsBySpeakerMap(saved.ytScriptsBySpeaker);
  }
  ytReconcileDraftFull = String(saved.ytReconcileDraftFull || "").trim();
  ytReconcileAdlibSegments = Array.isArray(saved.ytReconcileAdlibSegments)
    ? saved.ytReconcileAdlibSegments
    : [];
  ytReconcileAdlibSpans = Array.isArray(saved.ytReconcileAdlibSpans)
    ? saved.ytReconcileAdlibSpans
    : [];
  ytReconcileReady = Boolean(saved.ytReconcileReady && ytReconcileDraftFull);

  const ui = saved.ui || {};
  const showPipeline = ui.pipelineAfterTranscribe !== false && hasData;
  _wavrickSetElVisible("pipelineAfterTranscribe", showPipeline);
  _wavrickSetElVisible("ytLineAssignSection", ui.lineAssign !== false || showPipeline);
  _wavrickSetElVisible("ytCastSlotsSection", Boolean(ui.castSlots));
  _wavrickSetElVisible("scriptPreview", Boolean(ui.scriptPreview));
  _wavrickSetElVisible("ytReconcilePreview", Boolean(ui.reconcilePreview || ytReconcileReady));
  _wavrickSetElVisible("generateScriptButton", Boolean(ui.generateScript) && !ytReconcileReady);
  _wavrickSetElVisible("ytQuotePreview", Boolean(ui.quotePreview));

  bindYtSpeakerPickerOnce();
  bindEditorFullscreenOnce();
  bindYtTranscriptDragSelectOnce();
  bindYtTranscriptClickModeOnce();
  bindYtTranscriptEditableOnce();
  bindYtAssignSummaryOnce();
  syncYtAssignModeUi();
  renderYtSpeakerPicker();
  renderYtSpeakerNames();
  renderYtTranscriptAssignView({ forceValue: true });
  updateYtAssignHint();
  syncYtTranscriptUndoButtons();
  if (ui.castSlots) renderYtCastSlots();
  if (ui.scriptPreview) {
    updateYtQuotePreview();
    refreshYtRecordSpeakerSelect();
  }
  if (ytReconcileReady && ytReconcileDraftFull) {
    const reconcileField = document.getElementById("ytReconcileScript");
    if (reconcileField) reconcileField.value = ytReconcileDraftFull;
    void paintYtReconcileMirror(ytReconcileDraftFull, ytReconcileAdlibSegments, ytReconcileAdlibSpans);
  }
  return true;
}

function _wavrickRestorePipelineState() {
  try {
    let raw = sessionStorage.getItem(_YT_PIPELINE_STATE_KEY);
    if (!raw) {
      const localKey = _wavrickPipelineLocalKey();
      if (localKey) raw = localStorage.getItem(localKey);
    }
    if (!raw) return;
    const saved = JSON.parse(raw);
    _wavrickApplyPipelineState(saved);
  } catch (e) {
    console.warn("[wavrick] pipeline state restore failed", e);
  }
}

function _wavrickBindFormAutosave() {
  const handler = _wavrickSaveFormState;
  for (const id of _FORM_FIELDS_TO_SAVE) {
    const el = document.getElementById(id);
    if (!el) continue;
    el.addEventListener("input", handler);
    el.addEventListener("change", handler);
  }
  document.querySelectorAll('input[name="ytSourceMode"]').forEach((r) => {
    r.addEventListener("change", handler);
  });
  window.addEventListener("pagehide", handler);
  window.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "hidden") handler();
  });
}

function _wavrickCollectYtDraftPayload() {
  flushTextareaEdit();
  _wavrickSaveFormState();
  const form = {};
  try {
    const raw =
      sessionStorage.getItem(_FORM_AUTOSAVE_KEY) ||
      localStorage.getItem(_wavrickFormAutosaveLocalKey() || "") ||
      "{}";
    Object.assign(form, JSON.parse(raw));
  } catch (_) {
    /* ignore */
  }
  // ストレージではなくメモリ上の最新パイプラインを下書きに含める
  const speakerCount = getYtSpeakerCount();
  const pipeline = {
    ytTranscriptPlain,
    ytTranscriptPlainAtWhisper,
    ytTranscribeJobId,
    ytWhisperSegments,
    ytWhisperDurationSec,
    ytAssignRanges,
    ytAssignRangeHistory,
    ytAssignRangeSeq,
    ytActiveSpeaker,
    ytAssignClickMode,
    ytAssignPreviewFocusSpeaker,
    speakerCount,
    castSlots: loadYtCastSlots(speakerCount),
    ytScriptTimecodedFull,
    ytScriptsBySpeaker,
    ytReconcileDraftFull,
    ytReconcileAdlibSegments,
    ytReconcileAdlibSpans,
    ytReconcileReady,
    ytSpeakerColors: { ...ytSpeakerColors },
    ui: {
      pipelineAfterTranscribe: _wavrickElVisible("pipelineAfterTranscribe"),
      lineAssign: _wavrickElVisible("ytLineAssignSection"),
      castSlots: _wavrickElVisible("ytCastSlotsSection"),
      scriptPreview: _wavrickElVisible("scriptPreview"),
      reconcilePreview: _wavrickElVisible("ytReconcilePreview"),
      generateScript: _wavrickElVisible("generateScriptButton"),
      quotePreview: _wavrickElVisible("ytQuotePreview")
    },
    savedAt: Date.now()
  };
  return {
    version: 1,
    form,
    pipeline,
    castSlots: loadYtCastSlots(speakerCount),
    speakerCount,
    savedAt: Date.now()
  };
}

function _wavrickApplyYtDraftPayload(payload) {
  if (!payload || typeof payload !== "object") return;
  if (payload.form && typeof payload.form === "object") {
    const json = JSON.stringify(payload.form);
    sessionStorage.setItem(_FORM_AUTOSAVE_KEY, json);
    const localKey = _wavrickFormAutosaveLocalKey();
    if (localKey) localStorage.setItem(localKey, json);
    _wavrickRestoreFormState();
  }
  if (Array.isArray(payload.castSlots) && payload.castSlots.length) {
    const count = Number(payload.speakerCount) || payload.castSlots.length;
    const scEl = document.getElementById("ytSpeakerCount");
    if (scEl && count) scEl.value = String(count);
    saveYtCastSlots(payload.castSlots, count);
  }
  const pipeline = payload.pipeline && typeof payload.pipeline === "object" ? payload.pipeline : null;
  if (pipeline) {
    if (Array.isArray(payload.castSlots) && payload.castSlots.length) {
      pipeline.castSlots = payload.castSlots;
      pipeline.speakerCount = Number(payload.speakerCount) || payload.castSlots.length;
    }
    const json = JSON.stringify(pipeline);
    sessionStorage.setItem(_YT_PIPELINE_STATE_KEY, json);
    const localKey = _wavrickPipelineLocalKey();
    if (localKey) localStorage.setItem(localKey, json);
    _wavrickApplyPipelineState(pipeline);
  }
  syncYtSourceModeUi();
  refreshYtChannelUi();
}

function _wavrickClearYtWorkInProgress() {
  try {
    sessionStorage.removeItem(_FORM_AUTOSAVE_KEY);
    sessionStorage.removeItem(_YT_PIPELINE_STATE_KEY);
    const formKey = _wavrickFormAutosaveLocalKey();
    const pipeKey = _wavrickPipelineLocalKey();
    if (formKey) localStorage.removeItem(formKey);
    if (pipeKey) localStorage.removeItem(pipeKey);
  } catch (_) {
    /* ignore */
  }
}

function syncYtDraftStatusUi() {
  const el = document.getElementById("ytDraftStatus");
  if (!el || !isCustomerLoggedIn()) return;
  const D = getYtDraftsApi();
  const email = _wavrickDraftStorageEmail();
  if (!D || !email) {
    el.textContent = "";
    return;
  }
  const activeId = D.getActiveDraftId(email);
  if (!activeId) {
    el.textContent = "";
    return;
  }
  const draft = D.getLocalDraft(email, activeId);
  el.textContent = draft?.title ? `編集中の下書き: ${draft.title}` : "下書きから再開中";
}

async function saveCurrentYtDraft(options = {}) {
  const D = getYtDraftsApi();
  const email = _wavrickDraftStorageEmail();
  if (!D || !email) {
    setMessage("ytMessage", "下書きを保存するには顧客としてログインしてください。", "err");
    return { ok: false };
  }
  initSupabaseClient();
  const payload = _wavrickCollectYtDraftPayload();
  const hasContent =
    Object.keys(payload.form || {}).length > 0 ||
    payload.pipeline?.ytTranscriptPlain ||
    payload.pipeline?.ytTranscriptSrt ||
    (Array.isArray(payload.pipeline?.ytWhisperSegments) && payload.pipeline.ytWhisperSegments.length) ||
    String(payload.form?.ytScript || "").trim();
  if (!hasContent) {
    setMessage("ytMessage", "保存する内容がありません。URL入力や文字起こしのあとに保存してください。", "err");
    return { ok: false };
  }

  const title = String(options.title || "").trim();
  if (!title) {
    setMessage("ytMessage", "下書き名を入力してください。", "err");
    return { ok: false, reason: "title_required" };
  }

  const activeId = D.getActiveDraftId(email);
  const forceNew = Boolean(options.forceNew);
  let draftId = forceNew ? "" : activeId;
  if (!draftId) draftId = D.generateDraftId();

  const existing = D.getLocalDraft(email, draftId);
  const isUpdate = Boolean(existing?.draftId);
  const replaceDraftId = String(options.replaceDraftId || "").trim();

  if (!isUpdate && D.countDrafts(email) >= D.MAX_DRAFTS && !replaceDraftId) {
    return { ok: false, reason: "limit", count: D.countDrafts(email), max: D.MAX_DRAFTS };
  }

  const draft = {
    draftId,
    email,
    title,
    payload,
    createdAt: existing?.createdAt || new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };

  const localResult = D.saveLocalDraft(email, draft, {
    replaceDraftId: isUpdate ? "" : replaceDraftId
  });
  if (!localResult.ok) {
    if (localResult.reason === "limit") {
      return {
        ok: false,
        reason: "limit",
        count: localResult.count,
        max: localResult.max || D.MAX_DRAFTS
      };
    }
    setMessage("ytMessage", "下書きを端末に保存できませんでした。ストレージ容量を確認してください。", "err");
    return { ok: false, reason: localResult.reason || "storage" };
  }

  D.setActiveDraftId(email, draftId);

  let remoteOk = true;
  if (isSupabaseEnabled()) {
    if (localResult.replacedDraftId) {
      await D.deleteRemote(supabaseClient, email, localResult.replacedDraftId);
    }
    const result = await D.upsertRemote(supabaseClient, draft);
    remoteOk = result.ok;
  }

  syncYtDraftStatusUi();
  if (remoteOk) {
    setMessage("ytMessage", `下書きを保存しました（${title}）。`, "ok");
  } else {
    setMessage(
      "ytMessage",
      "下書きを端末に保存しました。クラウド同期は失敗したため、別の端末では表示されない場合があります。",
      "err"
    );
  }
  return { ok: true, draft };
}

async function resumeYtDraft(draftId) {
  const D = getYtDraftsApi();
  const email = _wavrickDraftStorageEmail();
  if (!D || !email || !draftId) return { ok: false };
  initSupabaseClient();
  let draft = D.getLocalDraft(email, draftId);
  if (!draft && isSupabaseEnabled()) {
    const remoteRows = await D.listRemote(supabaseClient, email);
    draft = remoteRows.find((r) => r.draftId === draftId) || null;
    if (draft) D.saveLocalDraft(email, draft);
  }
  if (!draft?.payload) {
    setMessage("ytMessage", "下書きが見つかりませんでした。", "err");
    return { ok: false };
  }
  _wavrickApplyYtDraftPayload(draft.payload);
  D.setActiveDraftId(email, draftId);
  syncYtDraftStatusUi();
  showPage("yt");
  if (ytTranscriptPlain) {
    renderYtTranscriptAssignView({ forceValue: true });
    scheduleRepaintYtTranscriptAssignEditor();
    updateYtAssignSummary();
    updateYtAssignHint();
  }
  setMessage("ytMessage", `下書き「${draft.title || "無題"}」を読み込みました。`, "ok");
  return { ok: true };
}

async function deleteYtDraft(draftId) {
  const D = getYtDraftsApi();
  const email = _wavrickDraftStorageEmail();
  if (!D || !email || !draftId) return { ok: false };
  initSupabaseClient();
  D.deleteLocalDraft(email, draftId);
  if (isSupabaseEnabled()) await D.deleteRemote(supabaseClient, email, draftId);
  syncYtDraftStatusUi();
  return { ok: true };
}

function closeYtDraftModalVisual() {
  const modal = document.getElementById("ytDraftModal");
  if (!modal) return;
  modal.classList.add("hidden");
  modal.setAttribute("aria-hidden", "true");
}

function closeYtDraftModal() {
  const modal = document.getElementById("ytDraftModal");
  if (!modal || modal.classList.contains("hidden")) return;
  const Nav = globalThis.WavrickNavBack;
  if (Nav && Nav.getStackDepth?.() > 0) {
    Nav.pop();
    return;
  }
  closeYtDraftModalVisual();
}

function closeYtDraftSaveModalVisual() {
  const modal = document.getElementById("ytDraftSaveModal");
  if (!modal) return;
  modal.classList.add("hidden");
  modal.setAttribute("aria-hidden", "true");
}

function closeYtDraftSaveModal() {
  const modal = document.getElementById("ytDraftSaveModal");
  if (!modal || modal.classList.contains("hidden")) return;
  const Nav = globalThis.WavrickNavBack;
  if (Nav && Nav.getStackDepth?.() > 0) {
    Nav.pop();
    return;
  }
  closeYtDraftSaveModalVisual();
}

function closeAllOverlayModals() {
  globalThis.WavrickNavBack?.discardStack?.();
  const talentModal = document.getElementById("talentProfileModal");
  if (talentModal && !talentModal.classList.contains("hidden")) {
    talentModal.classList.add("hidden");
    talentModal.setAttribute("aria-hidden", "true");
    document.body.style.overflow = "";
  }
  closeYtDraftModalVisual();
  closeYtDraftSaveModalVisual();
  if (typeof closeAdminDetailModalVisual === "function") closeAdminDetailModalVisual();
  else if (typeof closeAdminDetailModal === "function") closeAdminDetailModal();
}

function getYtDraftSaveMode() {
  const checked = document.querySelector('input[name="ytDraftSaveMode"]:checked');
  return checked?.value === "new" ? "new" : "overwrite";
}

function ytDraftSaveWillCreateNew() {
  const D = getYtDraftsApi();
  const email = _wavrickDraftStorageEmail();
  if (!D || !email) return true;
  const activeId = D.getActiveDraftId(email);
  if (!activeId) return true;
  return getYtDraftSaveMode() === "new";
}

async function getYtDraftRowsForUi() {
  const D = getYtDraftsApi();
  const email = _wavrickDraftStorageEmail();
  if (!D || !email) return [];
  initSupabaseClient();
  return D.listMerged(isSupabaseEnabled() ? supabaseClient : null, email);
}

function syncYtDraftSaveCountUi(count) {
  const el = document.getElementById("ytDraftSaveCount");
  const D = getYtDraftsApi();
  if (!el || !D) return;
  const max = D.MAX_DRAFTS || 20;
  el.textContent = `保存済み: ${count} / ${max} 件`;
}

function renderYtDraftReplaceList(rows) {
  const listEl = document.getElementById("ytDraftReplaceList");
  if (!listEl) return;
  if (!rows.length) {
    listEl.innerHTML = `<p class="section-desc">削除できる下書きがありません。</p>`;
    return;
  }
  listEl.innerHTML = rows
    .map((row, index) => {
      const title = escapeHtml(row.title || "無題の下書き");
      const when = escapeHtml(formatYtDraftDate(row.updatedAt || row.createdAt));
      const id = escapeHtml(row.draftId);
      return `
        <label class="yt-draft-replace-item">
          <input type="radio" name="ytDraftReplacePick" value="${id}"${index === 0 ? " checked" : ""}>
          <span>
            <strong>${title}</strong>
            <span class="yt-draft-item-meta">更新: ${when}</span>
          </span>
        </label>`;
    })
    .join("");
}

function syncYtDraftReplaceUi(rows) {
  const wrap = document.getElementById("ytDraftReplaceWrap");
  const D = getYtDraftsApi();
  if (!wrap || !D) return;
  const needsReplace =
    ytDraftSaveWillCreateNew() && (rows?.length ?? D.countDrafts(_wavrickDraftStorageEmail())) >= D.MAX_DRAFTS;
  wrap.classList.toggle("hidden", !needsReplace);
  if (needsReplace) {
    void getYtDraftRowsForUi().then((list) => renderYtDraftReplaceList(list));
  }
}

async function openYtDraftSaveModal() {
  const D = getYtDraftsApi();
  const email = _wavrickDraftStorageEmail();
  if (!D || !email) {
    setMessage("ytMessage", "下書きを保存するには顧客としてログインしてください。", "err");
    return;
  }
  const modal = document.getElementById("ytDraftSaveModal");
  const nameInput = document.getElementById("ytDraftSaveName");
  const modeWrap = document.getElementById("ytDraftSaveModeWrap");
  if (!modal || !nameInput) return;

  initSupabaseClient();
  const rows = await getYtDraftRowsForUi();
  const activeId = D.getActiveDraftId(email);
  const activeDraft = activeId ? rows.find((r) => r.draftId === activeId) || D.getLocalDraft(email, activeId) : null;
  const payload = _wavrickCollectYtDraftPayload();
  const suggested = activeDraft?.title || D.makeDraftTitle(payload) || "";

  nameInput.value = suggested;
  if (modeWrap) {
    modeWrap.classList.toggle("hidden", !activeDraft?.draftId);
    const overwriteRadio = modeWrap.querySelector('input[value="overwrite"]');
    const newRadio = modeWrap.querySelector('input[value="new"]');
    if (overwriteRadio) overwriteRadio.checked = true;
    if (newRadio) newRadio.checked = false;
  }

  syncYtDraftSaveCountUi(rows.length);
  syncYtDraftReplaceUi(rows);
  modal.classList.remove("hidden");
  modal.setAttribute("aria-hidden", "false");
  globalThis.WavrickNavBack?.push?.(closeYtDraftSaveModalVisual);
  globalThis.WavrickNavBack?.bindSwipeBack?.(
    modal.querySelector(".talent-modal-panel"),
    () => closeYtDraftSaveModal(),
    { headerSelector: ".talent-modal-title" }
  );
  nameInput.focus();
  nameInput.select();
}

async function confirmYtDraftSaveFromModal() {
  const D = getYtDraftsApi();
  const email = _wavrickDraftStorageEmail();
  const nameInput = document.getElementById("ytDraftSaveName");
  if (!D || !email || !nameInput) return;

  const title = nameInput.value.trim();
  if (!title) {
    setMessage("ytMessage", "下書き名を入力してください。", "err");
    nameInput.focus();
    return;
  }

  const forceNew = ytDraftSaveWillCreateNew();
  const rows = await getYtDraftRowsForUi();
  let replaceDraftId = "";

  if (forceNew && rows.length >= D.MAX_DRAFTS) {
    const picked = document.querySelector('input[name="ytDraftReplacePick"]:checked');
    replaceDraftId = picked?.value || "";
    if (!replaceDraftId) {
      setMessage("ytMessage", "削除して置き換える下書きを1件選んでください。", "err");
      return;
    }
  }

  const result = await saveCurrentYtDraft({
    title,
    forceNew,
    replaceDraftId
  });

  if (result.ok) {
    closeYtDraftSaveModal();
    return;
  }
  if (result.reason === "limit") {
    syncYtDraftReplaceUi(rows);
    setMessage(
      "ytMessage",
      `下書きは最大${result.max || D.MAX_DRAFTS}件です。削除して置き換える下書きを選んでから保存してください。`,
      "err"
    );
    return;
  }
  if (result.reason === "title_required") {
    nameInput.focus();
  }
}

function formatYtDraftDate(iso) {
  if (!iso) return "";
  try {
    return new Date(iso).toLocaleString("ja-JP", {
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit"
    });
  } catch (_) {
    return String(iso);
  }
}

async function renderYtDraftModalList() {
  const listEl = document.getElementById("ytDraftModalList");
  const emptyEl = document.getElementById("ytDraftModalEmpty");
  if (!listEl) return;
  const D = getYtDraftsApi();
  const email = _wavrickDraftStorageEmail();
  if (!D || !email) {
    listEl.innerHTML = "";
    if (emptyEl) emptyEl.classList.remove("hidden");
    return;
  }
  initSupabaseClient();
  listEl.innerHTML = `<p class="section-desc">読み込み中…</p>`;
  const rows = await D.listMerged(isSupabaseEnabled() ? supabaseClient : null, email);
  if (!rows.length) {
    listEl.innerHTML = "";
    if (emptyEl) emptyEl.classList.remove("hidden");
    const countEl = document.getElementById("ytDraftModalCount");
    if (countEl) countEl.classList.add("hidden");
    return;
  }
  if (emptyEl) emptyEl.classList.add("hidden");
  const countEl = document.getElementById("ytDraftModalCount");
  if (countEl) {
    countEl.textContent = `${rows.length} / ${D.MAX_DRAFTS || 20} 件`;
    countEl.classList.remove("hidden");
  }
  const activeId = D.getActiveDraftId(email);
  listEl.innerHTML = rows
    .map((row) => {
      const active = row.draftId === activeId ? " yt-draft-item--active" : "";
      const title = escapeHtml(row.title || "無題の下書き");
      const when = escapeHtml(formatYtDraftDate(row.updatedAt || row.createdAt));
      return `
        <div class="yt-draft-item${active}">
          <div class="yt-draft-item-main">
            <p class="yt-draft-item-title">${title}</p>
            <p class="yt-draft-item-meta">更新: ${when}</p>
          </div>
          <div class="yt-draft-item-actions">
            <button type="button" class="btn-red btn-sm" data-yt-draft-resume="${escapeHtml(row.draftId)}">再開</button>
            <button type="button" class="btn-ghost btn-sm" data-yt-draft-delete="${escapeHtml(row.draftId)}">削除</button>
          </div>
        </div>`;
    })
    .join("");
}

function openYtDraftModal() {
  const modal = document.getElementById("ytDraftModal");
  if (!modal) return;
  if (!isCustomerLoggedIn()) {
    setMessage("ytMessage", "下書き一覧を見るにはログインしてください。", "err");
    return;
  }
  modal.classList.remove("hidden");
  modal.setAttribute("aria-hidden", "false");
  globalThis.WavrickNavBack?.push?.(closeYtDraftModalVisual);
  globalThis.WavrickNavBack?.bindSwipeBack?.(
    modal.querySelector(".talent-modal-panel"),
    () => closeYtDraftModal(),
    { headerSelector: ".talent-modal-title" }
  );
  void renderYtDraftModalList();
}

function bindYtDraftUi() {
  const saveBtn = document.getElementById("ytDraftSaveBtn");
  const listBtn = document.getElementById("ytDraftListBtn");
  const modal = document.getElementById("ytDraftModal");
  const saveModal = document.getElementById("ytDraftSaveModal");
  const saveConfirmBtn = document.getElementById("ytDraftSaveConfirmBtn");
  const saveNameInput = document.getElementById("ytDraftSaveName");

  if (saveBtn && saveBtn.dataset.bound !== "1") {
    saveBtn.dataset.bound = "1";
    saveBtn.addEventListener("click", () => {
      void openYtDraftSaveModal();
    });
  }
  if (listBtn && listBtn.dataset.bound !== "1") {
    listBtn.dataset.bound = "1";
    listBtn.addEventListener("click", openYtDraftModal);
  }
  if (saveModal && saveModal.dataset.bound !== "1") {
    saveModal.dataset.bound = "1";
    saveModal.querySelectorAll("[data-close-yt-draft-save-modal]").forEach((node) => {
      node.addEventListener("click", closeYtDraftSaveModal);
    });
    saveModal.querySelectorAll('input[name="ytDraftSaveMode"]').forEach((node) => {
      node.addEventListener("change", () => {
        void getYtDraftRowsForUi().then((rows) => syncYtDraftReplaceUi(rows));
      });
    });
    if (saveConfirmBtn) {
      saveConfirmBtn.addEventListener("click", () => {
        void confirmYtDraftSaveFromModal();
      });
    }
    if (saveNameInput) {
      saveNameInput.addEventListener("keydown", (event) => {
        if (event.key === "Enter") {
          event.preventDefault();
          void confirmYtDraftSaveFromModal();
        }
      });
    }
  }
  if (modal && modal.dataset.bound !== "1") {
    modal.dataset.bound = "1";
    modal.querySelectorAll("[data-close-yt-draft-modal]").forEach((node) => {
      node.addEventListener("click", closeYtDraftModal);
    });
    const listEl = document.getElementById("ytDraftModalList");
    if (listEl) {
      listEl.addEventListener("click", (event) => {
        const resumeBtn = event.target.closest("[data-yt-draft-resume]");
        if (resumeBtn) {
          void resumeYtDraft(resumeBtn.getAttribute("data-yt-draft-resume")).then((result) => {
            if (result.ok) closeYtDraftModal();
          });
          return;
        }
        const deleteBtn = event.target.closest("[data-yt-draft-delete]");
        if (deleteBtn) {
          const draftId = deleteBtn.getAttribute("data-yt-draft-delete");
          if (!draftId) return;
          if (!window.confirm("この下書きを削除しますか？")) return;
          void deleteYtDraft(draftId).then(() => renderYtDraftModalList());
        }
      });
    }
  }
}

function isYouTubeUrl(value) {
  const raw = String(value || "").trim().replace(/[\r\n]+/g, "");
  if (!raw) return false;
  try {
    const normalized = /^https?:\/\//i.test(raw) ? raw : `https://${raw}`;
    const u = new URL(normalized);
    const host = u.hostname.toLowerCase();
    const base = host.startsWith("www.") ? host.slice(4) : host;
    if (base === "youtu.be") return u.pathname.replace(/^\//, "").length >= 6;
    if (
      base === "youtube.com" ||
      base === "m.youtube.com" ||
      base === "music.youtube.com" ||
      base === "youtube-nocookie.com"
    ) {
      return true;
    }
    return false;
  } catch {
    return /^(https?:\/\/)?(www\.)?(youtube\.com|youtu\.be)\//i.test(raw);
  }
}

function decodeUriComponentSafe(value) {
  try {
    return decodeURIComponent(String(value).replace(/\+/g, " "));
  } catch (_) {
    return String(value);
  }
}

function channelKeyToBase64(channelKey) {
  const bytes = new TextEncoder().encode(channelKey);
  let bin = "";
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin);
}

function channelKeyFromBase64(b64) {
  const std = String(b64 || "")
    .replace(/-/g, "+")
    .replace(/_/g, "/");
  const pad = std + "=".repeat((4 - (std.length % 4)) % 4);
  const bin = atob(pad);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new TextDecoder().decode(bytes).trim();
}

/** postMessage から channel_key を復元（ASCII の channelKeyB64 優先） */
function channelKeyFromOAuthMessage(d) {
  if (d.channelKeyB64) {
    try {
      return channelKeyFromBase64(d.channelKeyB64);
    } catch (_) {
      /* legacy */
    }
  }
  return d.channelKey || "";
}

function channelKeysMatch(a, b) {
  const norm = (s) => {
    let x = String(s || "").trim();
    for (let i = 0; i < 3; i++) {
      if (!/%[0-9A-Fa-f]{2}/.test(x)) break;
      const next = decodeUriComponentSafe(x);
      if (next === x) break;
      x = next;
    }
    return x.toLowerCase();
  };
  return norm(a) === norm(b);
}

function normalizeYoutubeChannelKey(urlValue) {
  try {
    const raw = urlValue.trim();
    if (!raw) return "";
    const parsed = new URL(raw.startsWith("http") ? raw : `https://${raw}`);
    const host = parsed.hostname.replace(/^www\./, "").toLowerCase();
    if (host !== "youtube.com" && host !== "m.youtube.com") return "";

    const path = decodeUriComponentSafe(parsed.pathname.replace(/\/+$/, ""));
    if (!path || path === "/") return "";
    const parts = path.split("/").filter(Boolean);
    const first = parts[0] || "";
    const second = parts[1] || "";

    if (first.startsWith("@")) return `handle:${first.toLowerCase()}`;
    if (first === "channel" && second) return `channel:${second}`;
    if (first === "user" && second) return `user:${second.toLowerCase()}`;
    if (first === "c" && second) return `custom:${second.toLowerCase()}`;
    return "";
  } catch (_) {
    return "";
  }
}

function getStoredSupabaseConfig() {
  const fromWindow = window.WAVRICK_CONFIG || {};
  if (fromWindow.supabaseUrl && fromWindow.supabaseAnonKey) {
    return {
      supabaseUrl: fromWindow.supabaseUrl,
      supabaseAnonKey: fromWindow.supabaseAnonKey
    };
  }
  return null;
}

/** OAuth / legacy keys — backed by js/i18n/messages.js */
function wavrickI18n(key) {
  return t(key);
}

function youtubeOAuthMessageFromCode(code) {
  const k = `oauth_${code}`;
  const text = wavrickI18n(k);
  return text === k ? wavrickI18n("yt_oauth_fail") : text;
}

/** ローカル開発: localhost / 127.0.0.1 の postMessage ずれを防ぐ */
const WAVRICK_YT_OAUTH_STORAGE_KEY = "wavrick_yt_oauth_v1";

function normalizeOAuthParentOrigin(origin) {
  const raw = (origin || window.location.origin || "").trim();
  if (!raw || raw === "null") return "";
  try {
    const u = new URL(raw);
    const port = u.port || (u.protocol === "https:" ? "443" : "80");
    if (
      (u.hostname === "localhost" || u.hostname === "127.0.0.1") &&
      (port === "8889" || port === "80")
    ) {
      return `http://127.0.0.1:8889`;
    }
  } catch (_) {
    /* keep */
  }
  return raw;
}

/** 本番 https://wavrick.com/wavrick/ などサブフォルダ配置向け */
function getWavrickAppBase() {
  const origin = normalizeOAuthParentOrigin(window.location.origin);
  if (!origin) return "";
  let path = window.location.pathname || "/";
  if (path.endsWith("/")) path = path.slice(0, -1);
  else {
    const last = path.split("/").pop() || "";
    if (last.includes(".")) path = path.slice(0, path.lastIndexOf("/"));
  }
  if (!path || path === "/") return origin;
  return `${origin}${path}`;
}

function buildYoutubeOAuthStartUrl(channelKey, parentBase, opts = {}) {
  const cfg = getStoredSupabaseConfig();
  if (!cfg?.supabaseUrl) return "";
  const linkAll = Boolean(opts.linkAll);
  if (!linkAll && !channelKey) return "";
  const base = String(cfg.supabaseUrl).replace(/\/+$/, "");
  const u = new URL(`${base}/functions/v1/youtube-oauth-start`);
  if (linkAll) {
    u.searchParams.set("link_mode", "link_all");
  } else {
    u.searchParams.set("channel_key_b64", channelKeyToBase64(channelKey));
  }
  u.searchParams.set(
    "parent_origin",
    parentBase || getWavrickAppBase() || normalizeOAuthParentOrigin(window.location.origin)
  );
  // ブラウザの window.open では Authorization ヘッダを付けられないため（anon は公開前提）
  if (cfg.supabaseAnonKey) {
    u.searchParams.set("apikey", cfg.supabaseAnonKey);
  }
  return u.toString();
}

function getSupabaseOriginForPostMessage() {
  const cfg = getStoredSupabaseConfig();
  if (!cfg?.supabaseUrl) return "";
  try {
    return new URL(cfg.supabaseUrl).origin;
  } catch (_) {
    return "";
  }
}

function initSupabaseClient() {
  if (supabaseClient) return true;
  if (isProductionSite()) {
    try {
      localStorage.removeItem("wavrick_supabase_config");
    } catch {
      /* ignore */
    }
  }
  const config = getStoredSupabaseConfig();
  if (!config || !window.supabase || !window.supabase.createClient) {
    supabaseClient = null;
    window.wavrickSupabaseClient = null;
    const Cloud = getCloudApi();
    if (Cloud?.setClientProvider) Cloud.setClientProvider(() => null);
    if (globalThis.WavrickTalentStats?.setClientProvider) {
      globalThis.WavrickTalentStats.setClientProvider(() => null);
    }
    if (globalThis.WavrickNotificationRealtime?.setClientProvider) {
      globalThis.WavrickNotificationRealtime.setClientProvider(() => null);
    }
    if (globalThis.WavrickWorkdataRealtime?.setClientProvider) {
      globalThis.WavrickWorkdataRealtime.setClientProvider(() => null);
    }
    return false;
  }
  // Desktop 複数タブや古い CDN 版での navigator.locks デッドロック回避
  // flowType implicit: password-recovery / magic-link emails open in mail apps
  // (different browser storage). PKCE would fail without the original code_verifier.
  supabaseClient = window.supabase.createClient(config.supabaseUrl, config.supabaseAnonKey, {
    auth: {
      persistSession: true,
      autoRefreshToken: true,
      detectSessionInUrl: true,
      flowType: "implicit",
      lock: async (_name, _acquireTimeout, fn) => fn()
    },
    realtime: {
      params: {
        eventsPerSecond: 20
      }
    }
  });
  window.wavrickSupabaseClient = supabaseClient;
  const Cloud = getCloudApi();
  if (Cloud?.setClientProvider) Cloud.setClientProvider(() => supabaseClient);
  if (globalThis.WavrickTalentStats?.setClientProvider) {
    globalThis.WavrickTalentStats.setClientProvider(() => supabaseClient);
  }
  if (globalThis.WavrickNotificationRealtime?.setClientProvider) {
    globalThis.WavrickNotificationRealtime.setClientProvider(() => supabaseClient);
  }
  if (globalThis.WavrickWorkdataRealtime?.setClientProvider) {
    globalThis.WavrickWorkdataRealtime.setClientProvider(() => supabaseClient);
  }
  ensureSupabaseAuthBootstrapListener();
  wireWavrickAuthGate();
  return true;
}
window.initSupabaseClient = initSupabaseClient;

function isSupabaseEnabled() {
  return Boolean(supabaseClient);
}

function isSupabaseServiceRestrictedMessage(message) {
  const text = String(message || "").toLowerCase();
  return (
    text.includes("exceed_egress_quota") ||
    text.includes("service for this project is restricted") ||
    text.includes("project is restricted")
  );
}

function formatSupabaseServiceRestrictedLoginMessage() {
  return (
    t("login.supabase_service_restricted") ||
    "クラウドサービス（Supabase）が一時停止しています。運営がプラン上限を解除するまで、ログインできません。"
  );
}

function getVoiceProfileStorageApi() {
  return typeof window !== "undefined" && window.WavrickVoiceProfileStorage
    ? window.WavrickVoiceProfileStorage
    : null;
}

function isPgDuplicateError(error) {
  const code = String(error?.code || "");
  const msg = String(error?.message || "").toLowerCase();
  return code === "23505" || msg.includes("duplicate") || msg.includes("already exists");
}

async function lookupVoiceProfileIdByEmail(email) {
  const normalized = String(email || "")
    .toLowerCase()
    .trim();
  if (!normalized || !isSupabaseEnabled() || !supabaseClient) {
    return { ok: false, id: null, error: { message: "no_email_or_supabase" } };
  }
  try {
    const { data, error } = await withTimeout(
      supabaseClient.from(TABLES.voiceProfiles).select("id").ilike("email", normalized).limit(1),
      20000,
      "voice_profile_lookup"
    );
    if (error) return { ok: false, id: null, error };
    const id = Array.isArray(data) && data[0]?.id ? data[0].id : null;
    return { ok: true, id, error: null };
  } catch (error) {
    return { ok: false, id: null, error };
  }
}

/**
 * Update-by-email or insert once. Never treats lookup failures as "missing"
 * (that path used to mint duplicate UUID rows for the same email).
 */
async function upsertVoiceProfileRemote(profileOrPayload, options = {}) {
  if (!isSupabaseEnabled()) return { ok: false, skipped: true };
  initSupabaseClient();
  if (!supabaseClient) return { ok: false, error: { message: "no_supabase" }, reason: "no_supabase" };

  const payload = options.alreadyMapped
    ? { ...profileOrPayload }
    : mapVoiceProfileToRemote(profileOrPayload);
  const email = String(payload.email || "")
    .toLowerCase()
    .trim();
  if (!email) return { ok: false, error: { message: "email required" }, reason: "no_email" };
  payload.email = email;

  const lookup = await lookupVoiceProfileIdByEmail(email);
  if (!lookup.ok) {
    return { ok: false, error: lookup.error, reason: "lookup_failed" };
  }

  if (lookup.id) {
    const { data: updatedRows, error } = await withTimeout(
      supabaseClient.from(TABLES.voiceProfiles).update(payload).eq("id", lookup.id).select("id"),
      20000,
      "voice_profile_update"
    );
    if (error || !Array.isArray(updatedRows) || !updatedRows.length) {
      return {
        ok: false,
        error: error || { message: "プロフィールの更新が反映されませんでした。" },
        reason: "update_failed"
      };
    }
    return { ok: true, id: updatedRows[0].id, created: false };
  }

  const insertPayload = { ...payload, created_at: new Date().toISOString() };
  const { data: insertedRows, error: insertError } = await withTimeout(
    supabaseClient.from(TABLES.voiceProfiles).insert(insertPayload).select("id"),
    20000,
    "voice_profile_insert"
  );
  if (!insertError && Array.isArray(insertedRows) && insertedRows.length) {
    return { ok: true, id: insertedRows[0].id, created: true };
  }

  // Race: another writer inserted first — update that row instead of failing open.
  if (insertError && isPgDuplicateError(insertError)) {
    const retry = await lookupVoiceProfileIdByEmail(email);
    if (retry.ok && retry.id) {
      const { data: updatedRows, error } = await withTimeout(
        supabaseClient.from(TABLES.voiceProfiles).update(payload).eq("id", retry.id).select("id"),
        20000,
        "voice_profile_update_after_dup"
      );
      if (!error && Array.isArray(updatedRows) && updatedRows.length) {
        return { ok: true, id: updatedRows[0].id, created: false };
      }
      return { ok: false, error: error || insertError, reason: "update_failed" };
    }
  }

  return {
    ok: false,
    error: insertError || { message: "insert failed" },
    reason: "insert_failed"
  };
}

function cloudSyncDelay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function ensureSupabaseClientUsesSession(session) {
  if (!session?.access_token || !initSupabaseClient()) return null;
  const refreshToken = session.refresh_token || "";
  try {
    const { data: current } = await supabaseClient.auth.getSession();
    if (current?.session?.access_token !== session.access_token && refreshToken) {
      const { data, error } = await supabaseClient.auth.setSession({
        access_token: session.access_token,
        refresh_token: refreshToken
      });
      if (!error && data?.session) return data.session;
      if (error) console.warn("[wavrick] ensureSupabaseClientUsesSession setSession failed", error);
    }
    // Force server round-trip so JWT claims (email) are usable for RLS auth_email().
    const { data: userData, error: userError } = await supabaseClient.auth.getUser();
    if (!userError && userData?.user?.email) {
      const { data: after } = await supabaseClient.auth.getSession();
      if (after?.session) return after.session;
    }
  } catch (error) {
    console.warn("[wavrick] ensureSupabaseClientUsesSession failed", error);
  }
  return session;
}

function isVoiceProfileRlsError(error) {
  const msg = String(error?.message || error || "");
  const code = String(error?.code || "");
  return (
    code === "42501" ||
    /row-level security|permission denied|not authorized|jwt/i.test(msg)
  );
}

async function getSupabaseAuthSessionForVoiceSave(preferredSession = null) {
  let session = null;
  if (preferredSession?.access_token && preferredSession?.user?.email) {
    session = preferredSession;
  } else if (initSupabaseClient()) {
    for (let attempt = 0; attempt < 4; attempt++) {
      const { data, error } = await supabaseClient.auth.getSession();
      if (!error && data?.session?.user?.email) {
        session = data.session;
        break;
      }
      if (attempt === 1) {
        try {
          const { data: refreshed, error: refreshError } = await supabaseClient.auth.refreshSession();
          if (!refreshError && refreshed?.session?.user?.email) {
            session = refreshed.session;
            break;
          }
        } catch {
          /* ignore */
        }
      }
      if (attempt < 3) await cloudSyncDelay(150 * (attempt + 1));
    }
  }
  if (session?.access_token) {
    const applied = await ensureSupabaseClientUsesSession(session);
    if (applied?.access_token) session = applied;
  }
  return session;
}

function mediaUploadErrorMessage(result) {
  if (result?.reason !== "media_upload_failed") return "";
  const err = result.error;
  if (!err) return "プロフィール画像・サンプル音声のアップロードに失敗しました。通信環境を確認して再度お試しください。";
  const msg =
    typeof err === "string"
      ? err
      : err.message || err.error_description || err.statusText || "";
  if (/invoke_timeout|voice_profile_media/i.test(msg)) {
    return "プロフィール画像・サンプル音声のアップロード用サーバーが応答しませんでした。しばらく待って再試行してください。";
  }
  if (/row-level security/i.test(msg)) {
    return "プロフィール画像・サンプル音声のアップロードが拒否されました。一度ログアウトして再ログインし、それでも失敗する場合は運営にお問い合わせください。";
  }
  if (msg && msg !== "[object Object]") {
    return `プロフィール画像・サンプル音声のアップロードに失敗しました。（${msg}）`;
  }
  return "プロフィール画像・サンプル音声のアップロードに失敗しました。通信環境を確認して再度お試しください。";
}

async function uploadVoiceProfileMediaForCloud(profile, options = {}) {
  const Storage = getVoiceProfileStorageApi();
  const hasMedia = Storage?.profileHasUploadableMedia
    ? Storage.profileHasUploadableMedia(profile)
    : false;
  if (!isSupabaseEnabled() || !profile?.email) {
    return { ok: true, profile };
  }
  if (!Storage?.uploadProfileMedia) {
    if (hasMedia) {
      return {
        ok: false,
        reason: "storage_module_unavailable",
        profile,
        error: { message: "メディアアップロード機能の読み込みに失敗しました。ページを再読み込みしてください。" }
      };
    }
    return { ok: true, profile };
  }
  if (!hasMedia) {
    return { ok: true, profile };
  }
  const authSession = await getSupabaseAuthSessionForVoiceSave(options.session || null);
  if (!authSession?.user?.email) {
    return { ok: false, reason: "no_auth_session", profile };
  }
  const authEmail = authSession.user.email.toLowerCase().trim();
  const profileEmail = (profile.email || "").toLowerCase().trim();
  if (authEmail !== profileEmail) {
    return { ok: false, reason: "auth_email_mismatch", profile };
  }
  return withTimeout(
    Storage.uploadProfileMedia(supabaseClient, profile, {
      ...options,
      authUid: authSession.user.id,
      ownerKey: authSession.user.id,
      authEmail
    }),
    120000,
    "voice_media_upload"
  );
}

async function updateVoiceMypageProfileInCloud(profile) {
  if (!isSupabaseEnabled()) {
    upsertLocalVoiceProfile(sanitizeVoiceProfileForLocalStorage(profile));
    return { ok: true, profile };
  }

  initSupabaseClient();
  const authSession = await getSupabaseAuthSessionForVoiceSave(null);
  if (!authSession?.user?.email) {
    return { ok: false, reason: "no_auth_session" };
  }

  const authEmail = authSession.user.email.toLowerCase().trim();
  const profileEmail = (profile.email || "").toLowerCase().trim();
  if (authEmail !== profileEmail) {
    return { ok: false, reason: "auth_email_mismatch" };
  }

  let merged = { ...profile };
  let mediaUploadDeferred = false;
  const Storage = getVoiceProfileStorageApi();
  if (Storage?.profileHasUploadableMedia(merged)) {
    const mediaUpload = await uploadVoiceProfileMediaForCloud(merged, { session: authSession });
    if (mediaUpload.ok && mediaUpload.profile) {
      merged = mediaUpload.profile;
    } else {
      console.warn(
        "[wavrick] voice mypage media upload failed; saving profile without media",
        mediaUpload.error || mediaUpload.reason
      );
      mediaUploadDeferred = true;
      merged = sanitizeVoiceProfileForLocalStorage(merged);
    }
  }

  upsertLocalVoiceProfile(sanitizeVoiceProfileForLocalStorage(merged));

  const remoteResult = await upsertVoiceProfileRemote(merged);
  if (!remoteResult.ok) {
    return {
      ok: false,
      reason: remoteResult.reason || "upsert_failed",
      error: remoteResult.error || { message: "プロフィールの保存に失敗しました。" },
      mediaUploadDeferred
    };
  }
  return { ok: true, profile: merged, mediaUploadDeferred };
}

function mapVoiceMypageSaveError(result) {
  if (!result) return "プロフィールの保存に失敗しました。";
  if (result.reason === "no_auth_session") {
    return "Supabase にログインしていないためクラウドへ保存できません。一度ログアウトして、声優アカウントで再ログインしてください。";
  }
  if (result.reason === "auth_email_mismatch") {
    return "ログイン中のメールとプロフィールが一致しません。メール変更の確認が完了しているか確認してください。";
  }
  if (result.reason === "media_upload_failed") {
    return mediaUploadErrorMessage({ reason: "media_upload_failed", error: result.error });
  }
  if (result.reason === "storage_module_unavailable") {
    return result.error?.message || "メディアアップロード機能の読み込みに失敗しました。ページを再読み込みしてください。";
  }
  if (result.reason === "lookup_failed" || result.reason === "update_failed" || result.reason === "insert_failed") {
    return result.error?.message || "クラウドへの保存に失敗しました。通信環境を確認して再度お試しください。";
  }
  return result.error?.message || "クラウドへの保存に失敗しました。通信環境を確認して再度お試しください。";
}

async function uploadVoicePendingSignupMediaToCloud(profile) {
  const Storage = getVoiceProfileStorageApi();
  if (!isSupabaseEnabled() || !profile?.email || !Storage?.uploadProfileMedia) {
    return { ok: true, profile };
  }
  if (!Storage.profileHasUploadableMedia(profile)) {
    return { ok: true, profile };
  }
  return Storage.uploadProfileMedia(supabaseClient, profile, { folder: "pending" });
}

function sanitizeVoiceProfileForPendingCloud(profile) {
  const { password: _password, termsAgree: _termsAgree, ...rest } = profile || {};
  const samples = parseVoiceSamplesFromStorage(rest.voiceSamples ?? rest.voiceSamplesJson).map((s) => {
    if (s.type === "file" && String(s.value || "").startsWith("data:")) {
      return { type: "file", value: "", name: s.name || "" };
    }
    return s;
  });
  let avatarUrl = String(rest.avatarUrl || "");
  if (avatarUrl.startsWith("data:")) avatarUrl = "";
  return {
    ...rest,
    voiceSamples: samples,
    voiceSamplesJson: JSON.stringify(samples),
    avatarUrl,
    sampleUrl:
      samples.find((s) => s.type === "url" && String(s.value || "").startsWith("http"))?.value ||
      rest.sampleUrl ||
      ""
  };
}

async function saveVoiceSignupPendingToCloud(profile) {
  if (!isSupabaseEnabled() || !profile?.email) return { ok: false, reason: "no_supabase" };
  let next = { ...profile };
  const mediaUpload = await uploadVoicePendingSignupMediaToCloud(next);
  if (mediaUpload.ok && mediaUpload.profile) {
    next = mediaUpload.profile;
  } else if (getVoiceProfileStorageApi()?.profileHasUploadableMedia(profile) && !mediaUpload.ok) {
    console.warn("[wavrick] pending voice media upload failed", mediaUpload.error || mediaUpload.reason);
  }
  const payload = sanitizeVoiceProfileForPendingCloud(next);
  const { data, error } = await supabaseClient.rpc("upsert_voice_signup_pending", {
    p_email: payload.email,
    p_profile: payload
  });
  if (error) {
    console.warn("[wavrick] upsert_voice_signup_pending failed", error);
    return { ok: false, error };
  }
  return { ok: Boolean(data), profile: payload };
}

async function loadVoiceSignupPendingFromCloud(email) {
  if (!isSupabaseEnabled() || !email) return null;
  const normalized = email.toLowerCase().trim();
  const { data, error } = await supabaseClient.rpc("get_voice_signup_pending", {
    p_email: normalized
  });
  if (error || !data || typeof data !== "object") return null;
  return data;
}

async function clearVoiceSignupPendingFromCloud(email) {
  if (!isSupabaseEnabled() || !email) return;
  const normalized = email.toLowerCase().trim();
  await supabaseClient.rpc("delete_voice_signup_pending", { p_email: normalized });
}

function decodeJwtPayload(token) {
  if (typeof token !== "string") return null;
  const parts = token.split(".");
  if (parts.length !== 3) return null;
  try {
    const b64 = parts[1].replace(/-/g, "+").replace(/_/g, "/");
    const padded = b64 + "=".repeat((4 - (b64.length % 4)) % 4);
    return JSON.parse(atob(padded));
  } catch {
    return null;
  }
}

function isUsableSupabaseAccessToken(token) {
  if (typeof token !== "string" || !token) return false;
  if (token.split(".").length !== 3) return false;
  const payload = decodeJwtPayload(token);
  if (!payload || typeof payload !== "object") return false;
  // 期限切れ（30秒猶予）は「無効」扱い → refresh させる。壊れた JWT のまま RPC すると 401 になる。
  if (typeof payload.exp === "number" && payload.exp * 1000 < Date.now() - 30000) {
    return false;
  }
  return true;
}

async function hasValidSupabaseAuthSession() {
  if (!initSupabaseClient()) return false;
  const { data, error } = await supabaseClient.auth.getSession();
  if (error || !data?.session?.access_token) return false;
  return isUsableSupabaseAccessToken(data.session.access_token);
}

/**
 * リロード時の JWT 復元を「再ログイン相当」にする。
 * 受動的に INITIAL_SESSION を待つのではなく、refreshSession を先に叩く。
 * （運営ダッシュボードが成功し、案件だけ止まる差の主因）
 */
async function forceRestoreSupabaseSession(options = {}) {
  if (!initSupabaseClient() || !supabaseClient) return false;
  const alreadyValid = await hasValidSupabaseAuthSession();
  // forceRefresh: 運営リロード等で refresh を強制。通常は usable JWT があれば即成功。
  if (alreadyValid && !options.forceRefresh) {
    globalThis.WavrickAuthGate?.notifySessionPresent?.("already_valid");
    return true;
  }

  const waitMs = Number.isFinite(options.waitMs) ? options.waitMs : 4000;

  // 1) すぐ refresh（ログイン直後と同じく access_token を取り直す）
  try {
    const refreshPromise = supabaseClient.auth.refreshSession();
    const { data, error } =
      typeof withTimeout === "function"
        ? await withTimeout(refreshPromise, 10000, "force_restore_refresh")
        : await refreshPromise;
    if (!error && isUsableSupabaseAccessToken(data?.session?.access_token)) {
      globalThis.WavrickAuthGate?.notifySessionPresent?.("force_refresh");
      return true;
    }
  } catch (error) {
    console.warn("[wavrick] forceRestoreSupabaseSession refresh failed", error);
  }

  if (await hasValidSupabaseAuthSession()) {
    globalThis.WavrickAuthGate?.notifySessionPresent?.("force_refresh_late");
    return true;
  }

  // 2) 短時間だけ INITIAL_SESSION / getSession を待つ
  const waited = await waitForSupabaseAuthReady(waitMs);
  if (waited.hasSession || (await hasValidSupabaseAuthSession())) {
    globalThis.WavrickAuthGate?.notifySessionPresent?.("force_wait");
    return true;
  }

  // 3) 最後にもう一度 refresh
  try {
    const refreshPromise = supabaseClient.auth.refreshSession();
    const { data, error } =
      typeof withTimeout === "function"
        ? await withTimeout(refreshPromise, 8000, "force_restore_refresh2")
        : await refreshPromise;
    if (!error && isUsableSupabaseAccessToken(data?.session?.access_token)) {
      globalThis.WavrickAuthGate?.notifySessionPresent?.("force_refresh2");
      return true;
    }
  } catch (error) {
    console.warn("[wavrick] forceRestoreSupabaseSession refresh2 failed", error);
  }

  return hasValidSupabaseAuthSession();
}

async function recoverSupabaseAuthSession(options = {}) {
  if (!initSupabaseClient() || !supabaseClient) return false;
  const retries = Number.isFinite(options.retries) ? options.retries : 2;
  const waitMs = Number.isFinite(options.waitMs) ? options.waitMs : 4000;

  if (await forceRestoreSupabaseSession({ waitMs })) return true;

  for (let attempt = 0; attempt <= retries; attempt += 1) {
    try {
      const refreshPromise = supabaseClient.auth.refreshSession();
      const { data, error } =
        typeof withTimeout === "function"
          ? await withTimeout(refreshPromise, 12000, "recover_auth_refresh")
          : await refreshPromise;
      if (!error && data?.session?.access_token) {
        globalThis.WavrickAuthGate?.notifySessionPresent?.("recover_refresh");
        return true;
      }
    } catch (error) {
      console.warn("[wavrick] recoverSupabaseAuthSession refresh failed", attempt, error);
    }
    if (attempt < retries) await cloudSyncDelay(300 + attempt * 250);
    if (await hasValidSupabaseAuthSession()) {
      globalThis.WavrickAuthGate?.notifySessionPresent?.("recover_valid");
      return true;
    }
  }
  return false;
}

async function tryRefreshSupabaseAuthSession() {
  return recoverSupabaseAuthSession({ retries: 1, waitMs: 4000 });
}

let supabaseAuthBootstrapListenerBound = false;
let supabaseAuthListenerBound = false;
let cloudRefreshTimer = null;
let cloudRefreshInFlight = null;
let cloudRefreshQueuedReason = null;
let sessionRecoveryTimer = null;
let sessionRecoveryInFlight = null;
let _wavrickCloudBootstrapDone = false;
let _wavrickDeferAdminDashboardLoad = false;
let _wavrickDeferWorkCloudLoad = false;
let _wavrickDeferRecruitmentsCloudLoad = false;

// 定期取得は WavrickWorkdataRealtime の 1 本に統一した（ここに独自 setInterval を戻さない）。
// このページ側では「開いた瞬間の取り直し」だけを行う。
let _workPageOpenHydrateAt = 0;
const WORK_PAGE_OPEN_HYDRATE_GAP_MS = 15_000;

function startWorkPagePolling() {
  if (_wavrickDeferWorkCloudLoad || !getCurrentSession()?.email) return;
  const WR = globalThis.WavrickWorkdataRealtime;
  void WR?.startLiveSync?.();
  if (Date.now() - _workPageOpenHydrateAt < WORK_PAGE_OPEN_HYDRATE_GAP_MS) return;
  _workPageOpenHydrateAt = Date.now();
  void WR?.runHydrate?.("page-open");
}

function stopWorkPagePolling() {
  /* ライブ同期はページを離れても続く（通知・別ページ更新のため） */
}

function isCloudBootstrapDone() {
  return _wavrickCloudBootstrapDone;
}

function getLocalYoutubeRequests() {
  try {
    return JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]");
  } catch {
    return [];
  }
}

/** リロード直後のお知らせ表示用 — ネットワーク待ちなしでローカル案件 ID を返す */
function getLocalVisibleRequestIdsForSession(session) {
  if (!session?.email) return new Set();
  const roles = getSessionRoles(session);
  if (roles.includes("admin") || session.role === "admin") return null;
  const rows = getLocalYoutubeRequests();
  const asCustomer = roles.includes("customer");
  const asVoice = roles.includes("voice");
  if (!asCustomer && !asVoice) return new Set();
  const email = session.email.toLowerCase().trim();
  const talentId = asVoice
    ? resolveVoiceTalentIdForSession(
        session.role === "voice" ? session : { ...session, role: "voice", roles }
      )
    : "";
  const ids = new Set();
  for (const r of rows) {
    const rid = String(r?.requestId || "").trim();
    if (!rid) continue;
    if (asCustomer && requestOwnedByCustomerEmail(r, email)) {
      ids.add(rid);
      continue;
    }
    if (asVoice && talentId && requestHasSpeakerAccountForVoice(r, talentId)) {
      ids.add(rid);
    }
  }
  return ids;
}

function scheduleSupabaseSessionRecovery(reason) {
  if (!getCurrentSession()?.email || !isSupabaseEnabled()) return;
  clearTimeout(sessionRecoveryTimer);
  sessionRecoveryTimer = setTimeout(() => {
    void recoverSupabaseSessionAndCloud(reason);
  }, 250);
}

async function recoverSupabaseSessionAndCloud(reason) {
  if (!getCurrentSession()?.email || !isSupabaseEnabled()) return;
  if (sessionRecoveryInFlight) return sessionRecoveryInFlight;
  sessionRecoveryInFlight = (async () => {
    try {
      const ok = await recoverSupabaseAuthSession({ retries: 3, waitMs: 6000 });
      if (!ok) {
        notifyTrace("recovery:no-jwt", { reason: reason || "session-recovery" });
        return;
      }
      scheduleCloudDataRefresh(reason || "session-recovery");
      void syncNotificationsFromRemote(true);
      void globalThis.WavrickAnnouncements?.refresh?.();
    } finally {
      sessionRecoveryInFlight = null;
    }
  })();
  return sessionRecoveryInFlight;
}

let supabaseSessionRecoveryBound = false;

function bindSupabaseSessionRecovery() {
  if (supabaseSessionRecoveryBound) return;
  supabaseSessionRecoveryBound = true;
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") {
      scheduleSupabaseSessionRecovery("visibility");
    }
  });
  window.addEventListener("pageshow", () => {
    scheduleSupabaseSessionRecovery("pageshow");
  });
  window.addEventListener("online", () => {
    scheduleSupabaseSessionRecovery("online");
  });
}

function ensureSupabaseAuthBootstrapListener() {
  if (!supabaseClient || supabaseAuthBootstrapListenerBound) return;
  supabaseAuthBootstrapListenerBound = true;
  supabaseClient.auth.onAuthStateChange((event, session) => {
    if (event === "PASSWORD_RECOVERY") {
      window.WavrickPasswordReset?.onAuthStateChange?.(event, session);
      return;
    }
    if (
      (event === "INITIAL_SESSION" || event === "TOKEN_REFRESHED" || event === "SIGNED_IN") &&
      session?.access_token
    ) {
      globalThis.WavrickAuthGate?.notifySessionPresent?.(event);
      scheduleCloudDataRefresh(event);
      void globalThis.WavrickI18n?.syncAccountLocale?.();
    }
  });
}

function wireWavrickAuthGate() {
  const Gate = globalThis.WavrickAuthGate;
  if (!Gate || Gate.__wavrickWired) return;
  Gate.__wavrickWired = true;
  Gate.setAdapters({
    hasLocalSession: () => Boolean(getCurrentSession()?.email),
    waitForSupabaseAuthReady,
    recoverSession: () => forceRestoreSupabaseSession({ waitMs: 5000 }),
    hasValidSession: hasValidSupabaseAuthSession
  });
}

let _deferredLocalSessionClearTimer = null;
/** Timestamp of last auth event that proves a live JWT (SIGNED_IN / refresh). */
let _lastSupabaseAuthPresentAt = 0;

function cancelDeferredLocalSessionClear() {
  if (_deferredLocalSessionClearTimer) {
    clearTimeout(_deferredLocalSessionClearTimer);
    _deferredLocalSessionClearTimer = null;
  }
}

function markSupabaseAuthPresent(reason) {
  _lastSupabaseAuthPresentAt = Date.now();
  cancelDeferredLocalSessionClear();
  globalThis.WavrickAuthGate?.notifySessionPresent?.(reason || "auth-present");
}

/**
 * Transient SIGNED_OUT must not wipe wavrick_session immediately.
 * Only clear after extended recovery failure.
 *
 * Important race: SIGNED_OUT handler runs async AFTER a later SIGNED_IN may have
 * already fired synchronously. Always re-check JWT / recent auth before clearing.
 */
function scheduleDeferredLocalSessionClear(reason) {
  if (inAuthCallbackGrace() || getEmailAuthCallbackMode()) {
    console.info("[wavrick] skip deferred session clear during email-auth callback", reason);
    return;
  }
  cancelDeferredLocalSessionClear();
  const scheduledAt = Date.now();
  _deferredLocalSessionClearTimer = setTimeout(() => {
    void (async () => {
      if (inAuthCallbackGrace() || getEmailAuthCallbackMode()) {
        console.info("[wavrick] skip deferred session clear — still in email-auth grace", reason);
        return;
      }
      // A newer SIGNED_IN / TOKEN_REFRESHED happened after this clear was scheduled.
      if (_lastSupabaseAuthPresentAt > scheduledAt) {
        console.info("[wavrick] skip deferred session clear — auth present after schedule", reason);
        return;
      }
      if (await hasValidSupabaseAuthSession()) {
        markSupabaseAuthPresent("deferred-clear-cancelled");
        return;
      }
      // One last restore attempt (refresh often finishes after transient SIGNED_OUT).
      const restored = await forceRestoreSupabaseSession({ waitMs: 6000, forceRefresh: true });
      if (restored || (await hasValidSupabaseAuthSession())) {
        markSupabaseAuthPresent("deferred-clear-restored");
        return;
      }
      if (!getCurrentSession()?.email) return;
      // Still within a fresh login window — don't kick the user to login.
      if (Date.now() - _lastSupabaseAuthPresentAt < 45_000) {
        console.warn(
          "[wavrick] skip deferred session clear — recent auth present",
          reason,
          Date.now() - _lastSupabaseAuthPresentAt
        );
        return;
      }
      console.warn("[wavrick] clearing local session after unrecovered SIGNED_OUT", reason);
      localStorage.removeItem("wavrick_session");
      if (typeof clearAdminDashboardCache === "function") clearAdminDashboardCache();
      globalThis.WavrickAuthGate?.notifySignedOut?.(reason || "signed-out-unrecoverable");
      syncMainNav();
      syncAccountPageUi();
      syncYtPageAuthUi();
      window.dispatchEvent(new Event("wavrick-logout"));
      setMessage(
        "loginMessage",
        "セッションの復元に失敗しました。もう一度ログインしてください。",
        "err"
      );
      if (_wavrickActivePageName !== "login") {
        showPage("login");
      }
    })();
  }, 15000);
}

/**
 * Supabase JS は INITIAL_SESSION より先に getSession() が空を返すことがある。
 * INITIAL_SESSION が null でも「未ログイン確定」にせず、TOKEN_REFRESHED / タイムアウトまで待つ。
 * （null で即 false にすると、リロード直後の案件・募集取得が失敗確定してしまう）
 */
function waitForSupabaseAuthReady(maxMs = 8000) {
  if (!initSupabaseClient() || !supabaseClient) {
    return Promise.resolve({ hasSession: false, timedOut: false });
  }
  return new Promise((resolve) => {
    let settled = false;
    let subscription = null;
    const finish = (hasSession, timedOut = false) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      try {
        subscription?.unsubscribe?.();
      } catch {
        /* ignore */
      }
      resolve({ hasSession: Boolean(hasSession), timedOut });
    };
    const timer = setTimeout(() => finish(false, true), maxMs);
    void supabaseClient.auth.getSession().then(({ data, error }) => {
      if (settled) return;
      if (!error && data?.session?.access_token) finish(true);
    });
    const listener = supabaseClient.auth.onAuthStateChange((event, session) => {
      if (settled) return;
      // Only settle success here. Null INITIAL_SESSION / transient SIGNED_OUT must not
      // mark "no session" early — wait for TOKEN_REFRESHED or the timeout.
      if (session?.access_token) {
        finish(true);
      }
    });
    subscription = listener?.data?.subscription || listener?.subscription || null;
  });
}

async function waitForLocalSessionCloudAuth(maxMs = 8000) {
  const session = getCurrentSession();
  if (!session?.email) {
    await waitForSupabaseAuthReady(Math.min(maxMs, 4000));
    return Boolean(await hasValidSupabaseAuthSession());
  }
  // ローカルセッションあり = 再ログイン相当。受動待ちより先に refresh する。
  if (await forceRestoreSupabaseSession({ waitMs: Math.min(maxMs, 5000) })) return true;
  await cloudSyncDelay(200);
  return recoverSupabaseAuthSession({ retries: 2, waitMs: 3000 });
}

function scheduleCloudDataRefresh(reason) {
  // ページ専用ロード（運営/案件/募集のリロード経路）中は競合させない
  if (
    _wavrickDeferAdminDashboardLoad ||
    _wavrickDeferWorkCloudLoad ||
    _wavrickDeferRecruitmentsCloudLoad
  ) {
    return;
  }
  clearTimeout(cloudRefreshTimer);
  cloudRefreshTimer = setTimeout(() => {
    void refreshAllAppCloudData(reason);
  }, 120);
}

let _softCloudRefreshAt = 0;
const SOFT_CLOUD_REFRESH_MIN_GAP_MS = 60_000;
const SOFT_CLOUD_REFRESH_REASONS = new Set([
  "visibility",
  "pageshow",
  "online",
  "TOKEN_REFRESHED",
  "session-recovery"
]);

async function refreshAllAppCloudData(reason) {
  if (!isSupabaseEnabled()) return;
  if (_wavrickActivePageName === "login" && !getCurrentSession()?.email) return;
  if (
    _wavrickDeferAdminDashboardLoad ||
    _wavrickDeferWorkCloudLoad ||
    _wavrickDeferRecruitmentsCloudLoad
  ) {
    cloudRefreshQueuedReason = reason || cloudRefreshQueuedReason || "queued";
    return;
  }
  if (cloudRefreshInFlight) {
    cloudRefreshQueuedReason = reason || cloudRefreshQueuedReason || "queued";
    return cloudRefreshInFlight;
  }
  // タブ復帰や token refresh のたびに全クラウド再同期しない
  if (
    SOFT_CLOUD_REFRESH_REASONS.has(String(reason || "")) &&
    _softCloudRefreshAt &&
    Date.now() - _softCloudRefreshAt < SOFT_CLOUD_REFRESH_MIN_GAP_MS
  ) {
    return;
  }
  cloudRefreshInFlight = (async () => {
    try {
      await waitForLocalSessionCloudAuth();
      const session = getCurrentSession();
      if (session?.email) {
        await ensureSupabaseAuthForLocalSession();
      }
      try {
        // タブ復帰 / token refresh ではキャッシュ優先。明示的な初期化・強制時だけ即取得。
        const forceVoice =
          reason === "init" ||
          reason === "login" ||
          reason === "force" ||
          String(reason || "").startsWith("force");
        await refreshRemoteVoiceProfiles({ force: forceVoice });
      } catch (error) {
        console.warn("[wavrick] refreshRemoteVoiceProfiles failed", reason, error);
      }
      try {
        await hydrateAllCloudData();
      } catch (error) {
        console.warn("[wavrick] hydrateAllCloudData failed", reason, error);
      }
      renderTalents();
      if (
        !_wavrickDeferWorkCloudLoad &&
        (_wavrickActivePageName === "work" || getCurrentSession()?.role === "voice")
      ) {
        // hydrateAllCloudData 済みなので再取得せず描画のみ
        // 詳細を開いているときだけ forceDetail（一覧中に別案件詳細へ飛ばさない）
        paintWorkdataUpdated({
          reason: reason || "refresh",
          requestId: getWorkSelectedRequestId() || "",
          forceDetail: isWorkCaseDetailOpen()
        });
      }
      if (
        !_wavrickDeferAdminDashboardLoad &&
        getCurrentSession()?.role === "admin" &&
        _wavrickActivePageName !== "login" &&
        (_wavrickActivePageName === "admin" || !adminDataState.dataReady)
      ) {
        await loadAdminData({ reason: reason || "refresh", force: true, silent: true });
      }
      if (
        !_wavrickDeferRecruitmentsCloudLoad &&
        _wavrickActivePageName === "recruitments" &&
        typeof refreshRecruitmentsPage === "function"
      ) {
        void refreshRecruitmentsPage();
      }
      if (SOFT_CLOUD_REFRESH_REASONS.has(String(reason || ""))) {
        _softCloudRefreshAt = Date.now();
      }
      window.dispatchEvent(
        new CustomEvent("wavrick:clouddata-ready", { detail: { reason: reason || "refresh" } })
      );
    } finally {
      cloudRefreshInFlight = null;
      const queued = cloudRefreshQueuedReason;
      cloudRefreshQueuedReason = null;
      if (queued) {
        void refreshAllAppCloudData(queued);
      }
    }
  })();
  return cloudRefreshInFlight;
}

async function ensureSupabaseAuthForLocalSession() {
  const session = getCurrentSession();
  if (!session?.email) return true;
  return recoverSupabaseAuthSession({ retries: 2, waitMs: 8000 });
}

async function reconcileLocalSessionWithJwt() {
  if (!isSupabaseEnabled()) return;
  // Password-recovery links must not be signed out by a mismatched leftover wavrick_session.
  try {
    if (sessionStorage.getItem("wavrick_password_recovery") === "1") return;
  } catch {
    /* ignore */
  }
  await waitForSupabaseAuthReady();
  const local = getCurrentSession();
  if (!local?.email) return;
  let hasJwt = await ensureSupabaseAuthForLocalSession();
  if (!hasJwt) {
    await new Promise((resolve) => setTimeout(resolve, 400));
    hasJwt = await ensureSupabaseAuthForLocalSession();
  }
  if (!hasJwt && local.role === "admin") {
    // リロード直後は JWT 復元が遅れる。ここでログアウトすると運営ダッシュボードが必ず失敗する。
    hasJwt = await forceRestoreSupabaseSession({ waitMs: 8000 });
  }
  const { data, error } = await supabaseClient.auth.getSession();
  if (error) return;
  const jwtEmail = data?.session?.user?.email?.toLowerCase().trim();
  const localEmail = local.email.toLowerCase().trim();
  if (!jwtEmail) {
    if (local.role === "admin") {
      const refreshed = await refreshSupabaseSessionForAdmin();
      if (!refreshed.ok) {
        // 即ログアウトしない。ensureAdminDashboardReady 側で再試行・エラー表示する。
        console.warn("[wavrick] admin JWT still missing after restore — keep local session for retry");
      }
    }
    return;
  }
  if (jwtEmail !== localEmail) {
    await performWavrickLogout({
      redirectTo: "login",
      loginMessage: "別のアカウントでログインされています。もう一度ログインしてください。"
    });
  }
}

async function insertRemote(table, payload) {
  if (!isSupabaseEnabled()) return { ok: false, skipped: true };
  const { error } = await supabaseClient.from(table).insert({
    ...payload,
    created_at: new Date().toISOString()
  });
  if (error) return { ok: false, error };
  return { ok: true };
}

async function upsertRemote(table, payload, onConflict, retries = 2) {
  if (!isSupabaseEnabled()) return { ok: false, skipped: true };
  let lastError = null;
  for (let attempt = 0; attempt < retries; attempt++) {
    const query = supabaseClient.from(table).upsert(payload, onConflict ? { onConflict } : undefined);
    const { error } = await query;
    if (!error) return { ok: true };
    lastError = error;
    // RLS / permission は一時障害ではない — リトライしても同じ結果
    if (isRlsOrPermissionError(error)) break;
    if (attempt < retries - 1) await cloudSyncDelay(400);
  }
  return { ok: false, error: lastError };
}

/**
 * workflow をクラウドへ安全に永続化する。
 * - 全エイリアスのリモートをマージ（決済・納品を落とさない）
 * - 既存 UUID 行は UPDATE で揃えるが、新規 UUID 行は作らない
 * - forcePaymentFields でもリモート取得をスキップしない
 */
async function upsertWorkflowRemoteSafe(wf, requestOrKeys = null, options = {}) {
  if (!wf?.requestId || !isSupabaseEnabled()) return { ok: false, skipped: true };
  initSupabaseClient();
  if (!supabaseClient) return { ok: false, skipped: true };

  const Sync = globalThis.WavrickWorkflowSync;
  if (Sync?.persistWorkflow) {
    const result = await Sync.persistWorkflow(wf, requestOrKeys || wf, {
      client: supabaseClient,
      forcePaymentFields: Boolean(options.forcePaymentFields),
      forceCancelFields: Boolean(options.forceCancelFields),
      skipAuth: Boolean(options.skipAuth)
    });
    // signal は persistWorkflow 内の 1 回だけ。ここではローカル alias を揃えるのみ。
    if (result?.ok) {
      syncWorkflowAliasesIntoStore(
        typeof requestOrKeys === "object" && !Array.isArray(requestOrKeys) ? [requestOrKeys] : null
      );
    }
    return result;
  }

  // Fallback if sync module missing
  const keys = [
    ...new Set(
      (requestOrKeys ? listRequestWorkflowAliasKeys(requestOrKeys) : [wf.requestId])
        .map((k) => String(k || "").trim())
        .filter(Boolean)
    )
  ];
  let merged = { ...wf };
  for (const key of keys) {
    try {
      const remote = await fetchRemoteWorkflowByAnyId(key);
      if (remote.row) merged = mergeWorkflowPair(remote.row, merged) || merged;
    } catch (err) {
      console.warn("[wavrick] upsertWorkflowRemoteSafe fetch failed", key, err);
    }
  }
  if (options.forcePaymentFields && isWorkflowPaymentCleared(wf)) {
    merged.paymentStatus = wf.paymentStatus;
    merged.paymentMode = wf.paymentMode || merged.paymentMode;
    merged.provisionalPaidAt = wf.provisionalPaidAt || merged.provisionalPaidAt;
    merged.stripePaymentIntentId = wf.stripePaymentIntentId || merged.stripePaymentIntentId;
  }
  if (options.forceCancelFields && wf.cancelNegotiation && typeof wf.cancelNegotiation === "object") {
    merged.cancelNegotiation = { ...wf.cancelNegotiation };
  }
  merged.updatedAt = new Date().toISOString();
  let anyOk = false;
  let lastError = null;
  const workflows = getWorkflows();
  const canonical = keys.find((k) => /^req_/i.test(k)) || wf.requestId;
  const expectCancel = Boolean(
    options.forceCancelFields && merged.cancelNegotiation && typeof merged.cancelNegotiation === "object"
  );
  for (const key of keys) {
    const isUuid = /^[0-9a-f-]{36}$/i.test(key);
    const payload = mapWorkflowToRemote({ ...merged, requestId: key });
    const existing = await supabaseClient
      .from(TABLES.requestWorkflows)
      .select("requestid")
      .eq("requestid", key)
      .maybeSingle();
    if (existing?.data) {
      const { data, error } = await supabaseClient
        .from(TABLES.requestWorkflows)
        .update(payload)
        .eq("requestid", key)
        .select(expectCancel ? "requestid,cancel_negotiation" : "requestid");
      if (!error && Array.isArray(data) && data.length) {
        if (expectCancel) {
          const remoteCn = data[0]?.cancel_negotiation;
          const expectStatus = String(merged.cancelNegotiation?.status || "");
          const expectAt = String(merged.cancelNegotiation?.requestedAt || "");
          const remoteStatus = String(remoteCn?.status || "");
          const remoteAtMs = Date.parse(remoteCn?.requestedAt || 0) || 0;
          const expectAtMs = Date.parse(expectAt) || 0;
          const atOk =
            !expectAt ||
            (expectAtMs && remoteAtMs && expectAtMs === remoteAtMs) ||
            String(remoteCn?.requestedAt || "") === expectAt;
          if (remoteStatus !== expectStatus || !atOk) {
            lastError = { message: "cancel_negotiation_not_persisted" };
          } else {
            anyOk = true;
            workflows[key] = { ...merged, requestId: key };
          }
        } else {
          anyOk = true;
          workflows[key] = { ...merged, requestId: key };
        }
      } else lastError = error || { message: "workflow_update_empty" };
    } else if (!isUuid && key === canonical) {
      const result = await upsertRemote(TABLES.requestWorkflows, payload, "requestid");
      if (result?.ok) {
        anyOk = true;
        workflows[key] = { ...merged, requestId: key };
      } else lastError = result?.error;
    }
  }
  if (anyOk) {
    persistWorkflowsLocalStorage(workflows);
    syncWorkflowAliasesIntoStore();
    if (globalThis.WavrickTalentStats) globalThis.WavrickTalentStats.invalidateCache();
    void signalWorkdataChangedSafe({ requestId: canonical });
  }
  return anyOk ? { ok: true } : { ok: false, error: lastError };
}

async function refreshSupabaseSessionForAdmin() {
  if (!initSupabaseClient() || !supabaseClient) return { ok: false, reason: "no_supabase" };
  const local = getCurrentSession();
  if (local?.role !== "admin") return { ok: true, skipped: true };
  const read = async () => {
    const { data } = await supabaseClient.auth.getSession();
    return data?.session?.access_token || "";
  };
  let token = await read();
  if (!isUsableSupabaseAccessToken(token)) {
    try {
      const refreshPromise = supabaseClient.auth.refreshSession();
      const { data: refreshed } =
        typeof withTimeout === "function"
          ? await withTimeout(refreshPromise, 15000, "admin_refresh_session")
          : await refreshPromise;
      token = refreshed?.session?.access_token || "";
    } catch (error) {
      console.warn("[wavrick] refreshSupabaseSessionForAdmin failed", error);
      return { ok: false, reason: "session_expired" };
    }
  }
  if (!isUsableSupabaseAccessToken(token)) return { ok: false, reason: "session_expired" };
  return { ok: true, accessToken: token };
}

