async function fetchAdminDashboardSnapshot(options = {}) {
  if (!isSupabaseEnabled()) return null;
  initSupabaseClient();
  if (!supabaseClient) return null;

  const budgetMs = Math.max(8000, Number(options.budgetMs) || 45000);
  // 外側 adminFetchWithTimeout と二重タイムアウトしないよう、RPC 1回分を予算内に収める
  const rpcMs = Math.min(28000, Math.max(8000, Math.floor(budgetMs * 0.7)));
  const refreshMs = Math.min(12000, Math.max(4000, Math.floor(budgetMs * 0.25)));
  const startedAt = Date.now();
  const remaining = () => Math.max(0, budgetMs - (Date.now() - startedAt));

  const callSnapshot = async (rpcName) => {
    if (remaining() < 2500) return null;
    const run = async () => {
      const { data, error } = await supabaseClient.rpc(rpcName);
      if (error) {
        console.warn(`[wavrick] ${rpcName} failed`, error);
        return null;
      }
      if (!data || data.ok === false) {
        console.warn(`[wavrick] ${rpcName} forbidden`, data?.error);
        return null;
      }
      return data;
    };
    try {
      return typeof withTimeout === "function"
        ? await withTimeout(run(), Math.min(rpcMs, remaining()), rpcName)
        : await run();
    } catch (error) {
      console.warn(`[wavrick] ${rpcName} timed out or failed`, error);
      return null;
    }
  };

  let snapshot = await callSnapshot("get_admin_dashboard_snapshot");
  if (!snapshot && remaining() > refreshMs + 3000) {
    try {
      const refreshPromise = supabaseClient.auth.refreshSession();
      if (typeof withTimeout === "function") {
        await withTimeout(refreshPromise, Math.min(refreshMs, remaining()), "admin_snapshot_refresh");
      } else {
        await refreshPromise;
      }
    } catch (error) {
      console.warn("[wavrick] snapshot auth refresh failed", error);
    }
    await new Promise((resolve) => setTimeout(resolve, 250));
    snapshot = await callSnapshot("get_admin_dashboard_snapshot");
  }
  if (snapshot) return snapshot;

  const legacy = await callSnapshot("get_admin_directory");
  if (!legacy) return null;
  return {
    ...legacy,
    youtubeRequests: [],
    workflows: [],
    notifications: []
  };
}

