async function fetchRemoteYoutubeRequestByAnyId(requestId) {
  const id = String(requestId || "").trim();
  if (!id || !isSupabaseEnabled()) return { row: null, error: "disabled" };
  initSupabaseClient();
  if (!supabaseClient) return { row: null, error: "no_client" };
  const hasJwt = await hasValidSupabaseAuthSession();
  if (!hasJwt) return { row: null, error: "no_jwt" };

  const byRequestId = await softAwait(
    supabaseClient.from(TABLES.youtubeRequests).select("*").eq("requestid", id).maybeSingle(),
    8000,
    `yt_by_requestid_${id.slice(0, 8)}`
  );
  if (byRequestId?.data) {
    return { row: mapYoutubeRequestFromRemote(byRequestId.data), error: null, via: "requestid" };
  }

  const uuidLike = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id);
  if (uuidLike) {
    const byId = await softAwait(
      supabaseClient.from(TABLES.youtubeRequests).select("*").eq("id", id).maybeSingle(),
      8000,
      `yt_by_uuid_${id.slice(0, 8)}`
    );
    if (byId?.data) {
      return { row: mapYoutubeRequestFromRemote(byId.data), error: null, via: "id" };
    }
    if (byId?.error) return { row: null, error: byId.error };
  }

  if (byRequestId?.error) return { row: null, error: byRequestId.error };
  return { row: null, error: "not_found" };
}

function isWorkflowAliasUuid(value) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
    String(value || "").trim()
  );
}

function rememberYoutubeRowId(requestId, uuid, requestidFromRemote = "") {
  const rid = String(requestId || requestidFromRemote || "").trim();
  const id = String(uuid || "").trim();
  if (!rid || !isWorkflowAliasUuid(id)) return null;
  let match = null;
  try {
    const localRows = JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]");
    match = localRows.find(
      (r) => r.requestId === rid || r.rowId === rid || String(r.id || "") === rid || r.rowId === id
    );
  } catch {
    /* ignore */
  }
  const next = {
    ...(match || {}),
    requestId: String(match?.requestId || requestidFromRemote || rid).trim() || rid,
    rowId: id,
    id
  };
  upsertLocalYoutubeRequest(next);
  return next;
}

/**
 * ローカル youtube 行に UUID (rowId) が欠けると、声優が更新した UUID 側 workflow を
 * 取りに行けず顧客画面が古いままになる。クラウドから id を補完する。
 */
async function resolveYoutubeAliasKeysForWorkflowFetch(requestId) {
  const id = String(requestId || "").trim();
  const tryKeys = [];
  const push = (v) => {
    const key = String(v || "").trim();
    if (key && !tryKeys.includes(key)) tryKeys.push(key);
  };
  push(id);

  let match = null;
  try {
    const localRows = JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]");
    match = localRows.find(
      (r) => r.requestId === id || r.rowId === id || String(r.id || "") === id
    );
    if (match) {
      for (const k of listRequestWorkflowAliasKeys(match)) push(k);
    }
  } catch {
    /* ignore */
  }

  if (!tryKeys.some(isWorkflowAliasUuid) && supabaseClient) {
    try {
      // 1) requestid 直指定
      let data = null;
      const byReq = await withTimeout(
        Promise.resolve(
          supabaseClient
            .from(TABLES.youtubeRequests)
            .select("id,requestid,email")
            .eq("requestid", id)
            .maybeSingle()
        ),
        4000,
        `yt_alias_${id.slice(0, 8)}`
      );
      data = byReq?.data || null;

      // 2) 顧客メール配下を舐めて requestid / id 一致を探す（ローカル専用 ID ズレ対策）
      if (!data?.id) {
        const email = String(getCurrentSession()?.email || match?.email || "")
          .toLowerCase()
          .trim();
        if (email) {
          const listed = await withTimeout(
            Promise.resolve(
              supabaseClient
                .from(TABLES.youtubeRequests)
                .select("id,requestid,email")
                .eq("email", email)
                .order("created_at", { ascending: false })
                .limit(200)
            ),
            6000,
            `yt_alias_list_${id.slice(0, 8)}`
          );
          const rows = Array.isArray(listed?.data) ? listed.data : [];
          data =
            rows.find(
              (r) => String(r.requestid || "") === id || String(r.id || "") === id
            ) || null;
        }
      }

      const uuid = String(data?.id || "").trim();
      if (uuid) {
        push(uuid);
        const reqKey = String(data.requestid || id).trim();
        if (reqKey && reqKey !== id) push(reqKey);
        rememberYoutubeRowId(id, uuid, data.requestid || id);
      }
    } catch (err) {
      console.warn("[wavrick] resolve youtube alias uuid failed", err);
    }
  }

  // 注意: 同じ声優が複数案件に出るため、talentId 一致だけで UUID を推測してはいけない。
  return tryKeys;
}

/** コンソール用: 案件のクラウド実体とローカル差分を返す */
async function diagnoseCaseCastSync(requestId) {
  const rid = String(requestId || "").trim();
  initSupabaseClient();
  const localYt = getLocalYoutubeRequests().find(
    (r) => r.requestId === rid || r.rowId === rid || String(r.id || "") === rid
  );
  const localWf = getWorkflows();
  const keys = await resolveYoutubeAliasKeysForWorkflowFetch(rid);
  const remote = {};
  for (const key of keys) {
    const { data, error } = await supabaseClient
      .from(TABLES.requestWorkflows)
      .select("requestid,updated_at,transaction_phase,status,cast_acceptance")
      .eq("requestid", key)
      .maybeSingle();
    remote[key] = {
      error: error?.message || null,
      updatedAt: data?.updated_at || null,
      phase: data?.transaction_phase || null,
      status: data?.status || null,
      cast: Array.isArray(data?.cast_acceptance)
        ? data.cast_acceptance.map((s) => ({
            i: s.speakerIndex,
            mode: s.mode,
            status: s.status,
            talentId: s.talentId || "",
            apps: Array.isArray(s.applications) ? s.applications.length : 0
          }))
        : null
    };
  }
  const ytRemote = await supabaseClient
    .from(TABLES.youtubeRequests)
    .select("id,requestid,email,updated_at")
    .eq("requestid", rid)
    .maybeSingle();
  const talentHits = Object.entries(localWf)
    .filter(([, wf]) =>
      (wf?.castAcceptance || []).some((s) =>
        /pyonyunyu@stayhome\.li|teyo785@tatsu\.uk/i.test(String(s?.talentId || ""))
      )
    )
    .map(([key, wf]) => ({
      key,
      updatedAt: wf.updatedAt,
      cast: (wf.castAcceptance || []).map((s) => ({
        i: s.speakerIndex,
        mode: s.mode,
        status: s.status,
        talentId: s.talentId || "",
        apps: (s.applications || []).length
      }))
    }));
  return {
    rid,
    keys,
    localYt: localYt
      ? { requestId: localYt.requestId, rowId: localYt.rowId || localYt.id || null, email: localYt.email }
      : null,
    ytRemote: { data: ytRemote.data, error: ytRemote.error?.message || null },
    remote,
    localTalentHits: talentHits
  };
}

async function repairCaseCastSync(requestId) {
  const rid = String(requestId || "").trim();
  const before = await diagnoseCaseCastSync(rid);
  const applied = await applyRemoteWorkflowDetail(rid);
  const afterLocal = getWorkflows()[rid] || null;
  const yt = getLocalYoutubeRequests().find((r) => r.requestId === rid || r.rowId === rid);
  paintWorkdataUpdated({ requestId: rid });
  return {
    applied,
    before,
    after: {
      rowId: yt?.rowId || yt?.id || null,
      updatedAt: afterLocal?.updatedAt || null,
      cast: (afterLocal?.castAcceptance || []).map((s) => ({
        i: s.speakerIndex,
        mode: s.mode,
        status: s.status,
        talentId: s.talentId || "",
        apps: (s.applications || []).length
      }))
    }
  };
}

