async function fetchRemoteWorkflowByAnyId(requestId) {
  const id = String(requestId || "").trim();
  if (!id || !isSupabaseEnabled()) return { row: null, error: "disabled" };
  initSupabaseClient();
  if (!supabaseClient) return { row: null, error: "no_client" };
  const hasJwt = await hasValidSupabaseAuthSession();
  if (!hasJwt) return { row: null, error: "no_jwt" };

  const tryKeys = await resolveYoutubeAliasKeysForWorkflowFetch(id);
  const Sync = globalThis.WavrickWorkflowSync;
  const selectCols =
    Sync?.WORKFLOW_SELECT_COLS ||
    "requestid,status,messages,deliveries,cast_acceptance,transaction_phase,paymentstatus,payment_mode,partial_retakes,cancel_negotiation,updated_at,created_at";

  let merged = null;
  let lastError = null;

  // One IN query for all aliases (avoids N× select=* timeouts on fat delivery rows).
  if (tryKeys.length) {
    try {
      const { data, error } = await withTimeout(
        supabaseClient.from(TABLES.requestWorkflows).select(selectCols).in("requestid", tryKeys),
        8000,
        "wf_fetch_batch"
      );
      if (!error && Array.isArray(data)) {
        for (const raw of data) {
          const mapped = stripHeavyWorkflowForLocalStorage(mapWorkflowFromRemote(raw));
          merged = mergeWorkflowPair(merged, mapped);
        }
      } else if (error) {
        lastError = error;
      }
    } catch (err) {
      lastError = err;
    }
  }

  if (merged) return { row: merged, error: null, keys: tryKeys };

  // Fallback: sequential, req_* first
  const ordered = [...tryKeys].sort(
    (a, b) => Number(/^req_/i.test(b)) - Number(/^req_/i.test(a))
  );
  for (const key of ordered) {
    try {
      const { data, error } = await withTimeout(
        supabaseClient
          .from(TABLES.requestWorkflows)
          .select(selectCols)
          .eq("requestid", key)
          .maybeSingle(),
        5000,
        `wf_fetch_${key.slice(0, 8)}`
      );
      if (data) {
        merged = mergeWorkflowPair(merged, stripHeavyWorkflowForLocalStorage(mapWorkflowFromRemote(data)));
      } else if (error) {
        lastError = error;
      }
    } catch (err) {
      lastError = err;
    }
  }
  if (merged) return { row: merged, error: null, keys: tryKeys };
  return { row: null, error: lastError || "not_found", keys: tryKeys };
}

/** 収録・進捗表示前にクラウドの最新 workflow をエイリアス全体へ反映（短時間で打ち切る） */
async function ensureFreshWorkflowForRequest(request, options = {}) {
  if (!request?.requestId && !request?.rowId) {
    return getWorkflowForRequest("", "", request);
  }
  const base = getWorkflowForRequest(request.requestId, request.status, request);
  if (!isSupabaseEnabled()) return base;

  // 既に収録解禁ならクラウド待ちしない
  if (!options.force && isRecordingUnlocked(base, request, getCurrentSession())) {
    return base;
  }

  const budgetMs = Number.isFinite(options.timeoutMs) ? options.timeoutMs : 6000;
  try {
    return await withTimeout(
      (async () => {
        try {
          await withTimeout(ensureSupabaseAuthForLocalSession(), Math.min(3500, budgetMs), "wf_fresh_auth");
        } catch {
          /* ignore — ローカル判定へフォールバック */
        }
        const keys = listRequestWorkflowAliasKeys(request);
        const remote = await fetchRemoteWorkflowByAnyId(keys[0] || request.requestId || request.rowId);
        if (!remote.row) return base;
        const next = mergeWorkflowPair(base, remote.row);
        next.updatedAt = remote.row.updatedAt || next.updatedAt || new Date().toISOString();
        saveWorkflowAliases(request, next, { syncRemote: false });
        syncWorkflowAliasesIntoStore([request]);
        return getWorkflowForRequest(request.requestId, request.status, request);
      })(),
      budgetMs,
      "ensure_fresh_workflow"
    );
  } catch (err) {
    console.warn("[wavrick] ensureFreshWorkflowForRequest aborted", err);
    return base;
  }
}

/** workflow.confirmed_deliverables から収録用メディア／台本を取り出す */
function mediaFieldsFromConfirmedDeliverables(confirmed) {
  const c = confirmed && typeof confirmed === "object" ? confirmed : null;
  if (!c) {
    return {
      videoUrl: "",
      script: "",
      scriptsBySpeaker: {},
      castSlots: null,
      rawAudioUrl: null,
      cleanedAudioUrl: null,
      confirmedDeliverables: null
    };
  }
  return {
    videoUrl: String(c.videoUrl || c.video_url || "").trim(),
    script: String(c.scriptFull || c.script || "").trim(),
    scriptsBySpeaker: normalizeScriptsBySpeakerMap(c.scriptsBySpeaker || c.scripts_by_speaker),
    castSlots: Array.isArray(c.castSlots)
      ? c.castSlots
      : Array.isArray(c.cast_slots)
        ? c.cast_slots
        : null,
    rawAudioUrl: c.rawAudioUrl || c.raw_audio_url || null,
    cleanedAudioUrl: c.cleanedAudioUrl || c.cleaned_audio_url || null,
    confirmedDeliverables: c
  };
}

function buildRequestStubFromWorkflow(requestId, wf, extras = {}) {
  const id = String(requestId || wf?.requestId || "").trim();
  const slots = Array.isArray(wf?.castAcceptance) ? wf.castAcceptance : [];
  const talentIds = slots.map((s) => String(s?.talentId || "").trim()).filter(Boolean);
  const fromConfirmed = mediaFieldsFromConfirmedDeliverables(wf?.confirmedDeliverables);
  const scriptsBySpeaker =
    Object.keys(normalizeScriptsBySpeakerMap(extras.scriptsBySpeaker || {})).length
      ? normalizeScriptsBySpeakerMap(extras.scriptsBySpeaker)
      : fromConfirmed.scriptsBySpeaker;
  return {
    requestId: id,
    rowId: extras.rowId || "",
    name: extras.name || "依頼案件",
    email: extras.email || "",
    videoUrl: String(extras.videoUrl || fromConfirmed.videoUrl || "").trim(),
    tone: extras.tone || "",
    deadline: extras.deadline || "",
    status: wf?.status || REQUEST_STATUS_FLOW[0],
    script: String(extras.script || fromConfirmed.script || "").trim(),
    castSlots: extras.castSlots || fromConfirmed.castSlots || slots,
    scriptsBySpeaker,
    confirmedDeliverables: extras.confirmedDeliverables || fromConfirmed.confirmedDeliverables || null,
    rawAudioUrl: extras.rawAudioUrl || fromConfirmed.rawAudioUrl || null,
    cleanedAudioUrl: extras.cleanedAudioUrl || fromConfirmed.cleanedAudioUrl || null,
    selectedTalentId: extras.selectedTalentId || talentIds.join(","),
    selectedTalentName: extras.selectedTalentName || "",
    createdAt: extras.createdAt || "",
    updatedAt: wf?.updatedAt || extras.updatedAt || new Date().toISOString()
  };
}

