function mapAdminPreferenceRowFromRemote(row) {
  const prefs = row.preferences && typeof row.preferences === "object" ? row.preferences : {};
  const parts = [];
  if (prefs.selectedTalent?.displayName) parts.push(`選択声優: ${prefs.selectedTalent.displayName}`);
  if (prefs.workSelectedRequestId) parts.push(`案件: ${prefs.workSelectedRequestId}`);
  if (prefs.ytFormAutosave) parts.push("依頼フォーム作業途中あり");
  if (prefs.ytPipelineState) parts.push("パイプライン作業途中あり");
  return {
    email: row.email || "",
    kind: "ユーザー設定",
    summary: parts.join(" / ") || "（設定データ）",
    count: Object.keys(prefs).length,
    payload: prefs,
    updatedAt: row.updated_at || "",
    source: "supabase"
  };
}

