function loadLocalAdminDraftRows() {
  const D = getYtDraftsApi();
  if (!D) return [];
  const rows = [];
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i) || "";
    if (!key.startsWith("wavrick_yt_drafts_index_v1:")) continue;
    const email = key.slice("wavrick_yt_drafts_index_v1:".length);
    for (const draft of D.listLocal(email)) {
      rows.push({
        draftId: draft.draftId,
        email: draft.email || email,
        title: draft.title || "無題の下書き",
        updatedAt: draft.updatedAt || draft.createdAt || "",
        payload: draft.payload || {},
        source: "local"
      });
    }
  }
  return rows;
}

function mergeAdminRowsByKey(rows, keyFn, updatedKey = "updatedAt") {
  const map = new Map();
  for (const row of rows || []) {
    const key = keyFn(row);
    if (!key) continue;
    const prev = map.get(key);
    const rowTs = new Date(row[updatedKey] || row.createdAt || 0).getTime();
    const prevTs = prev ? new Date(prev[updatedKey] || prev.createdAt || 0).getTime() : -1;
    const source =
      row.source === "supabase" || prev?.source === "supabase" ? "supabase" : row.source || prev?.source || "local";
    if (!prev || rowTs >= prevTs) map.set(key, { ...row, source });
    else map.set(key, { ...prev, source });
  }
  return [...map.values()];
}

function buildAdminWorkflowRows(localWorkflows, remoteWorkflows) {
  const map = new Map();
  const touch = (wf, source) => {
    if (!wf?.requestId) return;
    const prev = map.get(wf.requestId);
    if (source === "supabase") {
      map.set(wf.requestId, { ...wf, source: "supabase" });
      return;
    }
    if (prev?.source === "supabase") {
      const prevRatings = Array.isArray(prev.ratings) ? prev.ratings : [];
      const localRatings = Array.isArray(wf.ratings) ? wf.ratings : [];
      if (!prevRatings.length && localRatings.length) {
        map.set(wf.requestId, { ...prev, ratings: localRatings });
      }
      return;
    }
    const rowTs = new Date(wf.updatedAt || 0).getTime();
    const prevTs = prev ? new Date(prev.updatedAt || 0).getTime() : -1;
    if (!prev || rowTs >= prevTs) map.set(wf.requestId, { ...wf, source: "local" });
  };
  for (const wf of remoteWorkflows || []) touch(wf, "supabase");
  for (const wf of Object.values(localWorkflows || {})) touch(wf, "local");
  return [...map.values()].sort((a, b) => new Date(b.updatedAt || 0) - new Date(a.updatedAt || 0));
}

function summarizeWorkflowSlots(wf) {
  const slots = Array.isArray(wf?.castAcceptance) ? wf.castAcceptance : [];
  if (!slots.length) return "-";
  return slots
    .map((s) => `話者${s.speakerIndex}:${s.mode || "?"}${s.status ? `/${s.status}` : ""}`)
    .join(" / ");
}

async function findRemoteAccount(role, email) {
  if (!isSupabaseEnabled()) return null;
  const table = role === "voice" ? TABLES.voiceAccounts : TABLES.customerAccounts;
  const { data, error } = await supabaseClient
    .from(table)
    .select("*")
    .ilike("email", email)
    .limit(1);
  if (error || !Array.isArray(data) || !data.length) return null;
  return data[0];
}

function findLocalAccountByEmail(storageKey, email) {
  const normalized = (email || "").toLowerCase().trim();
  const accounts = JSON.parse(localStorage.getItem(storageKey) || "[]");
  return accounts.find((row) => (row.email || "").toLowerCase().trim() === normalized) || null;
}

const LOGIN_LOOKUP_TIMEOUT_MS = 12000;

function withTimeout(promise, ms, label) {
  let timer = null;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => {
      reject(new Error(`${label || "request"}_timeout`));
    }, ms);
  });
  return Promise.race([promise, timeout]).finally(() => {
    if (timer) clearTimeout(timer);
  });
}

function purgeSupabaseAuthStorageKeys() {
  try {
    const keys = [];
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key && /^sb-.*-auth-token/.test(key)) keys.push(key);
    }
    keys.forEach((key) => localStorage.removeItem(key));
  } catch {
    /* ignore */
  }
}

/** Serialize auth mutations — navigator.locks are disabled on this client. */
let _supabaseAuthOpChain = Promise.resolve();

function enqueueSupabaseAuthOp(fn) {
  const run = _supabaseAuthOpChain.then(fn, fn);
  _supabaseAuthOpChain = run.then(
    () => undefined,
    () => undefined
  );
  return run;
}

function recreateSupabaseClientAfterAuthReset() {
  purgeSupabaseAuthStorageKeys();
  supabaseClient = null;
  window.wavrickSupabaseClient = null;
  supabaseAuthBootstrapListenerBound = false;
  supabaseAuthListenerBound = false;
  initSupabaseClient();
  bindSupabaseAuthListener();
}

/**
 * Local sign-out, serialized. Prefer scope "local" so logout→re-login does not
 * fight a slow global revoke / concurrent signInWithPassword.
 */
async function signOutWavrickSupabase(options = {}) {
  const scope = options.scope === "global" ? "global" : "local";
  if (!initSupabaseClient() || !supabaseClient) {
    purgeSupabaseAuthStorageKeys();
    return { ok: true, skipped: true };
  }
  return enqueueSupabaseAuthOp(async () => {
    if (!supabaseClient) {
      purgeSupabaseAuthStorageKeys();
      return { ok: true, skipped: true };
    }
    try {
      if (!options.force) {
        const { data } = await supabaseClient.auth.getSession();
        if (!data?.session?.access_token) {
          purgeSupabaseAuthStorageKeys();
          return { ok: true, alreadySignedOut: true };
        }
      }
      await withTimeout(
        supabaseClient.auth.signOut({ scope }),
        Number.isFinite(options.timeoutMs) ? options.timeoutMs : 8000,
        "sign_out"
      );
      return { ok: true };
    } catch (error) {
      console.warn("[wavrick] signOut failed — resetting auth storage", error);
      recreateSupabaseClientAfterAuthReset();
      return { ok: false, error };
    }
  });
}

/** ログイン画面: 壊れた Supabase セッションを除去（デスクトップのタブ競合対策） */
async function prepareLoginPageAuth(options = {}) {
  if (!initSupabaseClient() || !supabaseClient) return;
  if (!options.force && getCurrentSession()?.email) return;
  // Finish any in-flight logout signOut before touching auth again.
  await _supabaseAuthOpChain.catch(() => {});
  try {
    const { data } = await supabaseClient.auth.getSession();
    if (!data?.session?.access_token) return;
  } catch {
    /* fall through and clear */
  }
  await signOutWavrickSupabase({ scope: "local", force: true, timeoutMs: 8000 });
}

function readLoginFormValues(form, emailInput) {
  const data = Object.fromEntries(new FormData(form).entries());
  return {
    email: String(emailInput?.value || data.email || "")
      .toLowerCase()
      .trim(),
    // Do not trim passwords — trailing/leading spaces may be intentional.
    password: String(document.getElementById("loginPassword")?.value || data.password || ""),
    adminPasscode: String(document.getElementById("loginAdminPasscode")?.value || data.adminPasscode || "")
  };
}

function formatPasswordSignInFailureMessage(signInResult) {
  if (!signInResult || signInResult.ok) return "";
  if (signInResult.reason === "auth_timeout") {
    return "接続がタイムアウトしました。ネットワークを確認して再度お試しください。";
  }
  const detail = String(signInResult.detail || "").toLowerCase();
  if (detail.includes("email not confirmed")) {
    return "メールアドレスが未確認です。登録時の確認メールのリンクを開いてから再度お試しください。";
  }
  if (
    detail.includes("invalid login credentials") ||
    detail.includes("invalid credentials") ||
    detail.includes("invalid email or password")
  ) {
    return "メールアドレスまたはパスワードが違います。";
  }
  return "ログインに失敗しました。時間をおいて再度お試しください。";
}

/** メールアドレスからログイン種別を自動判別（優先: 運営 → 声優 → 顧客） */
async function resolveLoginRoleFromEmail(email) {
  const normalized = (email || "").toLowerCase().trim();
  if (!normalized.includes("@")) return { role: null, roles: [], reason: "invalid_email" };

  if (!initSupabaseClient() || !supabaseClient) {
    if (findLocalAccountByEmail("wavrick_voice_accounts", normalized)) {
      return { role: "voice", roles: ["voice"] };
    }
    if (findLocalAccountByEmail("wavrick_customer_accounts", normalized)) {
      return { role: "customer", roles: ["customer"] };
    }
    return { role: null, roles: [], reason: "not_found" };
  }

  try {
    const { data: loginInfo, error: loginError } = await withTimeout(
      supabaseClient.rpc("get_wavrick_login_roles", { p_email: normalized }),
      LOGIN_LOOKUP_TIMEOUT_MS,
      "get_wavrick_login_roles"
    );
    if (!loginError && loginInfo && typeof loginInfo === "object") {
      const roles = Array.isArray(loginInfo.roles) ? loginInfo.roles.map(String) : [];
      const primary = loginInfo.primary ? String(loginInfo.primary) : roles[0] || null;
      if (primary) {
        return { role: primary, roles, multiple: roles.length > 1 };
      }
    }
    if (loginError) {
      console.warn("[wavrick] get_wavrick_login_roles failed", loginError);
    }
  } catch (error) {
    console.warn("[wavrick] get_wavrick_login_roles unavailable", error);
  }

  try {
    const { data: rpcRole, error: rpcError } = await withTimeout(
      supabaseClient.rpc("resolve_wavrick_login_role", { p_email: normalized }),
      LOGIN_LOOKUP_TIMEOUT_MS,
      "resolve_wavrick_login_role"
    );
    if (!rpcError && rpcRole) {
      return { role: rpcRole, roles: [String(rpcRole)] };
    }
    if (rpcError) {
      console.warn("[wavrick] resolve_wavrick_login_role failed", rpcError);
    }
  } catch (error) {
    console.warn("[wavrick] resolve_wavrick_login_role unavailable", error);
  }

  try {
    const { data: profileRows, error: profileError } = await withTimeout(
      supabaseClient.from(TABLES.voiceProfiles).select("email").ilike("email", normalized).limit(1),
      LOGIN_LOOKUP_TIMEOUT_MS,
      "voice_profile_login_lookup"
    );
    if (!profileError && Array.isArray(profileRows) && profileRows.length) {
      return { role: "voice", roles: ["voice"] };
    }
  } catch (error) {
    console.warn("[wavrick] voice profile login lookup failed", error);
  }

  if (findLocalAccountByEmail("wavrick_voice_accounts", normalized)) {
    return { role: "voice", roles: ["voice"] };
  }
  if (findLocalAccountByEmail("wavrick_customer_accounts", normalized)) {
    return { role: "customer", roles: ["customer"] };
  }

  return { role: null, roles: [], reason: "not_found" };
}

/** リロード直後に前回取得分を即表示するためのキャッシュ（公開データのみ） */
const REMOTE_VOICE_PROFILES_CACHE_KEY = "wavrick_remote_voice_profiles_cache_v1";
const REMOTE_VOICE_PROFILES_CACHE_MAX_AGE_MS = 24 * 60 * 60 * 1000;

function loadRemoteVoiceProfilesCache() {
  try {
    const raw = localStorage.getItem(REMOTE_VOICE_PROFILES_CACHE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed?.rows)) return null;
    const age = Date.now() - new Date(parsed.savedAt || 0).getTime();
    if (!Number.isFinite(age) || age > REMOTE_VOICE_PROFILES_CACHE_MAX_AGE_MS) return null;
    return parsed.rows;
  } catch {
    return null;
  }
}

function saveRemoteVoiceProfilesCache(rows) {
  try {
    localStorage.setItem(
      REMOTE_VOICE_PROFILES_CACHE_KEY,
      JSON.stringify({ savedAt: new Date().toISOString(), rows: Array.isArray(rows) ? rows : [] })
    );
  } catch {
    /* quota 超過などは無視（次回フェッチで復旧） */
  }
}

function hydrateRemoteVoiceProfilesFromCache() {
  if (remoteVoiceProfiles.length) return false;
  const cached = loadRemoteVoiceProfilesCache();
  if (!cached || !cached.length) return false;
  remoteVoiceProfiles = cached;
  return true;
}

let _voiceProfilesRefreshInFlight = null;
let _voiceProfilesRefreshAt = 0;
const VOICE_PROFILES_REFRESH_MIN_GAP_MS = 5 * 60 * 1000;

async function refreshRemoteVoiceProfiles(options = {}) {
  const force = Boolean(options.force);
  if (
    !force &&
    _voiceProfilesRefreshAt &&
    Date.now() - _voiceProfilesRefreshAt < VOICE_PROFILES_REFRESH_MIN_GAP_MS
  ) {
    if (!remoteVoiceProfiles.length) hydrateRemoteVoiceProfilesFromCache();
    return remoteVoiceProfiles;
  }
  if (_voiceProfilesRefreshInFlight) return _voiceProfilesRefreshInFlight;
  _voiceProfilesRefreshInFlight = (async () => {
    if (!initSupabaseClient() || !supabaseClient) return;
    const { data, error } = await supabaseClient
      .from(TABLES.voiceProfiles)
      .select("*")
      .order("created_at", { ascending: false });
    if (error) {
      // 失敗時はキャッシュ由来の表示を維持する（空配列で上書きしない）
      console.warn("[wavrick] refreshRemoteVoiceProfiles failed", error);
      return;
    }
    remoteVoiceProfiles = Array.isArray(data) ? data.map(mapVoiceProfileFromRemote) : [];
    _voiceProfilesRefreshAt = Date.now();
    saveRemoteVoiceProfilesCache(remoteVoiceProfiles);
    renderTalents();
  })().finally(() => {
    _voiceProfilesRefreshInFlight = null;
  });
  return _voiceProfilesRefreshInFlight;
}

function mapVoiceProfileToRemote(data) {
  const P = getPricingApi();
  const normalized = P ? P.normalizeVoicePricing(data) : {};
  const samples = sanitizeVoiceSamplesForRemote(normalizeVoiceSamplesPayload(data));
  const primarySampleUrl = samples.find((s) => s.type === "url")?.value || data.sampleUrl || "";
  let avatarurl = data.avatarUrl || "";
  if (avatarurl.startsWith("data:")) avatarurl = "";
  return {
    displayname: data.displayName || "",
    email: String(data.email || "")
      .toLowerCase()
      .trim(),
    bio: data.bio || "（プロフィール未入力）",
    genres: data.genres || "",
    ng_list: data.ngList || "",
    supported_languages: (() => {
      const SL = getScriptLanguagesApi();
      const csv = SL
        ? SL.formatLanguageCsv(data.supportedLanguages || data.supportedLanguagesCsv)
        : String(data.supportedLanguages || "ja");
      return csv || "ja";
    })(),
    work_history: data.workHistory || "",
    voice_samples: samples.length ? samples : null,
    ratefrom: data.rateFrom ? Number(data.rateFrom) : null,
    price_per_minute: normalized.pricePerMinute ?? (data.pricePerMinute ? Number(data.pricePerMinute) : null),
    minimum_order_price: normalized.minimumOrderPrice ?? 0,
    additional_retake_price: normalized.additionalRetakePrice ?? 0,
    jobcount: data.jobCount ? Number(data.jobCount) : null,
    sampleurl: primarySampleUrl,
    avatarurl,
    is_active: data.isActive === true
  };
}

function mapVoiceProfileFromRemote(row) {
  const voiceSamples = parseVoiceSamplesFromStorage(row.voice_samples ?? row.voiceSamples);
  const isBanned = row.is_banned === true || Boolean(row.banned_at || row.bannedAt);
  return {
    id: row.id || "",
    displayName: row.displayname || row.displayName || "",
    email: row.email || "",
    bio: row.bio || "",
    genres: row.genres || "",
    ngList: row.ng_list || row.ngList || "",
    supportedLanguages: row.supported_languages || row.supportedLanguages || "ja",
    workHistory: row.work_history || row.workHistory || "",
    voiceSamples,
    rateFrom: row.ratefrom ?? "",
    pricePerMinute: row.price_per_minute ?? row.pricePerMinute ?? "",
    minimumOrderPrice: row.minimum_order_price ?? row.minimumOrderPrice ?? "",
    additionalRetakePrice: row.additional_retake_price ?? row.additionalRetakePrice ?? "",
    jobCount: row.jobcount ?? "",
    sampleUrl: row.sampleurl || row.sampleUrl || voiceSamples.find((s) => s.type === "url")?.value || "",
    avatarUrl: row.avatarurl || row.avatarUrl || "",
    isActive: isBanned ? false : row.is_active === true,
    isBanned,
    bannedAt: row.banned_at || row.bannedAt || null,
    stripeConnectAccountId: row.stripe_connect_account_id || row.stripeConnectAccountId || "",
    stripeIdentityVerified: row.stripe_identity_verified === true || row.stripeIdentityVerified === true,
    stripeIdentityStatus: row.stripe_identity_status || row.stripeIdentityStatus || "none",
    stripeIdentityVerifiedAt: row.stripe_identity_verified_at || row.stripeIdentityVerifiedAt || "",
    updatedAt: row.updated_at || row.created_at || ""
  };
}

