let ytAssignComposing = false;
/** 本番顧客向け UI からタイムコードを隠すとき、収録ブース用に保持 */
let ytScriptTimecodedFull = "";
let ytScriptsBySpeaker = {};
let ytAdlibSegments = [];
/** Grok 翻訳前の reconcile 下書き（タイムコード付き・未翻訳） */
let ytReconcileDraftFull = "";
let ytReconcileAdlibSegments = [];
let ytReconcileAdlibSpans = [];
let ytReconcileReady = false;
let ytSpeakerColors = {};
let ytLastSpeakerCount = 2;
let pendingSpeakerRemoveContext = null;

function pickUnusedPaletteColor(usedLowercase) {
  const used = usedLowercase || new Set();
  for (let i = 1; i <= 6; i++) {
    const c = YT_SPEAKER_DEFAULT_COLORS[i];
    if (c && !used.has(String(c).toLowerCase())) return c;
  }
  return "#888888";
}

function normalizeYtSpeakerColors(raw, count) {
  const want = Math.min(6, Math.max(1, count || getYtSpeakerCount()));
  const out = {};
  const used = new Set();
  for (let i = 1; i <= want; i++) {
    const v = raw?.[i] || raw?.[String(i)];
    if (v) {
      out[i] = String(v);
      used.add(String(v).toLowerCase());
    }
  }
  for (let i = 1; i <= want; i++) {
    if (out[i]) continue;
    const c = pickUnusedPaletteColor(used);
    out[i] = c;
    used.add(c.toLowerCase());
  }
  return out;
}

function loadYtSpeakerColors(count) {
  const want = Math.min(6, Math.max(1, count || getYtSpeakerCount()));
  try {
    const raw = localStorage.getItem(YT_SPEAKER_COLORS_KEY);
    if (raw) {
      ytSpeakerColors = normalizeYtSpeakerColors(JSON.parse(raw), want);
      return ytSpeakerColors;
    }
  } catch {
    /* ignore */
  }
  ytSpeakerColors = normalizeYtSpeakerColors({}, want);
  return ytSpeakerColors;
}

function saveYtSpeakerColors(count) {
  const want = Math.min(6, Math.max(1, count || getYtSpeakerCount()));
  ytSpeakerColors = normalizeYtSpeakerColors(ytSpeakerColors, want);
  localStorage.setItem(YT_SPEAKER_COLORS_KEY, JSON.stringify(ytSpeakerColors));
  return ytSpeakerColors;
}

function getYtSpeakerColor(speakerIndex) {
  return (
    ytSpeakerColors[speakerIndex] ||
    YT_SPEAKER_DEFAULT_COLORS[speakerIndex] ||
    "#888888"
  );
}

function ytSpeakerAccentAttr(speakerIndex) {
  return ` style="--speaker-accent:${escapeAttr(getYtSpeakerColor(speakerIndex))}"`;
}

function setYtSpeakerColor(speakerIndex, color) {
  const count = getYtSpeakerCount();
  if (speakerIndex < 1 || speakerIndex > count) return;
  ytSpeakerColors[speakerIndex] = String(color || "").trim() || getYtSpeakerColor(speakerIndex);
  saveYtSpeakerColors(count);
  closeYtSpeakerColorPopover();
  renderYtSpeakerPicker();
  renderYtSpeakerNames();
  renderYtTranscriptAssignView();
  updateYtAssignSummary();
  _wavrickSavePipelineState();
}

let ytSpeakerColorPopover = null;
let ytSpeakerPickClickTimer = null;
let ytSpeakerColorPopoverOpenedAt = 0;
let editorFullscreenHostId = null;
let editorFullscreenHintRestore = null;
let editorFullscreenDomRestore = null;

function ensureYtSpeakerColorPopover() {
  if (ytSpeakerColorPopover) return ytSpeakerColorPopover;
  const pop = document.createElement("div");
  pop.id = "ytSpeakerColorPopover";
  pop.className = "speaker-color-popover hidden";
  pop.setAttribute("role", "dialog");
  pop.setAttribute("aria-label", "話者の色を選択");
  pop.innerHTML = `
    <p class="speaker-color-popover-title">話者の色</p>
    <div class="speaker-color-popover-swatches" role="listbox"></div>
    <button type="button" class="btn-ghost speaker-color-popover-custom">その他の色…</button>
  `;
  document.body.appendChild(pop);

  const onSwatchPick = (e) => {
    const sw = e.target.closest("[data-palette-color]");
    if (!sw) return;
    e.preventDefault();
    e.stopPropagation();
    const idx = Number(pop.dataset.speakerIndex);
    const color = sw.getAttribute("data-palette-color");
    if (idx && color) setYtSpeakerColor(idx, color);
  };
  pop.querySelector(".speaker-color-popover-swatches")?.addEventListener("mousedown", onSwatchPick);
  pop.querySelector(".speaker-color-popover-swatches")?.addEventListener("click", onSwatchPick);

  pop.querySelector(".speaker-color-popover-custom")?.addEventListener("click", (e) => {
    e.preventDefault();
    e.stopPropagation();
    const idx = Number(pop.dataset.speakerIndex);
    if (idx) openYtSpeakerColorNativeInput(idx);
  });

  pop.addEventListener("mousedown", (e) => e.stopPropagation());
  pop.addEventListener("click", (e) => e.stopPropagation());

  document.addEventListener(
    "pointerdown",
    (e) => {
      if (pop.classList.contains("hidden")) return;
      if (Date.now() - ytSpeakerColorPopoverOpenedAt < 280) return;
      if (pop.contains(e.target)) return;
      if (e.target.closest("[data-speaker-pick]")) return;
      closeYtSpeakerColorPopover();
    },
    true
  );
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && !ytSpeakerColorPopover?.classList.contains("hidden")) {
      closeYtSpeakerColorPopover();
    }
  });

  ytSpeakerColorPopover = pop;
  return pop;
}

function closeYtSpeakerColorPopover() {
  ytSpeakerColorPopover?.classList.add("hidden");
}

function openYtSpeakerColorPopover(speakerIndex, anchorEl) {
  const count = getYtSpeakerCount();
  if (speakerIndex < 1 || speakerIndex > count) return;
  const pop = ensureYtSpeakerColorPopover();
  pop.dataset.speakerIndex = String(speakerIndex);
  const title = pop.querySelector(".speaker-color-popover-title");
  if (title) title.textContent = `${getYtSpeakerLabel(speakerIndex)} の色`;

  const swatches = pop.querySelector(".speaker-color-popover-swatches");
  if (swatches) {
    const current = getYtSpeakerColor(speakerIndex).toLowerCase();
    swatches.innerHTML = Object.entries(YT_SPEAKER_DEFAULT_COLORS)
      .map(([idx, color]) => {
        const sel = color.toLowerCase() === current ? " is-selected" : "";
        return `<button type="button" class="speaker-color-swatch${sel}" data-palette-color="${escapeAttr(color)}" style="--swatch-color:${escapeAttr(color)}" title="色${idx}" aria-label="色${idx}"></button>`;
      })
      .join("");
  }

  pop.classList.remove("hidden");
  ytSpeakerColorPopoverOpenedAt = Date.now();
  const anchor = anchorEl?.getBoundingClientRect?.();
  if (anchor) {
    pop.style.position = "fixed";
    pop.style.left = `${Math.max(8, Math.min(anchor.left, window.innerWidth - 220))}px`;
    pop.style.top = `${Math.min(anchor.bottom + 6, window.innerHeight - 120)}px`;
  }
}

function openYtSpeakerColorNativeInput(speakerIndex) {
  const count = getYtSpeakerCount();
  if (speakerIndex < 1 || speakerIndex > count) return;
  let input = document.getElementById("ytSpeakerColorInput");
  if (!input) {
    input = document.createElement("input");
    input.type = "color";
    input.id = "ytSpeakerColorInput";
    input.setAttribute("aria-hidden", "true");
    input.tabIndex = -1;
    input.style.position = "fixed";
    input.style.left = "-9999px";
    input.style.width = "1px";
    input.style.height = "1px";
    input.style.opacity = "0";
    document.body.appendChild(input);
    input.addEventListener("change", () => {
      const idx = Number(input.dataset.speakerIndex);
      if (idx) setYtSpeakerColor(idx, input.value);
    });
  }
  input.value = getYtSpeakerColor(speakerIndex);
  input.dataset.speakerIndex = String(speakerIndex);
  if (typeof input.showPicker === "function") {
    try {
      input.showPicker();
      return;
    } catch {
      /* fall through */
    }
  }
  input.click();
}

function ensureEditorFullscreenLayer() {
  let layer = document.getElementById("editorFullscreenLayer");
  if (layer) return layer;
  layer = document.createElement("div");
  layer.id = "editorFullscreenLayer";
  layer.className = "editor-fullscreen-layer hidden";
  layer.setAttribute("aria-hidden", "true");
  layer.hidden = true;
  layer.innerHTML = '<div class="editor-fullscreen-layer-stage"></div>';
  document.body.appendChild(layer);
  return layer;
}

function ensureEditorFullscreenBar(host, title) {
  if (!host || host.querySelector(".editor-fullscreen-bar")) return;
  const bar = document.createElement("div");
  bar.className = "editor-fullscreen-bar";
  bar.innerHTML = `<p class="editor-fullscreen-bar-title">${escapeHtml(title)}</p><button type="button" class="editor-fullscreen-close">閉じる</button>`;
  host.insertBefore(bar, host.firstChild);
  bar.querySelector(".editor-fullscreen-close")?.addEventListener("click", () => {
    closeEditorFullscreen();
  });
}

function openEditorFullscreen(hostId) {
  const host = document.getElementById(hostId);
  if (!host) return;
  if (editorFullscreenHostId === hostId) return;
  if (editorFullscreenHostId && editorFullscreenHostId !== hostId) {
    closeEditorFullscreen();
  }

  const layer = ensureEditorFullscreenLayer();
  const stage = layer.querySelector(".editor-fullscreen-layer-stage");
  if (!stage) return;

  editorFullscreenDomRestore = {
    parent: host.parentNode,
    next: host.nextSibling,
    hostId
  };

  ensureEditorFullscreenBar(
    host,
    hostId === "ytTranscriptEditorShell" ? "文字起こし（全画面）" : "生成台本（全画面）"
  );

  stage.appendChild(host);
  host.classList.add("is-fullscreen");
  layer.classList.remove("hidden");
  layer.hidden = false;
  layer.setAttribute("aria-hidden", "false");

  editorFullscreenHostId = hostId;
  document.body.classList.add("editor-fullscreen-open");

  if (hostId === "ytTranscriptEditorShell") {
    document.body.classList.add("editor-fullscreen-open--transcript");
    const hint = document.getElementById("ytAssignHint");
    const sidebar = host.querySelector(".editor-workspace-sidebar");
    if (hint && sidebar && !editorFullscreenHintRestore) {
      editorFullscreenHintRestore = { parent: hint.parentNode, next: hint.nextSibling };
      sidebar.insertBefore(hint, sidebar.firstChild);
      hint.classList.add("speaker-assign-status-hint--fullscreen");
    }
  }

  window.requestAnimationFrame(() => {
    host.querySelector(".transcript-assign-stack, .yt-script-stack")?.dispatchEvent(new Event("scroll"));
    paintYtTranscriptAssignMirror();
  });
}

function closeEditorFullscreen() {
  const hostId = editorFullscreenHostId;
  const host = hostId ? document.getElementById(hostId) : null;

  document.body.classList.remove("editor-fullscreen-open");
  document.body.classList.remove("editor-fullscreen-open--transcript");

  const layer = document.getElementById("editorFullscreenLayer");
  if (layer) {
    layer.classList.add("hidden");
    layer.hidden = true;
    layer.setAttribute("aria-hidden", "true");
  }

  if (host) {
    host.classList.remove("is-fullscreen");
  }

  if (editorFullscreenHintRestore) {
    const hint = document.getElementById("ytAssignHint");
    const { parent, next } = editorFullscreenHintRestore;
    if (hint && parent) {
      if (next && next.parentNode === parent) parent.insertBefore(hint, next);
      else parent.appendChild(hint);
    }
    hint?.classList.remove("speaker-assign-status-hint--fullscreen");
    editorFullscreenHintRestore = null;
  }

  if (host && editorFullscreenDomRestore?.parent) {
    const { parent, next } = editorFullscreenDomRestore;
    if (parent.isConnected) {
      if (next && next.parentNode === parent) parent.insertBefore(host, next);
      else parent.appendChild(host);
    }
  }

  editorFullscreenDomRestore = null;
  editorFullscreenHostId = null;
}

function handleEditorExpandButtonClick(btn) {
  const hostId = btn.getAttribute("data-editor-fullscreen");
  if (!hostId) return;
  if (editorFullscreenHostId === hostId) {
    closeEditorFullscreen();
  } else {
    openEditorFullscreen(hostId);
  }
}

function bindEditorExpandButtons(root = document) {
  root.querySelectorAll("[data-editor-fullscreen]").forEach((btn) => {
    if (btn.dataset.expandBound === "1") return;
    btn.dataset.expandBound = "1";
    btn.addEventListener("mousedown", (e) => {
      e.preventDefault();
      e.stopPropagation();
    });
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      handleEditorExpandButtonClick(btn);
    });
  });
}

function bindEditorFullscreenOnce() {
  ensureEditorFullscreenLayer();
  closeEditorFullscreen();

  if (document.body.dataset.editorFullscreenBound === "1") {
    bindEditorExpandButtons();
    return;
  }
  document.body.dataset.editorFullscreenBound = "1";

  bindEditorExpandButtons();

  document.addEventListener("keydown", (e) => {
    if (e.key !== "Escape") return;
    if (ytSpeakerColorPopover && !ytSpeakerColorPopover.classList.contains("hidden")) return;
    if (editorFullscreenHostId) {
      e.preventDefault();
      closeEditorFullscreen();
    }
  });
}

/** @deprecated use openYtSpeakerColorPopover */
function openYtSpeakerColorPicker(speakerIndex) {
  const btn = document.querySelector(`#ytSpeakerPicker [data-speaker-pick="${speakerIndex}"]`);
  openYtSpeakerColorPopover(speakerIndex, btn);
}

function expandYtSpeakerColors(oldCount, newCount) {
  const out = {};
  for (let i = 1; i <= oldCount; i++) {
    out[i] = getYtSpeakerColor(i);
  }
  const used = new Set(Object.values(out).map((c) => String(c).toLowerCase()));
  for (let i = oldCount + 1; i <= newCount; i++) {
    const color = pickUnusedPaletteColor(used);
    out[i] = color;
    used.add(color.toLowerCase());
  }
  ytSpeakerColors = out;
  saveYtSpeakerColors(newCount);
}

function expandYtCastSlots(oldCount, newCount) {
  const slots = loadYtCastSlots(oldCount);
  for (let i = oldCount + 1; i <= newCount; i++) {
    slots.push({
      speakerIndex: i,
      speakerName: `話者${i}`,
      mode: "recruit",
      talentId: "",
      displayName: ""
    });
  }
  return slots;
}

function allSpeakersHaveAssignments(count) {
  if (!hasYtSpeakerAssignments()) return false;
  const plain = ytTranscriptPlain;
  if (!plain) return false;
  for (let i = 1; i <= count; i++) {
    const has = ytAssignRanges.some(
      (r) => r.speakerIndex === i && plain.slice(r.start, r.end).trim()
    );
    if (!has) return false;
  }
  return true;
}

function needsSpeakerRemovalPicker(oldCount, newCount) {
  if (newCount >= oldCount) return false;
  if (!hasYtSpeakerAssignments()) return false;
  if (allSpeakersHaveAssignments(oldCount)) return true;
  return ytAssignRanges.some((r) => r.speakerIndex > newCount);
}

function applyTrailingSpeakerRemoval(oldCount, newCount) {
  saveYtCastSlots(loadYtCastSlots(newCount), newCount);
  ytAssignRanges = ytAssignRanges.filter((r) => r.speakerIndex <= newCount);
  ytAssignRangeHistory = ytAssignRangeHistory.filter((id) =>
    ytAssignRanges.some((r) => r.id === id)
  );
  ytSpeakerColors = normalizeYtSpeakerColors(ytSpeakerColors, newCount);
  saveYtSpeakerColors(newCount);
  if (ytActiveSpeaker > newCount) ytActiveSpeaker = newCount;
  if (ytAssignPreviewFocusSpeaker > newCount) {
    ytAssignPreviewFocusSpeaker = 0;
    ytAssignPreviewFocusRangeId = 0;
  }
  renderYtSpeakerPicker();
  renderYtSpeakerNames();
  renderYtTranscriptAssignView();
  renderYtCastSlots();
  refreshYtRecordSpeakerSelect();
  _wavrickSavePipelineState();
}

function applySpeakerRemovalWithSelection(removedIndices, oldCount, newCount) {
  const removed = new Set(removedIndices);
  const kept = [];
  for (let i = 1; i <= oldCount; i++) {
    if (!removed.has(i)) kept.push(i);
  }
  if (kept.length !== newCount) {
    return { ok: false, message: `削除する話者は ${oldCount - newCount} 人選んでください。` };
  }

  const indexMap = {};
  kept.forEach((oldIdx, i) => {
    indexMap[oldIdx] = i + 1;
  });

  ytAssignRanges = ytAssignRanges
    .filter((r) => !removed.has(r.speakerIndex))
    .map((r) => ({ ...r, speakerIndex: indexMap[r.speakerIndex] }));
  ytAssignRangeHistory = ytAssignRangeHistory.filter((id) =>
    ytAssignRanges.some((r) => r.id === id)
  );

  const oldSlots = loadYtCastSlots(oldCount);
  const newSlots = kept.map((oldIdx, i) => {
    const slot = oldSlots.find((s) => s.speakerIndex === oldIdx);
    return {
      speakerIndex: i + 1,
      speakerName: String(slot?.speakerName || "").trim() || `話者${i + 1}`,
      mode: slot?.mode === "pick" ? "pick" : "recruit",
      talentId: String(slot?.talentId || ""),
      displayName: String(slot?.displayName || "")
    };
  });

  const newColors = {};
  kept.forEach((oldIdx, i) => {
    newColors[i + 1] = getYtSpeakerColor(oldIdx);
  });
  ytSpeakerColors = normalizeYtSpeakerColors(newColors, newCount);
  saveYtSpeakerColors(newCount);
  saveYtCastSlots(newSlots, newCount);

  if (removed.has(ytActiveSpeaker)) ytActiveSpeaker = 1;
  else ytActiveSpeaker = indexMap[ytActiveSpeaker] || 1;
  if (ytAssignPreviewFocusSpeaker && removed.has(ytAssignPreviewFocusSpeaker)) {
    ytAssignPreviewFocusSpeaker = 0;
    ytAssignPreviewFocusRangeId = 0;
  } else if (ytAssignPreviewFocusSpeaker) {
    ytAssignPreviewFocusSpeaker = indexMap[ytAssignPreviewFocusSpeaker] || 0;
  }

  const scEl = document.getElementById("ytSpeakerCount");
  if (scEl) scEl.value = String(newCount);
  ytLastSpeakerCount = newCount;

  renderYtSpeakerPicker();
  renderYtSpeakerNames();
  renderYtTranscriptAssignView();
  updateYtAssignSummary();
  renderYtCastSlots();
  refreshYtRecordSpeakerSelect();
  _wavrickSavePipelineState();

  const removedLabel = removedIndices.sort((a, b) => a - b).join("・");
  return { ok: true, message: `話者を${newCount}人にしました（話者${removedLabel}を削除）。` };
}

function closeSpeakerRemovalPanel() {
  pendingSpeakerRemoveContext = null;
  document.getElementById("ytSpeakerRemovePanel")?.classList.add("hidden");
}

function renderSpeakerRemovalPanel(context) {
  const panel = document.getElementById("ytSpeakerRemovePanel");
  const msg = document.getElementById("ytSpeakerRemoveMessage");
  const choices = document.getElementById("ytSpeakerRemoveChoices");
  const confirmBtn = document.getElementById("ytSpeakerRemoveConfirmBtn");
  if (!panel || !choices || !context) return;

  const { oldCount, newCount, removeCount } = context;
  if (msg) {
    msg.textContent = allSpeakersHaveAssignments(oldCount)
      ? `全ての話者（${oldCount}人）に振り分けがあるため、そのまま人数だけ減らすことはできません。${newCount}人にするには、削除する話者を${removeCount}人選んでください。`
      : `割り当てがある話者を残したまま人数を減らすには、削除する話者を${removeCount}人選んでください。`;
  }

  choices.innerHTML = Array.from({ length: oldCount }, (_, i) => {
    const n = i + 1;
    const label = escapeHtml(getYtSpeakerLabel(n));
    const assigned = ytAssignRanges.some((r) => r.speakerIndex === n);
    const note = assigned ? "（割り当てあり）" : "";
    return `<label class="speaker-remove-choice speaker-${n}"${ytSpeakerAccentAttr(n)}>
      <input type="checkbox" value="${n}" data-speaker-remove="${n}">
      <span>${label}${note}</span>
    </label>`;
  }).join("");

  if (confirmBtn) confirmBtn.disabled = true;
  panel.classList.remove("hidden");

  choices.querySelectorAll("[data-speaker-remove]").forEach((cb) => {
    cb.addEventListener("change", () => {
      const selected = choices.querySelectorAll("[data-speaker-remove]:checked");
      if (confirmBtn) confirmBtn.disabled = selected.length !== removeCount;
    });
  });
}

function openSpeakerRemovalPanel(oldCount, newCount) {
  pendingSpeakerRemoveContext = {
    oldCount,
    newCount,
    removeCount: oldCount - newCount
  };
  renderSpeakerRemovalPanel(pendingSpeakerRemoveContext);
}

function handleYtSpeakerCountChange() {
  const speakerCountEl = document.getElementById("ytSpeakerCount");
  const newCount = getYtSpeakerCount();
  const oldCount = ytLastSpeakerCount;

  if (newCount >= oldCount) {
    if (newCount > oldCount) {
      saveYtCastSlots(expandYtCastSlots(oldCount, newCount), newCount);
      expandYtSpeakerColors(oldCount, newCount);
    } else {
      saveYtCastSlots(loadYtCastSlots(newCount), newCount);
      ytSpeakerColors = normalizeYtSpeakerColors(ytSpeakerColors, newCount);
      saveYtSpeakerColors(newCount);
    }
    if (ytActiveSpeaker > newCount) ytActiveSpeaker = newCount;
    renderYtSpeakerPicker();
    renderYtSpeakerNames();
    renderYtCastSlots();
    refreshYtRecordSpeakerSelect();
    ytLastSpeakerCount = newCount;
    _wavrickSavePipelineState();
    return;
  }

  if (speakerCountEl) speakerCountEl.value = String(oldCount);

  if (!needsSpeakerRemovalPicker(oldCount, newCount)) {
    applyTrailingSpeakerRemoval(oldCount, newCount);
    if (speakerCountEl) speakerCountEl.value = String(newCount);
    ytLastSpeakerCount = newCount;
    return;
  }

  if (allSpeakersHaveAssignments(oldCount)) {
    setMessage(
      "ytMessage",
      `全ての話者（${oldCount}人）に振り分けがあるため、${newCount}人に減らすには削除する話者を選んでください。`,
      "err"
    );
  } else {
    setMessage(
      "ytMessage",
      `割り当てがある話者がいるため、${newCount}人に減らすには削除する話者を${oldCount - newCount}人選んでください。`,
      "err"
    );
  }
  openSpeakerRemovalPanel(oldCount, newCount);
}

function bindYtSpeakerRemovePanelOnce() {
  const confirmBtn = document.getElementById("ytSpeakerRemoveConfirmBtn");
  const cancelBtn = document.getElementById("ytSpeakerRemoveCancelBtn");
  if (!confirmBtn || confirmBtn.dataset.bound === "1") return;
  confirmBtn.dataset.bound = "1";

  confirmBtn.addEventListener("click", () => {
    const ctx = pendingSpeakerRemoveContext;
    if (!ctx) return;
    const choices = document.getElementById("ytSpeakerRemoveChoices");
    const selected = [...(choices?.querySelectorAll("[data-speaker-remove]:checked") || [])].map(
      (el) => Number(el.value)
    );
    if (selected.length !== ctx.removeCount) {
      setMessage("ytMessage", `削除する話者を${ctx.removeCount}人選んでください。`, "err");
      return;
    }
    const result = applySpeakerRemovalWithSelection(selected, ctx.oldCount, ctx.newCount);
    closeSpeakerRemovalPanel();
    setMessage("ytMessage", result.message, result.ok ? "ok" : "err");
  });

  cancelBtn?.addEventListener("click", () => {
    closeSpeakerRemovalPanel();
    setMessage("ytMessage", "話者人数の変更をキャンセルしました。", "ok");
  });
}

function getYtSpeakerCount() {
  const el = document.getElementById("ytSpeakerCount");
  const n = Number(el?.value || 2);
  if (!Number.isFinite(n)) return 2;
  return Math.min(6, Math.max(1, Math.round(n)));
}

function getSpeakerAssignApi() {
  return typeof WavrickSpeakerAssign !== "undefined" ? WavrickSpeakerAssign : null;
}

function defaultYtCastSlots(count) {
  return Array.from({ length: count }, (_, i) => ({
    speakerIndex: i + 1,
    speakerName: `話者${i + 1}`,
    mode: "recruit",
    talentId: "",
    displayName: ""
  }));
}

function getYtSpeakerLabel(speakerIndex) {
  const slots = loadYtCastSlots(getYtSpeakerCount());
  const slot = slots.find((s) => s.speakerIndex === speakerIndex);
  const name = String(slot?.speakerName || "").trim();
  return name || t("yt.speaker_default", { index: speakerIndex });
}

function setYtSpeakerName(speakerIndex, name) {
  const count = getYtSpeakerCount();
  const slots = loadYtCastSlots(count);
  const slot = slots.find((s) => s.speakerIndex === speakerIndex);
  if (!slot) return;
  slot.speakerName = String(name || "").trim() || `話者${speakerIndex}`;
  saveYtCastSlots(slots, count);
  renderYtSpeakerPicker();
  renderYtSpeakerNames();
  renderYtCastSlots();
  renderYtTranscriptAssignView();
  refreshYtRecordSpeakerSelect();
}

function loadYtCastSlots(count) {
  const want = Math.min(6, Math.max(1, count || getYtSpeakerCount()));
  try {
    const raw = localStorage.getItem(YT_CAST_SLOTS_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      const saved = Array.isArray(parsed?.slots) ? parsed.slots : Array.isArray(parsed) ? parsed : null;
      if (saved?.length) {
        const byIndex = new Map(
          saved
            .filter((s) => s && typeof s.speakerIndex === "number")
            .map((s) => [s.speakerIndex, s])
        );
        return defaultYtCastSlots(want).map((slot) => {
          const prev = byIndex.get(slot.speakerIndex);
          if (!prev) return slot;
          return {
            speakerIndex: slot.speakerIndex,
            speakerName: String(prev.speakerName || "").trim() || `話者${slot.speakerIndex}`,
            mode: prev.mode === "pick" ? "pick" : "recruit",
            talentId: String(prev.talentId || ""),
            displayName: String(prev.displayName || "")
          };
        });
      }
    }
  } catch (_) {
    /* ignore corrupt storage */
  }
  return defaultYtCastSlots(want);
}

function saveYtCastSlots(slots, count) {
  const want = Math.min(6, Math.max(1, count || getYtSpeakerCount()));
  const normalized = defaultYtCastSlots(want).map((slot) => {
    const found = (slots || []).find((s) => s.speakerIndex === slot.speakerIndex);
    if (!found) return slot;
    return {
      speakerIndex: slot.speakerIndex,
      speakerName: String(found.speakerName || "").trim() || `話者${slot.speakerIndex}`,
      mode: found.mode === "pick" ? "pick" : "recruit",
      talentId: String(found.talentId || ""),
      displayName: String(found.displayName || "")
    };
  });
  localStorage.setItem(
    YT_CAST_SLOTS_KEY,
    JSON.stringify({ speakerCount: want, slots: normalized, updatedAt: new Date().toISOString() })
  );
  return normalized;
}

function validateYtCastSlots(count) {
  const slots = loadYtCastSlots(count);
  const customerEmail = getCustomerEmailForFavorites();
  for (const slot of slots) {
    if (slot.mode === "pick" && !slot.talentId) {
      return {
        ok: false,
        message: `話者${slot.speakerIndex} で「自分で選ぶ」を選んだ場合は、声優一覧から声優を選んでください。`,
        slots
      };
    }
    if (slot.mode === "pick" && slot.talentId && customerEmail) {
      const B = getTalentBlocksApi();
      if (B?.isBlockedBetween(customerEmail, slot.talentId)) {
        return {
          ok: false,
          message: `話者${slot.speakerIndex} に選んだ声優はブロック中のため依頼できません。別の声優を選ぶか、ブロックを解除してください。`,
          slots
        };
      }
    }
  }
  return { ok: true, slots };
}

const RW_SCRIPT_IMPORT_VER = "rw-speaker-booth-2026-06-17";
const RW_GROK_WHISPER_ALIGN_VER = "rw-grok-whisper-align-2026-05-29";
const WAVRICK_ADLIB_SCRIPT_VER = "wavrick-adlib-script-2026-06-24";

function looksLikeBrokenTimecodedScript(raw) {
  const rows = String(raw || "")
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter(Boolean);
  if (rows.length < 4) return false;
  const tcOnly = rows.filter((l) => /^\[\d{1,2}:\d{2}/.test(l) && !/\]\s+\S/.test(l)).length;
  return tcOnly >= Math.max(3, Math.floor(rows.length * 0.25));
}

function sanitizeScriptTextForRetime(raw) {
  const t = String(raw || "");
  const embeddedTcRe =
    /\[\d{1,2}:\d{2}(?:\.\d{1,3})?(?:\s*(?:->|→|-)\s*\d{1,2}:\d{2}(?:\.\d{1,3})?)?\]/g;
  const leadingTcLineRe =
    /^\[\d{1,2}:\d{2}(?:\.\d{1,3})?(?:\s*(?:->|→|-)\s*\d{1,2}:\d{2}(?:\.\d{1,3})?)?\]\s*(.*)$/;

  const out = [];
  for (const line of t.split(/\r?\n/)) {
    const trimmed = String(line || "").trim();
    if (!trimmed) continue;

    const m = trimmed.match(leadingTcLineRe);
    let text = null;
    if (m) {
      text = (m[1] || "").trim();
      if (!text) continue; // tc-only
    } else {
      text = trimmed;
    }

    text = text.replace(embeddedTcRe, "").trim();
    if (!text) continue;
    out.push(text);
  }

  return out.join("\n").trim();
}

function shouldHideYtScriptTimecodesForCustomer() {
  const cfg = window.WAVRICK_CONFIG || {};
  if (cfg.hideYtScriptTimecodesForCustomer === true) return true;
  if (isProductionSite()) return true;
  try {
    const p = new URLSearchParams(window.location.search);
    if (p.get("scriptTimecodes") === "0") return true;
    if (p.get("scriptTimecodes") === "1") return false;
  } catch {
    /* ignore */
  }
  return false;
}

/** 生成台本（編集可）に [00:xx] / [NEW_BLOCK] / を表示するか */
function shouldShowYtScriptTimecodesInField() {
  return !shouldHideYtScriptTimecodesForCustomer();
}

function stripInvisibleAdlibMarkers(text) {
  return String(text || "")
    .replace(/\uE000/g, "")
    .replace(/\uE001/g, "")
    .replace(/【ADLIB】/g, "")
    .replace(/【\/ADLIB】/g, "");
}

function stripTimecodesFromCastScriptForCustomer(raw) {
  const text = String(raw || "");
  if (!text || shouldShowYtScriptTimecodesInField()) return text;
  const lines = text.split(/\r?\n/);
  const out = [];
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed === "[NEW_BLOCK]" || trimmed === "/") continue;
    if (/^\[\d{1,2}:\d{2}/.test(trimmed)) {
      let body = trimmed.replace(/^\[[^\]]+\]\s*/, "").trim();
      const speakerM = body.match(/^\(([^)]+)\)\s*(.+)$/);
      out.push(speakerM ? speakerM[2].trim() : body);
      continue;
    }
    out.push(line);
  }
  return out.join("\n").trim();
}

function getYtScriptMirror() {
  return document.getElementById("ytScriptMirror");
}

function getYtScriptStack() {
  return document.getElementById("ytScriptStack");
}

function syncYtScriptMirrorScroll() {
  const field = document.getElementById("ytScript");
  const mirror = getYtScriptMirror();
  if (!field || !mirror) return;
  mirror.scrollTop = field.scrollTop;
  mirror.scrollLeft = field.scrollLeft;
}

function resetYtReconcilePreview() {
  ytReconcileDraftFull = "";
  ytReconcileAdlibSegments = [];
  ytReconcileAdlibSpans = [];
  ytReconcileReady = false;
  const box = document.getElementById("ytReconcilePreview");
  const field = document.getElementById("ytReconcileScript");
  const genBtn = document.getElementById("generateScriptButton");
  if (box) box.classList.add("hidden");
  if (field) field.value = "";
  if (genBtn) genBtn.classList.remove("hidden");
  void paintYtReconcileMirror("");
}

function invalidateYtReconcilePreview() {
  if (!ytReconcileReady && !ytReconcileDraftFull) return;
  resetYtReconcilePreview();
}

function getYtReconcileMirror() {
  return document.getElementById("ytReconcileMirror");
}

function getYtReconcileStack() {
  return document.getElementById("ytReconcileStack");
}

function syncYtReconcileMirrorScroll() {
  const field = document.getElementById("ytReconcileScript");
  const mirror = getYtReconcileMirror();
  if (!field || !mirror) return;
  mirror.scrollTop = field.scrollTop;
  mirror.scrollLeft = field.scrollLeft;
}

async function paintYtReconcileMirror(sourceText, segments, spans) {
  const field = document.getElementById("ytReconcileScript");
  const mirror = getYtReconcileMirror();
  const stack = getYtReconcileStack();
  const hint = document.getElementById("ytReconcileAdlibHint");
  const text = String(sourceText ?? ytReconcileDraftFull ?? field?.value ?? "");
  const spanList = spans ?? ytReconcileAdlibSpans ?? [];
  let segs = segments ?? ytReconcileAdlibSegments ?? [];
  if (
    !segs.some((s) => String(s?.text || "").trim()) &&
    spanList.length &&
    ytTranscriptPlain
  ) {
    segs = spanList.map((s) => ({
      text: ytTranscriptPlain.slice(Number(s.start) || 0, Number(s.end) || 0),
    }));
  }
  if (!field || !mirror || !stack) return;

  if (!text.trim()) {
    mirror.innerHTML = "";
    stack.classList.remove("yt-script-stack--overlay");
    if (hint) hint.classList.add("hidden");
    return;
  }

  try {
    const mod = await import(
      `./js/wavrick-adlib-script.js?v=${WAVRICK_ADLIB_SCRIPT_VER}`
    );
    const hasSegments = Array.isArray(segs) && segs.some((s) => String(s?.text || "").trim());
    if (hasSegments) {
      mirror.innerHTML = mod.highlightAdlibSegmentsInHtml(text, segs);
    } else {
      mirror.innerHTML = mod.escapeHtml(text);
    }
    stack.classList.toggle("yt-script-stack--overlay", hasSegments);
    if (hint) hint.classList.toggle("hidden", !hasSegments);
    syncYtReconcileMirrorScroll();
  } catch (e) {
    console.warn("[yt] reconcile mirror paint failed", e);
    mirror.innerHTML = "";
    stack.classList.remove("yt-script-stack--overlay");
    if (hint) hint.classList.add("hidden");
  }
}

function showYtReconcilePreview(draftText, adlibSegments, adlibSpans) {
  const box = document.getElementById("ytReconcilePreview");
  const field = document.getElementById("ytReconcileScript");
  const genBtn = document.getElementById("generateScriptButton");
  if (!box || !field) return;
  ytReconcileDraftFull = String(draftText || "").trim();
  ytReconcileAdlibSegments = Array.isArray(adlibSegments) ? adlibSegments : [];
  ytReconcileAdlibSpans = Array.isArray(adlibSpans) ? adlibSpans : [];
  ytReconcileReady = Boolean(ytReconcileDraftFull);
  field.value = ytReconcileDraftFull;
  box.classList.remove("hidden");
  if (genBtn) genBtn.classList.add("hidden");
  void paintYtReconcileMirror(ytReconcileDraftFull, ytReconcileAdlibSegments, ytReconcileAdlibSpans);
  scheduleRepaintYtTranscriptAssignEditor();
}

function collectYtScriptGenerationPayload() {
  const videoUrlField = document.getElementById("ytVideoUrl");
  const count = getYtSpeakerCount();
  flushTextareaEdit();
  const plainForGen = ensureTranscriptTextareaSynced();
  if (!hasYtSpeakerAssignments()) {
    return {
      ok: false,
      message:
        "先に話者ボタンを選び、文字起こしをドラッグして全文に話者を割り当ててください。"
    };
  }
  const assignProgress = getYtAssignmentProgress(plainForGen, ytAssignRanges);
  if (!assignProgress.complete) {
    return {
      ok: false,
      message: `話者割り当てが完了していません。未割り当ての文字が ${assignProgress.unassigned} 文字あります（空白・改行は除く）。すべての文字を話者に割り当ててから台本生成してください。`
    };
  }
  const castCheck = validateYtCastSlots(count);
  if (!castCheck.ok) {
    return { ok: false, message: castCheck.message };
  }
  const speakers = collectSpeakersFromRanges(count);
  if (!speakers.length) {
    return {
      ok: false,
      message:
        "話者に割り当てられたセリフがありません。文字起こし欄を一度クリックしてから、もう一度お試しください。"
    };
  }
  if (!initSupabaseClient()) {
    return { ok: false, message: "Supabase に接続してから利用してください。" };
  }
  if (!ytTranscribeJobId) {
    return {
      ok: false,
      message:
        "先に「素材から文字起こし（Whisper）」を実行してください（単語タイムコード付きジョブが必要です）。"
    };
  }
  const assignRanges = ytAssignRanges.map((r) => ({
    start: r.start,
    end: r.end,
    speakerIndex: r.speakerIndex,
    text: ytTranscriptPlain.slice(r.start, r.end)
  }));
  return {
    ok: true,
    videoUrl: videoUrlField?.value?.trim() || "",
    count,
    castCheck,
    speakers,
    assignRanges
  };
}

async function paintYtScriptMirror(sourceText, segments) {
  const field = document.getElementById("ytScript");
  const mirror = getYtScriptMirror();
  const stack = getYtScriptStack();
  const hint = document.getElementById("ytScriptAdlibHint");
  const text = String(
    sourceText ?? ytScriptTimecodedFull ?? field?.value ?? ""
  );
  const segs = segments ?? ytAdlibSegments ?? [];
  if (!field || !mirror || !stack) return;

  if (!text.trim()) {
    mirror.innerHTML = "";
    stack.classList.remove("yt-script-stack--overlay");
    if (hint) hint.classList.add("hidden");
    return;
  }

  try {
    const mod = await import(
      `./js/wavrick-adlib-script.js?v=${WAVRICK_ADLIB_SCRIPT_VER}`
    );
    const hasMarkers = mod.scriptContainsAdlibMarkers(text);
    const hasSegments = Array.isArray(segs) && segs.some((s) => String(s?.text || "").trim());
    const showAdlib = hasMarkers || hasSegments;

    if (hasMarkers) {
      mirror.innerHTML = mod.renderScriptHtmlWithAdlibHighlights(text);
    } else if (hasSegments) {
      mirror.innerHTML = mod.highlightAdlibSegmentsInHtml(text, segs);
    } else {
      mirror.innerHTML = mod.escapeHtml(text);
    }

    stack.classList.toggle("yt-script-stack--overlay", showAdlib);
    if (hint) hint.classList.toggle("hidden", !showAdlib);
    syncYtScriptMirrorScroll();
  } catch (e) {
    console.warn("[yt] script mirror paint failed", e);
    mirror.innerHTML = "";
    stack.classList.remove("yt-script-stack--overlay");
    if (hint) hint.classList.add("hidden");
  }
}

async function refreshYtScriptAdlibPreview(sourceText) {
  await paintYtScriptMirror(sourceText);
}

function bindYtScriptAdlibPreviewOnce() {
  const field = document.getElementById("ytScript");
  if (!field || field.dataset.adlibPreviewBound === "1") return;
  field.dataset.adlibPreviewBound = "1";
  field.addEventListener("input", () => {
    void paintYtScriptMirror(field.value);
  });
  field.addEventListener("scroll", syncYtScriptMirrorScroll);
}

async function applyTimecodedScriptToYtField() {
  const scriptField = document.getElementById("ytScript");
  let raw = scriptField?.value?.trim();
  if (!raw) {
    return null;
  }
  const hasWhisper = Array.isArray(ytWhisperSegments) && ytWhisperSegments.length;
  const whisperSegments = hasWhisper ? ytWhisperSegments : null;
  const hasAnyTc = /\[\d{1,2}:\d{2}/.test(raw);

  const isCastFormattedScript =
    /---\s*WAVRICK_CAST\s*---/i.test(raw) ||
    /^【[^】]+\/[^】]*声優:/m.test(raw) ||
    /^【台本（時系列）】/m.test(raw);
  if (isCastFormattedScript) {
    if (hasWhisper) {
      try {
        const { refinePipelineCastScriptTimings } = await import(
          `./js/record-workspace/script-import.js?v=${RW_SCRIPT_IMPORT_VER}`
        );
        const { resolveTimelineDurationSec } = await import(
          `./js/record-workspace/timecode.js?v=${RW_SCRIPT_IMPORT_VER}`
        );
        const dur = resolveTimelineDurationSec(
          ytWhisperDurationSec > 0 ? ytWhisperDurationSec : 0,
          whisperSegments
        );
        const refined = refinePipelineCastScriptTimings(raw, whisperSegments, dur);
        if (refined && refined !== raw) {
          scriptField.value = refined;
          raw = refined;
        }
      } catch (e) {
        console.warn("[yt] pipeline cast timecode refine failed", e);
      }
    }
    return {
      script: scriptField?.value?.trim() || raw,
      source: "pipeline-cast",
      lineCount: (raw.match(/^\[\d{1,2}:\d{2}/gm) || []).length
    };
  }

  if (ytWhisperTimeline.trim() && hasAnyTc) {
    raw = await alignYtScriptToWhisperTimeline(raw);
    scriptField.value = raw;
  }

  // Grok が生成したタイムコード付き台本はフロントで再計算しない（パースのみ）
  if (hasAnyTc) {
    try {
      const { isGrokTimecodedScript, parseScriptLines, scriptLinesToText } = await import(
        `./js/record-workspace/script-import.js?v=${RW_SCRIPT_IMPORT_VER}`
      );
      if (isGrokTimecodedScript(raw)) {
        const lines = parseScriptLines(raw);
        if (lines.length) {
          scriptField.value = scriptLinesToText(lines);
          const isSrt = /\d{2}:\d{2}:\d{2},\d{3}\s*-->/.test(raw);
          setMessage(
            "ytMessage",
            isSrt
              ? `SRT 台本を反映しました（${lines.length} キュー・フロント再計算なし）。`
              : `Grok のタイムコード台本を反映しました（${lines.length} 行・フロント再計算なし）。`,
            "ok"
          );
          return {
            script: scriptField.value,
            source: "grok-timecoded",
            lineCount: lines.length
          };
        }
      }
    } catch (e) {
      console.warn("[yt] grok timecode preserve check failed", e);
    }
  }
  if (hasWhisper && hasAnyTc) {
    raw = sanitizeScriptTextForRetime(raw);
    scriptField.value = raw;
  } else if (looksLikeBrokenTimecodedScript(raw)) {
    if (hasAnyTc) {
      raw = sanitizeScriptTextForRetime(raw);
      scriptField.value = raw;
    } else {
      raw = raw
        .split(/\r?\n/)
        .map((l) => l.trim())
        .filter(
          (l) =>
            l &&
            !/^\[\d{1,2}:\d{2}(?:\.\d{1,3})?(?:\s*(?:->|→|-)\s*\d{1,2}:\d{2}(?:\.\d{1,3})?)?\]\s*$/.test(
              l
            )
        )
        .join("\n");
      scriptField.value = raw;
    }
  }
  const SA = window.WavrickSpeakerAssign;
  try {
    const { prepareScriptForWorkspace } = await import(
      `./js/record-workspace/script-import.js?v=${RW_SCRIPT_IMPORT_VER}`
    );
    const { resolveTimelineDurationSec } = await import(
      `./js/record-workspace/timecode.js?v=${RW_SCRIPT_IMPORT_VER}`
    );
    const dur = resolveTimelineDurationSec(
      ytWhisperDurationSec > 0 ? ytWhisperDurationSec : 0,
      whisperSegments
    );
    if (!hasWhisper) {
      setMessage(
        "ytMessage",
        "タイムコードを付けるには先に「文字起こし」が必要です（Whisper の発話時刻を使います）。",
        "err"
      );
      return null;
    }
    const prep = prepareScriptForWorkspace(raw, dur, {
      whisperSegments,
      whisperDurationSec: dur
    });
    if (prep.script) {
      scriptField.value = prep.script;
    }
    if (prep?.script) {
      const src = prep.source || "ok";
      const kind = String(src).includes("whisper")
        ? "ok"
        : "err";
      setMessage(
        "ytMessage",
        kind === "ok"
          ? `台本を整形しました（${src} / ${prep.lineCount || 0}行・発話開始/終了時刻）`
          : `台本を整形しましたが Whisper 未連携です（${src}）。文字起こし後にもう一度お試しください。`,
        kind
      );
    }
    return prep;
  } catch (e) {
    console.warn("[yt] timecode apply failed", e);
    setMessage(
      "ytMessage",
      `台本の整形に失敗しました: ${e instanceof Error ? e.message : String(e)}`,
      "err"
    );
    return null;
  }
}

function getSpeakerLabelFromCast(cast, speakerIndex) {
  const slot = cast?.castSlots?.find((s) => Number(s.speakerIndex) === speakerIndex);
  return String(slot?.speakerName || "").trim() || `話者${speakerIndex}`;
}

function getSpeakerCountFromScript(script, castSlots) {
  if (Array.isArray(castSlots) && castSlots.length) {
    return Math.min(6, Math.max(1, castSlots.length));
  }
  const cast = parseCastMetaFromScript(script);
  if (cast?.speakerCount) {
    return Math.min(6, Math.max(1, Number(cast.speakerCount) || 1));
  }
  if (cast?.castSlots?.length) {
    return Math.min(6, Math.max(1, cast.castSlots.length));
  }
  const blockSections = String(script || "").match(/^【[^】]+\/[^】]*声優:/gm);
  if (blockSections?.length) {
    return Math.min(6, Math.max(1, blockSections.length));
  }
  return 1;
}

function stripCastBlockFromScript(rawScript) {
  const raw = String(rawScript || "").trim();
  if (!raw) return raw;
  return raw
    .replace(/^(---\s*WAVRICK_CAST\s*---\s*[\s\S]*?\s*---\s*\n?)/i, "")
    .trim();
}

function filterPipelineScriptForSpeaker(rawScript, speakerIndex, labelHints = []) {
  const idx = Number(speakerIndex);
  if (!Number.isFinite(idx) || idx < 1) return stripCastBlockFromScript(rawScript);

  const raw = String(rawScript || "").trim();
  if (!raw) return raw;

  const castMeta = parseCastMetaFromScript(raw);
  const hints = [...labelHints];
  if (castMeta) hints.push(getSpeakerLabelFromCast(castMeta, idx));

  let body = stripCastBlockFromScript(raw);

  const SECTION_HEAD_RE = /^【([^】]+)】\s*$/;
  const SECTION_HEAD_SKIP_RE = /^【(参考:|結合版)/;
  const rows = body.split(/\r?\n/);
  const sections = [];
  let current = null;

  for (const row of rows) {
    const t = row.trim();
    if (!t) {
      if (current) current.lines.push("");
      continue;
    }
    if (SECTION_HEAD_SKIP_RE.test(t)) {
      if (current) sections.push(current);
      current = null;
      continue;
    }
    const sec = t.match(SECTION_HEAD_RE);
    if (sec) {
      if (current) sections.push(current);
      current = { title: sec[1], lines: [] };
      continue;
    }
    if (current) current.lines.push(row);
  }
  if (current) sections.push(current);
  if (!sections.length) return body || stripCastBlockFromScript(raw);

  let matched = sections.filter((s) =>
    speakerSectionTitleMatchesIndex(s.title, idx, hints)
  );

  if (!matched.length) {
    const speakerBlockSections = sections.filter((s) => /\/\s*声優:/.test(s.title));
    if (speakerBlockSections.length >= idx) {
      matched = [speakerBlockSections[idx - 1]];
    }
  }

  if (!matched.length) {
    const chrono = sections.find((s) => /時系列/.test(s.title));
    if (chrono?.lines?.length) {
      const labels = [...new Set(hints.map((h) => String(h || "").trim()).filter(Boolean))];
      const SPEAKER_LINE_RE =
        /^\[(\d{1,2}):(\d{2})(?:\.(\d{1,3}))?(?:\s*(?:->|→|-)\s*(\d{1,2}):(\d{2})(?:\.(\d{1,3}))?)?\]\s*(.+)$/;
      const filteredLines = chrono.lines.filter((row) => {
        const t = String(row || "").trim();
        if (!t) return false;
        const m = t.match(SPEAKER_LINE_RE);
        const text = (m ? m[7] : t).trim();
        return labels.some((label) => {
          if (!label) return false;
          const esc = label.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
          if (new RegExp(`^\\(${esc}\\)`).test(text)) return true;
          return (
            label === `話者${idx}` &&
            new RegExp(`^\\(話者${idx}\\)`).test(text)
          );
        });
      });
      if (filteredLines.length) return filteredLines.join("\n").trim();
    }
    return body || stripCastBlockFromScript(raw);
  }

  const out = [];
  for (const sec of matched) {
    out.push(`【${sec.title}】`);
    out.push(...sec.lines);
    out.push("");
  }
  return out.join("\n").trim();
}

async function resolveYtFullScriptForRecord({ skipRefine = false } = {}) {
  flushTextareaEdit();
  const videoUrl = document.getElementById("ytVideoUrl")?.value?.trim() || "";
  let base = String(ytScriptTimecodedFull || "").trim();
  const fieldVal = document.getElementById("ytScript")?.value?.trim() || "";
  if (!base && /\[\d{1,2}:\d{2}/.test(fieldVal)) {
    base = fieldVal;
  }
  if (!base && videoUrl) {
    try {
      const rows = JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]");
      const match = rows.find((r) => r.videoUrl === videoUrl && r.script);
      if (match?.script) base = String(match.script).trim();
      if (match?.scriptsBySpeaker && !Object.keys(ytScriptsBySpeaker).length) {
        ytScriptsBySpeaker = normalizeScriptsBySpeakerMap(match.scriptsBySpeaker);
      }
    } catch {
      /* ignore */
    }
  }
  if (!base) base = fieldVal;
  if (!base) return "";

  const hasWhisper = Array.isArray(ytWhisperSegments) && ytWhisperSegments.length;
  if (hasWhisper && !skipRefine) {
    try {
      const { refinePipelineCastScriptTimings } = await import(
        `./js/record-workspace/script-import.js?v=${RW_SCRIPT_IMPORT_VER}`
      );
      const { resolveTimelineDurationSec } = await import(
        `./js/record-workspace/timecode.js?v=${RW_SCRIPT_IMPORT_VER}`
      );
      const dur = resolveTimelineDurationSec(
        ytWhisperDurationSec > 0 ? ytWhisperDurationSec : 0,
        ytWhisperSegments
      );
      base = refinePipelineCastScriptTimings(base, ytWhisperSegments, dur) || base;
    } catch (e) {
      console.warn("[yt] record script refine failed", e);
    }
  }
  return base;
}

function normalizeScriptsBySpeakerMap(raw) {
  if (!raw || typeof raw !== "object") return {};
  const out = {};
  for (const [key, value] of Object.entries(raw)) {
    const text = String(value || "").trim();
    if (text) out[String(key)] = text;
  }
  return out;
}

/** 全文台本の【話者N】セクションから scriptsBySpeaker を復元（タイムコード付き想定） */
function rebuildScriptsBySpeakerFromCastScript(script, speakerCount = 0, castSlots = null) {
  const raw = String(script || "").trim();
  if (!raw) return {};
  const cast = parseCastMetaFromScript(raw);
  let count = Number(speakerCount) || 0;
  if (!count && Array.isArray(castSlots) && castSlots.length) {
    count = Math.max(0, ...castSlots.map((s) => Number(s.speakerIndex) || 0));
  }
  if (!count && Number(cast?.speakerCount) > 0) count = Number(cast.speakerCount);
  if (!count) {
    const hits = [...raw.matchAll(/【\s*話者\s*(\d+)/g)];
    count = hits.reduce((m, x) => Math.max(m, Number(x[1]) || 0), 0);
  }
  if (!count) {
    const blockHits = [...raw.matchAll(/\/\s*声優:/g)];
    if (blockHits.length) count = blockHits.length;
  }
  if (!count) return {};

  const fullBody = stripCastBlockFromScript(raw).trim();
  const out = {};
  const maxTry = Math.min(Math.max(count, 1), 16);
  for (let i = 1; i <= maxTry; i++) {
    const hints = [];
    if (cast) hints.push(getSpeakerLabelFromCast(cast, i));
    const slot = Array.isArray(castSlots)
      ? castSlots.find((s) => Number(s.speakerIndex) === i)
      : null;
    if (slot?.speakerName) hints.push(slot.speakerName);
    if (slot?.displayName) hints.push(slot.displayName);
    const filtered = String(filterPipelineScriptForSpeaker(raw, i, hints) || "").trim();
    if (!filtered) continue;
    // フィルタ失敗で全文が返った場合は捨てる（全レーン重複防止）
    if (count > 1 && filtered === fullBody) continue;
    if (!scriptTextLooksRecordable(filtered)) continue;
    out[String(i)] = filtered;
  }
  return normalizeScriptsBySpeakerMap(out);
}

function scriptsBySpeakerHasTimecodes(map) {
  return Object.values(normalizeScriptsBySpeakerMap(map)).some((v) =>
    /\[\d{1,2}:\d{2}/.test(String(v || ""))
  );
}

function ensureScriptsBySpeakerOnRequest(request) {
  if (!request) return request;
  const existing = normalizeScriptsBySpeakerMap(request.scriptsBySpeaker);
  if (scriptsBySpeakerHasTimecodes(existing)) {
    return { ...request, scriptsBySpeaker: existing };
  }
  const script = String(
    request.script ||
      request.confirmedDeliverables?.scriptFull ||
      request.confirmedDeliverables?.script ||
      ""
  ).trim();
  const slots =
    (Array.isArray(request.castSlots) && request.castSlots.length
      ? request.castSlots
      : null) || getCastSlotsForRequest(request);
  const rebuilt = rebuildScriptsBySpeakerFromCastScript(
    script,
    request.speakerCount || slots.length || 0,
    slots
  );
  if (!Object.keys(rebuilt).length) {
    return { ...request, scriptsBySpeaker: existing };
  }
  return {
    ...request,
    scriptsBySpeaker: Object.keys(existing).length
      ? { ...rebuilt, ...existing }
      : rebuilt
  };
}

function requestNeedsSpeakerBlockEnrichment(request) {
  if (!request) return true;
  const map = normalizeScriptsBySpeakerMap(request.scriptsBySpeaker);
  if (scriptsBySpeakerHasTimecodes(map)) return false;
  // 台本全文にあればローカル復元できるのでクラウド必須ではない
  if (/\[\d{1,2}:\d{2}/.test(String(request.script || ""))) return false;
  return true;
}

function getYtScriptsBySpeakerForRecord() {
  const fromMemory = normalizeScriptsBySpeakerMap(ytScriptsBySpeaker);
  if (Object.keys(fromMemory).length) return fromMemory;
  const videoUrl = document.getElementById("ytVideoUrl")?.value?.trim() || "";
  if (!videoUrl) return {};
  try {
    const rows = JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]");
    const match = rows.find((r) => r.videoUrl === videoUrl);
    if (match?.scriptsBySpeaker) {
      return normalizeScriptsBySpeakerMap(match.scriptsBySpeaker);
    }
  } catch {
    /* ignore */
  }
  return {};
}

function scriptTextLooksRecordable(text) {
  const t = String(text || "").trim();
  if (!t || t === "（空）") return false;
  if (/\[\d{1,2}:\d{2}/.test(t)) return true;
  return t.replace(/\s/g, "").length >= 8;
}

function resolveRecordScriptForSpeaker(rawScript, speakerIndex, castSlots, scriptsBySpeaker) {
  const idx = Number(speakerIndex);
  const raw = String(rawScript || "").trim();
  if (!raw || !Number.isFinite(idx) || idx < 1) return stripCastBlockFromScript(raw);

  const map = normalizeScriptsBySpeakerMap(scriptsBySpeaker || getYtScriptsBySpeakerForRecord());
  const direct = String(map[String(idx)] || map[idx] || "").trim();
  if (direct && scriptTextLooksRecordable(direct)) {
    return direct;
  }

  const hints = [];
  const cast =
    parseCastMetaFromScript(raw) ||
    (Array.isArray(castSlots) && castSlots.length
      ? { castSlots, speakerCount: castSlots.length }
      : null);
  if (cast) hints.push(getSpeakerLabelFromCast(cast, idx));
  const filtered = filterPipelineScriptForSpeaker(raw, idx, hints);
  if (scriptTextLooksRecordable(filtered)) return filtered;
  if (direct) return direct;
  return filtered;
}

function speakerSectionTitleMatchesIndex(title, speakerIndex, labelHints = []) {
  const base = String(title || "")
    .replace(/\s*\/\s*声優:.*/, "")
    .replace(/\s*\/\s*ブロック\d+\s*$/, "")
    .trim();
  if (!base) return false;
  const idx = Number(speakerIndex);
  if (Number.isFinite(idx) && idx >= 1) {
    const idxLabel = `話者${idx}`;
    if (base === idxLabel || base.startsWith(`${idxLabel} /`)) return true;
  }
  const hints = [
    ...labelHints,
    Number.isFinite(idx) && idx >= 1 ? `話者${idx}` : ""
  ]
    .map((s) => String(s || "").trim())
    .filter(Boolean);
  return [...new Set(hints)].some((h) => base === h || base.startsWith(`${h} /`));
}

function refreshRecordSpeakerSelect(selectEl, count, getLabelFn, options = {}) {
  if (!selectEl) return;
  const includeAll = options.includeAll !== false;
  const allowed =
    Array.isArray(options.speakerIndexes) && options.speakerIndexes.length
      ? options.speakerIndexes
          .map((n) => Number(n) || 0)
          .filter((n) => n >= 1 && n <= 6)
      : null;
  const n = Math.min(6, Math.max(1, count || 1));
  const indexes = allowed || Array.from({ length: n }, (_, i) => i + 1);
  const prev = selectEl.value || (includeAll ? "0" : String(indexes[0] || "1"));
  const optionsHtml = [];
  if (includeAll) {
    optionsHtml.push(`<option value="0">全話者（台本全体）</option>`);
  }
  for (const i of indexes) {
    const label = (getLabelFn ? getLabelFn(i) : `話者${i}`).trim() || `話者${i}`;
    optionsHtml.push(`<option value="${i}">${escapeHtml(label)}（話者${i}）</option>`);
  }
  if (!optionsHtml.length) {
    optionsHtml.push(`<option value="">担当話者がありません</option>`);
  }
  selectEl.innerHTML = optionsHtml.join("");
  if (selectEl.querySelector(`option[value="${prev}"]`)) selectEl.value = prev;
  else if (indexes[0]) selectEl.value = String(indexes[0]);
}

function renderRecordSpeakerOpenButtons(container, count, getLabelFn, onOpen, messageId = "ytMessage", options = {}) {
  if (!container) return;
  const includeAll = options.includeAll !== false;
  const allowed =
    Array.isArray(options.speakerIndexes) && options.speakerIndexes.length
      ? options.speakerIndexes
          .map((n) => Number(n) || 0)
          .filter((n) => n >= 1 && n <= 6)
      : null;
  const n = Math.min(6, Math.max(1, count || 1));
  const indexes = allowed || Array.from({ length: n }, (_, i) => i + 1);
  if (container.dataset.bound !== "1") {
    container.dataset.bound = "1";
    container.addEventListener("click", (event) => {
      const btn = event.target.closest("[data-record-speaker-open]");
      if (!btn) return;
      event.preventDefault();
      event.stopPropagation();
      const speakerIndex = Number(btn.getAttribute("data-record-speaker-open")) || 0;
      if (messageId) setMessage(messageId, "収録ページを開いています…", "ok");
      Promise.resolve(onOpen(speakerIndex))
        .catch((err) => {
          console.error("[record] open record page failed", err);
          const msg = err instanceof Error ? err.message : String(err);
          if (messageId) {
            setMessage(messageId, msg || "収録ページを開けませんでした。", "err");
            document.getElementById(messageId)?.scrollIntoView({ block: "nearest", behavior: "smooth" });
          }
        });
    });
  }
  if (!indexes.length && !includeAll) {
    container.innerHTML =
      `<p class="section-desc work-record-speaker-empty">担当として受諾済みの話者枠がありません。</p>`;
    return;
  }
  const disabled = options.disabled === true;
  const rows = [];
  if (includeAll) {
    rows.push(
      `<button type="button" class="record-speaker-open-btn record-speaker-open-btn--all" data-record-speaker-open="0"${disabled ? " disabled" : ""}>全話者（台本全体）</button>`
    );
  }
  for (const i of indexes) {
    const label = (getLabelFn ? getLabelFn(i) : `話者${i}`).trim() || `話者${i}`;
    const color = escapeHtml(getYtSpeakerColor(i));
    rows.push(
      `<button type="button" class="record-speaker-open-btn speaker-${i}" data-record-speaker-open="${i}"${disabled ? " disabled" : ""}${ytSpeakerAccentAttr(i)}>` +
        `<span class="record-speaker-open-btn-dot" style="background-color:${color}" aria-hidden="true"></span>` +
        `<span>${escapeHtml(label)}で収録</span>` +
        `</button>`
    );
  }
  container.innerHTML = rows.join("");
}

function refreshYtRecordSpeakerButtons() {
  refreshRecordSpeakerSelect(
    document.getElementById("ytRecordSpeakerSelect"),
    getYtSpeakerCount(),
    (i) => getYtSpeakerLabel(i)
  );
  renderRecordSpeakerOpenButtons(
    document.getElementById("ytRecordSpeakerButtons"),
    getYtSpeakerCount(),
    (i) => getYtSpeakerLabel(i),
    (speakerIndex) => openRecordWorkspaceFromYtForm(speakerIndex)
  );
}

function talentIdsEqual(a, b) {
  const na = String(a || "").toLowerCase().trim();
  const nb = String(b || "").toLowerCase().trim();
  if (!na || !nb) return false;
  if (na === nb) return true;
  const strip = (s) => s.replace(/^voice:/, "");
  return strip(na) === strip(nb);
}

/** 声優が収録できる話者番号（受諾済み枠。ID表記ゆれも吸収） */
function getVoiceRecordableSpeakerIndexes(request, talentId) {
  if (!request || !talentId) return [];
  const Tx = getTransactionApi();
  const wf = getWorkflowForRequest(request.requestId, request.status, request);
  const slots =
    Array.isArray(wf?.castAcceptance) && wf.castAcceptance.length
      ? wf.castAcceptance
      : getCastSlotsForRequest(request);
  const acceptedStatus = Tx?.SLOT_STATUS?.accepted || "accepted";
  const indexes = [];
  for (const slot of slots || []) {
    if (!talentIdsEqual(slot?.talentId, talentId)) continue;
    if (String(slot?.status || "") !== String(acceptedStatus)) continue;
    const idx = Number(slot.speakerIndex) || 0;
    if (idx >= 1 && !indexes.includes(idx)) indexes.push(idx);
  }
  return indexes.sort((a, b) => a - b);
}

function refreshWorkRecordSpeakerButtons(request) {
  void refreshWorkRecordSpeakerButtonsAsync(request);
}

async function refreshWorkRecordSpeakerButtonsAsync(request) {
  const paint = (req) => {
    const castSlots = getCastSlotsForRequest(req);
    const script = String(req?.script || "").trim();
    const count = getSpeakerCountFromScript(script, castSlots);
    const session = getCurrentSession();
    const wf = getWorkflowForRequest(req?.requestId, req?.status, req);
    const recordingUnlocked = isRecordingUnlocked(wf, req, session);
    workOpenTrace("record-ui-lock-state", {
      requestId: req?.requestId || "",
      role: session?.role || "",
      paymentStatus: wf?.paymentStatus || "",
      transactionPhase: wf?.transactionPhase || "",
      recordingUnlocked,
      acceptedSlots: (wf?.castAcceptance || []).filter((s) => String(s?.status) === "accepted").length
    });

    const selectOpts = {};
    const buttonOpts = {};
    if (session?.role === "voice") {
      const talentId = resolveVoiceTalentIdForSession(session);
      // 空配列でも必ず渡す（undefined だと全話者ボタンが出てしまう）
      const accepted = getVoiceRecordableSpeakerIndexes(req, talentId);
      selectOpts.includeAll = false;
      selectOpts.speakerIndexes = accepted;
      buttonOpts.includeAll = false;
      buttonOpts.speakerIndexes = accepted;
    }
    // キャンセル済みは押せない。それ以外は決済ゲートをクリック時に判定
    buttonOpts.disabled = isWorkflowCancelled(wf);
    syncWorkRecordPaymentLock(req, wf, session);
    refreshRecordSpeakerSelect(
      document.getElementById("workRecordSpeakerSelect"),
      count,
      (i) => getSpeakerLabelFromCast({ castSlots }, i),
      selectOpts
    );
    renderRecordSpeakerOpenButtons(
      document.getElementById("workRecordSpeakerButtons"),
      count,
      (i) => getSpeakerLabelFromCast({ castSlots }, i),
      (speakerIndex) => openRecordWorkspaceFromWorkPage(speakerIndex),
      "workMessage",
      buttonOpts
    );
  };

  // まずローカル状態で即描画（クラウド待ちでUIを固めない）
  paint(request);

  const session = getCurrentSession();
  if (session?.role === "voice" && request && isSupabaseEnabled()) {
    // 運営テストはクラウド再取得でUIを遅延させない
    if (!isOpsTestCase(request, getWorkflowForRequest(request.requestId, request.status, request), session)) {
      try {
        await ensureFreshWorkflowForRequest(request, { timeoutMs: 2500 });
        paint(request);
      } catch (err) {
        console.warn("[wavrick] refreshWorkRecordSpeakerButtons hydrate failed", err);
      }
    }
  }
}

function refreshYtRecordSpeakerSelect() {
  refreshYtRecordSpeakerButtons();
}

function refreshWorkRecordSpeakerSelect(request) {
  refreshWorkRecordSpeakerButtons(request);
}

function getReferenceAudioFromRequest(request) {
  const ref = getReferenceAudioUrls();
  return {
    rawAudioUrl: String(request?.rawAudioUrl || ref?.rawAudioUrl || "").trim(),
    cleanedAudioUrl: String(request?.cleanedAudioUrl || ref?.cleanedAudioUrl || "").trim()
  };
}

function attachReferenceAudioFields(target, request = null) {
  const audio = getReferenceAudioFromRequest(request);
  if (audio.rawAudioUrl) target.rawAudioUrl = audio.rawAudioUrl;
  if (audio.cleanedAudioUrl) target.cleanedAudioUrl = audio.cleanedAudioUrl;
  return target;
}

function resolveRecordMediaFromYtForm() {
  const videoUrl = document.getElementById("ytVideoUrl")?.value?.trim() || "";
  const sourceMode = getYtSourceMode();
  const audio = getReferenceAudioFromRequest();
  const audioFile = document.getElementById("ytAudioFile")?.files?.[0];
  const audioFileName = audioFile?.name || "";
  return {
    videoUrl,
    sourceMode,
    rawAudioUrl: audio.rawAudioUrl,
    cleanedAudioUrl: audio.cleanedAudioUrl,
    audioFileName,
    hasMedia: Boolean(videoUrl || audio.rawAudioUrl || audio.cleanedAudioUrl)
  };
}

function recordMediaReadyForWorkspace(media) {
  if (!media) return false;
  if (isYouTubeUrl(media.videoUrl)) return true;
  return Boolean(media.rawAudioUrl || media.cleanedAudioUrl);
}

function persistYtRecordContextToLocalStore({
  videoUrl = "",
  fullScript = "",
  castSlots = [],
  speakerCount = 0,
  requestName = "ブース直接"
} = {}) {
  const H = window.WavrickRecordHandoff;
  if (!H) return;
  const audio = getReferenceAudioFromRequest();
  const requestId = resolveYtAdhocRequestId(videoUrl);
  H.upsertRequestRow({
    requestId,
    videoUrl,
    script: fullScript,
    scriptsBySpeaker: normalizeScriptsBySpeakerMap(ytScriptsBySpeaker),
    castSlots,
    whisperSegments: Array.isArray(ytWhisperSegments) ? ytWhisperSegments.slice(0, 2500) : null,
    whisperDurationSec: ytWhisperDurationSec || 0,
    rawAudioUrl: audio.rawAudioUrl,
    cleanedAudioUrl: audio.cleanedAudioUrl,
    name: requestName
  });
}

function getSelectedRecordSpeakerIndex(selectId) {
  const n = Number(document.getElementById(selectId)?.value);
  return Number.isFinite(n) && n >= 1 ? n : 0;
}

function resolveYtAdhocRequestId(videoUrl) {
  try {
    const rows = JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]");
    const url = String(videoUrl || "").trim();
    const match =
      (url && rows.find((r) => String(r.videoUrl || "").trim() === url)) ||
      [...rows].reverse().find((r) => r.rawAudioUrl || r.script);
    return match?.requestId || `adhoc_${Date.now()}`;
  } catch {
    return `adhoc_${Date.now()}`;
  }
}

function navigateToRecordWorkspace(requestId, speakerIndex, options = {}) {
  const id = String(requestId || "").trim();
  if (!id) throw new Error("案件 ID がありません。");
  let spk = Number(speakerIndex) || 0;
  const H = window.WavrickRecordHandoff;
  const session = getCurrentSession();
  // 依頼フォーム / 顧客 → 顧客向け。案件管理の声優・運営 → 声優用収録ページ。
  const useCustomer =
    options.preferCustomer === true ||
    options.from === "yt" ||
    session?.role === "customer";

  if (useCustomer) {
    if (H?.goCustomerWorkspace) {
      H.goCustomerWorkspace(id, spk);
      return;
    }
    if (H?.setHandoff) H.setHandoff(id, spk);
    const params = new URLSearchParams();
    params.set("case", id);
    if (spk > 0) params.set("speaker", String(spk));
    window.location.href = `./customer-record-workspace.html?${params.toString()}`;
    return;
  }

  // 声優は受諾済みの担当話者以外へ遷移させない（URL 直打ち・誤クリック対策）
  if (session?.role === "voice" && !options.preferCustomer) {
    const talentId = resolveVoiceTalentIdForSession(session);
    let request = null;
    try {
      request = findLocalWorkRequestByAnyId(id);
    } catch {
      request = null;
    }
    if (!request) {
      try {
        request =
          JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]").find(
            (r) => r.requestId === id || r.rowId === id
          ) || null;
      } catch {
        request = null;
      }
    }
    const allowed = request ? getVoiceRecordableSpeakerIndexes(request, talentId) : [];
    if (allowed.length) {
      if (spk > 0 && !allowed.includes(spk)) {
        throw new Error(
          `話者${spk} は担当外です。担当の話者（${allowed.map((n) => `話者${n}`).join("・")}）のみ開けます。`
        );
      }
      if (!spk) spk = allowed[0];
    } else if (spk > 0) {
      throw new Error("受諾済みの担当話者枠がありません。先に案件を受諾してから収録してください。");
    }
  }

  if (H?.go) {
    H.go(id, spk);
    return;
  }
  if (H?.setHandoff) H.setHandoff(id, spk);
  const params = new URLSearchParams();
  params.set("case", id);
  if (spk > 0) params.set("speaker", String(spk));
  window.location.href = `./record-workspace.html?${params.toString()}`;
}

async function openRecordWorkspaceFromYtForm(speakerIndexOverride = null) {
  setMessage("ytMessage", "収録ページを開いています…", "ok");
  const media = resolveRecordMediaFromYtForm();
  if (!recordMediaReadyForWorkspace(media)) {
    setMessage(
      "ytMessage",
      media.sourceMode === "audio"
        ? "先に音声ファイルを選んで文字起こしするか、台本生成まで進めてください。"
        : "先に YouTube 動画 URL を入力するか、台本生成まで進めてください。",
      "err"
    );
    document.getElementById("ytMessage")?.scrollIntoView({ block: "nearest", behavior: "smooth" });
    return;
  }
  const fullScript = await resolveYtFullScriptForRecord({ skipRefine: true });
  if (!fullScript) {
    setMessage("ytMessage", "台本が空です。生成するか、タイムコード付き台本を貼り付けてください。", "err");
    document.getElementById("ytMessage")?.scrollIntoView({ block: "nearest", behavior: "smooth" });
    return;
  }
  const speakerIndex =
    speakerIndexOverride != null
      ? Number(speakerIndexOverride) || 0
      : getSelectedRecordSpeakerIndex("ytRecordSpeakerSelect");
  const castSlots = loadYtCastSlots(getYtSpeakerCount());
  const scriptsBySpeaker = getYtScriptsBySpeakerForRecord();
  const scriptForWorkspace =
    speakerIndex > 0
      ? resolveRecordScriptForSpeaker(fullScript, speakerIndex, castSlots, scriptsBySpeaker)
      : stripCastBlockFromScript(fullScript);
  if (!scriptTextLooksRecordable(scriptForWorkspace)) {
    setMessage(
      "ytMessage",
      speakerIndex > 0
        ? `話者${speakerIndex} の台本が見つかりません。生成台本の話者ブロックを確認するか、「全話者」で開いてください。`
        : "台本が空です。",
      "err"
    );
    document.getElementById("ytMessage")?.scrollIntoView({ block: "nearest", behavior: "smooth" });
    return;
  }
  persistYtRecordContextToLocalStore({
    videoUrl: media.videoUrl,
    fullScript,
    castSlots,
    speakerCount: castSlots.length
  });
  const requestId = resolveYtAdhocRequestId(media.videoUrl);
  const refAudio = getReferenceAudioUrls();
  const H = window.WavrickRecordHandoff;
  if (!H) {
    setMessage(
      "ytMessage",
      "収録引き継ぎモジュールが読み込まれていません。ページを再読み込みしてください。",
      "err"
    );
    document.getElementById("ytMessage")?.scrollIntoView({ block: "nearest", behavior: "smooth" });
    return;
  }
  H.upsertRequestRow({
    requestId,
    videoUrl: media.videoUrl,
    script: fullScript,
    scriptsBySpeaker: normalizeScriptsBySpeakerMap(scriptsBySpeaker),
    castSlots,
    whisperSegments: ytWhisperSegments,
    whisperDurationSec: ytWhisperDurationSec,
    rawAudioUrl: refAudio?.rawAudioUrl || media.rawAudioUrl,
    cleanedAudioUrl: refAudio?.cleanedAudioUrl || media.cleanedAudioUrl,
    sourceMode: media.sourceMode,
    name: "台本生成"
  });
  setWorkSelectedRequestId(requestId);
  navigateToRecordWorkspace(requestId, speakerIndex, { from: "yt", preferCustomer: true });
}

function enrichWorkRequestForRecord(request) {
  if (!request) return null;
  const wf = getWorkflowForRequest(request.requestId, request.status, request);
  const confirmed = getConfirmedDeliverables(request, wf);
  const fromWfRaw = mediaFieldsFromConfirmedDeliverables(
    wf?.confirmedDeliverables || request?.confirmedDeliverables
  );
  const castSlots =
    (Array.isArray(request.castSlots) && request.castSlots.length
      ? request.castSlots
      : null) ||
    (Array.isArray(confirmed?.castSlots) && confirmed.castSlots.length
      ? confirmed.castSlots
      : fromWfRaw.castSlots) ||
    getCastSlotsForRequest(request);

  const reqScripts = normalizeScriptsBySpeakerMap(request.scriptsBySpeaker);
  const confScripts = normalizeScriptsBySpeakerMap(
    confirmed?.scriptsBySpeaker || fromWfRaw.scriptsBySpeaker || {}
  );
  let scriptsBySpeaker = reqScripts;
  if (scriptsBySpeakerHasTimecodes(confScripts) && !scriptsBySpeakerHasTimecodes(reqScripts)) {
    scriptsBySpeaker = { ...confScripts, ...reqScripts };
  } else if (!Object.keys(reqScripts).length && Object.keys(confScripts).length) {
    scriptsBySpeaker = confScripts;
  } else if (Object.keys(confScripts).length) {
    scriptsBySpeaker = { ...confScripts, ...reqScripts };
  }

  return {
    ...request,
    castSlots,
    scriptsBySpeaker,
    script: String(request.script || confirmed?.scriptFull || fromWfRaw.script || "").trim(),
    videoUrl: String(
      request.videoUrl || confirmed?.videoUrl || fromWfRaw.videoUrl || ""
    ).trim(),
    rawAudioUrl:
      request.rawAudioUrl || confirmed?.rawAudioUrl || fromWfRaw.rawAudioUrl || null,
    cleanedAudioUrl:
      request.cleanedAudioUrl || confirmed?.cleanedAudioUrl || fromWfRaw.cleanedAudioUrl || null,
    whisperSegments:
      request.whisperSegments ||
      (Array.isArray(confirmed?.whisperSegments) ? confirmed.whisperSegments : null),
    whisperDurationSec:
      Number(request.whisperDurationSec) ||
      Number(confirmed?.whisperDurationSec) ||
      0
  };
}

function requestHasRecordMedia(request) {
  const videoUrl = String(request?.videoUrl || "").trim();
  const audio = getReferenceAudioFromRequest(request);
  if (audio.rawAudioUrl || audio.cleanedAudioUrl) return true;
  if (!videoUrl) return false;
  if (isYouTubeUrl(videoUrl)) return true;
  // アフレコ用: http(s) の動画/音声 URL も素材として認める
  return /^https?:\/\//i.test(videoUrl);
}

function requestHasExtractedAudio(request) {
  return Boolean(
    String(request?.rawAudioUrl || "").trim() ||
      String(request?.cleanedAudioUrl || "").trim() ||
      String(request?.confirmedDeliverables?.rawAudioUrl || "").trim() ||
      String(request?.confirmedDeliverables?.cleanedAudioUrl || "").trim()
  );
}

function requestNeedsMediaEnrichment(request) {
  if (!request) return true;
  // 収録ページを開ける素材が既にあればクラウド補完は必須ではない（任意の改善のみ）
  if (requestHasRecordMedia(request)) return false;
  return true;
}

async function softAwait(promise, ms, label) {
  try {
    return await withTimeout(Promise.resolve(promise), ms, label || "soft_await");
  } catch (err) {
    console.warn("[wavrick]", label || "soft_await", "timed out or failed", err);
    return null;
  }
}

/** ローカル stub に YouTube/音声が無いとき、クラウドから本体をマージする */
async function enrichRequestRowFromRemote(request) {
  if (!request || !isSupabaseEnabled()) return request;
  const ids = listRequestWorkflowAliasKeys(request);
  let best = request;
  let ytHit = false;
  for (const id of ids) {
    const remote = await softAwait(fetchRemoteYoutubeRequestByAnyId(id), 4500, `enrich_yt_${id.slice(0, 8)}`);
    if (!remote?.row) {
      workOpenTrace("enrich-yt-miss", {
        id,
        error: remote?.error && (remote.error.message || remote.error)
      });
      continue;
    }
    ytHit = true;
    best = mergeYoutubeRequestFields(best, remote.row);
    workOpenTrace("enrich-media-from-remote", {
      id,
      via: remote.via || null,
      videoUrl: String(best.videoUrl || "").slice(0, 80),
      hasRaw: Boolean(best.rawAudioUrl),
      hasClean: Boolean(best.cleanedAudioUrl)
    });
  }

  // 音声 or 話者ブロック不足なら workflow.confirmed_deliverables も必ず見る
  if (
    requestNeedsMediaEnrichment(best) ||
    requestNeedsSpeakerBlockEnrichment(best)
  ) {
    for (const id of ids) {
      const wfRemote = await softAwait(fetchRemoteWorkflowByAnyId(id), 4500, `enrich_wf_${id.slice(0, 8)}`);
      if (!wfRemote?.row) continue;
      const workflows = getWorkflows();
      workflows[id] = { ...wfRemote.row, requestId: id };
      if (wfRemote.row.requestId && wfRemote.row.requestId !== id) {
        workflows[wfRemote.row.requestId] = wfRemote.row;
      }
      persistWorkflowsLocalStorage(workflows);

      const listing = findRecruitmentListingCase(id);
      const fromConfirmed = mediaFieldsFromConfirmedDeliverables(wfRemote.row.confirmedDeliverables);
      const patched = {
        ...best,
        videoUrl: String(
          best.videoUrl || listing?.videoUrl || fromConfirmed.videoUrl || ""
        ).trim(),
        script: String(best.script || listing?.script || fromConfirmed.script || "").trim(),
        scriptsBySpeaker: {
          ...fromConfirmed.scriptsBySpeaker,
          ...normalizeScriptsBySpeakerMap(best.scriptsBySpeaker)
        },
        castSlots:
          (Array.isArray(best.castSlots) && best.castSlots.length
            ? best.castSlots
            : null) ||
          fromConfirmed.castSlots ||
          wfRemote.row.castAcceptance ||
          [],
        confirmedDeliverables:
          best.confirmedDeliverables || fromConfirmed.confirmedDeliverables || null,
        rawAudioUrl: best.rawAudioUrl || fromConfirmed.rawAudioUrl || null,
        cleanedAudioUrl: best.cleanedAudioUrl || fromConfirmed.cleanedAudioUrl || null
      };
      best = mergeYoutubeRequestFields(best, patched);
      workOpenTrace("enrich-media-from-workflow", {
        id,
        ytHit,
        videoUrl: String(best.videoUrl || "").slice(0, 80),
        hasRaw: Boolean(best.rawAudioUrl),
        hasConfirmed: Boolean(fromConfirmed.confirmedDeliverables),
        confirmedVideo: String(fromConfirmed.videoUrl || "").slice(0, 80),
        scriptKeys: Object.keys(normalizeScriptsBySpeakerMap(best.scriptsBySpeaker))
      });
      if (
        !requestNeedsMediaEnrichment(best) &&
        !requestNeedsSpeakerBlockEnrichment(best)
      ) {
        break;
      }
    }
  }

  if (best !== request) {
    upsertLocalYoutubeRequest(best);
  }
  return best;
}

/** 話者ブロック = scriptsBySpeaker の担当枠（アフレコ用の話者分け単位） */
function getSpeakerBlockTextForRequest(request, speakerIndex) {
  const map = normalizeScriptsBySpeakerMap(request?.scriptsBySpeaker);
  const idx = Number(speakerIndex) || 0;
  if (idx < 1) return "";
  return String(map[String(idx)] || map[idx] || "").trim();
}

function requestHasSpeakerBlocks(request, speakerIndex = 0) {
  const map = normalizeScriptsBySpeakerMap(request?.scriptsBySpeaker);
  if (Number(speakerIndex) > 0) return Boolean(getSpeakerBlockTextForRequest(request, speakerIndex));
  return Object.keys(map).length > 0;
}

async function openRecordWorkspaceFromWorkPage(speakerIndexOverride = null, navOptions = {}) {
  const setRecordMsg = (text, status = "ok") => {
    setMessage("workMessage", text, status);
    const local = document.getElementById("workRecordOpenMessage");
    if (local) {
      local.hidden = !text;
      local.textContent = text || "";
      local.classList.remove("ok", "err");
      if (status) local.classList.add(status);
      if (status === "err") {
        local.scrollIntoView({ block: "nearest", behavior: "smooth" });
      }
    }
  };

  setRecordMsg("収録ページを開いています…", "ok");
  workOpenTrace("record-open-start", {
    speakerIndexOverride,
    preferCustomer: Boolean(navOptions?.preferCustomer)
  });

  try {
    // 高速ルート: ローカル即判定。クラウド待ちはしない
    return await withTimeout(
      openRecordWorkspaceFromWorkPageInner(speakerIndexOverride, navOptions, setRecordMsg),
      4000,
      "record_open"
    );
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    workOpenTrace("record-open-timeout-or-fail", { error: msg });
    setRecordMsg(
      msg.includes("timeout")
        ? "収録ページの準備がタイムアウトしました。ページを再読み込みしてから再度お試しください。"
        : msg || "収録ページを開けませんでした。",
      "err"
    );
    return false;
  }
}

/** ブラウザ内 ADR キャッシュを同期マージ（ネットワークなし） */
function mergeBrowserAdrIntoRequest(request) {
  if (!request?.requestId) return request;
  try {
    const adr = globalThis.WavrickAdrApi?.readBrowserProject?.(request.requestId);
    if (!adr) return request;
    const audioUrl = String(adr.audioUrl || adr.audio_url || "").trim();
    if (audioUrl) {
      request.rawAudioUrl = request.rawAudioUrl || audioUrl;
      request.cleanedAudioUrl = request.cleanedAudioUrl || audioUrl;
    }
    if (!String(request.videoUrl || "").trim() && adr.videoUrl) {
      request.videoUrl = adr.videoUrl;
    }
    if (Array.isArray(adr.speakers) && adr.speakers.length) request.adrSpeakers = adr.speakers;
    if (Array.isArray(adr.cues) && adr.cues.length) {
      request.adrCues = adr.cues;
      if (!scriptsBySpeakerHasTimecodes(request.scriptsBySpeaker)) {
        const fmt = (sec) => {
          const s = Math.max(0, Number(sec) || 0);
          const m = Math.floor(s / 60);
          const rem = s - m * 60;
          const whole = Math.floor(rem);
          const frac = Math.round((rem - whole) * 100);
          return `${String(m).padStart(2, "0")}:${String(whole).padStart(2, "0")}.${String(frac).padStart(2, "0")}`;
        };
        const indexById = {};
        (adr.speakers || []).forEach((sp, i) => {
          indexById[sp.id] = i + 1;
        });
        const map = {};
        for (const c of [...adr.cues].sort(
          (a, b) => (Number(a.startSec) || 0) - (Number(b.startSec) || 0)
        )) {
          const key = String(indexById[c.speakerId] || 1);
          const text = String(c.comment || c.text || "").trim();
          const line = `[${fmt(c.startSec)} - ${fmt(c.endSec)}]${text ? ` ${text}` : ""}`;
          map[key] = map[key] ? `${map[key]}\n${line}` : line;
        }
        request.scriptsBySpeaker = normalizeScriptsBySpeakerMap(map);
      }
    }
    if (!request.sourceMode) request.sourceMode = "adr";
  } catch {
    /* ignore */
  }
  return request;
}

async function openRecordWorkspaceFromWorkPageInner(speakerIndexOverride, navOptions, setRecordMsg) {
  const session = getCurrentSession();
  const requestSelect = document.getElementById("workRequestSelect");
  const preferredId =
    String(requestSelect?.value || "").trim() ||
    getPreferredWorkRequestId() ||
    getWorkSelectedRequestId();

  let rows = await getVisibleRequestsForCurrentSession({ localOnly: true });
  let rawRequest =
    rows.find(
      (r) =>
        r.requestId === preferredId ||
        r.rowId === preferredId ||
        String(r.id || "") === String(preferredId)
    ) ||
    rows[0] ||
    null;

  if (!rawRequest && preferredId) {
    try {
      const localAll = JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]");
      rawRequest =
        localAll.find(
          (r) =>
            r.requestId === preferredId ||
            r.rowId === preferredId ||
            String(r.id || "") === preferredId
        ) || null;
    } catch {
      /* ignore */
    }
  }
  if (!rawRequest) {
    workOpenTrace("record-open-no-request", {
      preferredId,
      visibleCount: rows.length,
      role: session?.role || ""
    });
    setRecordMsg("開ける案件がありません。先に案件を開いてから収録してください。", "err");
    return false;
  }

  let request = ensureScriptsBySpeakerOnRequest(enrichWorkRequestForRecord(rawRequest));
  request = mergeBrowserAdrIntoRequest(request);
  setWorkSelectedRequestId(request.requestId);
  setWorkCaseOpenLock(request.requestId);

  const talentId = session?.role === "voice" ? resolveVoiceTalentIdForSession(session) : "";
  let speakerIndex =
    speakerIndexOverride != null
      ? Number(speakerIndexOverride) || 0
      : getSelectedRecordSpeakerIndex("workRecordSpeakerSelect");

  const wfLocal = getWorkflowForRequest(request.requestId, request.status, request);
  if (isWorkflowCancelled(wfLocal)) {
    workOpenTrace("record-open-cancelled", {
      requestId: request.requestId,
      status: wfLocal?.status || "",
      transactionPhase: wfLocal?.transactionPhase || ""
    });
    setRecordMsg(cancelledCaseMessage(), "err");
    return false;
  }
  const opsTest = isOpsTestCase(request, wfLocal, session);
  const skipLivePaymentGate =
    Boolean(navOptions?.preferCustomer) ||
    Boolean(navOptions?.skipPaymentGate) ||
    opsTest;

  if (session?.role === "voice") {
    const allowed = getVoiceRecordableSpeakerIndexes(request, talentId);
    if (!allowed.length && !navOptions?.preferCustomer) {
      setRecordMsg(
        "受諾済みの担当話者枠がありません。先に案件を受諾してから収録ページを開いてください。",
        "err"
      );
      return false;
    }

    if (opsTest) {
      // 運営テスト: 受諾済みなら収録ページは開ける。
      // ただし仮決済ボタンを押すまで paymentStatus は書き換えない（決済完了通知の誤発火防止）。
      workOpenTrace("record-open-ops-test-unlock", {
        requestId: request.requestId,
        paymentStatus: wfLocal?.paymentStatus || "",
        phase: wfLocal?.transactionPhase || "",
        paymentCleared: isWorkflowPaymentCleared(wfLocal, request, session)
      });
    } else if (!skipLivePaymentGate) {
      // 本番: 受諾済みなら収録ページ可。未決済なら注意ダイアログのあと開く（納品は別ゲート）
      if (!isRecordingUnlocked(wfLocal, request, session)) {
        workOpenTrace("record-open-accept-blocked", {
          requestId: request.requestId,
          paymentStatus: wfLocal?.paymentStatus || "",
          transactionPhase: wfLocal?.transactionPhase || ""
        });
        setRecordMsg(
          t("work.record_accept_required") ||
            "受諾済みの担当話者枠がありません。先に案件を受諾してから収録ページを開いてください。",
          "err"
        );
        return false;
      }
      if (!isWorkflowPaymentCleared(wfLocal, request, session)) {
        workOpenTrace("record-open-prepay-notice", {
          requestId: request.requestId,
          paymentStatus: wfLocal?.paymentStatus || "",
          transactionPhase: wfLocal?.transactionPhase || ""
        });
        const title =
          t("work.record_prepay_notice_title") || "決済完了前の収録について";
        const body =
          t("work.record_prepay_notice_body") ||
          "顧客の決済が完了していません。決済完了前ではキャンセルなどをされても声優への送金はできません。納品（提出）も決済完了後に可能になります。";
        const okLabel = t("work.record_prepay_notice_ok") || "はい";
        const acknowledged = await confirmModalAsync(title, body, {
          confirmLabel: okLabel,
          okOnly: true,
          safe: true
        });
        if (!acknowledged) {
          setRecordMsg("", "");
          return false;
        }
      }
    }

    if (!allowed.length) {
      /* already handled above when !preferCustomer */
    } else if (speakerIndex > 0 && !allowed.includes(speakerIndex)) {
      setRecordMsg(
        `話者${speakerIndex} は担当外です。担当の話者（${allowed.map((n) => `話者${n}`).join("・")}）のみ収録ページを開けます。`,
        "err"
      );
      return false;
    } else if (!speakerIndex || speakerIndex <= 0) {
      speakerIndex = allowed[0];
    }
  }

  if (!requestHasRecordMedia(request)) {
    setRecordMsg(
      "この案件の動画URL／参考音声がありません。案件を開き直すか、顧客側で素材を確認してください。",
      "err"
    );
    return false;
  }

  const castSlots =
    (getWorkflowForRequest(request.requestId, request.status, request)?.castAcceptance?.length
      ? getWorkflowForRequest(request.requestId, request.status, request).castAcceptance
      : null) || getCastSlotsForRequest(request);
  const scriptsBySpeaker = normalizeScriptsBySpeakerMap(request.scriptsBySpeaker);
  const speakerBlock =
    speakerIndex > 0 ? getSpeakerBlockTextForRequest(request, speakerIndex) : "";

  const H = window.WavrickRecordHandoff;
  if (!H) {
    setRecordMsg(
      "収録引き継ぎモジュールが読み込まれていません。ページを再読み込みしてください。",
      "err"
    );
    return false;
  }

  const fullScript = String(request.script || "").trim();
  const handoffPatch = {
    requestId: request.requestId,
    videoUrl: String(request.videoUrl || "").trim(),
    castSlots,
    whisperDurationSec: Number(request.whisperDurationSec) || 0,
    rawAudioUrl: request.rawAudioUrl || null,
    cleanedAudioUrl: request.cleanedAudioUrl || null,
    sourceMode: request.sourceMode || "",
    name: request.name || "案件",
    email: request.email || ""
  };
  if (fullScript) handoffPatch.script = fullScript;
  if (Object.keys(scriptsBySpeaker).length) handoffPatch.scriptsBySpeaker = scriptsBySpeaker;
  if (Array.isArray(request.whisperSegments) && request.whisperSegments.length) {
    handoffPatch.whisperSegments = request.whisperSegments;
  }
  if (Array.isArray(request.adrSpeakers) && request.adrSpeakers.length) {
    handoffPatch.adrSpeakers = request.adrSpeakers;
  }
  if (Array.isArray(request.adrCues) && request.adrCues.length) {
    handoffPatch.adrCues = request.adrCues;
  }
  try {
    H.upsertRequestRow(handoffPatch);
  } catch (upsertErr) {
    console.warn("[wavrick] handoff upsert failed", upsertErr);
  }
  setWorkSelectedRequestId(request.requestId);
  workOpenTrace("record-open-navigate", {
    requestId: request.requestId,
    speakerIndex,
    role: session?.role || "",
    opsTest,
    hasMedia: true,
    hasSpeakerBlock: Boolean(speakerBlock),
    mode: "fast-local"
  });
  try {
    navigateToRecordWorkspace(request.requestId, speakerIndex, {
      from: "work",
      ...navOptions
    });
  } catch (err) {
    console.error("[wavrick] navigateToRecordWorkspace failed", err);
    setRecordMsg(err instanceof Error ? err.message : "収録ページを開けませんでした。", "err");
    return false;
  }
  return true;
}

function splitYtScriptBodyIntoLines(text) {
  const t = String(text || "").trim();
  if (!t) return [];
  const rows = t
    .split(/\r?\n/)
    .map((s) => s.trim())
    .filter((s) => s && s !== "/" && s !== "[NEW_BLOCK]");
  if (rows.some((r) => /^\[\d{1,2}:\d{2}/.test(r))) {
    return rows;
  }
  if (rows.length > 1) return rows;
  if (/[。！？!?]/.test(t)) {
    const sentences = t
      .split(/(?<=[。！？!?])/)
      .map((s) => s.trim())
      .filter(Boolean);
    if (sentences.length > 1) return sentences;
  }
  return [t];
}

function splitYtSpeakerScriptIntoBlocks(bodyText) {
  const t = String(bodyText || "").trim();
  if (!t) return [];
  if (/\d{2}:\d{2}:\d{2},\d{3}\s*-->/.test(t)) {
    return t
      .split(/\n\s*\n\s*\n/)
      .map((b) => b.trim())
      .filter(Boolean);
  }
  if (/\n\n---\n\n/.test(t) && /->/.test(t)) {
    return t
      .split(/\n\n---\n\n/)
      .map((b) => b.trim())
      .filter(Boolean);
  }
  if (/\[NEW_BLOCK\]/i.test(t)) {
    return t
      .split(/\n*\[NEW_BLOCK\]\n*/)
      .map((b) => b.trim())
      .filter(Boolean);
  }
  if (/\n---\n/.test(t)) {
    return t
      .split(/\n---\n/)
      .map((b) => b.trim())
      .filter(Boolean);
  }
  if (/^\[(\d{1,2}):(\d{2})/m.test(t)) {
    return [t];
  }
  return splitGeneratedSpeakerBodyByTimeGap(t, YT_ASSIGN_GAP_SEC);
}

const YT_SCRIPT_RECONCILE_BATCH_THRESHOLD = 60;

function mergeScriptReconcileResults(results) {
  const merged = {
    ok: true,
    mode: "script-reconcile",
    scriptsBySpeaker: {},
    script: "",
    chronologicalScript: "",
    adlibSegments: [],
    adlibSpans: [],
    timecodedByWhisper: true,
    sourceOnly: true,
    durationMs: 0
  };
  const chronoParts = [];
  for (const data of results) {
    if (!data?.ok) continue;
    const bySp = data.scriptsBySpeaker || {};
    for (const [k, v] of Object.entries(bySp)) {
      const prev = String(merged.scriptsBySpeaker[k] || "").trim();
      const next = String(v || "").trim();
      merged.scriptsBySpeaker[k] = prev && next ? `${prev}\n${next}` : prev || next;
    }
    if (Array.isArray(data.adlibSegments)) {
      merged.adlibSegments.push(...data.adlibSegments);
    }
    if (Array.isArray(data.adlibSpans)) {
      merged.adlibSpans.push(...data.adlibSpans);
    }
    merged.durationMs += Number(data.durationMs) || 0;
    const chrono = String(data.chronologicalScript || data.script || "").trim();
    if (chrono) chronoParts.push(chrono);
  }
  merged.chronologicalScript = chronoParts.join("\n");
  merged.script = merged.chronologicalScript;
  return merged;
}

async function invokeScriptReconcileBatched(basePayload, assignRanges, progressEl) {
  const speakerIds = [
    ...new Set(assignRanges.map((r) => r.speakerIndex).filter((n) => n >= 1))
  ].sort((a, b) => a - b);
  if (
    assignRanges.length < YT_SCRIPT_RECONCILE_BATCH_THRESHOLD ||
    speakerIds.length <= 1
  ) {
    return invokeMediaPipeline({ ...basePayload, assignRanges });
  }
  const results = [];
  const prevLabel = progressEl?.textContent || "";
  for (let si = 0; si < speakerIds.length; si++) {
    const sp = speakerIds[si];
    if (progressEl) {
      progressEl.textContent = `台本下書きを作成中... (${si + 1}/${speakerIds.length})`;
    }
    const spRanges = assignRanges.filter((r) => r.speakerIndex === sp);
    const { data, error } = await invokeMediaPipeline({
      ...basePayload,
      assignRanges: spRanges
    });
    if (error && (!data || data.ok === undefined)) {
      if (progressEl) progressEl.textContent = prevLabel;
      return { data, error };
    }
    if (data && data.ok === false) {
      if (progressEl) progressEl.textContent = prevLabel;
      return { data, error: null };
    }
    results.push(data);
  }
  if (progressEl) progressEl.textContent = prevLabel;
  return { data: mergeScriptReconcileResults(results), error: null };
}

function formatPipelineScriptForField(data, count, slots) {
  const parts = [];
  const scriptsBySpeaker =
    data?.scriptsBySpeaker && typeof data.scriptsBySpeaker === "object"
      ? data.scriptsBySpeaker
      : {};
  const hasPerSpeakerScripts = Object.values(scriptsBySpeaker).some((v) =>
    String(v || "").trim()
  );
  const chronoBody = String(data?.script || "").trim();
  const useChronological =
    !hasPerSpeakerScripts &&
    data?.timecodedByWhisper &&
    chronoBody &&
    /^\[(\d{1,2}):(\d{2})/m.test(chronoBody);

  if (useChronological) {
    parts.push("【台本（時系列）】");
    const blockLines = splitYtScriptBodyIntoLines(chronoBody);
    parts.push(blockLines.length ? blockLines.join("\n") : "（空）");
    parts.push("");
    parts.push("【キャスト】");
    for (let i = 1; i <= count; i++) {
      const slot = slots.find((s) => s.speakerIndex === i);
      const speakerLabel = getYtSpeakerLabel(i);
      const castLabel =
        slot?.mode === "recruit" || slot?.mode === "omakase"
          ? "募集"
          : slot?.displayName || slot?.talentId || "未選択";
      parts.push(`・${speakerLabel} → 声優: ${castLabel}`);
    }
    parts.push("");
  } else {
    for (let i = 1; i <= count; i++) {
      const key = String(i);
      const bodyText = String(scriptsBySpeaker[key] || scriptsBySpeaker[i] || "").trim();
      const slot = slots.find((s) => s.speakerIndex === i);
      const speakerLabel = getYtSpeakerLabel(i);
      const castLabel =
        slot?.mode === "recruit" || slot?.mode === "omakase"
          ? "募集"
          : slot?.displayName || slot?.talentId || "未選択";
      const blocks = splitYtSpeakerScriptIntoBlocks(bodyText);
      if (!blocks.length) {
        parts.push(`【${speakerLabel} / 声優: ${castLabel}】`);
        parts.push("（空）");
        parts.push("");
        continue;
      }
      blocks.forEach((block, bi) => {
        const partLabel = blocks.length > 1 ? ` / ブロック${bi + 1}` : "";
        parts.push(`【${speakerLabel} / 声優: ${castLabel}${partLabel}】`);
        const blockLines = splitYtScriptBodyIntoLines(block || "");
        parts.push(blockLines.length ? blockLines.join("\n") : "（空）");
        parts.push("");
      });
    }
  }
  return parts.join("\n").trim();
}

function resetYtSpeakerAssign() {
  ytTranscriptPlain = "";
  ytTranscriptPlainAtWhisper = "";
  ytTranscribeJobId = "";
  ytWhisperSegments = [];
  ytWhisperDurationSec = 0;
  ytWhisperTimeline = "";
  ytAssignRanges = [];
  ytAssignRangeHistory = [];
  ytAssignRangeSeq = 0;
  ytActiveSpeaker = 1;
  ytAssignAnchor = null;
  ytAssignPreviewFocusSpeaker = 0;
  ytAssignPreviewFocusRangeId = 0;
  resetYtReconcilePreview();
}

function splitGeneratedSpeakerBodyByTimeGap(bodyText, gapSec) {
  const raw = String(bodyText || "").trim();
  if (!raw) return [];
  const LINE_RE =
    /^(~?)\[(\d{1,2}):(\d{2})(?:\.(\d{1,3}))?(?:\s*(?:->|→|-)\s*(\d{1,2}):(\d{2})(?:\.(\d{1,3}))?)?\](~?)\s*(.+)$/;
  const parseTc = (min, sec, frac) => {
    const f = frac == null || frac === "" ? 0 : Number(frac);
    const digits = String(frac || "").length;
    const fracSec = !Number.isFinite(f) ? 0 : digits <= 2 ? f / 100 : digits === 3 ? f / 1000 : f;
    return Number(min) * 60 + Number(sec) + fracSec;
  };
  const rows = [];
  for (const line of raw.split(/\r?\n/)) {
    const t = line.trim();
    if (!t || t === "/" || t === "[NEW_BLOCK]") continue;
    const m = t.match(LINE_RE);
    if (!m) {
      if (rows.length) rows[rows.length - 1].textLines.push(t);
      else rows.push({ startSec: 0, endSec: null, textLines: [t] });
      continue;
    }
    const startSec = parseTc(m[2], m[3], m[4]);
    const endSec = m[5] != null ? parseTc(m[5], m[6], m[7]) : null;
    rows.push({ startSec, endSec, textLines: [m[9].trim()] });
  }
  if (!rows.length) return [raw];
  const blocks = [];
  let batch = [];
  let lastEnd = null;
  const flush = () => {
    if (!batch.length) return;
    blocks.push(batch.join("\n"));
    batch = [];
  };
  for (const row of rows) {
    if (lastEnd != null && row.startSec - lastEnd > gapSec) flush();
    const end =
      row.endSec != null && row.endSec > row.startSec
        ? row.endSec
        : row.startSec + 2;
    batch.push(`[${formatYtTimecode(row.startSec)}${row.endSec != null ? ` - ${formatYtTimecode(row.endSec)}` : ""}] ${row.textLines.join(" ")}`);
    lastEnd = end;
  }
  flush();
  return blocks.length ? blocks : [raw];
}

function formatYtTimecode(seconds) {
  const s = Math.max(0, seconds);
  const m = Math.floor(s / 60);
  const sec = s - m * 60;
  const whole = Math.floor(sec);
  const cs = Math.round((sec - whole) * 100);
  return `${String(m).padStart(2, "0")}:${String(whole).padStart(2, "0")}.${String(cs).padStart(2, "0")}`;
}

function isYtTranscriptSrtLike(text) {
  const t = String(text || "").trim();
  if (!t) return false;
  return (
    /\d{1,2}:\d{2}:\d{2}[,.]\d{3}\s*-->/.test(t) ||
    /^\[\d{1,2}:\d{2}(?:\.\d{2})?\s*(?:->|→|-)/m.test(t)
  );
}

async function buildYtWhisperSrtForDisplay(segments, durationSec, apiSrt, apiTimeline) {
  if (typeof apiSrt === "string" && apiSrt.trim()) {
    return apiSrt.trim();
  }
  if (typeof apiTimeline === "string" && apiTimeline.trim()) {
    return apiTimeline.trim();
  }
  if (!Array.isArray(segments) || !segments.length) return "";
  try {
    const { buildBracketTimelineFromWhisperSegments } = await import(
      `./js/record-workspace/timecode-silence-gap.js?v=${RW_SCRIPT_IMPORT_VER}`
    );
    return buildBracketTimelineFromWhisperSegments(segments, durationSec) || "";
  } catch (e) {
    console.warn("[yt] build whisper timeline failed", e);
    return "";
  }
}

async function ingestWhisperTimingFromTranscribe(data) {
  ytTranscribeJobId = String(data?.jobId || "").trim();
  ytWhisperDurationSec =
    Number(data?.audioDurationSec) ||
    Number(data?.whisperDurationSec) ||
    0;
  ytWhisperSegments = [];
  ytWhisperTimeline = "";
  ytTranscriptSrt = "";
  ytTranscriptSrtAtWhisper = "";
  ytTranscriptPlainAtWhisper = resolveYtTranscriptPlainFromWhisper(data);
}

async function alignYtScriptToWhisperTimeline(scriptText) {
  const canon = String(ytWhisperTimeline || "").trim();
  const raw = String(scriptText || "").trim();
  if (!canon || !raw || !/\[\d{1,2}:\d{2}/.test(raw)) return raw;
  try {
    const { alignGrokScriptToWhisperTimeline, stripTranscribeBuildMarker } = await import(
      `./js/record-workspace/grok-whisper-align.js?v=${RW_GROK_WHISPER_ALIGN_VER}`
    );
    return alignGrokScriptToWhisperTimeline(stripTranscribeBuildMarker(canon), raw);
  } catch (e) {
    console.warn("[yt] align script to whisper timeline failed", e);
    return raw;
  }
}

const REFERENCE_AUDIO_KEY = "wavrick_reference_audio";

function storeReferenceAudioUrls(rawUrl, cleanedUrl) {
  const payload = { rawAudioUrl: rawUrl || null, cleanedAudioUrl: cleanedUrl || null };
  try { localStorage.setItem(REFERENCE_AUDIO_KEY, JSON.stringify(payload)); } catch { /* */ }
}

function persistReferenceAudioToYoutubeRequest(videoUrl, rawUrl, cleanedUrl) {
  const url = String(videoUrl || "").trim();
  if (!rawUrl && !cleanedUrl) return;
  try {
    const rows = JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]");
    if (!Array.isArray(rows)) return;
    const match =
      (url && rows.find((r) => String(r.videoUrl || "").trim() === url)) ||
      rows[rows.length - 1];
    if (!match) return;
    if (rawUrl) match.rawAudioUrl = rawUrl;
    if (cleanedUrl) match.cleanedAudioUrl = cleanedUrl;
    match.updatedAt = new Date().toISOString();
    localStorage.setItem("wavrick_youtube_requests", JSON.stringify(rows));
    void persistYoutubeRequestToCloud(match);
  } catch {
    /* ignore */
  }
}

function enrichRecordWorkspacePayload(payload) {
  const base = { ...(payload || {}) };
  if (base.rawAudioUrl) return base;
  const ref = getReferenceAudioUrls();
  if (ref.rawAudioUrl) {
    return {
      ...base,
      rawAudioUrl: ref.rawAudioUrl,
      cleanedAudioUrl: ref.cleanedAudioUrl || undefined
    };
  }
  const videoUrl = String(base.videoUrl || "").trim();
  const requestId = String(base.requestId || "").trim();
  if (!videoUrl && !requestId) return base;
  try {
    const rows = JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]");
    const match = rows.find(
      (r) =>
        (requestId && r.requestId === requestId) ||
        (videoUrl && String(r.videoUrl || "").trim() === videoUrl)
    );
    if (match?.rawAudioUrl) {
      return {
        ...base,
        rawAudioUrl: match.rawAudioUrl,
        cleanedAudioUrl: match.cleanedAudioUrl || undefined
      };
    }
  } catch {
    /* ignore */
  }
  return base;
}

function getReferenceAudioUrls() {
  try { return JSON.parse(localStorage.getItem(REFERENCE_AUDIO_KEY) || "null"); } catch { return null; }
}

function resolvePlainTextPosition(container, plainOffset) {
  if (!container) return null;
  const walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT);
  let pos = 0;
  let node = walker.nextNode();
  while (node) {
    const len = node.textContent.length;
    if (plainOffset <= pos + len) {
      return { node, offset: Math.max(0, plainOffset - pos) };
    }
    pos += len;
    node = walker.nextNode();
  }
  return null;
}

function getPlainOffsetFromPointer(container, clientX, clientY) {
  if (!container) return null;
  let range = null;
  if (document.caretRangeFromPoint) {
    range = document.caretRangeFromPoint(clientX, clientY);
  } else if (document.caretPositionFromPoint) {
    const caret = document.caretPositionFromPoint(clientX, clientY);
    if (caret) {
      range = document.createRange();
      range.setStart(caret.offsetNode, caret.offset);
      range.collapse(true);
    }
  }
  if (!range || !container.contains(range.startContainer)) return null;
  const pre = document.createRange();
  pre.selectNodeContents(container);
  pre.setEnd(range.startContainer, range.startOffset);
  const offset = pre.toString().length;
  const max = ytTranscriptPlain.length;
  return Math.max(0, Math.min(offset, max));
}

function setDomSelectionPlainRange(container, start, end) {
  const startPos = resolvePlainTextPosition(container, start);
  const endPos = resolvePlainTextPosition(container, end);
  if (!startPos || !endPos) return false;
  const range = document.createRange();
  range.setStart(startPos.node, startPos.offset);
  range.setEnd(endPos.node, endPos.offset);
  const sel = window.getSelection();
  if (!sel) return false;
  sel.removeAllRanges();
  sel.addRange(range);
  return true;
}

function scrollPlainOffsetIntoView(container, plainOffset) {
  const pos = resolvePlainTextPosition(container, plainOffset);
  if (!pos) return;
  const range = document.createRange();
  range.setStart(pos.node, pos.offset);
  range.collapse(true);
  const rect = range.getClientRects()[0];
  if (!rect) return;
  const boxRect = container.getBoundingClientRect();
  if (rect.top < boxRect.top || rect.bottom > boxRect.bottom) {
    let el = pos.node.nodeType === Node.TEXT_NODE ? pos.node.parentElement : pos.node;
    while (el && el !== container) {
      if (el.scrollIntoView) {
        el.scrollIntoView({ block: "nearest", behavior: "smooth" });
        break;
      }
      el = el.parentElement;
    }
  }
}

function syncYtAssignModeUi() {
  const btn = document.getElementById("ytAssignApplyBtn");
  const stack = document.getElementById("ytTranscriptAssignStack");
  const input = getYtTranscriptAssignInput();
  const label = btn?.querySelector(".speaker-assign-btn-label");
  if (btn) {
    btn.classList.toggle("is-on", ytAssignClickMode);
    btn.setAttribute("aria-pressed", ytAssignClickMode ? "true" : "false");
    if (label) {
      label.textContent = ytAssignClickMode ? "クリックで範囲指定: ON" : "クリックで範囲指定: OFF";
    }
  }
  if (stack) {
    stack.classList.toggle("transcript-assign--click-mode", ytAssignClickMode);
    stack.dataset.clickMode = ytAssignClickMode ? "1" : "0";
  }
  if (input) {
    input.readOnly = false;
  }
}

function toggleYtAssignClickMode() {
  ytAssignClickMode = !ytAssignClickMode;
  ytAssignAnchor = null;
  const sel = window.getSelection();
  if (sel) sel.removeAllRanges();
  syncYtAssignModeUi();
  updateYtAssignHint();
  _wavrickSavePipelineState();
  setMessage(
    "ytMessage",
    ytAssignClickMode
      ? "クリック指定 ON — 文字起こしで始まりの位置をタップし、続けて終わりの位置をタップすると色付けされます。"
      : "クリック指定 OFF — いつも通りドラッグで範囲を選べます（離すと色付き）。",
    "ok"
  );
}

function assignPlainRangeToActiveSpeaker(start, end, opts = {}) {
  if (!opts.skipFlush) flushTextareaEdit();
  const added = addYtAssignRange(start, end, ytActiveSpeaker);
  if (!added) return { ok: false, message: "選択範囲が短すぎます。" };
  ytAssignPreviewFocusSpeaker = 0;
  ytAssignPreviewFocusRangeId = 0;
  const input = getYtTranscriptAssignInput();
  if (input) {
    input.focus();
    input.setSelectionRange(end, end);
  }
  renderYtTranscriptAssignView({ restoreCursor: end });
  scheduleRepaintYtTranscriptAssignEditor();
  updateYtAssignHint();
  updateYtAssignSummary();
  document.getElementById("ytCastSlotsSection")?.classList.remove("hidden");
  document.getElementById("generateScriptButton")?.classList.remove("hidden");
  _wavrickSavePipelineState();
  const stack = document.getElementById("ytTranscriptAssignStack");
  stack?.classList.add("assign-flash");
  setTimeout(() => stack?.classList.remove("assign-flash"), 450);
  const len = countAssignablePlainCharsInSpan(ytTranscriptPlain, start, end);
  return {
    ok: true,
    message: `話者${ytActiveSpeaker} に ${len} 文字を割り当てました。`
  };
}

function selectAssignRangeInEditor(rangeId) {
  const input = getYtTranscriptAssignInput();
  if (!input || !ytTranscriptPlain) {
    return { ok: false, message: "文字起こしがまだありません。" };
  }
  const r = ytAssignRanges.find((x) => x.id === rangeId);
  if (!r) {
    return { ok: false, message: "割り当て範囲が見つかりません。" };
  }
  const sorted = [...ytAssignRanges].sort((a, b) => a.start - b.start);
  const chunkIdx = sorted.findIndex((x) => x.id === rangeId) + 1;

  ytAssignPreviewFocusRangeId = rangeId;
  ytAssignPreviewFocusSpeaker = r.speakerIndex;
  ytActiveSpeaker = r.speakerIndex;
  renderYtSpeakerPicker();
  renderYtTranscriptAssignView({ preserveSelection: true });
  scheduleRepaintYtTranscriptAssignEditor();

  input.focus();
  input.setSelectionRange(r.start, r.end);
  scrollTextareaPlainOffsetIntoView(input, r.start);

  updateYtAssignHint();
  updateYtAssignSummary();
  const spkLabel = getYtSpeakerLabel(r.speakerIndex);
  return {
    ok: true,
    message: `${spkLabel} · 範囲${chunkIdx}（${r.end - r.start} 文字）をエディタで選択しました。`
  };
}

function selectSpeakerAssignmentsInEditor(speakerIndex) {
  const input = getYtTranscriptAssignInput();
  if (!input || !ytTranscriptPlain) {
    return { ok: false, message: "文字起こしがまだありません。" };
  }
  const chunks = ytAssignRanges
    .filter((r) => r.speakerIndex === speakerIndex)
    .sort((a, b) => a.start - b.start);
  if (!chunks.length) {
    return { ok: false, message: `話者${speakerIndex} に割り当てられた文字はまだありません。` };
  }

  ytAssignPreviewFocusRangeId = 0;
  ytAssignPreviewFocusSpeaker = speakerIndex;
  ytActiveSpeaker = speakerIndex;
  renderYtSpeakerPicker();
  renderYtTranscriptAssignView({ preserveSelection: true });
  scheduleRepaintYtTranscriptAssignEditor();

  input.focus();
  input.setSelectionRange(chunks[0].start, chunks[chunks.length - 1].end);
  scrollTextareaPlainOffsetIntoView(input, chunks[0].start);

  const totalChars = chunks.reduce((n, r) => n + (r.end - r.start), 0);
  updateYtAssignHint();
  updateYtAssignSummary();
  return {
    ok: true,
    message: `話者${speakerIndex} の割り当て ${totalChars} 文字（${chunks.length} か所）をエディタで選択しました。`
  };
}

function getTextareaSelectionOffsets(input) {
  if (!input) return null;
  const start = input.selectionStart;
  const end = input.selectionEnd;
  if (start == null || end == null || end <= start) return null;
  const max = String(input.value ?? ytTranscriptPlain ?? "").length;
  return {
    start: Math.max(0, Math.min(start, max)),
    end: Math.max(0, Math.min(end, max))
  };
}

function addYtAssignRange(start, end, speakerIndex) {
  const max = getAssignMirrorPlain().length;
  const s = Math.max(0, Math.min(start, max));
  const e = Math.max(s, Math.min(end, max));
  if (e <= s) return false;

  const kept = [];
  for (const r of ytAssignRanges) {
    if (r.end <= s || r.start >= e) {
      kept.push(r);
      continue;
    }
    if (r.start < s) {
      kept.push({
        id: ++ytAssignRangeSeq,
        start: r.start,
        end: s,
        speakerIndex: r.speakerIndex
      });
    }
    if (r.end > e) {
      kept.push({
        id: ++ytAssignRangeSeq,
        start: e,
        end: r.end,
        speakerIndex: r.speakerIndex
      });
    }
  }
  ytAssignRanges = kept;
  const id = ++ytAssignRangeSeq;
  ytAssignRanges.push({ id, start: s, end: e, speakerIndex });
  ytAssignRanges.sort((a, b) => a.start - b.start);
  ytAssignRangeHistory.push(id);
  invalidateYtReconcilePreview();
  return true;
}

function countAssignablePlainCharsInSpan(plain, start, end) {
  const SA = getSpeakerAssignApi();
  if (SA?.countAssignablePlainCharsInSpan) {
    return SA.countAssignablePlainCharsInSpan(plain, start, end);
  }
  const src = String(plain || "");
  const s = Math.max(0, Math.min(Number(start) || 0, src.length));
  const e = Math.max(s, Math.min(Number(end) || 0, src.length));
  let n = 0;
  for (let i = s; i < e; i++) {
    const ch = src[i];
    if (ch && !/[\s\u3000\uFEFF]/.test(ch)) n++;
  }
  return n;
}

function getYtAssignmentProgress(plain = getTranscriptPlainForUi(), ranges = ytAssignRanges) {
  const SA = getSpeakerAssignApi();
  if (SA?.getTranscriptAssignmentProgress) {
    return SA.getTranscriptAssignmentProgress(plain, ranges);
  }
  const text = String(plain || "");
  const isChar = (ch) => ch && !/[\s\u3000\uFEFF]/.test(ch);
  let total = 0;
  for (const ch of text) if (isChar(ch)) total++;
  const assignedSet = new Set();
  for (const r of ranges || []) {
    if (Number(r.speakerIndex) < 1) continue;
    const start = Math.max(0, Math.min(Number(r.start) || 0, text.length));
    const end = Math.max(start, Math.min(Number(r.end) || 0, text.length));
    for (let i = start; i < end; i++) {
      if (isChar(text[i])) assignedSet.add(i);
    }
  }
  const assigned = assignedSet.size;
  const unassigned = Math.max(0, total - assigned);
  return { total, assigned, unassigned, complete: total === 0 || unassigned === 0 };
}

function countAssignedChars() {
  return getYtAssignmentProgress().assigned;
}

function isYtTranscriptFullyAssigned(plain = ytTranscriptPlain, ranges = ytAssignRanges) {
  return getYtAssignmentProgress(plain, ranges).complete;
}

function renderYtSpeakerNames() {
  const grid = document.getElementById("ytSpeakerNames");
  if (!grid) return;
  const count = getYtSpeakerCount();
  const slots = loadYtCastSlots(count);
  grid.innerHTML = slots
    .map((slot) => {
      const i = slot.speakerIndex;
      const val = escapeHtml(slot.speakerName || `話者${i}`);
      return `
        <label class="speaker-assign-name-field">
          <span class="speaker-assign-name-chip speaker-${i}"${ytSpeakerAccentAttr(i)}>${escapeHtml(getYtSpeakerLabel(i))}</span>
          <input type="text" class="speaker-assign-name-input" data-speaker-name="${i}" value="${val}" maxlength="40" placeholder="例: ナレーター">
        </label>`;
    })
    .join("");

  grid.querySelectorAll("[data-speaker-name]").forEach((input) => {
    if (input.dataset.bound === "1") return;
    input.dataset.bound = "1";
    input.addEventListener("change", () => {
      const idx = Number(input.getAttribute("data-speaker-name")) || 1;
      setYtSpeakerName(idx, input.value);
    });
    input.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        e.preventDefault();
        input.blur();
      }
    });
  });
}

function bindYtSpeakerPickerOnce() {
  const picker = document.getElementById("ytSpeakerPicker");
  if (!picker || picker.dataset.bound === "1") return;
  picker.dataset.bound = "1";
  picker.addEventListener("click", (e) => {
    const dot = e.target.closest("[data-speaker-color-dot]");
    const btn = e.target.closest("[data-speaker-pick]");
    if (!btn) return;
    if (dot) {
      e.preventDefault();
      e.stopPropagation();
      clearTimeout(ytSpeakerPickClickTimer);
      const speakerIndex = Number(btn.getAttribute("data-speaker-pick")) || 1;
      openYtSpeakerColorPopover(speakerIndex, btn);
      return;
    }
    e.preventDefault();
    clearTimeout(ytSpeakerPickClickTimer);
    ytSpeakerPickClickTimer = setTimeout(() => {
      ytActiveSpeaker = Number(btn.getAttribute("data-speaker-pick")) || 1;
      renderYtSpeakerPicker();
      updateYtAssignHint();
      _wavrickSavePipelineState();
      setMessage(
        "ytMessage",
        `いまは話者${ytActiveSpeaker} です。下の文字起こしをドラッグして範囲を選ぶと、この色で塗ります。`,
        "ok"
      );
    }, 220);
  });
  picker.addEventListener("dblclick", (e) => {
    const btn = e.target.closest("[data-speaker-pick]");
    if (!btn) return;
    e.preventDefault();
    e.stopPropagation();
    clearTimeout(ytSpeakerPickClickTimer);
    const speakerIndex = Number(btn.getAttribute("data-speaker-pick")) || 1;
    openYtSpeakerColorPopover(speakerIndex, btn);
    setMessage(
      "ytMessage",
      `話者${speakerIndex} の色を選んでください（丸いスウォッチ）。`,
      "ok"
    );
  });
}

function bindYtTranscriptDragSelectOnce() {
  if (document.documentElement.dataset.ytDragBound === "1") return;
  document.documentElement.dataset.ytDragBound = "1";

  document.addEventListener("mousedown", (e) => {
    const inp = e.target.closest?.("#ytTranscriptAssign");
    if (!inp || ytAssignClickMode) return;
    ytAssignDragFromEditor = true;
  });

  function tryAssignFromSelection() {
    const section = document.getElementById("ytLineAssignSection");
    if (!section || section.classList.contains("hidden")) return;
    if (ytAssignClickMode) return;

    const inp = getYtTranscriptAssignInput();
    if (!inp) return;

    const wasDrag = ytAssignDragFromEditor;
    ytAssignDragFromEditor = false;
    if (!wasDrag && document.activeElement !== inp && !ytAssignLastSelection) return;

    if (
      inp.selectionStart != null &&
      inp.selectionEnd != null &&
      inp.selectionEnd > inp.selectionStart
    ) {
      captureYtAssignEditorSelection();
    } else if (ytAssignLastSelection && document.activeElement === inp) {
      inp.setSelectionRange(ytAssignLastSelection.start, ytAssignLastSelection.end);
    }

    const result = assignSelectionToActiveSpeaker();
    if (result?.ok) scheduleRepaintYtTranscriptAssignEditor();
    if (result?.message) setMessage("ytMessage", result.message, result.ok ? "ok" : "err");
  }

  document.addEventListener("mouseup", () => {
    setTimeout(tryAssignFromSelection, 0);
  });
  document.addEventListener("touchend", () => {
    setTimeout(tryAssignFromSelection, 0);
  }, { passive: true });
}

function bindYtTranscriptClickModeOnce() {
  const input = getYtTranscriptAssignInput();
  if (!input || input.dataset.clickBound === "1") return;
  input.dataset.clickBound = "1";

  input.addEventListener("click", () => {
    if (!ytAssignClickMode) return;
    const offset = input.selectionStart ?? 0;

    if (ytAssignAnchor == null) {
      ytAssignAnchor = offset;
      input.setSelectionRange(offset, offset);
      updateYtAssignHint();
      setMessage("ytMessage", "始まりの位置を指定しました。続けて終わりの位置をタップしてください。", "ok");
      return;
    }

    const start = Math.min(ytAssignAnchor, offset);
    const end = Math.max(ytAssignAnchor, offset);
    ytAssignAnchor = null;
    if (end <= start) {
      setMessage("ytMessage", "終わりの位置が始まりと同じです。もう一度始まりから指定してください。", "err");
      return;
    }
    const result = assignPlainRangeToActiveSpeaker(start, end);
    setMessage("ytMessage", result.message, result.ok ? "ok" : "err");
  });
}

function bindYtAssignSummaryOnce() {
  const summary = document.getElementById("ytAssignSummary");
  if (!summary || summary.dataset.bound === "1") return;
  summary.dataset.bound = "1";
  summary.addEventListener("click", (e) => {
    const chunkBtn = e.target.closest("[data-assign-range-id]");
    if (chunkBtn) {
      e.preventDefault();
      const rangeId = Number(chunkBtn.getAttribute("data-assign-range-id")) || 0;
      const result = selectAssignRangeInEditor(rangeId);
      setMessage("ytMessage", result.message, result.ok ? "ok" : "err");
      return;
    }
    const row = e.target.closest("[data-speaker-summary]");
    if (!row) return;
    e.preventDefault();
    const speakerIndex = Number(row.getAttribute("data-speaker-summary")) || 1;
    const result = selectSpeakerAssignmentsInEditor(speakerIndex);
    setMessage("ytMessage", result.message, result.ok ? "ok" : "err");
  });
  summary.addEventListener("dblclick", (e) => {
    const group = e.target.closest("[data-speaker-group]");
    if (!group) return;
    e.preventDefault();
    e.stopPropagation();
    const speakerIndex = Number(group.getAttribute("data-speaker-group")) || 0;
    if (!speakerIndex) return;
    if (ytAssignSummaryExpandedSpeakers.has(speakerIndex)) {
      ytAssignSummaryExpandedSpeakers.delete(speakerIndex);
    } else {
      ytAssignSummaryExpandedSpeakers.add(speakerIndex);
    }
    updateYtAssignSummary();
  });
}

function renderYtSpeakerPicker() {
  const picker = document.getElementById("ytSpeakerPicker");
  if (!picker) return;
  const count = getYtSpeakerCount();
  loadYtSpeakerColors(count);
  picker.innerHTML = Array.from({ length: count }, (_, i) => {
    const n = i + 1;
    const active = n === ytActiveSpeaker ? " active" : "";
    const label = escapeHtml(getYtSpeakerLabel(n));
    const color = escapeHtml(getYtSpeakerColor(n));
    return `<button type="button" class="speaker-chip speaker-${n}${active}" data-speaker-pick="${n}" role="tab" aria-selected="${n === ytActiveSpeaker}" title="クリックで選択・ダブルクリックで色変更"${ytSpeakerAccentAttr(n)}><span class="speaker-chip-color-dot" data-speaker-color-dot="${n}" style="background-color:${color}" aria-hidden="true"></span><span class="speaker-chip-label">${label}</span></button>`;
  }).join("");
}

function getYtTranscriptAssignInput() {
  return document.getElementById("ytTranscriptAssign");
}

function getYtTranscriptAssignMirror() {
  return document.getElementById("ytTranscriptAssignMirror");
}

function hasYtAssignMirrorHighlights(plain = getAssignMirrorPlain()) {
  const text = String(plain || "");
  if (!text.length) return false;
  const hasSpeakers = ytAssignRanges.some(
    (r) => Number(r.speakerIndex) >= 1 && (Number(r.end) || 0) > (Number(r.start) || 0)
  );
  if (hasSpeakers) return true;
  return getTranscriptAdlibSpansForUi(text).length > 0;
}

/** 話者色ミラー描画（app.js 内で完結 — 外部モジュール未読込でも動く） */
function paintYtTranscriptAssignMirror() {
  const stack = document.getElementById("ytTranscriptAssignStack");
  const mirror = getYtTranscriptAssignMirror();
  const input = getYtTranscriptAssignInput();
  if (!stack || !mirror || !input || input.tagName !== "TEXTAREA") return;

  ensureTranscriptTextareaSynced();
  const plain = getAssignMirrorPlain();
  const hint = document.getElementById("ytTranscriptAdlibHint");
  if (hint) {
    const spans = getTranscriptAdlibSpansForUi(plain);
    hint.classList.toggle("hidden", spans.length === 0);
  }

  if (hasYtAssignMirrorHighlights(plain)) {
    mirror.innerHTML = buildAssignMirrorHtml(
      plain,
      ytAssignRanges,
      getTranscriptAdlibSpansForUi(plain)
    );
    stack.classList.add("transcript-assign-stack--overlay");
  } else {
    mirror.innerHTML = "";
    stack.classList.remove("transcript-assign-stack--overlay");
  }

  mirror.scrollTop = input.scrollTop;
  mirror.scrollLeft = input.scrollLeft;
}

function repaintYtTranscriptAssignEditor() {
  paintYtTranscriptAssignMirror();
}

function scheduleRepaintYtTranscriptAssignEditor() {
  paintYtTranscriptAssignMirror();
  if (ytAssignMirrorPaintRaf) cancelAnimationFrame(ytAssignMirrorPaintRaf);
  ytAssignMirrorPaintRaf = requestAnimationFrame(() => {
    ytAssignMirrorPaintRaf = 0;
    paintYtTranscriptAssignMirror();
    requestAnimationFrame(paintYtTranscriptAssignMirror);
  });
}

function captureYtAssignEditorSelection() {
  const input = getYtTranscriptAssignInput();
  if (!input) return;
  const start = input.selectionStart;
  const end = input.selectionEnd;
  if (start == null || end == null || end <= start) return;
  const max = String(input.value ?? "").length;
  ytAssignLastSelection = {
    start: Math.max(0, Math.min(start, max)),
    end: Math.max(0, Math.min(end, max))
  };
}

function getTranscriptAdlibSpansForUi(plain = getTranscriptPlainForUi()) {
  const text = String(plain || "");
  if (!text.length) return [];

  const filterSpans = (spans) =>
    (spans || []).filter(
      (s) =>
        (Number(s?.end) || 0) > (Number(s?.start) || 0) &&
        (Number(s?.start) || 0) < text.length
    );

  // reconcile 済みなら API の ver2 spans を優先
  if (ytReconcileReady && Array.isArray(ytReconcileAdlibSpans) && ytReconcileAdlibSpans.length) {
    return filterSpans(ytReconcileAdlibSpans);
  }

  // 話者割り当て後: Whisper 原文との差分から追加台詞を表示（§7.2）
  if (!hasYtSpeakerAssignments()) return [];

  const SA = getSpeakerAssignApi();
  const baseline = ensureYtWhisperBaselinePlain();
  if (!SA?.computeAdlibInsertRanges || !baseline || baseline === text) return [];

  return filterSpans(
    SA.computeAdlibInsertRanges(baseline, text).map((r, i) => ({
      start: r.start,
      end: r.end,
      speakerIndex: 0,
      chunkId: `assign-${i}`,
      rule: "G",
    }))
  );
}

function renderPlainWithAdlibMirrorHtml(plain, start, end, adlibSpans) {
  const text = plain.slice(start, end);
  if (!text) return "";
  const scoped = (adlibSpans || []).filter((a) => a.end > start && a.start < end);
  if (!scoped.length) return escapeHtml(text);

  const points = new Set([start, end]);
  for (const a of scoped) {
    points.add(Math.max(start, a.start));
    points.add(Math.min(end, a.end));
  }
  const cuts = [...points].sort((a, b) => a - b);
  let html = "";
  for (let i = 0; i < cuts.length - 1; i++) {
    const segStart = cuts[i];
    const segEnd = cuts[i + 1];
    const slice = plain.slice(segStart, segEnd);
    if (!slice) continue;
    const isAdlib = scoped.some((a) => a.start <= segStart && a.end >= segEnd);
    if (isAdlib) {
      html += `<span class="transcript-adlib-mark"><span class="transcript-adlib-caret transcript-adlib-caret--start" aria-hidden="true">▼</span><span class="wavrick-adlib-highlight">${escapeHtml(slice)}</span><span class="transcript-adlib-caret transcript-adlib-caret--end" aria-hidden="true">▽</span></span>`;
    } else {
      html += escapeHtml(slice);
    }
  }
  return html;
}

function buildAssignMirrorHtml(plain, ranges, adlibSpans = []) {
  const sorted = [...ranges].sort((a, b) => a.start - b.start);
  let html = "";
  let pos = 0;
  sorted.forEach((r, chunkIdx) => {
    const rangeStart = Math.max(0, Math.min(Number(r.start) || 0, plain.length));
    const rangeEnd = Math.max(rangeStart, Math.min(Number(r.end) || 0, plain.length));
    if (rangeEnd <= rangeStart) return;
    if (rangeStart > pos) {
      html += renderPlainWithAdlibMirrorHtml(plain, pos, rangeStart, adlibSpans);
    }
    if (r.speakerIndex >= 1 && r.speakerIndex <= 6) {
      const variant = chunkIdx % 2 === 0 ? "even" : "odd";
      const rangeFocus =
        ytAssignPreviewFocusRangeId === r.id ? " speaker-assign-chunk--focused" : "";
      const speakerFocus =
        !ytAssignPreviewFocusRangeId &&
        ytAssignPreviewFocusSpeaker === r.speakerIndex
          ? " speaker-assign-preview-focus"
          : "";
      const spkLabel = getYtSpeakerLabel(r.speakerIndex);
      const charLen = rangeEnd - rangeStart;
      const title = `${spkLabel} · 範囲${chunkIdx + 1} · ${charLen}文字`;
      const inner = renderPlainWithAdlibMirrorHtml(plain, rangeStart, rangeEnd, adlibSpans);
      html += `<span class="speaker-highlight speaker-${r.speakerIndex} speaker-assign-chunk speaker-assign-chunk--${variant}${rangeFocus}${speakerFocus}" title="${escapeHtml(title)}"${ytSpeakerAccentAttr(r.speakerIndex)}>${inner}</span>`;
    } else {
      html += renderPlainWithAdlibMirrorHtml(plain, rangeStart, rangeEnd, adlibSpans);
    }
    pos = rangeEnd;
  });
  if (pos < plain.length) {
    html += renderPlainWithAdlibMirrorHtml(plain, pos, plain.length, adlibSpans);
  }
  return html;
}

function getAssignMirrorPlain() {
  const input = getYtTranscriptAssignInput();
  if (!input) return String(ytTranscriptPlain ?? "");
  return String(input.value ?? ytTranscriptPlain ?? "");
}

function syncAssignMirrorScroll(input) {
  const mirror = getYtTranscriptAssignMirror();
  if (!input || !mirror) return;
  mirror.scrollTop = input.scrollTop;
  mirror.scrollLeft = input.scrollLeft;
}

function refreshAssignMirrorOverlay() {
  scheduleRepaintYtTranscriptAssignEditor();
}

function paintAssignMirrorOnly() {
  repaintYtTranscriptAssignEditor();
}

function scheduleAssignMirrorPaint() {
  clearTimeout(ytAssignMirrorDebounce);
  ytAssignMirrorDebounce = setTimeout(() => {
    ytAssignMirrorDebounce = null;
    repaintYtTranscriptAssignEditor();
  }, 120);
}

function scheduleAssignSummaryRefresh() {
  clearTimeout(ytAssignSummaryDebounce);
  ytAssignSummaryDebounce = setTimeout(() => {
    ytAssignSummaryDebounce = null;
    updateYtAssignSummary();
  }, 280);
}

function remapTranscriptPlainState(prevPlain, nextPlain) {
  if (prevPlain === nextPlain) return;
  ytTranscriptPlain = nextPlain;
  if (!ytAssignRanges.length) {
    invalidateYtReconcilePreview();
    return;
  }
  const SA = getSpeakerAssignApi();
  if (!SA?.remapSpeakerAssignRanges) {
    invalidateYtReconcilePreview();
    return;
  }
  const remapped = SA.remapSpeakerAssignRanges(prevPlain, nextPlain, ytAssignRanges);
  ytAssignRangeHistory = ytAssignRangeHistory.filter((id) =>
    remapped.some((r) => r.id === id)
  );
  ytAssignRanges = remapped;
  invalidateYtReconcilePreview();
}

function paintYtTranscriptAssignDom(plain, opts = {}) {
  const input = getYtTranscriptAssignInput();
  const mirror = getYtTranscriptAssignMirror();
  if (!input) return false;

  const next = String(
    plain != null ? plain : ytTranscriptPlain ?? getAssignMirrorPlain() ?? ""
  );
  if (!next) {
    input.value = "";
    if (mirror) mirror.innerHTML = "";
    const stack = document.getElementById("ytTranscriptAssignStack");
    stack?.classList.remove("transcript-assign-stack--overlay");
    return true;
  }

  const isFocused = document.activeElement === input;
  const mayWriteValue = Boolean(opts.forceValue) || !isFocused;
  if (mayWriteValue && input.value !== next) {
    input.value = next;
  }

  if (mirror && input.tagName === "TEXTAREA") {
    repaintYtTranscriptAssignEditor();
  } else if (mirror) {
    mirror.innerHTML = "";
    document.getElementById("ytTranscriptAssignStack")?.classList.remove("transcript-assign-stack--overlay");
  }

  if (opts.restoreCursor != null) {
    const pos = Math.max(0, Math.min(opts.restoreCursor, next.length));
    input.setSelectionRange(pos, pos);
  } else if (!opts.preserveSelection && !isFocused) {
    input.setSelectionRange(next.length, next.length);
  }
  return true;
}

function syncTranscriptPlainFromInput(opts = {}) {
  const input = getYtTranscriptAssignInput();
  if (!input || ytAssignComposing) return false;
  const newPlain = input.value;
  if (newPlain === ytTranscriptPlain) return false;
  const prevPlain = ytTranscriptPlain;
  remapTranscriptPlainState(prevPlain, newPlain);
  if (opts.updateMirror) {
    repaintYtTranscriptAssignEditor();
  } else {
    repaintYtTranscriptAssignEditor();
  }
  return true;
}

function scrollTextareaPlainOffsetIntoView(textarea, plainOffset) {
  if (!textarea) return;
  textarea.focus();
  textarea.setSelectionRange(plainOffset, plainOffset);
  const lineHeight = parseFloat(getComputedStyle(textarea).lineHeight) || 20;
  const textBefore = textarea.value.slice(0, plainOffset);
  const lineCount = (textBefore.match(/\n/g) || []).length;
  textarea.scrollTop = Math.max(0, lineCount * lineHeight - textarea.clientHeight / 3);
}

function applyTextareaPlainFromInput(newPlain, opts = {}) {
  const input = getYtTranscriptAssignInput();
  if (!input) return false;
  const next = String(newPlain ?? "");
  const forceValue = Boolean(opts.forceValue);
  if (!forceValue && next === ytTranscriptPlain && input.value === next) return false;

  const prevPlain = ytTranscriptPlain;
  remapTranscriptPlainState(prevPlain, next);

  const isFocused = document.activeElement === input;
  paintYtTranscriptAssignDom(next, {
    forceValue: Boolean(opts.forceValue),
    restoreCursor: opts.restoreCursor != null ? opts.restoreCursor : null,
    preserveSelection:
      Boolean(opts.preserveSelection) || (isFocused && opts.restoreCursor == null)
  });
  return true;
}

function scrollYtPipelineMessageIntoView() {
  document.getElementById("ytMessage")?.scrollIntoView({ block: "nearest", behavior: "smooth" });
}

/** textarea と ytTranscriptPlain のズレを解消（編集中以外はメモリを正とする） */
function ensureTranscriptTextareaSynced() {
  const input = getYtTranscriptAssignInput();
  if (!input || ytAssignComposing) return String(ytTranscriptPlain ?? "");
  const domPlain = input.value;
  const savedPlain = String(ytTranscriptPlain ?? "");
  const isEditing = document.activeElement === input;

  if (!savedPlain && domPlain && !isEditing) {
    applyTextareaPlainFromInput("", { forceValue: true });
    return "";
  }
  if (savedPlain && domPlain !== savedPlain && !isEditing) {
    applyTextareaPlainFromInput(domPlain, { forceValue: false });
    return String(ytTranscriptPlain ?? "");
  }
  if (!domPlain && savedPlain) {
    paintYtTranscriptAssignDom(savedPlain, { forceValue: true });
    return savedPlain;
  }
  if (domPlain !== savedPlain && isEditing) {
    applyTextareaPlainFromInput(domPlain, { forceValue: false });
    return String(ytTranscriptPlain ?? "");
  }
  return savedPlain || domPlain;
}

function flushTextareaEdit() {
  clearTimeout(ytAssignEditDebounce);
  clearTimeout(ytAssignMirrorDebounce);
  ytAssignEditDebounce = null;
  ytAssignMirrorDebounce = null;
  ytAssignEditUndoPending = false;
  const input = getYtTranscriptAssignInput();
  if (!input || ytAssignComposing) return false;
  const newPlain = input.value;
  const savedPlain = String(ytTranscriptPlain ?? "");
  if (!newPlain && savedPlain) {
    paintYtTranscriptAssignDom(savedPlain, { forceValue: true });
    return false;
  }
  if (newPlain === savedPlain) return false;
  return applyTextareaPlainFromInput(newPlain, { forceValue: false });
}

function getTranscriptPlainForUi() {
  const input = getYtTranscriptAssignInput();
  if (input && document.activeElement === input && input.value != null) {
    return input.value;
  }
  return ytTranscriptPlain;
}

function applyTranscriptPlainLive(newPlain) {
  const next = String(newPlain ?? "");
  const prev = ytTranscriptPlain;
  if (prev === next) {
    repaintYtTranscriptAssignEditor();
    return false;
  }
  remapTranscriptPlainState(prev, next);
  repaintYtTranscriptAssignEditor();
  updateYtAssignHint();
  return true;
}

function scheduleTextareaEditPersist() {
  clearTimeout(ytAssignEditDebounce);
  ytAssignEditDebounce = setTimeout(() => {
    ytAssignEditDebounce = null;
    ytAssignEditUndoPending = false;
    scheduleAssignSummaryRefresh();
    _wavrickSavePipelineState();
  }, 450);
}

function bindYtTranscriptTextareaOnce() {
  const input = getYtTranscriptAssignInput();
  if (!input || input.dataset.textareaBound === "1") return;
  input.dataset.textareaBound = "1";

  input.addEventListener("compositionstart", () => {
    ytAssignComposing = true;
  });
  input.addEventListener("compositionend", () => {
    ytAssignComposing = false;
    if (!ytAssignEditUndoPending) {
      pushYtTranscriptEditUndo();
      ytAssignEditUndoPending = true;
    }
    applyTranscriptPlainLive(input.value);
    scheduleTextareaEditPersist();
  });
  input.addEventListener("input", () => {
    if (ytAssignComposing) return;
    if (!ytAssignEditUndoPending) {
      pushYtTranscriptEditUndo();
      ytAssignEditUndoPending = true;
    }
    applyTranscriptPlainLive(input.value);
    scheduleTextareaEditPersist();
  });
  input.addEventListener("focus", () => {
    repaintYtTranscriptAssignEditor();
  });
  input.addEventListener("blur", () => {
    clearTimeout(ytAssignEditDebounce);
    clearTimeout(ytAssignMirrorDebounce);
    ytAssignEditDebounce = null;
    ytAssignMirrorDebounce = null;
    ytAssignEditUndoPending = false;
    applyTranscriptPlainLive(input.value);
    updateYtAssignSummary();
    scheduleRepaintYtTranscriptAssignEditor();
    _wavrickSavePipelineState();
  });
  input.addEventListener("select", captureYtAssignEditorSelection);
  input.addEventListener("scroll", () => syncAssignMirrorScroll(input));
  if (typeof ResizeObserver !== "undefined") {
    const stack = document.getElementById("ytTranscriptAssignStack");
    if (stack && !stack.dataset.mirrorResizeBound) {
      stack.dataset.mirrorResizeBound = "1";
      new ResizeObserver(() => paintYtTranscriptAssignMirror()).observe(stack);
    }
  }
  input.addEventListener("keydown", (e) => {
    if ((e.metaKey || e.ctrlKey) && e.key === "z" && !e.shiftKey) {
      e.preventDefault();
      const result = undoYtTranscriptEdit();
      setMessage("ytMessage", result.message, result.ok ? "ok" : "err");
    }
  });
}

function bindYtTranscriptEditableOnce() {
  bindYtTranscriptTextareaOnce();
}

function renderYtTranscriptAssignView(opts = {}) {
  const input = getYtTranscriptAssignInput();
  if (!input) return;
  const plain = Boolean(opts.forceValue)
    ? String(ytTranscriptPlain ?? "")
    : (ensureTranscriptTextareaSynced(), String(getAssignMirrorPlain() ?? ""));

  paintYtTranscriptAssignDom(plain, {
    forceValue: Boolean(opts.forceValue),
    restoreCursor: opts.restoreCursor,
    preserveSelection: Boolean(opts.preserveSelection)
  });
  if (opts.refreshSummary !== false) {
    if (document.activeElement === input) {
      scheduleAssignSummaryRefresh();
    } else {
      updateYtAssignSummary();
    }
  }
}

function updateYtAssignHint() {
  const hint = document.getElementById("ytAssignHint");
  if (!hint) return;
  const plain = getTranscriptPlainForUi();
  const progress = getYtAssignmentProgress(plain, ytAssignRanges);
  const { total, assigned, unassigned, complete } = progress;
  if (!total && !String(plain || "").length) {
    hint.textContent = `いまの操作: 話者${ytActiveSpeaker} — 「文字起こし」後にここに全文が表示されます。`;
    hint.classList.remove("speaker-assign-status-hint--incomplete");
    return;
  }
  hint.classList.toggle("speaker-assign-status-hint--incomplete", !complete && total > 0);
  const countLabel = complete
    ? `${assigned}/${total} 文字割り当て済み`
    : `${assigned}/${total} 文字割り当て済み（未割り当て ${unassigned}・空白/改行除く）`;
  if (ytAssignClickMode) {
    if (ytAssignAnchor != null) {
      hint.textContent = `クリック指定 ON — 話者${ytActiveSpeaker} — 終わりの位置をタップしてください（${countLabel}）。`;
      return;
    }
    hint.textContent = `クリック指定 ON — 話者${ytActiveSpeaker} — 始まり→終わりの順にタップ（${countLabel}）。`;
    return;
  }
  hint.textContent = `ドラッグ選択 — 話者${ytActiveSpeaker} — 下のテキストをドラッグして範囲選択（${countLabel}）。離すと色付き。同じ範囲を選び直すと話者を変更できます。`;
}

function updateYtAssignSummary() {
  const el = document.getElementById("ytAssignSummary");
  if (!el) return;
  const plain = getTranscriptPlainForUi();
  const count = getYtSpeakerCount();
  const sortedAll = [...ytAssignRanges].sort((a, b) => a.start - b.start);
  const globalChunkIndex = new Map(sortedAll.map((r, i) => [r.id, i + 1]));
  const adlibSpans = getTranscriptAdlibSpansForUi(plain);
  const rows = [];
  for (let i = 1; i <= count; i++) {
    const spkLabel = getYtSpeakerLabel(i);
    const ranges = ytAssignRanges
      .filter((r) => r.speakerIndex === i)
      .sort((a, b) => a.start - b.start);
    const activePreview = ytAssignPreviewFocusSpeaker === i ? " is-preview-active" : "";
    const totalChars = ranges.reduce(
      (n, r) => n + countAssignablePlainCharsInSpan(plain, r.start, r.end),
      0
    );
    const chunkButtons = ranges.length
      ? ranges
          .map((r) => {
            const chunkNo = globalChunkIndex.get(r.id) || 0;
            const variant = chunkNo % 2 === 0 ? "odd" : "even";
            const text = truncateText(plain.slice(r.start, r.end).trim(), 40);
            const len = countAssignablePlainCharsInSpan(plain, r.start, r.end);
            const focused =
              ytAssignPreviewFocusRangeId === r.id ? " is-chunk-focused" : "";
            const hasAdlib = adlibSpans.some(
              (a) => (Number(a.start) || 0) < r.end && (Number(a.end) || 0) > r.start
            );
            const adlibBadge = hasAdlib
              ? `<span class="speaker-summary-chunk-adlib" title="Whisper に無い追記">▼</span>`
              : "";
            return (
              `<button type="button" class="speaker-summary-chunk speaker-${i} speaker-assign-chunk--${variant}${focused}" data-assign-range-id="${r.id}" title="${escapeHtml(spkLabel)} · 範囲${chunkNo} · ${len}文字${hasAdlib ? " · 追加台詞あり" : ""}"${ytSpeakerAccentAttr(i)}>` +
                `<span class="speaker-summary-chunk-badge">範囲${chunkNo}</span>` +
                adlibBadge +
                `<span class="speaker-summary-chunk-text">${escapeHtml(text || "（空）")}</span>` +
                `<span class="speaker-summary-chunk-meta">${len}文字</span>` +
              `</button>`
            );
          })
          .join("")
      : `<p class="speaker-summary-empty">（まだなし）</p>`;
    const previewText = ranges.length
      ? truncateText(
          ranges
            .map((r) => plain.slice(r.start, r.end).trim())
            .filter(Boolean)
            .join(" / "),
          88
        )
      : "（まだなし）";
    const expanded = ytAssignSummaryExpandedSpeakers.has(i);
    rows.push(
      `<div class="speaker-summary-group speaker-${i}${activePreview}${expanded ? " is-expanded" : ""}" data-speaker-group="${i}"${ytSpeakerAccentAttr(i)}>` +
        `<button type="button" class="speaker-summary-head" data-speaker-summary="${i}" title="${escapeHtml(spkLabel)}の割り当てをすべて選択（ダブルクリックで範囲一覧）">` +
          `<strong>${escapeHtml(spkLabel)}</strong>` +
          `<span class="speaker-summary-head-meta">${ranges.length ? `${ranges.length} 範囲 · ${totalChars} 文字` : "未割り当て"}</span>` +
        `</button>` +
        `<p class="speaker-summary-compact-preview" title="ダブルクリックで範囲一覧を表示">${escapeHtml(previewText)}</p>` +
        `<div class="speaker-summary-chunks">${chunkButtons}</div>` +
      `</div>`
    );
  }
  el.innerHTML = rows.join("");
}

function pushYtTranscriptEditUndo() {
  ytTranscriptEditUndoStack.push({
    plain: ytTranscriptPlain,
    assignRanges: ytAssignRanges.map((r) => ({ ...r })),
    assignHistory: ytAssignRangeHistory.slice()
  });
  if (ytTranscriptEditUndoStack.length > YT_TRANSCRIPT_EDIT_UNDO_MAX) {
    ytTranscriptEditUndoStack.shift();
  }
}

function syncYtTranscriptUndoButtons() {
  const undoBtn = document.getElementById("ytTranscriptUndoBtn");
  if (undoBtn) undoBtn.disabled = ytTranscriptEditUndoStack.length === 0;
  const resetBtn = document.getElementById("ytTranscriptResetBtn");
  if (resetBtn) resetBtn.disabled = !getYtWhisperBaselinePlain();
}

function bindYtTranscriptUndoResetButtonsOnce() {
  const undoTranscriptBtn = document.getElementById("ytTranscriptUndoBtn");
  const resetTranscriptBtn = document.getElementById("ytTranscriptResetBtn");
  syncYtTranscriptUndoButtons();
  if (undoTranscriptBtn && undoTranscriptBtn.dataset.bound !== "1") {
    undoTranscriptBtn.dataset.bound = "1";
    undoTranscriptBtn.addEventListener("click", () => {
      const result = undoYtTranscriptEdit();
      setMessage("ytMessage", result.message, result.ok ? "ok" : "err");
    });
  }
  if (resetTranscriptBtn && resetTranscriptBtn.dataset.bound !== "1") {
    resetTranscriptBtn.dataset.bound = "1";
    resetTranscriptBtn.addEventListener("click", () => {
      void resetYtTranscriptToWhisper().then((result) => {
        setMessage("ytMessage", result.message, result.ok ? "ok" : "err");
      });
    });
  }
}

function extractPlainFromBracketTimeline(text) {
  const SA = getSpeakerAssignApi();
  if (SA?.buildPlainFromWhisperTimeline) {
    return SA.buildPlainFromWhisperTimeline(text);
  }
  const parts = [];
  const leadingTcRe =
    /^\[\d{1,2}:\d{2}(?:\.\d{1,3})?(?:\s*(?:->|→|-)\s*\d{1,2}:\d{2}(?:\.\d{1,3})?)?\]\s*(.*)$/;
  for (const line of String(text || "").split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed === "[NEW_BLOCK]" || trimmed === "/") continue;
    const m = trimmed.match(leadingTcRe);
    if (m) {
      const body = (m[1] || "").trim();
      if (body) parts.push(body);
      continue;
    }
    if (/\d{1,2}:\d{2}:\d{2}[,.]\d{3}\s*-->/.test(trimmed)) continue;
  }
  return parts.join("");
}

async function extractPlainTextFromYtTranscriptField(fieldText) {
  const t = String(fieldText || "").trim();
  if (!t) return "";
  // 話者割り当て済みのときはプレーンテキストとしてそのまま扱う（SRT 再パースでずれない）
  if (ytAssignRanges.length > 0 && !isYtTranscriptSrtLike(t)) return t;
  if (!isYtTranscriptSrtLike(t)) return t;
  if (/^\[\d{1,2}:\d{2}/m.test(t)) {
    const plain = extractPlainFromBracketTimeline(t);
    if (plain) return plain;
  }
  if (/\d{1,2}:\d{2}:\d{2}[,.]\d{3}\s*-->/.test(t)) {
    try {
      const { parseSrtToScriptLines } = await import(
        `./js/record-workspace/srt-timecode.js?v=${RW_SCRIPT_IMPORT_VER}`
      );
      const lines = parseSrtToScriptLines(t);
      if (lines.length) {
        return lines
          .map((l) => String(l.text || "").trim())
          .filter(Boolean)
          .join(" ");
      }
    } catch (e) {
      console.warn("[yt] parse SRT for plain text failed", e);
    }
  }
  return (ytTranscriptPlainAtWhisper || ytTranscriptPlain || "").trim();
}

/** @deprecated 旧 textarea 同期（互換スタブ） */
function syncYtTranscriptEditFieldForAssign() {}

async function applyYtTranscriptEditToSpeakerAssign(opts = {}) {
  void opts;
  flushTextareaEdit();
  const section = document.getElementById("ytLineAssignSection");
  if (section) section.classList.remove("hidden");
  bindYtSpeakerPickerOnce();
  bindEditorFullscreenOnce();
  bindYtTranscriptDragSelectOnce();
  bindYtTranscriptClickModeOnce();
  bindYtTranscriptEditableOnce();
  bindYtAssignSummaryOnce();
  syncYtAssignModeUi();
  renderYtSpeakerPicker();
  renderYtSpeakerNames();
  renderYtTranscriptAssignView();
  updateYtAssignHint();
  renderYtCastSlots();
  _wavrickSavePipelineState();
  syncYtTranscriptUndoButtons();
  return { ok: true, message: "反映済みです。" };
}

function undoYtTranscriptEdit() {
  const prev = ytTranscriptEditUndoStack.pop();
  if (!prev) return { ok: false, message: "戻せる編集がありません。" };
  ytAssignEditUndoPending = false;
  clearTimeout(ytAssignEditDebounce);
  ytAssignRanges = Array.isArray(prev.assignRanges)
    ? prev.assignRanges.map((r) => ({ ...r }))
    : [];
  ytAssignRangeHistory = Array.isArray(prev.assignHistory) ? prev.assignHistory.slice() : [];
  applyTextareaPlainFromInput(prev.plain || "", { forceValue: true, restoreCursor: 0 });
  updateYtAssignHint();
  updateYtAssignSummary();
  _wavrickSavePipelineState();
  syncYtTranscriptUndoButtons();
  return { ok: true, message: "直前の編集に戻しました。" };
}

async function resetYtTranscriptToWhisper() {
  const baseline = ensureYtWhisperBaselinePlain();
  if (!baseline) {
    return { ok: false, message: "Whisper の元データがありません。" };
  }
  flushTextareaEdit();
  pushYtTranscriptEditUndo();
  ytAssignEditUndoPending = false;
  ytAssignRanges = [];
  ytAssignRangeHistory = [];
  ytAssignPreviewFocusRangeId = 0;
  ytAssignPreviewFocusSpeaker = 0;
  ytActiveSpeaker = 1;
  applyTextareaPlainFromInput(baseline, { forceValue: true, restoreCursor: 0 });
  invalidateYtReconcilePreview();
  bindYtSpeakerPickerOnce();
  renderYtSpeakerPicker();
  renderYtSpeakerNames();
  renderYtTranscriptAssignView({ forceValue: true });
  updateYtAssignHint();
  updateYtAssignSummary();
  renderYtCastSlots();
  _wavrickSavePipelineState();
  syncYtTranscriptUndoButtons();
  return { ok: true, message: "Whisper の文字起こしに戻しました（話者割り当てもリセット）。" };
}

async function startYtSpeakerAssignFromTranscript() {
  if (ytTranscriptPlainAtWhisper) {
    ytTranscriptPlain = ytTranscriptPlainAtWhisper;
  }
  const section = document.getElementById("ytLineAssignSection");
  if (section) section.classList.remove("hidden");
  bindYtSpeakerPickerOnce();
  bindEditorFullscreenOnce();
  bindYtTranscriptDragSelectOnce();
  bindYtTranscriptClickModeOnce();
  bindYtTranscriptEditableOnce();
  bindYtAssignSummaryOnce();
  syncYtAssignModeUi();
  renderYtSpeakerPicker();
  renderYtSpeakerNames();
  renderYtTranscriptAssignView({ forceValue: true });
  scheduleRepaintYtTranscriptAssignEditor();
  updateYtAssignHint();
  syncYtTranscriptUndoButtons();
  requestAnimationFrame(() => {
    renderYtTranscriptAssignView({ forceValue: true });
    scheduleRepaintYtTranscriptAssignEditor();
    updateYtAssignHint();
  });
  return true;
}

function assignSelectionToActiveSpeaker() {
  const input = getYtTranscriptAssignInput();
  const plain = getAssignMirrorPlain();
  if (!input || !plain) {
    return { ok: false, message: "文字起こしがまだありません。" };
  }
  let start = input.selectionStart;
  let end = input.selectionEnd;
  if (start == null || end == null || end <= start) {
    return { ok: false, message: "" };
  }
  const valueBeforeFlush = input.value;
  const plainBeforeFlush = ytTranscriptPlain;
  flushTextareaEdit();
  const syncedPlain = ytTranscriptPlain;
  const max = String(syncedPlain ?? "").length;
  if (valueBeforeFlush !== plainBeforeFlush || plainBeforeFlush !== syncedPlain) {
    const SA = getSpeakerAssignApi();
    if (SA?.buildPlainOffsetMap) {
      const map = SA.buildPlainOffsetMap(valueBeforeFlush, syncedPlain);
      start = map[Math.max(0, Math.min(start, valueBeforeFlush.length))] ?? start;
      end = map[Math.max(0, Math.min(end, valueBeforeFlush.length))] ?? end;
    }
  }
  start = Math.max(0, Math.min(start, max));
  end = Math.max(start, Math.min(end, max));
  if (end <= start) return { ok: false, message: "" };
  return assignPlainRangeToActiveSpeaker(start, end, { skipFlush: true });
}

function undoYtSpeakerAssign() {
  const lastId = ytAssignRangeHistory.pop();
  if (lastId == null) return { ok: false, message: "取り消す割り当てがありません。" };
  ytAssignRanges = ytAssignRanges.filter((r) => r.id !== lastId);
  if (ytAssignPreviewFocusRangeId === lastId) ytAssignPreviewFocusRangeId = 0;
  renderYtTranscriptAssignView();
  refreshAssignMirrorOverlay();
  updateYtAssignHint();
  updateYtAssignSummary();
  _wavrickSavePipelineState();
  return { ok: true, message: "直前の割り当てを取り消しました。" };
}

function collectSpeakersFromRanges(count) {
  const SA = getSpeakerAssignApi();
  const plain = ytTranscriptPlain;
  const timeAt = SA
    ? SA.buildPlainOffsetTimeMapper(plain, ytWhisperSegments, ytWhisperDurationSec)
  : (offset) => (offset / Math.max(plain.length, 1)) * (ytWhisperDurationSec || 1);

  const buckets = [];
  for (let i = 1; i <= count; i++) {
    const speakerRanges = ytAssignRanges
      .filter((r) => r.speakerIndex === i)
      .sort((a, b) => a.start - b.start);
    const lines = SA
      ? SA.groupSpeakerLinesByTimeGap(speakerRanges, plain, timeAt, YT_ASSIGN_GAP_SEC)
      : speakerRanges
          .map((r) => plain.slice(r.start, r.end).trim())
          .filter(Boolean);
    if (lines.length) {
      buckets.push({ id: i, label: getYtSpeakerLabel(i), lines });
    }
  }
  return buckets;
}

function hasYtSpeakerAssignments() {
  return ytAssignRanges.length > 0;
}



function renderYtCastSlotSuggestion(slot) {
  const SA = getSpeakerAssignApi();
  if (!SA || (slot.mode === "pick" && slot.talentId)) return "";
  const hit = SA.suggestVaPreset(slot.speakerName || `話者${slot.speakerIndex}`);
  if (!hit) return "";
  const profile = resolveVoiceProfileByTalentId(hit.talentId);
  if (profile && isTalentBlockedForCustomer(profile)) return "";
  const name = escapeHtml(hit.displayName || hit.talentId);
  const spk = escapeHtml(hit.speakerName);

  if (profile && profile.isActive !== true) {
    return `<p class="cast-slot-suggestion cast-slot-suggestion--offline">以前「${spk}」には <strong>${name}</strong> を使っています。<br><span class="talent-offline-notice">※この声優は現在案件を受けていません</span></p>`;
  }

  return `<p class="cast-slot-suggestion">以前「${spk}」には <strong>${name}</strong> を使っています。<button type="button" class="btn-ghost cast-slot-suggestion-btn" data-apply-preset="${slot.speakerIndex}">この声優を提案どおりに選ぶ</button></p>`;
}

function renderCastSlotTalentPreview(slot) {
  if (slot.mode !== "pick" || !slot.talentId) return "";
  const profile = resolveVoiceProfileByTalentId(slot.talentId);
  if (!profile) {
    return `<p class="cast-slot-talent-name">${escapeHtml(slot.displayName || "未選択")}</p>`;
  }
  const { name, meta } = getTalentDisplayMeta(profile);
  const genres = parseGenres(profile.genres).slice(0, 3);
  const tagsHtml = genres.length
    ? genres.map((g) => `<span class="talent-tag">${g}</span>`).join("")
    : "";
  const TS = globalThis.WavrickTalentStats;
  const tid = getTalentId(profile);
  const statsHtml = TS ? TS.renderCardStatsHtml(TS.getTalentStats(tid)) : "";
  const offline = profile.isActive !== true;
  const offlineNotice = offline
    ? `<p class="talent-offline-notice">※この声優は現在案件を受けていません</p>`
    : "";
  return `
    <div class="cast-slot-profile${offline ? " cast-slot-profile--offline" : ""}">
      <div class="talent-top">
        ${renderTalentAvatarHtml(profile)}
        <div>
          <p class="talent-name">${name}</p>
          <p class="talent-meta">${meta}</p>
        </div>
      </div>
      ${offlineNotice}
      ${statsHtml}
      ${renderTalentPricingHtml(profile)}
      ${renderTalentLanguagesHtml(profile)}
      ${tagsHtml ? `<div class="talent-tags">${tagsHtml}</div>` : ""}
    </div>`;
}

function renderYtCastSlots() {
  const container = document.getElementById("ytCastSlots");
  const section = document.getElementById("ytCastSlotsSection");
  const genBtn = document.getElementById("generateScriptButton");
  if (!container || !section) return;
  const count = getYtSpeakerCount();
  const slots = loadYtCastSlots(count);
  saveYtCastSlots(slots, count);
  section.classList.remove("hidden");
  if (genBtn) genBtn.classList.remove("hidden");

  container.innerHTML = slots
    .map((slot) => {
      const i = slot.speakerIndex;
      const pickHidden = slot.mode !== "pick" ? " hidden" : "";
      const recruitNote =
        slot.mode === "recruit"
          ? `<p class="section-desc cast-slot-recruit-note">${escapeHtml(t("yt.cast_recruit_note"))}<br>${renderScriptLanguageMetaHtml(getYtScriptLanguage(), "yt.cast_recruit_language")}</p>`
          : "";
      const talentPreview = renderCastSlotTalentPreview(slot);
      const showPlain = slot.mode === "pick" && !slot.talentId;
      return `
    <div class="cast-slot-card" data-speaker-index="${i}">
      <h4>${escapeHtml(t("yt.cast_voice_title", { speaker: getYtSpeakerLabel(i) }))}</h4>
      ${renderYtCastSlotSuggestion(slot)}
      <div class="cast-slot-modes">
        <label><input type="radio" name="castSlotMode${i}" value="pick" ${slot.mode === "pick" ? "checked" : ""}> ${escapeHtml(t("yt.cast_pick_mode"))}</label>
        <label><input type="radio" name="castSlotMode${i}" value="recruit" ${slot.mode !== "pick" ? "checked" : ""}> ${escapeHtml(t("yt.cast_recruit_mode"))}</label>
      </div>
      ${recruitNote}
      <div class="cast-slot-pick${pickHidden}" id="castSlotPick${i}">
        ${talentPreview || (showPlain ? `<p class="cast-slot-talent-name">${escapeHtml(t("yt.cast_unselected"))}</p>` : "")}
        ${slot.mode === "pick" ? renderCastSlotFavoritesHtml(i) : ""}
        <button type="button" class="btn-ghost" data-pick-talent-slot="${i}">${escapeHtml(slot.talentId ? t("yt.cast_pick_btn") : t("yt.cast_browse_btn"))}</button>
      </div>
    </div>`;
    })
    .join("");

  slots.forEach((slot) => {
    const i = slot.speakerIndex;
    container.querySelectorAll(`input[name="castSlotMode${i}"]`).forEach((radio) => {
      radio.addEventListener("change", () => {
        const updated = loadYtCastSlots(count);
        const target = updated.find((s) => s.speakerIndex === i);
        if (!target) return;
        target.mode = radio.value === "pick" ? "pick" : "recruit";
        if (target.mode === "recruit") {
          target.talentId = "";
          target.displayName = "";
        }
        saveYtCastSlots(updated, count);
        renderYtCastSlots();
      });
    });
  });

  container.querySelectorAll("[data-pick-talent-slot]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const idx = Number(btn.getAttribute("data-pick-talent-slot"));
      sessionStorage.setItem("wavrick_pick_talent_slot", String(idx));
      showPage("talents");
    });
  });

  container.querySelectorAll("[data-favorite-pick-slot]").forEach((btn) => {
    btn.addEventListener("click", () => {
      if (btn.disabled) return;
      const idx = Number(btn.getAttribute("data-favorite-pick-slot"));
      const tid = btn.getAttribute("data-talent-id");
      const profile = resolveVoiceProfileByTalentId(tid);
      if (!profile) {
        setMessage("ytMessage", "声優プロフィールを読み込めませんでした。", "err");
        return;
      }
      if (profile.isActive !== true) {
        setMessage("ytMessage", "この声優は現在案件を募集していません。", "err");
        return;
      }
      if (isTalentBlockedForCustomer(profile)) {
        setMessage("ytMessage", "この声優はブロック中のため選べません。", "err");
        return;
      }
      if (assignProfileToYtCastSlot(idx, profile)) {
        const { name } = getTalentDisplayMeta(profile);
        setMessage("ytMessage", `「${getYtSpeakerLabel(idx)}」に ${name} を割り当てました（お気に入り）。`, "ok");
      }
    });
  });

  container.querySelectorAll("[data-apply-preset]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const idx = Number(btn.getAttribute("data-apply-preset"));
      const SA = getSpeakerAssignApi();
      const slots = loadYtCastSlots(getYtSpeakerCount());
      const slot = slots.find((s) => s.speakerIndex === idx);
      if (!slot || !SA) return;
      const hit = SA.suggestVaPreset(slot.speakerName || `話者${idx}`);
      if (!hit?.talentId) return;
      const profile = resolveVoiceProfileByTalentId(hit.talentId);
      if (profile && isTalentBlockedForCustomer(profile)) {
        setMessage("ytMessage", "この声優はブロック中のためおまかせ提案を適用できません。", "err");
        return;
      }
      slot.mode = "pick";
      slot.talentId = hit.talentId;
      slot.displayName = hit.displayName || hit.talentId;
      saveYtCastSlots(slots, getYtSpeakerCount());
      renderYtCastSlots();
      setMessage("ytMessage", `「${slot.speakerName}」に ${slot.displayName} を割り当てました（以前の利用履歴）。`, "ok");
    });
  });

  updateYtQuotePreview();
}

function getCastSlotsForRequest(request) {
  if (Array.isArray(request?.castSlots) && request.castSlots.length) return request.castSlots;
  const meta = parseCastMetaFromScript(request?.script || "");
  return meta?.castSlots || [];
}

function buildQuoteForCastAndScript(castSlots, script) {
  const P = getPricingApi();
  if (!P || !script?.trim()) return null;
  return P.computeProjectQuote({
    castSlots: castSlots || [],
    script,
    resolveVoice: resolveVoiceProfileByTalentId
  });
}

function buildQuoteForCurrentYtForm() {
  const script =
    String(ytScriptTimecodedFull || "").trim() ||
    document.getElementById("ytScript")?.value?.trim() ||
    "";
  const count = getYtSpeakerCount();
  const slots = loadYtCastSlots(count);
  return buildQuoteForCastAndScript(slots, script);
}

function updateYtQuotePreview() {
  const box = document.getElementById("ytQuotePreview");
  const body = document.getElementById("ytQuotePreviewBody");
  const P = getPricingApi();
  if (!box || !body || !P) return;
  const quote = buildQuoteForCurrentYtForm();
  if (!quote || quote.totalBillableSeconds <= 0) {
    box.classList.add("hidden");
    return;
  }
  const count = getYtSpeakerCount();
  const formSlots = loadYtCastSlots(count);
  const Tx = getTransactionApi();
  const speakerRows = quote.speakers
    .map((s) => {
      const slot = formSlots.find((x) => x.speakerIndex === s.speakerIndex);
      let name = s.displayName;
      if (slot?.mode === "recruit" && !slot.talentId) name = "募集枠";
      else if (Tx && slot) name = Tx.getCustomerSlotLabel({ ...slot, status: slot.status || "recruiting" }, formSlots);
      return `<tr><td>話者${s.speakerIndex}</td><td>${escapeHtml(name)}</td><td>${escapeHtml(P.formatSpeakerQuoteDuration(s.rawSeconds, s.billableSeconds))}</td><td>${escapeHtml(P.formatUsd(s.subtotalUsd))}${s.minimumApplied ? ' <span class="quote-min">(最低価格)</span>' : ""}</td></tr>`;
    })
    .join("");
  body.innerHTML = `
    <table class="quote-table">
      <thead><tr><th>話者</th><th>声優</th><th>発話時間（タイムコード）</th><th>小計</th></tr></thead>
      <tbody>${speakerRows}</tbody>
    </table>
    <p class="quote-total"><strong>お支払い総額: ${escapeHtml(P.formatUsd(quote.totalUsd))}</strong></p>
    <p class="section-desc">分配予定: 声優 ${escapeHtml(P.formatUsd(quote.voiceUsd))}（70%） / 運営 ${escapeHtml(P.formatUsd(quote.platformUsd))}（30%）</p>
  `;
  box.classList.remove("hidden");
  refreshYtProvisionalPayButton();
}

function isYtFormVerified() {
  if (isCustomerLoggedIn()) return true;
  const badge = document.getElementById("verifyBadge");
  return Boolean(badge?.classList.contains("done"));
}

async function handleStripePaymentReturn(sessionId, requestIdHint) {
  const Tx = getTransactionApi();
  if (!sessionId) {
    showPage("work");
    if (requestIdHint) setWorkSelectedRequestId(requestIdHint);
    setMessage("workMessage", "決済セッション ID がありません。案件管理から状態を確認してください。", "err");
    return;
  }
  if (!isSupabaseEnabled() || !supabaseClient) {
    showPage("work");
    if (requestIdHint) setWorkSelectedRequestId(requestIdHint);
    setMessage(
      "workMessage",
      "決済確認には Supabase 接続が必要です。ログイン後、案件管理から進捗を確認してください。",
      "err"
    );
    return;
  }

  let verifyResult;
  try {
    const { data, error } = await supabaseClient.functions.invoke("stripe-verify-payment", {
      body: {
        sessionId,
        requestId: requestIdHint || ""
      }
    });
    if (error) {
      throw new Error(error.message || "決済確認に失敗しました。");
    }
    verifyResult = data;
  } catch (e) {
    const errMsg = e instanceof Error ? e.message : String(e);
    showPage("work");
    if (requestIdHint) setWorkSelectedRequestId(requestIdHint);
    setMessage("workMessage", `決済確認に失敗しました: ${errMsg}`, "err");
    return;
  }

  if (!verifyResult?.ok || !verifyResult?.requestId) {
    showPage("work");
    if (requestIdHint) setWorkSelectedRequestId(requestIdHint);
    setMessage("workMessage", verifyResult?.error || "決済を確認できませんでした。", "err");
    return;
  }

  const requestId = verifyResult.requestId;
  const workflows = getWorkflows();
  const wf = verifyResult.workflow
    ? mapWorkflowFromRemote(verifyResult.workflow)
    : workflows[requestId] || defaultWorkflow(requestId);

  if (verifyResult.paymentType === "retake") {
    wf.retakePaymentStatus = "paid";
    wf.retakePaymentMode = "live";
    if (verifyResult.workflow?.stripe_retake_payment_intent_id) {
      wf.stripeRetakePaymentIntentId = verifyResult.workflow.stripe_retake_payment_intent_id;
    }
  } else {
    wf.paymentStatus = "paid";
    wf.paymentMode = "live";
    wf.transactionPhase = Tx ? Tx.TRANSACTION_PHASE.in_production : "in_production";
    wf.provisionalPaidAt = wf.provisionalPaidAt || new Date().toISOString();
    if (verifyResult.workflow?.stripe_payment_intent_id) {
      wf.stripePaymentIntentId = verifyResult.workflow.stripe_payment_intent_id;
    }
    if (REQUEST_STATUS_FLOW.indexOf(wf.status) < REQUEST_STATUS_FLOW.indexOf("進行中")) {
      wf.status = "進行中";
    }
  }
  wf.updatedAt = new Date().toISOString();
  const rows = await getMergedYoutubeRequests({ localOnly: true });
  const requestRow =
    rows.find(
      (r) =>
        r.requestId === requestId ||
        r.rowId === requestId ||
        String(r.id || "") === requestId
    ) || null;
  if (requestRow) {
    saveWorkflowAliases(requestRow, wf, { syncRemote: false });
  } else {
    const workflows = getWorkflows();
    workflows[requestId] = wf;
    saveWorkflows(workflows, requestId);
  }

  if (verifyResult.paymentType === "retake") {
    const pending = window.WavrickPartialRetake?.getPendingRetakeSend?.(requestId);
    if (pending?.items?.length && window.WavrickPartialRetake?.submitPartialRetake) {
      try {
        await window.WavrickPartialRetake.submitPartialRetake({
          requestId,
          items: pending.items,
          voiceMessages: pending.voiceMessages || []
        });
        setWorkCaseOpenLock(requestId);
        showPage("work");
        setMessage("workMessage", "リテイク料金の支払いを確認し、リテイクを声優へ送信しました。", "ok");
        return;
      } catch (err) {
        console.warn("[wavrick] auto retake send after payment failed", err);
      }
    }
    setWorkCaseOpenLock(requestId);
    showPage("work");
    setMessage("workMessage", "リテイク料金の支払いを確認しました。リテイク依頼を送信できます。", "ok");
    return;
  }

  // Production-start notify is sent server-side from applyPaidCheckoutSession (webhook + verify).
  setWorkCaseOpenLock(requestId);
  showPage("work");
  setMessage("workMessage", "決済が完了しました。制作を開始できます。", "ok");
  window.dispatchEvent(new Event("wavrick-workdata-updated"));
}

function refreshYtProvisionalPayButton() {
  const payBtn = document.getElementById("ytProvisionalPayBtn");
  if (payBtn) payBtn.classList.add("hidden");
}

function collectOmakaseCriteriaFromForm() {
  const gender = document.getElementById("ytOmakaseGender")?.value?.trim() || "";
  const budgetRaw = document.getElementById("ytOmakaseBudget")?.value;
  const genres = document.getElementById("ytOmakaseGenres")?.value?.trim() || "";
  const budgetMaxUsd = budgetRaw !== "" && budgetRaw != null ? Number(budgetRaw) : null;
  return {
    gender,
    budgetMaxUsd: budgetMaxUsd != null && !Number.isNaN(budgetMaxUsd) ? budgetMaxUsd : null,
    genres
  };
}

function syncRequestTalentIdsFromCastAcceptance(request, castAcceptance) {
  const Tx = getTransactionApi();
  const declined = Tx?.SLOT_STATUS?.declined || "declined";
  const activeSlots = (castAcceptance || []).filter(
    (s) => s?.talentId && String(s.status || "") !== String(declined)
  );
  const ids = activeSlots.map((s) => s.talentId).filter(Boolean);
  request.selectedTalentId = [...new Set(ids)].join(",");
  request.selectedTalentName = (castAcceptance || [])
    .map((s) => {
      const label = Tx ? Tx.getCustomerSlotLabel(s, castAcceptance) : s.displayName || "—";
      return `話者${s.speakerIndex}: ${label}`;
    })
    .join(" / ");
}

function resolveTalentEmailFromTalentId(talentId) {
  const tid = String(talentId || "").trim();
  if (!tid) return "";
  if (tid.startsWith("voice:") && tid.includes("@")) {
    return tid.slice(6).toLowerCase().trim();
  }
  const profile = resolveVoiceProfileByTalentId(tid);
  return String(profile?.email || "").toLowerCase().trim();
}

function findLocalRequestById(requestId) {
  const rid = String(requestId || "").trim();
  if (!rid) return null;
  try {
    const rows = JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]");
    return (
      (Array.isArray(rows) ? rows : []).find(
        (r) => String(r?.requestId || r?.requestid || "").trim() === rid
      ) || null
    );
  } catch {
    return null;
  }
}

/** Collect customer + cast talent emails for a case.（辞退・離任済み声優は含めない） */
function collectCaseParticipantEmails(requestId, request, wf, options = {}) {
  const req = request || findLocalRequestById(requestId);
  const workflow =
    wf ||
    (typeof getWorkflowForRequest === "function"
      ? getWorkflowForRequest(requestId, req?.status, req)
      : null);
  const emails = new Set();
  const customerEmail = String(req?.email || "").toLowerCase().trim();
  if (customerEmail) emails.add(customerEmail);
  const Tx = getTransactionApi();
  const declined = Tx?.SLOT_STATUS?.declined || "declined";
  for (const slot of workflow?.castAcceptance || []) {
    if (!slot) continue;
    if (String(slot.status || "") === String(declined)) continue;
    const tid = String(slot.talentId || "").trim();
    if (!tid) continue;
    // lastCancelled と同一なら離任済み（talentId 残留の取りこぼし防止）
    if (
      slot.lastCancelledTalentId &&
      (Tx?.talentIdsMatch
        ? Tx.talentIdsMatch(slot.lastCancelledTalentId, tid)
        : String(slot.lastCancelledTalentId) === tid)
    ) {
      continue;
    }
    const email = resolveTalentEmailFromTalentId(tid);
    if (email) emails.add(email);
  }
  const exclude = String(options.excludeEmail || "")
    .toLowerCase()
    .trim();
  if (exclude) emails.delete(exclude);
  if (options.voicesOnly && customerEmail) emails.delete(customerEmail);
  return [...emails];
}

/**
 * Case-scoped notification with resolved recipients.
 * @param {string} text
 * @param {string} requestId
 * @param {{
 *   to?: 'customer'|'voice'|'participants',
 *   kind?: string,
 *   category?: string,
 *   talentId?: string,
 *   targetEmails?: string[],
 *   targetRole?: string,
 *   request?: object,
 *   workflow?: object,
 *   excludeSelf?: boolean,
 *   batchId?: string
 * }} [options]
 */
function pushCaseNotification(text, requestId, options = {}) {
  const session = getCurrentSession();
  const me = String(session?.email || "")
    .toLowerCase()
    .trim();
  const to = String(options.to || "participants").trim() || "participants";
  const req = options.request || findLocalRequestById(requestId);
  const wf =
    options.workflow ||
    (typeof getWorkflowForRequest === "function"
      ? getWorkflowForRequest(requestId, req?.status, req)
      : null);

  let targetEmails = normalizeNotificationEmails(options.targetEmails);
  let targetRole = String(options.targetRole || "").trim();

  if (!targetEmails.length) {
    if (to === "customer") {
      const email = String(req?.email || "")
        .toLowerCase()
        .trim();
      targetEmails = email ? [email] : [];
      targetRole = targetRole || "customer";
    } else if (to === "voice") {
      if (options.talentId) {
        const one = resolveTalentEmailFromTalentId(options.talentId);
        targetEmails = one ? [one] : [];
      } else {
        targetEmails = collectCaseParticipantEmails(requestId, req, wf, { voicesOnly: true });
      }
      targetRole = targetRole || "voice";
    } else {
      targetEmails = collectCaseParticipantEmails(requestId, req, wf, {
        excludeEmail: options.excludeSelf === false ? "" : me
      });
      targetRole = targetRole || "all";
    }
  }

  if (options.excludeSelf !== false && me) {
    targetEmails = targetEmails.filter((e) => e !== me);
  }

  // 辞退・離任済み声優には案件お知らせを送らない（キャンセル了承依頼の迷子防止）
  const activeVoice = new Set(
    collectCaseParticipantEmails(requestId, req, wf, { voicesOnly: true })
  );
  const customerEmail = String(req?.email || "")
    .toLowerCase()
    .trim();
  targetEmails = targetEmails.filter(
    (e) => activeVoice.has(e) || (customerEmail && e === customerEmail)
  );

  if (options.emailTemplate && targetEmails.length) {
    sendCaseTransactionalEmail(
      options.emailTemplate,
      targetEmails,
      requestId,
      options.emailVars
    );
  }

  return pushNotification(text, requestId, {
    kind: options.kind || "system",
    category: options.category || "case",
    batchId: options.batchId,
    targetRole: targetRole || "all",
    targetEmails,
    targetMode: targetEmails.length ? "users" : "role"
  });
}

function sendCaseTransactionalEmail(templateKey, emails, requestId, vars) {
  const key = String(templateKey || "").trim();
  const list = normalizeNotificationEmails(emails);
  if (!key || !list.length) return;
  globalThis.WavrickEmailNotify?.sendQuiet?.(key, list, {
    requestId: String(requestId || "").trim(),
    vars: vars && typeof vars === "object" ? vars : {}
  });
}

function notifyNamedTalentCastOffer(requestId, castAcceptance, options = {}) {
  const Tx = getTransactionApi();
  const emailTemplate = String(options.emailTemplate || "invited").trim();
  for (const slot of castAcceptance || []) {
    if (!slot?.talentId) continue;
    if (slot.status !== Tx?.SLOT_STATUS.pending_acceptance) continue;
    const email = resolveTalentEmailFromTalentId(slot.talentId);
    // Never fall back to role broadcast — that spams every voice who can see the case.
    if (!email) {
      console.warn("[wavrick] cast offer skipped — talent email unresolved", slot.talentId);
      continue;
    }
    pushNotification(t("work.notify_invited"), requestId, {
      kind: "customer",
      targetRole: "voice",
      targetEmails: [email],
      category: "case",
      targetMode: "users"
    });
    if (emailTemplate) {
      sendCaseTransactionalEmail(emailTemplate, [email], requestId, {
        speaker: String(slot.speakerIndex || "")
      });
    }
  }
}

/** Notify applicants who were not selected for a speaker slot. */
function notifyPassedApplicantsForSpeaker(requestId, slot, speakerIndex) {
  const apps = Array.isArray(slot?.applications) ? slot.applications : [];
  const winnerId = String(slot?.talentId || "").trim();
  const emails = [];
  for (const app of apps) {
    if (String(app?.status || "") !== "passed") continue;
    const tid = String(app?.talentId || "").trim();
    if (!tid || (winnerId && tid === winnerId)) continue;
    const email = resolveTalentEmailFromTalentId(tid);
    if (email) emails.push(email);
  }
  const unique = [...new Set(emails)];
  for (const email of unique) {
    pushNotification(t("work.notify_applicant_passed", { speaker: speakerIndex }), requestId, {
      kind: "customer",
      targetRole: "voice",
      targetEmails: [email],
      category: "case",
      targetMode: "users"
    });
  }
}

function maybeAdvanceTransactionPhase(wf, request = null) {
  if (!wf) return wf;
  if (wf.transactionPhase === "cancelled" || wf.status === "キャンセル") {
    wf.status = "キャンセル";
    wf.transactionPhase = "cancelled";
    return wf;
  }
  const Tx = getTransactionApi();
  if (Tx?.maybeHealStuckTalentSlotCancel) {
    const healed = Tx.maybeHealStuckTalentSlotCancel(wf);
    if (healed?.wf) wf = healed.wf;
  }
  if (Tx?.maybeExpireUnpaidQuote) {
    const expired = Tx.maybeExpireUnpaidQuote(wf);
    if (expired?.expired) return expired.wf || wf;
  }
  const Sync = globalThis.WavrickWorkflowSync;
  if (typeof Sync?.syncWorkflowProgress === "function") {
    const next = Sync.syncWorkflowProgress(wf) || wf;
    if (Tx?.ensureQuotedAt && String(next.transactionPhase || "") === "quoted") {
      Tx.ensureQuotedAt(next);
    }
    return next;
  }
  // Fallback when sync module is not loaded yet
  if (!Tx || !wf?.castAcceptance?.length) return wf;
  if (wf.paymentStatus === "paid" || wf.paymentStatus === "paid_provisional") {
    if (Tx.allSlotsAccepted(wf.castAcceptance)) {
      wf.transactionPhase = Tx.TRANSACTION_PHASE.in_production;
      if (REQUEST_STATUS_FLOW.indexOf(wf.status) < REQUEST_STATUS_FLOW.indexOf("進行中")) {
        wf.status = "進行中";
      }
    }
    return wf;
  }
  if (Tx.allSlotsAccepted(wf.castAcceptance)) {
    wf.transactionPhase = Tx.TRANSACTION_PHASE.quoted;
    Tx.ensureQuotedAt?.(wf);
    if (REQUEST_STATUS_FLOW.indexOf(wf.status) < REQUEST_STATUS_FLOW.indexOf("選定中")) {
      wf.status = "選定中";
    }
  } else {
    wf.transactionPhase = Tx.TRANSACTION_PHASE.casting;
    if (!wf.status || wf.status === REQUEST_STATUS_FLOW[0]) {
      wf.status = REQUEST_STATUS_FLOW[0];
    }
  }
  return wf;
}

function countPendingRecruitApplicants(wf) {
  const Tx = getTransactionApi();
  if (!Tx || !wf?.castAcceptance?.length) return 0;
  let n = 0;
  for (const slot of wf.castAcceptance) {
    if (slot.mode !== "recruit") continue;
    if (
      slot.status !== Tx.SLOT_STATUS.recruiting &&
      slot.status !== Tx.SLOT_STATUS.needs_reselection
    ) {
      continue;
    }
    n += (Tx.getSelectableApplicants(slot) || []).length;
  }
  return n;
}

function buildCustomerApplicantSelectHtml(slot, request) {
  const Tx = getTransactionApi();
  if (
    !Tx ||
    slot.mode !== "recruit" ||
    (slot.status !== Tx.SLOT_STATUS.recruiting && slot.status !== Tx.SLOT_STATUS.needs_reselection)
  ) {
    return "";
  }
  const applicants = Tx.getSelectableApplicants(slot) || [];
  if (!applicants.length) {
    return `<div class="cast-applicants cast-applicants--empty">
      <h4 class="cast-applicants-title">応募者の選定</h4>
      <p class="section-desc">ここが応募の受け取り・選定スペースです。声優が応募すると、この枠に候補が表示され「この声優に選定」できます。いまはまだ応募がありません。</p>
    </div>`;
  }
  return `<div class="cast-applicants cast-applicants--select">
    <div class="cast-applicants-head">
      <h4 class="cast-applicants-title">応募者の選定</h4>
      <span class="cast-applicants-count">${applicants.length} 人</span>
    </div>
    <p class="section-desc">選定すると、その声優に受諾依頼が届きます。選定後は案件管理から回答状況を確認できます。</p>
    <div class="cast-applicant-list">
      ${applicants
        .map((a) => {
          const profile = resolveVoiceProfileByTalentId(a.talentId);
          const name = formatParticipantDisplayName(a.displayName || profile?.displayName || a.talentId, a.talentId);
          const meta = [
            profile?.gender ? String(profile.gender) : "",
            Array.isArray(profile?.supportedLanguages)
              ? profile.supportedLanguages.slice(0, 2).join("/")
              : ""
          ]
            .filter(Boolean)
            .join(" · ");
          return `<div class="cast-applicant-card">
            <div class="cast-applicant-card-main">
              <strong class="cast-applicant-name">${escapeHtml(name)}</strong>
              ${meta ? `<span class="cast-applicant-meta">${escapeHtml(meta)}</span>` : ""}
            </div>
            <div class="cast-applicant-card-actions">
              ${
                profile
                  ? `<button type="button" class="btn-ghost btn-sm" data-view-applicant="${escapeAttr(a.talentId)}">プロフィール</button>`
                  : ""
              }
              <button type="button" class="btn-red btn-sm" data-select-applicant="${slot.speakerIndex}" data-talent-id="${escapeAttr(a.talentId)}">この声優に選定</button>
            </div>
          </div>`;
        })
        .join("")}
    </div>
  </div>`;
}

const _quoteExpiryPersistInflight = new Set();
const _quoteRemindSent = new Set();

/** Client-side backup for day-3 / day-6 payment reminders (server cron is primary). */
function maybeNotifyQuotePaymentReminders(request, wf, session) {
  if (session?.role !== "customer" && session?.role !== "admin") return;
  const Tx = getTransactionApi();
  const reqId = String(request?.requestId || "").trim();
  if (!Tx || !reqId || !wf) return;
  const pay = String(wf.paymentStatus || wf.paymentstatus || "").toLowerCase();
  if (pay === "paid" || pay === "paid_provisional" || pay === "refunded" || pay === "cancelled") return;
  if (String(wf.status || "") === "キャンセル") return;
  if (String(wf.transactionPhase || "") !== "quoted" && !Tx.allSlotsAccepted?.(wf.castAcceptance || [])) {
    return;
  }
  const quotedMs = Tx.getQuotedAtMs?.(wf) || 0;
  if (!quotedMs) return;
  const age = Date.now() - quotedMs;
  const day = 24 * 60 * 60 * 1000;
  let key = "";
  let text = "";
  if (age >= 6 * day && age < 7 * day) {
    key = `d6:${reqId}`;
    text = t("work.notify_quote_pay_remind_final", { id: reqId });
  } else if (age >= 3 * day && age < 6 * day) {
    key = `d3:${reqId}`;
    text = t("work.notify_quote_pay_remind_mid", { id: reqId });
  }
  if (!key || !text || _quoteRemindSent.has(key)) return;
  try {
    if (sessionStorage.getItem(`wavrick_quote_remind:${key}`)) {
      _quoteRemindSent.add(key);
      return;
    }
  } catch {
    /* ignore */
  }
  _quoteRemindSent.add(key);
  try {
    sessionStorage.setItem(`wavrick_quote_remind:${key}`, "1");
  } catch {
    /* ignore */
  }
  pushCaseNotification(text, reqId, {
    to: "customer",
    kind: "system",
    category: "case",
    request,
    excludeSelf: false
  });
}

async function maybePersistQuotePaymentExpiry(request, wf) {
  const Tx = getTransactionApi();
  const reqId = String(request?.requestId || wf?.requestId || "").trim();
  if (!Tx?.maybeExpireUnpaidQuote || !reqId) return;
  if (_quoteExpiryPersistInflight.has(reqId)) return;
  // Don't mutate the live wf: probe on a deep clone
  let wouldExpire = false;
  try {
    const clone = JSON.parse(JSON.stringify(wf || {}));
    wouldExpire = Boolean(Tx.maybeExpireUnpaidQuote(clone)?.expired);
  } catch {
    return;
  }
  if (!wouldExpire) return;
  _quoteExpiryPersistInflight.add(reqId);
  try {
    let didExpire = false;
    await updateWorkflowForRequest(reqId, (inner) => {
      const result = Tx.maybeExpireUnpaidQuote(inner);
      didExpire = Boolean(result?.expired);
      return result?.wf || inner;
    });
    if (!didExpire) return;
    await logCaseCancelEvent({
      requestId: reqId,
      caseTitle: caseTitleForRequest(request),
      customerEmail: request?.email || "",
      cancelledByRole: "system",
      cancelledByEmail: getCurrentSession()?.email || null,
      cancelKind: "transaction",
      reasonCode: "A",
      reasonDetail: "payment_deadline_expired",
      progressPhase: "cancelled",
      progressStatus: "キャンセル",
      hasDeliveries: false,
      metadata: { source: "auto_quote_payment_deadline", days: 7 }
    });
    pushCaseNotification(
      t("work.notify_quote_expired") ||
        "決済期限（全員受諾から7日以内）を過ぎたため、この取引は自動的にキャンセルされました。",
      reqId,
      {
        to: "participants",
        kind: "system",
        category: "case",
        request: request || { requestId: reqId },
        emailTemplate: "quote_expired"
      }
    );
  } catch (err) {
    console.warn("[wavrick] quote expiry persist failed", err);
  } finally {
    _quoteExpiryPersistInflight.delete(reqId);
  }
}

function renderWorkTransactionPanel(request, session, wf) {
  const card = document.getElementById("workTransactionCard");
  const phaseEl = document.getElementById("workTransactionPhase");
  const listEl = document.getElementById("workCastAcceptanceList");
  const quoteEl = document.getElementById("workQuoteSummary");
  const payBtn = document.getElementById("workPayQuoteBtn");
  const cancelBtn = document.getElementById("workCancelTransactionBtn");
  const banner = document.getElementById("workApplicantSelectBanner");
  const bannerText = document.getElementById("workApplicantSelectBannerText");
  const Tx = getTransactionApi();
  const P = getPricingApi();
  const canManageCast = session?.role === "customer" || session?.role === "admin";
  if (!card || !phaseEl || !listEl || !canManageCast) {
    banner?.classList.add("hidden");
    if (banner) banner.hidden = true;
    return;
  }

  // 全員受諾から7日未決済 → 自動キャンセル（表示時に検知して永続化）
  // ※ renderWorkDetails 側でも呼ぶ。ここでは顧客パネル再描画用の保険。
  void maybePersistQuotePaymentExpiry(request, wf);
  // Mid / final payment reminders while viewing the case (server cron also sends these).
  maybeNotifyQuotePaymentReminders(request, wf, session);

  const phase = wf.transactionPhase || "draft";
  const show =
    phase === Tx?.TRANSACTION_PHASE.casting ||
    phase === Tx?.TRANSACTION_PHASE.quoted ||
    phase === Tx?.TRANSACTION_PHASE.paid_provisional ||
    phase === Tx?.TRANSACTION_PHASE.awaiting_acceptance ||
    phase === Tx?.TRANSACTION_PHASE.in_production ||
    (wf.castAcceptance?.length > 0 && phase !== Tx?.TRANSACTION_PHASE.cancelled);

  card.classList.toggle("hidden", !show);
  if (!show) {
    banner?.classList.add("hidden");
    if (banner) banner.hidden = true;
    return;
  }

  const pendingApplicants = countPendingRecruitApplicants(wf);
  if (banner) {
    const showBanner = pendingApplicants > 0;
    banner.classList.toggle("hidden", !showBanner);
    banner.hidden = !showBanner;
    if (bannerText && showBanner) {
      bannerText.textContent = `応募 ${pendingApplicants} 人。下の「応募者の選定」から声優を選ぶと、その声優に受諾依頼が届きます。`;
    }
    const jumpBtn = document.getElementById("workApplicantSelectJumpBtn");
    if (jumpBtn && jumpBtn.dataset.bound !== "1") {
      jumpBtn.dataset.bound = "1";
      jumpBtn.addEventListener("click", () => {
        document.getElementById("workTransactionCard")?.scrollIntoView({
          behavior: "smooth",
          block: "start"
        });
      });
    }
  }

  const declinedPickCount = (wf.castAcceptance || []).filter(
    (s) => s?.mode === "pick" && s?.status === Tx?.SLOT_STATUS.declined
  ).length;
  const phaseHint =
    phase === Tx?.TRANSACTION_PHASE.quoted
      ? (() => {
          const qms = Tx.getQuotedAtMs?.(wf) || Date.parse(wf?.quotedAt || "") || 0;
          const left = qms ? Tx.QUOTE_PAYMENT_DEADLINE_MS - (Date.now() - qms) : null;
          const daysLeft =
            left != null && left > 0 ? Math.max(1, Math.ceil(left / 86400000)) : null;
          const base =
            t("work.quoted_pay_hint") ||
            "全員の受諾が完了しました。見積を確認して決済してください。";
          if (daysLeft != null) {
            return `${base}（決済期限までおよそ ${daysLeft} 日。過ぎると自動キャンセル）`;
          }
          return base;
        })()
      : phase === Tx?.TRANSACTION_PHASE.in_production
        ? "決済済み・制作進行中です。"
        : declinedPickCount > 0
          ? t("work.cast_invite_cancelled_hint") ||
            "声優の依頼がキャンセルされました。下から新たに依頼するか募集してください。"
          : pendingApplicants > 0
            ? `募集枠に応募が ${pendingApplicants} 件あります。下の「応募者の選定」から声優を選んでください。`
            : "指名枠は受諾待ち、募集枠は応募・選定・受諾を進めてください。";
  phaseEl.textContent = Tx ? `${Tx.transactionPhaseLabel(phase)} — ${phaseHint}` : phase;

  const slots = wf.castAcceptance || [];
  const canSeeNames = Tx ? Tx.customerCanSeeTalentNames(slots) : true;
  // スタックした talent_slot 交渉を解除してからボタン活性を判定
  if (Tx?.maybeHealStuckTalentSlotCancel) {
    Tx.maybeHealStuckTalentSlotCancel(wf);
  }
  const castingLocked = Boolean(Tx?.isCastingLockedForCancel?.(wf));
  const cancelCn = Tx?.getCancelNegotiation?.(wf) || null;
  const talentSlotCancelPending =
    Boolean(Tx?.isTalentSlotCancelPending?.(wf)) ||
    (Boolean(Tx?.isCancelPending?.(wf)) &&
      Tx?.getCancelScope?.(cancelCn) === (Tx?.CANCEL_SCOPE?.talent_slot || "talent_slot"));
  const cancelTargetTalentId = talentSlotCancelPending
    ? String(cancelCn?.targetTalentId || "").trim()
    : "";
  const cancelTargetSpeakerIndex =
    Number(
      Tx?.getCancelTargetSpeakerIndex?.(cancelCn) || cancelCn?.targetSpeakerIndex || 0
    ) || 0;
  const cancelDisputed = Boolean(talentSlotCancelPending && Tx?.isCancelDisputed?.(wf));

  listEl.innerHTML = slots.length
    ? slots
        .map((slot) => {
          const isDeclinedPick =
            slot.status === Tx?.SLOT_STATUS.declined &&
            (slot.mode === "pick" || Boolean(slot.talentId) || Boolean(slot.lastCancelledTalentId));
          const label = Tx ? Tx.getCustomerSlotLabel(slot, slots) : slot.displayName || "—";
          const statusLabel = isDeclinedPick
            ? t("work.cast_invite_cancelled") || "声優の依頼がキャンセルされました"
            : Tx
              ? Tx.slotStatusLabel(slot.status)
              : slot.status;
          const slotCancelPending =
            talentSlotCancelPending &&
            Boolean(slot.talentId) &&
            (Tx?.talentIdsMatch
              ? Tx.talentIdsMatch(slot.talentId, cancelTargetTalentId)
              : String(slot.talentId) === cancelTargetTalentId) &&
            (cancelTargetSpeakerIndex < 1 ||
              Number(slot.speakerIndex) === cancelTargetSpeakerIndex);
          const declinedActions = isDeclinedPick
            ? `<div class="cast-acceptance-decline-actions">
                <button type="button" class="btn-primary btn-sm" data-recast-speaker="${slot.speakerIndex}" ${
                  castingLocked ? "disabled" : ""
                }>${escapeHtml(
                  t("work.recast_new_invite") || "新たに依頼する"
                )}</button>
                <button type="button" class="btn-ghost btn-sm" data-open-recruit-speaker="${slot.speakerIndex}" ${
                  castingLocked ? "disabled" : ""
                }>${escapeHtml(
                  t("work.open_recruit") || "募集する"
                )}</button>
              </div>${
                castingLocked
                  ? `<p class="section-desc">${escapeHtml(
                      t("work.cancel_cast_locked") ||
                        "キャンセル交渉中のため、キャスティング変更はできません。"
                    )}</p>`
                  : ""
              }`
            : "";
          const applicantHtml = isDeclinedPick || castingLocked
            ? ""
            : buildCustomerApplicantSelectHtml(slot, request);
          const nameCell = canSeeNames || slot.talentId || isDeclinedPick
            ? escapeHtml(label)
            : escapeHtml(label);
          const isAccepted =
            slot.status === Tx?.SLOT_STATUS.accepted && Boolean(slot.talentId);
          const modeBadge = isDeclinedPick
            ? `<span class="cast-slot-mode-badge cast-slot-mode-badge--cancelled">${escapeHtml(
                t("work.cast_mode_cancelled") || "キャンセル"
              )}</span>`
            : slot.mode === "recruit"
              ? `<span class="cast-slot-mode-badge">募集</span>`
              : `<span class="cast-slot-mode-badge cast-slot-mode-badge--pick">指名</span>`;
          const slotCancelBadge = slotCancelPending
            ? `<span class="cast-slot-mode-badge cast-slot-mode-badge--cancel-pending">${escapeHtml(
                cancelDisputed
                  ? t("work.slot_cancel_disputed_badge") || "キャンセル係争中"
                  : t("work.slot_cancel_pending_badge") || "この声優のキャンセル交渉中"
              )}</span>`
            : "";
          const slotCancelHint = slotCancelPending
            ? (() => {
                const reason = cancelReasonLabel(cancelCn?.reasonCode);
                const detail = String(cancelCn?.reasonDetail || "").trim();
                const body = cancelDisputed
                  ? t("work.slot_cancel_disputed_hint") ||
                    "この声優がキャンセルに了承しませんでした。運営が判断します。"
                  : t("work.slot_cancel_pending_hint") ||
                    "この声優へのキャンセル依頼を送信済みです。了承待ちです。了承されない場合は運営が判断します。";
                return `<p class="section-desc cast-slot-cancel-hint">${escapeHtml(body)}${
                  reason || detail
                    ? `<br>${escapeHtml(`${reason}${detail ? ` — ${detail}` : ""}`)}`
                    : ""
                }</p>`;
              })()
            : "";
          const nameHtml = isAccepted
            ? `<button type="button" class="cast-acceptance-name cast-acceptance-name--link" data-view-accepted-talent="${escapeAttr(
                slot.talentId
              )}" data-accepted-speaker="${Number(slot.speakerIndex) || 0}">${nameCell}</button>`
            : `<span class="cast-acceptance-name">${nameCell}</span>`;
          return `<div class="cast-acceptance-row cast-acceptance-row--customer${
            isDeclinedPick ? " cast-acceptance-row--declined" : ""
          }${slotCancelPending ? " cast-acceptance-row--cancel-pending" : ""}">
            <div class="cast-acceptance-row-main">
              <span class="cast-acceptance-speaker">話者${slot.speakerIndex}</span>
              ${modeBadge}
              ${nameHtml}
              ${slotCancelBadge}
              ${isDeclinedPick || slotCancelPending ? "" : `<span class="cast-acceptance-status">${escapeHtml(statusLabel)}</span>`}
            </div>
            ${slotCancelHint}
            ${declinedActions}
            ${applicantHtml}
          </div>`;
        })
        .join("")
    : `<p class="section-desc">キャスティング情報はまだありません。</p>`;

  listEl.querySelectorAll("[data-view-accepted-talent]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const talentId = btn.getAttribute("data-view-accepted-talent");
      const speakerIndex = Number(btn.getAttribute("data-accepted-speaker")) || 0;
      const profile = resolveVoiceProfileByTalentId(talentId);
      if (!profile) {
        setMessage("workMessage", t("work.talent_profile_missing") || "声優プロフィールを取得できませんでした。", "err");
        return;
      }
      openTalentProfileModal(profile, {
        caseContext: {
          requestId: request.requestId || request.rowId || "",
          caseTitle: request.name || request.requestId || "",
          customerEmail: request.email || "",
          speakerIndex,
          showReportCancel: true
        }
      });
    });
  });

  listEl.querySelectorAll("[data-recast-speaker]").forEach((btn) => {
    btn.addEventListener("click", () => {
      if (Tx?.isCastingLockedForCancel?.(wf)) {
        setMessage(
          "workMessage",
          t("work.cancel_cast_locked") || "キャンセル交渉中のため、キャスティング変更はできません。",
          "err"
        );
        return;
      }
      const idx = Number(btn.getAttribute("data-recast-speaker"));
      sessionStorage.setItem("wavrick_recast_speaker", String(idx));
      sessionStorage.setItem("wavrick_recast_request", request.requestId || "");
      showPage("talents");
    });
  });

  listEl.querySelectorAll("[data-open-recruit-speaker]").forEach((btn) => {
    btn.addEventListener("click", () => {
      if (Tx?.isCastingLockedForCancel?.(wf)) {
        setMessage(
          "workMessage",
          t("work.cancel_cast_locked") || "キャンセル交渉中のため、キャスティング変更はできません。",
          "err"
        );
        return;
      }
      const speakerIndex = Number(btn.getAttribute("data-open-recruit-speaker"));
      if (!speakerIndex) return;
      bindWorkOpenRecruitModal();
      openWorkOpenRecruitModal(request, speakerIndex, wf);
    });
  });

  listEl.querySelectorAll("[data-view-applicant]").forEach((btn) => {
    btn.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const talentId = btn.getAttribute("data-view-applicant");
      const profile = resolveVoiceProfileByTalentId(talentId);
      if (!profile) {
        setMessage("workMessage", "プロフィールを開けませんでした。", "err");
        return;
      }
      const scrollY = window.scrollY;
      openTalentProfileModal(profile);
      // Modal history push used to clear #hash and jump to top; restore just in case.
      requestAnimationFrame(() => {
        if (Math.abs(window.scrollY - scrollY) > 8) window.scrollTo(0, scrollY);
      });
    });
  });

  listEl.querySelectorAll("[data-select-applicant]").forEach((btn) => {
    btn.addEventListener("click", async (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (Tx?.isCastingLockedForCancel?.(wf)) {
        setMessage(
          "workMessage",
          t("work.cancel_cast_locked") || "キャンセル交渉中のため、キャスティング変更はできません。",
          "err"
        );
        return;
      }
      const speakerIndex = Number(btn.getAttribute("data-select-applicant"));
      const talentId = btn.getAttribute("data-talent-id");
      if (!Tx || !talentId) return;
      const caseId = request.requestId || request.rowId;
      if (!caseId) {
        setMessage("workMessage", "対象案件がありません。", "err");
        return;
      }
      btn.disabled = true;
      let selectError = "";
      let result;
      try {
        result = await updateWorkflowForRequest(caseId, (innerWf) => {
          const sel = Tx.customerSelectApplicant(innerWf.castAcceptance || [], speakerIndex, talentId);
          if (!sel.ok) {
            selectError = sel.error || "選定に失敗しました。";
            return innerWf;
          }
          innerWf.castAcceptance = sel.slots;
          return maybeAdvanceTransactionPhase(innerWf, request);
        });
      } catch (err) {
        console.warn("[wavrick] customerSelectApplicant failed", err);
        setMessage("workMessage", err instanceof Error ? err.message : "選定に失敗しました。", "err");
        btn.disabled = false;
        return;
      }
      if (!result?.ok) {
        setMessage("workMessage", result?.error || "選定に失敗しました。", "err");
        btn.disabled = false;
        return;
      }
      if (selectError) {
        setMessage("workMessage", selectError, "err");
        btn.disabled = false;
        return;
      }
      const updatedRequest = result.request || request;
      const requestId = updatedRequest.requestId || caseId;
      const rows = JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]");
      const reqIdx = rows.findIndex(
        (r) =>
          r.requestId === requestId ||
          r.rowId === requestId ||
          r.requestId === request.rowId ||
          r.rowId === request.requestId
      );
      const updatedWf = result.workflow || getWorkflowForRequest(requestId, updatedRequest.status, updatedRequest);
      if (reqIdx >= 0 && updatedWf) {
        syncRequestTalentIdsFromCastAcceptance(rows[reqIdx], updatedWf.castAcceptance);
        rows[reqIdx].updatedAt = new Date().toISOString();
        localStorage.setItem("wavrick_youtube_requests", JSON.stringify(rows));
        void persistYoutubeRequestToCloud(rows[reqIdx]);
      }
      pushCaseNotification(t("work.notify_speaker_selected", { speaker: speakerIndex }), requestId, {
        to: "participants",
        kind: "customer",
        category: "case"
      });
      const selectedSlot = updatedWf?.castAcceptance?.find(
        (s) => Number(s.speakerIndex) === Number(speakerIndex)
      );
      if (selectedSlot?.talentId) {
        notifyNamedTalentCastOffer(requestId, [selectedSlot], {
          emailTemplate: "speaker_selected"
        });
      } else {
        pushNotification(t("work.notify_invited"), requestId, {
          kind: "customer",
          targetRole: "voice",
          category: "case"
        });
      }
      notifyPassedApplicantsForSpeaker(requestId, selectedSlot, speakerIndex);
      setMessage("workMessage", `話者${speakerIndex} の声優を選定しました。受諾をお待ちください。`, "ok");
      renderWorkDetails(updatedRequest, session);
    });
  });

  const quote = buildQuoteForCastAndScript(slots, request.script || "");
  if (quoteEl && P && quote?.totalBillableSeconds > 0) {
    const speakerRows = quote.speakers
      .map(
        (s) =>
          `<tr><td>話者${s.speakerIndex}</td><td>${escapeHtml(s.displayName)}</td><td>${escapeHtml(P.formatSpeakerQuoteDuration(s.rawSeconds, s.billableSeconds))}</td><td>${escapeHtml(P.formatUsd(s.subtotalUsd))}${s.minimumApplied ? ' <span class="quote-min">(最低価格)</span>' : ""}</td></tr>`
      )
      .join("");
    quoteEl.innerHTML = `
      <h4>見積もり（$15/分・枠最低 $20）</h4>
      <table class="quote-table">
        <thead><tr><th>話者</th><th>担当</th><th>発話時間</th><th>小計</th></tr></thead>
        <tbody>${speakerRows}</tbody>
      </table>
      <p class="quote-total"><strong>お支払い総額: ${escapeHtml(P.formatUsd(quote.totalUsd))}</strong></p>`;
    quoteEl.classList.toggle("hidden", phase !== Tx?.TRANSACTION_PHASE.quoted);
  } else if (quoteEl) {
    quoteEl.classList.add("hidden");
  }

  if (payBtn) {
    const payBlocked =
      isWorkflowCancelled(wf) ||
      Boolean(Tx?.isPaymentBlockedByCancel?.(wf)) ||
      Boolean(Tx?.isCancelPending?.(wf));
    const canPay =
      session?.role === "customer" &&
      phase === Tx?.TRANSACTION_PHASE.quoted &&
      quote?.totalUsd > 0 &&
      !isWorkflowPaymentCleared(wf, request, session) &&
      !payBlocked;
    payBtn.classList.toggle("hidden", !canPay);
    payBtn.disabled = false;
    payBtn.textContent = quote ? `この見積（${P.formatUsd(quote.totalUsd)}）で決済する` : "決済する";
  }

  const adminSkipBtn = document.getElementById("workAdminTestPaySkipBtn");
  if (adminSkipBtn) {
    const showAdminProvisional =
      (session?.role === "admin" || isAdminTestRequest(request, session)) &&
      phase === Tx?.TRANSACTION_PHASE.quoted &&
      !isWorkflowPaymentCleared(wf, request, session);
    adminSkipBtn.classList.toggle("hidden", !showAdminProvisional);
  }

  if (cancelBtn) {
    const cancelled = phase === Tx?.TRANSACTION_PHASE.cancelled || isWorkflowCancelled(wf);
    const pending = Boolean(Tx?.isCancelPending?.(wf));
    const completed = String(wf?.status || "").trim() === "完了";
    // 制作中もキャンセル可。キャンセル済み・交渉中・取引完了のみ非表示。
    cancelBtn.classList.toggle("hidden", cancelled || pending || completed);
    cancelBtn.disabled = pending;
  }
}

function renderWorkVoiceRecruitCard(request, session, wf) {
  const card = document.getElementById("workVoiceRecruitCard");
  const listEl = document.getElementById("workVoiceRecruitList");
  const Tx = getTransactionApi();
  if (!card || !listEl || session?.role !== "voice") return;
  if (isWorkflowCancelled(wf)) {
    card.classList.add("hidden");
    return;
  }

  const talentId = resolveVoiceTalentIdForSession(session);
  const slots = wf.castAcceptance || [];
  const openSlots = Tx ? Tx.getOpenRecruitSlots(slots) : [];
  const customerEmail = (request?.email || "").toLowerCase().trim();
  const B = getTalentBlocksApi();
  const blockedByRelation = Boolean(customerEmail && B?.isBlockedBetween(customerEmail, talentId));

  if (!openSlots.length) {
    card.classList.add("hidden");
    return;
  }

  card.classList.remove("hidden");
  listEl.innerHTML = openSlots
    .map((slot) => {
      const applied = Tx?.voiceHasAppliedToSlot(slot, talentId);
      const canApply = !blockedByRelation && Tx?.canTalentApplyToSlot(slot, talentId);
      const btn = applied
        ? `<span class="cast-acceptance-status">応募済み</span>`
        : blockedByRelation
          ? `<span class="cast-acceptance-status">ブロック中</span>`
          : canApply
          ? `<button type="button" class="btn-red btn-sm" data-apply-slot="${slot.speakerIndex}">この枠に応募する</button>`
          : `<span class="cast-acceptance-status">応募不可</span>`;
      return `<div class="cast-acceptance-row">
        <span class="cast-acceptance-speaker">話者${slot.speakerIndex}</span>
        <span class="cast-acceptance-name">${escapeHtml(request.name || request.email || "顧客")}</span>
        ${btn}
      </div>`;
    })
    .join("");

  listEl.querySelectorAll("[data-apply-slot]").forEach((btn) => {
    btn.addEventListener("click", async (event) => {
      event.preventDefault();
      event.stopPropagation();
      const speakerIndex = Number(btn.getAttribute("data-apply-slot"));
      if (blockedByRelation) {
        setMessage("workMessage", "この顧客とはブロック関係のため応募できません。", "err");
        return;
      }
      const profile = resolveVoiceProfileByTalentId(talentId);
      const displayName = profile?.displayName || session?.name || talentId;
      if (!Tx) return;
      const caseId = request.requestId || request.rowId;
      if (!caseId) {
        setMessage("workMessage", "対象案件がありません。", "err");
        return;
      }
      let applyError = "";
      let result;
      try {
        result = await updateWorkflowForRequest(caseId, (innerWf) => {
          const applied = Tx.applyTalentApplication(
            innerWf.castAcceptance || [],
            speakerIndex,
            talentId,
            displayName
          );
          if (!applied.ok) {
            applyError = applied.error || "応募に失敗しました。";
            return innerWf;
          }
          innerWf.castAcceptance = applied.slots;
          return maybeAdvanceTransactionPhase(innerWf, request);
        });
      } catch (err) {
        console.warn("[wavrick] applyTalentApplication failed", err);
        setMessage("workMessage", err instanceof Error ? err.message : "応募に失敗しました。", "err");
        return;
      }
      if (!result?.ok) {
        setMessage("workMessage", result?.error || "応募に失敗しました。", "err");
        return;
      }
      if (applyError) {
        setMessage("workMessage", applyError, "err");
        return;
      }
      if (result.remoteOk === false) {
        setMessage(
          "workMessage",
          "応募の保存に失敗しました。通信状況を確認して再度お試しください。",
          "err"
        );
        return;
      }
      const requestId = result.request?.requestId || caseId;
      pushCaseNotification(t("work.notify_speaker_applied", { speaker: speakerIndex }), requestId, {
        to: "customer",
        kind: "customer",
        category: "case",
        request
      });
      setMessage("workMessage", `話者${speakerIndex} に応募しました。`, "ok");
      renderWorkDetails(result.request || request, session);
    });
  });
}

function renderWorkVoiceOfferCard(request, session, wf) {
  const card = document.getElementById("workVoiceOfferCard");
  const hint = document.getElementById("workVoiceOfferHint");
  const acceptBtn = document.getElementById("workVoiceAcceptBtn");
  const declineBtn = document.getElementById("workVoiceDeclineBtn");
  const Tx = getTransactionApi();
  // 受諾／辞退 UI は声優のみ（顧客・運営には出さない）
  if (!card || session?.role !== "voice") {
    card?.classList.add("hidden");
    return;
  }
  if (isWorkflowCancelled(wf)) {
    card.classList.add("hidden");
    return;
  }

  const talentId = resolveVoiceTalentIdForSession(session);
  const phase = wf.transactionPhase || "draft";
  const awaiting =
    phase === Tx?.TRANSACTION_PHASE.casting ||
    phase === Tx?.TRANSACTION_PHASE.awaiting_acceptance ||
    phase === Tx?.TRANSACTION_PHASE.paid_provisional ||
    phase === Tx?.TRANSACTION_PHASE.quoted ||
    phase === Tx?.TRANSACTION_PHASE.in_production;
  const slots = wf.castAcceptance || [];
  const pendingStatus = Tx?.SLOT_STATUS?.pending_acceptance || "pending_acceptance";
  const selectedApp = Tx?.APP_STATUS?.selected || "selected";
  // 同一案件で既に別枠を受諾済みでも、新規選定された枠の受諾UIは出す
  const pendingSlots = slots.filter((s) => {
    if (!s || String(s.status || "") !== String(pendingStatus)) return false;
    if (talentIdsEqual(s.talentId, talentId)) return true;
    return (s.applications || []).some(
      (a) =>
        talentIdsEqual(a?.talentId, talentId) && String(a?.status || "") === String(selectedApp)
    );
  });
  const mySlot =
    pendingSlots[0] ||
    (Tx ? Tx.getVoiceSlotForTalent(slots, talentId) : slots.find((s) => s.talentId === talentId));
  const appliedOnly =
    !mySlot &&
    !pendingSlots.length &&
    Tx &&
    slots.some((s) => Tx.voiceHasAppliedToSlot(s, talentId) && !s.talentId);

  if (pendingSlots.length && awaiting) {
    card.classList.remove("hidden");
    const indexes = pendingSlots
      .map((s) => Number(s.speakerIndex) || 0)
      .filter((n) => n >= 1)
      .sort((a, b) => a - b);
    const speakerLabel =
      indexes.length > 1 ? indexes.join("・") : String(indexes[0] || pendingSlots[0].speakerIndex);
    hint.textContent = t("work.offer_pending_hint", { speaker: speakerLabel });
    acceptBtn?.classList.remove("hidden");
    declineBtn?.classList.remove("hidden");
    if (acceptBtn) acceptBtn.disabled = false;
    if (declineBtn) declineBtn.disabled = false;
    return;
  }

  // 一度回答したら「案件への回答」カード自体を出さない（受諾済み・辞退済み・他声優待ち）
  if (
    mySlot &&
    (mySlot.status === Tx?.SLOT_STATUS.accepted ||
      mySlot.status === Tx?.SLOT_STATUS.declined ||
      Tx?.isTransactionOnHoldForVoice(slots, talentId))
  ) {
    card.classList.add("hidden");
    acceptBtn?.classList.add("hidden");
    declineBtn?.classList.add("hidden");
    return;
  }

  if (!awaiting || (!mySlot && !appliedOnly)) {
    card.classList.add("hidden");
    return;
  }

  card.classList.remove("hidden");

  if (appliedOnly) {
    hint.textContent = t("work.offer_applied_wait");
    acceptBtn?.classList.add("hidden");
    declineBtn?.classList.add("hidden");
    return;
  }

  const pending = mySlot.status === Tx?.SLOT_STATUS.pending_acceptance;
  if (!pending) {
    card.classList.add("hidden");
    acceptBtn?.classList.add("hidden");
    declineBtn?.classList.add("hidden");
    return;
  }

  hint.textContent = t("work.offer_pending_hint", { speaker: mySlot.speakerIndex });
  acceptBtn?.classList.remove("hidden");
  declineBtn?.classList.remove("hidden");
  acceptBtn.disabled = false;
  declineBtn.disabled = false;
}

function renderWorkVoiceCancelCard(request, session, wf) {
  const card = document.getElementById("workVoiceCancelCard");
  const btn = document.getElementById("workVoiceCancelTransactionBtn");
  const Tx = getTransactionApi();
  if (!card || session?.role !== "voice") {
    card?.classList.add("hidden");
    if (card) card.hidden = true;
    return;
  }
  if (isWorkflowCancelled(wf)) {
    card.classList.add("hidden");
    card.hidden = true;
    return;
  }
  const talentId = resolveVoiceTalentIdForSession(session);
  // 別声優のキャンセル交渉中でも、自分が回答対象でなければ自己キャンセル可能
  const selfOk = Tx?.canVoiceSelfCancel?.(wf, talentId);
  if (selfOk && selfOk.ok === false) {
    card.classList.add("hidden");
    card.hidden = true;
    return;
  }
  const slots = wf.castAcceptance || [];
  const mySlot = Tx ? Tx.getVoiceSlotForTalent(slots, talentId) : null;
  const accepted = Boolean(mySlot && mySlot.status === Tx?.SLOT_STATUS.accepted);
  card.classList.toggle("hidden", !accepted);
  card.hidden = !accepted;
  if (btn) btn.disabled = !accepted;
}

function bindYtPipelineWizard() {
  bindYtScriptAdlibPreviewOnce();
  bindYtTranscriptUndoResetButtonsOnce();
  const scriptField = document.getElementById("ytScript");
  if (scriptField && scriptField.dataset.quoteBound !== "1") {
    scriptField.dataset.quoteBound = "1";
    scriptField.addEventListener("input", () => updateYtQuotePreview());
  }
  const transcribeBtn = document.getElementById("ytTranscribeButton");
  const assignUndoBtn = document.getElementById("ytAssignUndoBtn");
  const assignApplyBtn = document.getElementById("ytAssignApplyBtn");
  const genBtn = document.getElementById("generateScriptButton");
  const status = document.getElementById("aiStatus");
  const afterBox = document.getElementById("pipelineAfterTranscribe");
  const scriptPreview = document.getElementById("scriptPreview");
  const videoUrlField = document.getElementById("ytVideoUrl");
  const speakerCountEl = document.getElementById("ytSpeakerCount");
  const step1 = document.getElementById("aiStep1");
  if (!transcribeBtn || !genBtn || !videoUrlField) return;

  bindYtSpeakerPickerOnce();
  bindEditorFullscreenOnce();
  bindYtTranscriptDragSelectOnce();
  bindYtTranscriptClickModeOnce();
  bindYtTranscriptEditableOnce();
  bindYtAssignSummaryOnce();
  syncYtAssignModeUi();
  renderYtSpeakerPicker();
  renderYtSpeakerNames();
  updateYtAssignHint();

  if (speakerCountEl) {
    speakerCountEl.addEventListener("change", () => {
      handleYtSpeakerCountChange();
    });
  }
  bindYtSpeakerRemovePanelOnce();
  ytLastSpeakerCount = getYtSpeakerCount();
  loadYtSpeakerColors(ytLastSpeakerCount);

  transcribeBtn.addEventListener("click", async () => {
    const sourceMode = getYtSourceMode();
    const videoUrl = videoUrlField.value.trim();
    const mismatchEl = document.getElementById("ytChannelMismatch");
    const CA = getCustomerAccountApi();
    let pipelineBody = { mode: "transcribe" };

    if (sourceMode === "audio") {
      const fileInput = document.getElementById("ytAudioFile");
      const file = fileInput?.files?.[0];
      if (!file) {
        setMessage("ytMessage", "音声ファイルを選択してください。", "err");
        return;
      }
      setMessage("ytMessage", "音声をアップロードしています…", "ok");
      try {
        const uploaded = await uploadCustomerAudioWithFallback(file);
        pipelineBody = { mode: "transcribe", audioUrl: uploaded.url };
      } catch (err) {
        setMessage("ytMessage", err instanceof Error ? err.message : String(err), "err");
        return;
      }
    } else {
      if (!isYouTubeUrl(videoUrl)) {
        setMessage(
          "ytMessage",
          "YouTube の動画URLとして認識できませんでした。例: https://www.youtube.com/watch?v=…",
          "err"
        );
        return;
      }
      if (isCustomerLoggedIn() && !isYtChannelCheckBypassed()) {
        const channels = getCustomerChannels();
        if (!channels.length) {
          setMessage(
            "ytMessage",
            "YouTube 利用にはチャンネル登録が必要です。マイページから追加してください。",
            "err"
          );
          showPage("account");
          return;
        }
        if (CA) {
          try {
            const meta = await CA.fetchVideoMeta(videoUrl);
            const match = CA.videoUploaderMatchesChannels(meta, channels);
            if (!match.ok) {
              if (mismatchEl) mismatchEl.classList.remove("hidden");
              setMessage(
                "ytMessage",
                "この動画のチャンネルは登録一覧と一致しません。マイページからチャンネルを追加するか、テスト用の「チャンネル不一致ロックを無効化」をオンにしてください。",
                "err"
              );
              return;
            }
            if (mismatchEl) mismatchEl.classList.add("hidden");
          } catch (err) {
            setMessage("ytMessage", err instanceof Error ? err.message : String(err), "err");
            return;
          }
        }
      }
      if (isAdminSession() && mismatchEl) mismatchEl.classList.add("hidden");
      pipelineBody = { mode: "transcribe", videoUrl };
    }

    if (!isLocalWavrickDevHost() && !initSupabaseClient()) {
      setMessage("ytMessage", "Supabase に接続するか、ローカル開発サーバ (8889) で開いてください。", "err");
      return;
    }

    setMessage("ytMessage", "");
    if (status) status.classList.remove("hidden");
    if (afterBox) afterBox.classList.add("hidden");
    if (scriptPreview) scriptPreview.classList.add("hidden");
    resetYtReconcilePreview();
    transcribeBtn.disabled = true;
    const label = transcribeBtn.textContent;
    transcribeBtn.textContent = "文字起こし中...";
    if (step1) {
      step1.textContent =
        sourceMode === "audio"
          ? "音声ファイルを WhisperX で文字起こし中..."
          : "動画から音声を取得し、WhisperX で文字起こし中...";
      step1.classList.add("ai-step-active");
    }

    try {
      let prepData = null;
      if (
        !isLocalWavrickDevHost() &&
        pipelineBody.mode === "transcribe" &&
        pipelineBody.videoUrl &&
        !pipelineBody.audioUrl
      ) {
        transcribeBtn.textContent = "音声を取得中...";
        if (step1) {
          step1.textContent = "YouTube から音声を取得して Storage に保存中...";
        }
        const prep = await invokeMediaPipeline({
          mode: "prepare-audio",
          videoUrl: pipelineBody.videoUrl,
          requestId: pipelineBody.requestId
        });
        if (prep.error && (!prep.data || prep.data.ok === undefined)) {
          setMessage("ytMessage", formatMediaPipelineErrorMessage(prep.error.message) || "音声の取得に失敗しました。", "err");
          return;
        }
        if (!prep.data?.ok || !prep.data.rawAudioUrl) {
          setMessage(
            "ytMessage",
            formatMediaPipelineErrorMessage(prep.data?.error) || "音声の取得に失敗しました。",
            "err"
          );
          return;
        }
        prepData = prep.data;
        pipelineBody = {
          ...pipelineBody,
          audioUrl: prep.data.rawAudioUrl,
          existingJobId: prep.data.jobId
        };
        transcribeBtn.textContent = "文字起こし中...";
        if (step1) {
          step1.textContent = "WhisperX で文字起こし中...";
        }
      }

      const { data, error } = await invokeMediaPipeline(pipelineBody);
      if (error && (!data || data.ok === undefined)) {
        setMessage("ytMessage", formatMediaPipelineErrorMessage(error.message) || "文字起こしに失敗しました。", "err");
        return;
      }
      if (data && data.ok === false && !data.async) {
        setMessage("ytMessage", formatMediaPipelineErrorMessage(data.error) || "文字起こしに失敗しました。", "err");
        return;
      }

      let finalData = data;
      const shouldPollTranscribe =
        data?.jobId &&
        !data?.whisperTranscript &&
        (data?.async === true || data?.status === "running");
      if (shouldPollTranscribe) {
        transcribeBtn.textContent = "文字起こし待機中...";
        if (step1) {
          step1.textContent = "WhisperX で文字起こし中（30秒ごとに進捗確認）...";
        }
        finalData = await pollMediaPipelineTranscribe(data.jobId, (statusData, attempt) => {
          transcribeBtn.textContent = `文字起こし中... (${attempt * 30}秒)`;
          const runpodStatus = statusData?.runpodStatus;
          if (step1) {
            step1.textContent = runpodStatus
              ? `WhisperX 処理中（RunPod: ${runpodStatus}）...`
              : "WhisperX で文字起こし中（30秒ごとに進捗確認）...";
          }
        });
      }

      if (!finalData?.ok || !finalData.whisperTranscript) {
        const detail = [
          finalData?.transcribeBuild != null ? `build=${finalData.transcribeBuild}` : null,
          finalData?.status ? `status=${finalData.status}` : null,
          finalData?.async != null ? `async=${finalData.async}` : null,
          finalData?.error ? String(finalData.error) : null
        ]
          .filter(Boolean)
          .join(" · ");
        setMessage(
          "ytMessage",
          "文字起こし結果がありません。" +
            (detail ? `（${detail}）` : "") +
            " Edge Function media-pipeline の再デプロイと RunPod 設定を確認してください。",
          "err"
        );
        return;
      }

      await ingestWhisperTimingFromTranscribe(finalData);
      ytTranscriptPlain = resolveYtTranscriptPlainFromWhisper(finalData);
      ytTranscriptPlainAtWhisper = ytTranscriptPlain;
      if (finalData.rawAudioUrl || finalData.cleanedAudioUrl || prepData?.rawAudioUrl) {
        const raw = finalData.rawAudioUrl || prepData?.rawAudioUrl;
        const cleaned = finalData.cleanedAudioUrl;
        storeReferenceAudioUrls(raw, cleaned);
        persistReferenceAudioToYoutubeRequest(videoUrlField.value.trim(), raw, cleaned);
      }
      if (afterBox) afterBox.classList.remove("hidden");
      await startYtSpeakerAssignFromTranscript();
      syncYtTranscriptUndoButtons();
      _wavrickSavePipelineState();
      const ms = typeof finalData.durationMs === "number" ? Math.round(finalData.durationMs / 1000) : null;
      const build = finalData.transcribeBuild;
      const gaps = finalData.silenceGapCount;
      const buildHint =
        build >= 8
          ? ` 末尾の [Wavrick-${build}] が見えれば最新パイプラインです。`
          : build != null
            ? `（build=${build} は古いです → ./scripts/restart-local-ai.sh）`
            : "（build 不明・WhisperX 未接続の可能性）";
      setMessage(
        "ytMessage",
        `文字起こしが完了しました${ms != null ? `（約${ms}秒）` : ""}。` +
          (gaps != null ? `・2秒以上の間 ${gaps} 箇所` : "") +
          buildHint +
          " 下の欄で編集し、ドラッグで話者を割り当ててください。",
        "ok"
      );
    } catch (err) {
      setMessage("ytMessage", err instanceof Error ? err.message : String(err), "err");
    } finally {
      if (status) status.classList.add("hidden");
      transcribeBtn.disabled = false;
      transcribeBtn.textContent = label;
      if (step1) step1.classList.remove("ai-step-active");
    }
  });

  if (assignUndoBtn) {
    assignUndoBtn.addEventListener("click", () => {
      const result = undoYtSpeakerAssign();
      setMessage("ytMessage", result.message, result.ok ? "ok" : "err");
    });
  }

  if (assignApplyBtn) {
    assignApplyBtn.addEventListener("click", () => {
      toggleYtAssignClickMode();
    });
  }

  document.getElementById("ytOpenRecordWorkspaceBtn")?.addEventListener("click", () => {
    openRecordWorkspaceFromYtForm();
  });

  genBtn.addEventListener("click", async () => {
    const collected = collectYtScriptGenerationPayload();
    if (!collected.ok) {
      setMessage("ytMessage", collected.message, "err");
      updateYtAssignHint();
      scrollYtPipelineMessageIntoView();
      return;
    }

    setMessage("ytMessage", "");
    genBtn.disabled = true;
    const genLabel = genBtn.textContent;
    genBtn.textContent = "台本下書きを作成中...";

    try {
      const { data, error } = await invokeScriptReconcileBatched(
        {
          mode: "script-reconcile",
          videoUrl: collected.videoUrl || undefined,
          transcribeJobId: ytTranscribeJobId,
          speakerCount: collected.count,
          speakers: collected.speakers,
          whisperDurationSec: ytWhisperDurationSec || 0,
          transcriptPlain: ytTranscriptPlain || "",
          transcriptPlainAtWhisper: ytTranscriptPlainAtWhisper || ""
        },
        collected.assignRanges,
        genBtn
      );
      if (error && (!data || data.ok === undefined)) {
        setMessage("ytMessage", formatMediaPipelineErrorMessage(error.message, { mode: "script-reconcile" }) || "台本下書きの作成に失敗しました。", "err");
        return;
      }
      if (data && data.ok === false) {
        setMessage("ytMessage", formatMediaPipelineErrorMessage(data.error, { mode: "script-reconcile" }) || "台本下書きの作成に失敗しました。", "err");
        return;
      }
      if (!data?.ok) {
        setMessage("ytMessage", "想定外の応答です。media-pipeline の script-reconcile モードを確認してください。", "err");
        return;
      }

      const draftText = formatPipelineScriptForField(data, collected.count, collected.castCheck.slots);
      showYtReconcilePreview(draftText, data.adlibSegments, data.adlibSpans);
      _wavrickSavePipelineState();
      const ms = typeof data.durationMs === "number" ? Math.round(data.durationMs / 1000) : null;
      setMessage(
        "ytMessage",
        `翻訳前の台本下書きを表示しました${ms != null ? `（約${ms}秒）` : ""}。内容を確認して「この内容で翻訳を進める」を押してください。`,
        "ok"
      );
    } catch (err) {
      setMessage("ytMessage", err instanceof Error ? err.message : String(err), "err");
    } finally {
      genBtn.disabled = false;
      genBtn.textContent = genLabel;
    }
  });

  const confirmTranslateBtn = document.getElementById("ytConfirmTranslateButton");
  const reconcileRedoBtn = document.getElementById("ytReconcileRedoButton");
  const reconcileField = document.getElementById("ytReconcileScript");
  if (reconcileField && reconcileField.dataset.scrollBound !== "1") {
    reconcileField.dataset.scrollBound = "1";
    reconcileField.addEventListener("scroll", syncYtReconcileMirrorScroll);
  }

  if (reconcileRedoBtn && reconcileRedoBtn.dataset.bound !== "1") {
    reconcileRedoBtn.dataset.bound = "1";
    reconcileRedoBtn.addEventListener("click", () => {
      resetYtReconcilePreview();
      _wavrickSavePipelineState();
      setMessage("ytMessage", "下書きを閉じました。話者分けを直した場合は、もう一度「台本を下書き」を押してください。", "ok");
    });
  }

  if (confirmTranslateBtn && confirmTranslateBtn.dataset.bound !== "1") {
    confirmTranslateBtn.dataset.bound = "1";
    confirmTranslateBtn.addEventListener("click", async () => {
      if (!ytReconcileReady || !ytReconcileDraftFull) {
        setMessage("ytMessage", "先に台本下書きを作成してください。", "err");
        return;
      }
      const collected = collectYtScriptGenerationPayload();
      if (!collected.ok) {
        setMessage("ytMessage", collected.message, "err");
        scrollYtPipelineMessageIntoView();
        return;
      }

      setMessage("ytMessage", "");
      confirmTranslateBtn.disabled = true;
      const confirmLabel = confirmTranslateBtn.textContent;
      confirmTranslateBtn.textContent = "Grok で翻訳中...";

      try {
        const { data, error } = await invokeMediaPipeline({
          mode: "script",
          videoUrl: collected.videoUrl || undefined,
          transcribeJobId: ytTranscribeJobId,
          speakerCount: collected.count,
          speakers: collected.speakers,
          tone: "",
          scriptLanguage: getYtScriptLanguage(),
          whisperDurationSec: ytWhisperDurationSec || 0,
          transcriptPlain: ytTranscriptPlain || "",
          transcriptPlainAtWhisper: ytTranscriptPlainAtWhisper || "",
          assignRanges: collected.assignRanges
        });
        if (error && (!data || data.ok === undefined)) {
          setMessage("ytMessage", formatMediaPipelineErrorMessage(error.message) || "台本生成に失敗しました。", "err");
          return;
        }
        if (data && data.ok === false) {
          setMessage("ytMessage", formatMediaPipelineErrorMessage(data.error) || "台本生成に失敗しました。", "err");
          return;
        }
        if (!data?.ok) {
          setMessage("ytMessage", "想定外の応答です。media-pipeline の script モードを確認してください。", "err");
          return;
        }

        const fullScript = formatPipelineScriptForField(data, collected.count, collected.castCheck.slots);
        scriptField.value = fullScript;
        await applyTimecodedScriptToYtField();
        ytScriptTimecodedFull = scriptField.value;
        ytScriptsBySpeaker = normalizeScriptsBySpeakerMap(data.scriptsBySpeaker);
        ytAdlibSegments = Array.isArray(data.adlibSegments) ? data.adlibSegments : [];
        if (!shouldShowYtScriptTimecodesInField()) {
          scriptField.value = stripTimecodesFromCastScriptForCustomer(ytScriptTimecodedFull);
        }
        bindYtScriptAdlibPreviewOnce();
        await paintYtScriptMirror(scriptField.value, ytAdlibSegments);
        persistYtRecordContextToLocalStore({
          videoUrl: collected.videoUrl,
          fullScript: ytScriptTimecodedFull || scriptField.value,
          castSlots: collected.castCheck.slots,
          speakerCount: collected.count,
          requestName: "台本生成"
        });
        resetYtReconcilePreview();
        if (scriptPreview) scriptPreview.classList.remove("hidden");
        refreshYtRecordSpeakerButtons();
        updateYtQuotePreview();
        _wavrickSavePipelineState();
        const ms = typeof data.durationMs === "number" ? Math.round(data.durationMs / 1000) : null;
        setMessage(
          "ytMessage",
          `話者別の台本を生成しました${ms != null ? `（約${ms}秒）` : ""}。見積もりを確認してから依頼を送信できます。`,
          "ok"
        );
      } catch (err) {
        setMessage("ytMessage", err instanceof Error ? err.message : String(err), "err");
      } finally {
        confirmTranslateBtn.disabled = false;
        confirmTranslateBtn.textContent = confirmLabel;
      }
    });
  }
}

function bindMediaPipelineUi() {
  bindYtPipelineWizard();
}


function bindYtForm() {
  const form = document.getElementById("ytForm");
  if (!form) return;
  const submitButton = document.getElementById("ytSubmitButton");
  const verifyBadge = document.getElementById("verifyBadge");
  const verifyEmailBtn = document.getElementById("verifyEmailBtn");
  const verifyChannelBtn = document.getElementById("verifyChannelBtn");

  const verifyState = {
    email: false,
    channel: false,
    verifiedChannelKey: "",
    verifiedChannelId: ""
  };

  function refreshVerificationUi() {
    const verified = isCustomerLoggedIn() || (verifyState.email && verifyState.channel);
    if (submitButton) {
      submitButton.disabled = !verified;
      submitButton.textContent = verified ? "キャスティングを開始して依頼する" : "本人確認後に依頼を送信";
    }
    if (verifyBadge) {
      verifyBadge.textContent = verified ? "完了" : "未完了";
      verifyBadge.classList.toggle("done", verified);
    }
    refreshYtProvisionalPayButton();
  }

  function markStepDone(key, button, label) {
    verifyState[key] = true;
    if (button) {
      button.classList.add("done");
      button.textContent = label + "（完了）";
      button.disabled = true;
    }
    refreshVerificationUi();
  }

  ytEmailVerificationBridge = {
    getFormEmail: () => {
      const session = getCurrentSession();
      if (session?.role === "customer" && session.email) return session.email;
      const el = document.getElementById("ytEmail");
      return el ? el.value.trim() : "";
    },
    markEmailDone: () => {
      if (verifyEmailBtn) markStepDone("email", verifyEmailBtn, "1) メール認証");
    }
  };

  if (verifyEmailBtn && isEmailVerifiedForForm(ytEmailVerificationBridge.getFormEmail())) {
    markStepDone("email", verifyEmailBtn, "1) メール認証");
  }

  if (verifyEmailBtn) {
    verifyEmailBtn.addEventListener("click", async () => {
      const email = ytEmailVerificationBridge.getFormEmail();
      if (!email.includes("@")) {
        setMessage("ytMessage", "先にメールアドレスを入力してください。", "err");
        return;
      }
      if (!isSupabaseEnabled() && !initSupabaseClient()) {
        markStepDone("email", verifyEmailBtn, "1) メール認証を完了");
        setMessage(
          "ytMessage",
          "Supabase に接続できないため、メール認証を完了できません。接続設定を確認してください。",
          "ok"
        );
        return;
      }
      bindSupabaseAuthForYtEmail();
      verifyEmailBtn.disabled = true;
      const prevLabel = verifyEmailBtn.textContent;
      verifyEmailBtn.textContent = wavrickI18n("yt_email_verify_sending");
      const result = await sendYtEmailVerificationLink(email);
      verifyEmailBtn.disabled = false;
      if (!result.ok) {
        verifyEmailBtn.textContent = prevLabel;
        if (result.reason === "blocked_signup") {
          setMessage("ytMessage", result.message || wavrickI18n("yt_email_verify_fail"), "err");
          return;
        }
        const detail = result.error?.message ? ` (${result.error.message})` : "";
        setMessage("ytMessage", `${wavrickI18n("yt_email_verify_fail")}${detail}`, "err");
        return;
      }
      verifyEmailBtn.textContent = wavrickI18n("yt_email_verify_sent_btn");
      setMessage("ytMessage", wavrickI18n("yt_email_verify_sent"), "ok");
    });
  }

  if (verifyChannelBtn) {
    verifyChannelBtn.addEventListener("click", () => {
      const channelField = document.getElementById("ytChannelUrl");
      const key = normalizeYoutubeChannelKey(channelField ? channelField.value : "");
      if (!key) {
        setMessage("ytMessage", "先にチャンネルURLを正しい形式で入力してください。", "err");
        return;
      }
      const idle = wavrickI18n("yt_channel_btn");
      const started = startYoutubeOAuthPopup({
        channelKey: key,
        linkAll: false,
        btn: verifyChannelBtn,
        idleLabel: idle,
        onResult: (d) => {
          verifyChannelBtn.disabled = false;
          verifyChannelBtn.textContent = idle;
          if (d.ok) {
            verifyState.verifiedChannelKey = key;
            verifyState.verifiedChannelId = d.channelId || "";
            markStepDone("channel", verifyChannelBtn, wavrickI18n("yt_channel_done"));
            let okMsg = wavrickI18n("yt_oauth_success");
            if (verifyState.verifiedChannelId) {
              okMsg +=
                wavrickI18n("yt_oauth_channel_id_prefix") +
                verifyState.verifiedChannelId +
                wavrickI18n("yt_oauth_channel_id_suffix");
            }
            setMessage("ytMessage", okMsg, "ok");
          } else {
            const extra = d.detail ? ` (${d.detail})` : "";
            const errText = d.code ? youtubeOAuthMessageFromCode(d.code) : wavrickI18n("yt_oauth_fail");
            setMessage("ytMessage", errText + extra, "err");
          }
        }
      });
      if (!started.ok) {
        verifyChannelBtn.disabled = false;
        verifyChannelBtn.textContent = idle;
        setMessage("ytMessage", started.message, "err");
      }
    });
  }

  refreshVerificationUi();

  const provisionalPayBtn = document.getElementById("ytProvisionalPayBtn");
  if (provisionalPayBtn) {
    provisionalPayBtn.addEventListener("click", () => {
      setMessage(
        "ytMessage",
        "決済は案件管理で全員の受諾が完了してから行います。まず「キャスティングを開始して依頼する」を送信してください。",
        "err"
      );
    });
  }

  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    setMessage("ytMessage", "");
    if (globalThis.WavrickAccountRestriction?.isSessionSuspended?.(getCurrentSession())) {
      setMessage("ytMessage", t("account.restriction_block_new_work"), "err");
      return;
    }
    initSupabaseClient();
    const collected = collectYtRequestDataFromForm(form);
    if (!collected.ok) {
      setMessage("ytMessage", collected.message, "err");
      return;
    }
    const data = collected.data;
    if (ytFormNeedsValidVideoUrl() && !isYouTubeUrl(data.videoUrl)) {
      setMessage("ytMessage", "翻訳したい YouTube 動画 URL の形式を確認してください。", "err");
      return;
    }

    const speakerCount = getYtSpeakerCount();
    const castCheck = validateYtCastSlots(speakerCount);
    if (!castCheck.ok) {
      setMessage("ytMessage", castCheck.message, "err");
      return;
    }
    data.sourceMode = getYtSourceMode();
    data.speakerCount = speakerCount;
    data.scriptLanguage = getYtScriptLanguage();
    data.castMode = "multi";
    data.castSlots = castCheck.slots;
    data.selectedTalentId = castCheck.slots
      .filter((s) => s.mode === "pick" && s.talentId)
      .map((s) => s.talentId)
      .join(",");
    data.selectedTalentName = castCheck.slots
      .map((s) =>
        `話者${s.speakerIndex}: ${s.mode === "pick" ? s.displayName || s.talentId || "未選択" : "募集"}`
      )
      .join(" / ");
    data.requestId = generateRequestId();
    data.status = REQUEST_STATUS_FLOW[0];

    const signupResult = { ok: true, skipped: true };

    const { password: _customerPassword, ...ytDataForSave } = data;
    ytDataForSave.identityProofText = isAdminSession()
      ? "運営ログイン（チャンネル確認スキップ）"
      : "顧客ログイン済み";
    const quote = buildQuoteForCastAndScript(castCheck.slots, ytDataForSave.script || "");
    if (quote) {
      ytDataForSave.quoteBreakdown = quote;
      ytDataForSave.billableSeconds = quote.totalBillableSeconds;
      ytDataForSave.quoteAmountUsd = quote.totalUsd;
    }
    const Tx = getTransactionApi();
    const castAcceptance = Tx ? Tx.initCastAcceptanceFromSlots(castCheck.slots) : [];
    syncRequestTalentIdsFromCastAcceptance(ytDataForSave, castAcceptance);
    // 顧客表示用にタイムコードを隠していても、保存はタイムコード付き全文を使う
    const timecodedScript =
      String(ytScriptTimecodedFull || "").trim() ||
      String(ytDataForSave.script || "").trim();
    if (timecodedScript) ytDataForSave.script = timecodedScript;
    let scriptsMap = normalizeScriptsBySpeakerMap(ytScriptsBySpeaker);
    if (!scriptsBySpeakerHasTimecodes(scriptsMap) && timecodedScript) {
      scriptsMap = {
        ...rebuildScriptsBySpeakerFromCastScript(
          timecodedScript,
          speakerCount,
          castCheck.slots
        ),
        ...scriptsMap
      };
    }
    ytDataForSave.scriptsBySpeaker = normalizeScriptsBySpeakerMap(scriptsMap);
    ytDataForSave.transcriptPlain = ytTranscriptPlain || "";
    ytDataForSave.whisperSegments = Array.isArray(ytWhisperSegments) ? ytWhisperSegments.slice(0, 2500) : null;
    ytDataForSave.whisperDurationSec = ytWhisperDurationSec || 0;
    attachReferenceAudioFields(ytDataForSave);
    const confirmedDeliverables = buildConfirmedDeliverablesSnapshot(ytDataForSave);
    ytDataForSave.confirmedDeliverables = confirmedDeliverables;
    ytDataForSave.updatedAt = new Date().toISOString();
    ytDataForSave.createdAt = ytDataForSave.createdAt || ytDataForSave.updatedAt;
    const workflows = getWorkflows();
    const wfBase = {
      requestId: ytDataForSave.requestId,
      status: ytDataForSave.status,
      messages: [],
      quoteAmount: quote ? String(quote.totalUsd) : "",
      quoteAmountUsd: quote?.totalUsd ?? null,
      quoteBreakdown: quote,
      billableSeconds: quote?.totalBillableSeconds ?? 0,
      paymentStatus: "unpaid",
      stripeUrl: "",
      deliveries: [],
      revisionCount: 0,
      freeRetakesUsed: 0,
      retakePaymentStatus: "none",
      retakeFeeUsd: 0,
      transactionPhase: Tx ? Tx.TRANSACTION_PHASE.casting : "casting",
      castAcceptance,
      confirmedDeliverables,
      omakaseCriteria: {},
      provisionalPaidAt: null,
      stripePaymentIntentId: "",
      updatedAt: new Date().toISOString()
    };
    workflows[ytDataForSave.requestId] = maybeAdvanceTransactionPhase(wfBase, ytDataForSave);
    saveWorkflows(workflows, ytDataForSave.requestId);
    pushCaseNotification(t("work.notify_project_created", { name: ytDataForSave.name }), ytDataForSave.requestId, {
      to: "customer",
      kind: "system",
      category: "case",
      request: ytDataForSave,
      excludeSelf: false,
      emailTemplate: "project_created",
      emailVars: { name: String(ytDataForSave.name || "") }
    });
    window.WavrickAnalytics?.trackFeature?.("request_submitted", {
      requestId: ytDataForSave.requestId,
      castMode: ytDataForSave.castMode || ""
    });
    notifyNamedTalentCastOffer(ytDataForSave.requestId, castAcceptance);
    upsertLocalByEmail("wavrick_customer_accounts", {
      role: "customer",
      email: ytDataForSave.email,
      name: ytDataForSave.name,
      channelUrl: ytDataForSave.channelUrl
    });
    const requestResult = await persistYoutubeRequestToCloud(ytDataForSave);
    await ensureCustomerAccountRecord({
      email: ytDataForSave.email,
      name: ytDataForSave.name,
      channelUrl: ytDataForSave.channelUrl
    });
    form.reset();
    resetYtSpeakerAssign();
    _wavrickClearYtWorkInProgress();
    const draftEmail = _wavrickDraftStorageEmail();
    const D = getYtDraftsApi();
    if (D && draftEmail) {
      const activeDraftId = D.getActiveDraftId(draftEmail);
      if (activeDraftId) void deleteYtDraft(activeDraftId);
    }
    refreshVerificationUi();
    tryApplyYtEmailVerificationFromSession();
    const sp = document.getElementById("scriptPreview");
    if (sp) sp.classList.add("hidden");
    if (requestResult.ok && signupResult.ok && isSupabaseEnabled()) {
      setMessage("ytMessage", "キャスティングを開始しました。案件管理で募集・選定の進捗を確認できます。", "ok");
    } else if (requestResult.ok) {
      setMessage("ytMessage", "キャスティングを開始しました（Supabase + ローカル保存）。", "ok");
    } else if (isSupabaseEnabled() && !requestResult.skipped) {
      const detail = requestResult.error?.message || requestResult.error?.hint || "";
      setMessage(
        "ytMessage",
        detail
          ? `ローカル保存は成功しましたが、Supabase保存に失敗しました: ${detail}`
          : "ローカル保存は成功しましたが、Supabase保存に失敗しました。",
        "err"
      );
    } else if (!isSupabaseEnabled()) {
      setMessage(
        "ytMessage",
        "キャスティングを開始しました（ローカル保存のみ）。Supabaseに繋がっていません。",
        "err"
      );
    } else {
      setMessage("ytMessage", "キャスティングを開始しました（ローカル保存）。", "ok");
    }
    setWorkSelectedRequestId(ytDataForSave.requestId);
    showPage("work");
  });

  const scInit = getYtSpeakerCount();
  saveYtCastSlots(loadYtCastSlots(scInit), scInit);
}

function bindCustomerSignupForm() {
  const form = document.getElementById("customerSignupForm");
  if (!form || form.dataset.bound === "1") return;
  form.dataset.bound = "1";

  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    setMessage("customerSignupMessage", "");
    initSupabaseClient();

    const data = Object.fromEntries(new FormData(form).entries());
    const name = String(data.name || "").trim();
    const email = String(data.email || "").toLowerCase().trim();

    if (!name) {
      setMessage("customerSignupMessage", "表示名を入力してください。", "err");
      return;
    }
    if (!email.includes("@")) {
      setMessage("customerSignupMessage", "メールアドレスの形式を確認してください。", "err");
      return;
    }
    if (!isSupabaseEnabled()) {
      setMessage(
        "customerSignupMessage",
        "メール認証には Supabase 接続が必要です。しばらくしてから再度お試しください。",
        "err"
      );
      return;
    }

    const submitBtn = form.querySelector('button[type="submit"]');
    if (submitBtn) submitBtn.disabled = true;

    const result = await sendCustomerSignupEmail(email, name);
    if (submitBtn) submitBtn.disabled = false;

    if (!result.ok) {
      if (result.reason === "already_exists" || result.reason === "blocked_cross_role") {
        setMessage(
          "customerSignupMessage",
          result.message ||
            t("account.signup.already_customer") ||
            "このメールは既に登録されています。ログイン画面からログインリンクを送ってください。",
          "err"
        );
        return;
      }
      const detail = result.error?.message ? ` (${result.error.message})` : "";
      setMessage("customerSignupMessage", `確認メールの送信に失敗しました。${detail}`, "err");
      return;
    }

    setMessage(
      "customerSignupMessage",
      "確認メールを送信しました。Wavrick から届いたメールのリンクを開くと登録が完了します。",
      "ok"
    );
  });
}

function getVoiceNotifiedRequestIds(session) {
  const email = (session?.email || "").toLowerCase().trim();
  if (!email) return new Set();
  let rows = [];
  try {
    rows = JSON.parse(localStorage.getItem("wavrick_notifications") || "[]");
  } catch {
    rows = [];
  }
  const ids = new Set();
  for (const n of Array.isArray(rows) ? rows : []) {
    const rid = String(n?.requestId || "").trim();
    if (!rid) continue;
    const targets = Array.isArray(n.targetEmails)
      ? n.targetEmails.map((e) => String(e || "").toLowerCase().trim())
      : [];
    const targetRole = String(n.targetRole || n.kind || "").toLowerCase().trim();
    // 案件管理の声優側表示: 声優向け通知のみ（全 case 通知や顧客 owner 一致では広げない）
    const forVoice =
      targetRole === "voice" ||
      (targets.includes(email) && targetRole !== "customer" && targetRole !== "admin");
    if (forVoice) ids.add(rid);
  }
  return ids;
}

function requestOwnedByCustomerEmail(request, email) {
  const normalized = String(email || "")
    .toLowerCase()
    .trim();
  if (!normalized || !request) return false;
  const owner = String(request.email || "")
    .toLowerCase()
    .trim();
  // 空メールの案件は誰の所有でもない（誤って全員に出さない）
  if (!owner) return false;
  return owner === normalized;
}

/** 声優の案件管理: 話者枠に自分のアカウントがある案件のみ（応募のみ・通知のみは除外） */
function requestVisibleToVoiceForWork(request, session) {
  if (!request || !session) return false;
  const talentId = resolveVoiceTalentIdForSession(
    session.role === "voice" ? session : { ...session, role: "voice" }
  );
  return Boolean(talentId && requestHasSpeakerAccountForVoice(request, talentId));
}

/** 声優へ依頼済み・まだ受ける/受けないが未確定の枠か */
function voiceHasPendingInviteOnRequest(request, talentId) {
  if (!request || !talentId) return false;
  const Tx = getTransactionApi();
  const pending = Tx?.SLOT_STATUS?.pending_acceptance || "pending_acceptance";
  const wf = getWorkflowForRequest(request.requestId, request.status, request);
  const slots = getWorkflowCastSlots(request, wf);
  if (
    slots.some(
      (s) =>
        talentIdsEqual(s?.talentId, talentId) && String(s?.status || "") === String(pending)
    )
  ) {
    return true;
  }
  // talentId 未同期の選定済み応募も回答待ちとして扱う
  const selected = Tx?.APP_STATUS?.selected || "selected";
  return slots.some(
    (s) =>
      String(s?.status || "") === String(pending) &&
      (s.applications || []).some(
        (a) =>
          talentIdsEqual(a?.talentId, talentId) && String(a?.status || "") === String(selected)
      )
  );
}

function getVoiceSlotForWorkCard(request, talentId) {
  if (!request || !talentId) return null;
  const Tx = getTransactionApi();
  const wf = getWorkflowForRequest(request.requestId, request.status, request);
  const slots = getWorkflowCastSlots(request, wf);
  if (Tx?.getVoiceSlotForTalent) {
    const found = Tx.getVoiceSlotForTalent(slots, talentId);
    if (found) return found;
  }
  return slots.find((s) => talentIdsEqual(s?.talentId, talentId)) || null;
}

/** 回答待ちの依頼を先頭に（進行中と混同しないよう一覧で目立たせる） */
function sortVisibleWorkRowsForSession(rows, session) {
  if (!Array.isArray(rows) || !rows.length) return rows || [];
  if (!sessionHasRole(session, "voice")) return rows;
  const talentId = resolveVoiceTalentIdForSession(
    session.role === "voice" ? session : { ...session, role: "voice" }
  );
  if (!talentId) return rows;
  return [...rows].sort((a, b) => {
    const pa = voiceHasPendingInviteOnRequest(a, talentId) ? 0 : 1;
    const pb = voiceHasPendingInviteOnRequest(b, talentId) ? 0 : 1;
    if (pa !== pb) return pa - pb;
    return requestRowTimestamp(b) - requestRowTimestamp(a);
  });
}

/** 案件管理でその案件を一覧・詳細に出してよいか */
function sessionCanAccessWorkRequest(session, request) {
  if (!session || !request) return false;
  const roles = getSessionRoles(session);
  if (roles.includes("admin") || session.role === "admin") return true;
  const email = String(session.email || "")
    .toLowerCase()
    .trim();
  const asCustomer = roles.includes("customer");
  const asVoice = roles.includes("voice");
  if (asCustomer && requestOwnedByCustomerEmail(request, email)) return true;
  if (asVoice && requestVisibleToVoiceForWork(request, session)) return true;
  return false;
}

async function ensureSessionRolesHydrated() {
  const session = getCurrentSession();
  if (!session?.email) return session;
  const existing = normalizeSessionRoles(session.roles, session.role);
  // すでに複数ロール、または admin のみなら追加取得不要
  if (existing.includes("admin") || existing.length > 1) {
    if (!Array.isArray(session.roles) || session.roles.join(",") !== existing.join(",")) {
      session.roles = existing;
      localStorage.setItem("wavrick_session", JSON.stringify(session));
    }
    return session;
  }
  try {
    const info = await resolveLoginRoleFromEmail(session.email);
    const roles = normalizeSessionRoles(info?.roles || existing, session.role);
    if (!roles.length) return session;
    session.roles = roles;
    if (roles.includes("voice") && !session.talentId) {
      session.talentId =
        resolveVoiceTalentIdForSession({ ...session, role: "voice", roles }) ||
        `voice:${String(session.email).toLowerCase().trim()}`;
    }
    localStorage.setItem("wavrick_session", JSON.stringify(session));
  } catch (err) {
    console.warn("[wavrick] ensureSessionRolesHydrated failed", err);
  }
  return getCurrentSession() || session;
}

async function getVisibleRequestsForCurrentSession(options = {}) {
  let session = getCurrentSession();
  if (!options.skipRoleHydrate) {
    session = (await ensureSessionRolesHydrated()) || session;
  }
  const rows = await getMergedYoutubeRequests(options);
  if (!session) return [];

  const roles = getSessionRoles(session);
  if (roles.includes("admin") || session.role === "admin") return rows;

  const asCustomer = roles.includes("customer");
  const asVoice = roles.includes("voice");
  if (!asCustomer && !asVoice) return [];

  const email = (session.email || "").toLowerCase().trim();
  const seen = new Set();
  const out = [];
  for (const row of rows) {
    const id = String(row?.requestId || row?.rowId || row?.id || "").trim();
    if (!id || seen.has(id)) continue;
    const showCustomer = asCustomer && requestOwnedByCustomerEmail(row, email);
    const showVoice = asVoice && requestVisibleToVoiceForWork(row, session);
    if (!showCustomer && !showVoice) continue;
    seen.add(id);
    out.push(row);
  }
  return sortVisibleWorkRowsForSession(out, session);
}

async function resolveWorkRequestByAnyId(requestId) {
  const id = String(requestId || "").trim();
  if (!id) return null;

  let request = findLocalWorkRequestByAnyId(id);
  if (request) {
    workOpenTrace("hit-local-merge", {
      id,
      requestId: request.requestId,
      rowId: request.rowId,
      needsMedia: requestNeedsMediaEnrichment(request)
    });
    // stub（workflow 由来など）は videoUrl が空のことがある → 必ずクラウドで補完
    if (requestNeedsMediaEnrichment(request) || !String(request.script || "").trim()) {
      try {
        await softAwait(ensureSupabaseAuthForLocalSession(), WORK_OPEN_AUTH_TIMEOUT_MS, "resolve_auth");
      } catch {
        /* ignore */
      }
      request = (await softAwait(enrichRequestRowFromRemote(request), WORK_OPEN_ENRICH_TIMEOUT_MS, "resolve_enrich")) || request;
    }
    return request;
  }

  const jwtOk = isSupabaseEnabled() ? await hasValidSupabaseAuthSession() : false;
  workOpenTrace("miss-local-merge", {
    id,
    jwtOk,
    listingCount: Array.isArray(recruitmentsPageCases) ? recruitmentsPageCases.length : 0
  });

  if (isSupabaseEnabled()) {
    const byId = await fetchRemoteYoutubeRequestByAnyId(id);
    workOpenTrace("fetch-youtube-by-id", {
      id,
      via: byId.via || null,
      error: byId.error && (byId.error.message || byId.error),
      hit: Boolean(byId.row)
    });
    if (byId.row) {
      upsertLocalYoutubeRequest(byId.row);
      return byId.row;
    }

    const wfRemote = await fetchRemoteWorkflowByAnyId(id);
    workOpenTrace("fetch-workflow-by-id", {
      id,
      error: wfRemote.error && (wfRemote.error.message || wfRemote.error),
      hit: Boolean(wfRemote.row),
      phase: wfRemote.row?.transactionPhase || null,
      slots: (wfRemote.row?.castAcceptance || []).length
    });
    if (wfRemote.row) {
      const workflows = getWorkflows();
      workflows[id] = { ...wfRemote.row, requestId: id };
      if (wfRemote.row.requestId && wfRemote.row.requestId !== id) {
        workflows[wfRemote.row.requestId] = wfRemote.row;
      }
      persistWorkflowsLocalStorage(workflows);
      const listing = findRecruitmentListingCase(id);
      const stub = buildRequestStubFromWorkflow(id, wfRemote.row, {
        name: listing?.customerName,
        email: listing?.customerEmail,
        videoUrl: listing?.videoUrl,
        tone: listing?.tone,
        deadline: listing?.deadline,
        script: listing?.script,
        castSlots: listing?.castSlots,
        scriptsBySpeaker: listing?.scriptsBySpeaker
      });
      upsertLocalYoutubeRequest(stub);
      return stub;
    }

    try {
      await softAwait(hydrateRemoteWorkData(), 30000, "resolve_hydrate");
      syncWorkflowAliasesIntoStore();
    } catch (err) {
      workOpenTrace("hydrate-failed", { id, error: err instanceof Error ? err.message : String(err) });
    }
    request = findLocalWorkRequestByAnyId(id);
    if (request) {
      workOpenTrace("hit-after-hydrate", { id, requestId: request.requestId });
      return request;
    }
  }

  workOpenTrace("resolve-failed", {
    id,
    jwtOk,
    listingCount: Array.isArray(recruitmentsPageCases) ? recruitmentsPageCases.length : 0,
    reason: !jwtOk
      ? "no_jwt_and_not_in_local"
      : "not_found_in_youtube_or_workflow_or_listing"
  });
  return null;
}

function buildConfirmedDeliverablesSnapshot(request) {
  const scriptFull = String(request?.script || "").trim();
  const scriptsBySpeaker = normalizeScriptsBySpeakerMap(request?.scriptsBySpeaker);
  const castSlots = getCastSlotsForRequest(request);
  let transcriptPlain = String(request?.transcriptPlain || request?.whisperTranscript || "").trim();
  if (!transcriptPlain && Array.isArray(request?.whisperSegments) && request.whisperSegments.length) {
    transcriptPlain = buildYtSegmentPlain(request.whisperSegments);
  }
  const audio = {
    rawAudioUrl: String(request?.rawAudioUrl || "").trim() || null,
    cleanedAudioUrl: String(request?.cleanedAudioUrl || "").trim() || null
  };
  return {
    confirmedAt: new Date().toISOString(),
    transcriptPlain,
    scriptFull,
    scriptsBySpeaker,
    castSlots,
    speakerCount: Number(request?.speakerCount) || castSlots.length || 0,
    videoUrl: String(request?.videoUrl || "").trim(),
    rawAudioUrl: audio.rawAudioUrl,
    cleanedAudioUrl: audio.cleanedAudioUrl
  };
}

function normalizeConfirmedDeliverables(raw) {
  if (!raw || typeof raw !== "object") return null;
  const scriptFull = String(raw.scriptFull || raw.script || "").trim();
  const transcriptPlain = String(raw.transcriptPlain || raw.transcript_plain || "").trim();
  const videoUrl = String(raw.videoUrl || raw.video_url || "").trim();
  const scriptsBySpeaker = normalizeScriptsBySpeakerMap(
    raw.scriptsBySpeaker || raw.scripts_by_speaker
  );
  const rawAudioUrl = raw.rawAudioUrl || raw.raw_audio_url || null;
  const cleanedAudioUrl = raw.cleanedAudioUrl || raw.cleaned_audio_url || null;
  // アフレコ: 台本テキストが空でも動画／話者ブロックがあれば有効
  if (
    !scriptFull &&
    !transcriptPlain &&
    !videoUrl &&
    !rawAudioUrl &&
    !cleanedAudioUrl &&
    !Object.keys(scriptsBySpeaker).length
  ) {
    return null;
  }
  return {
    confirmedAt: raw.confirmedAt || raw.confirmed_at || null,
    transcriptPlain,
    scriptFull,
    scriptsBySpeaker,
    castSlots: Array.isArray(raw.castSlots)
      ? raw.castSlots
      : Array.isArray(raw.cast_slots)
        ? raw.cast_slots
        : [],
    speakerCount: Number(raw.speakerCount || raw.speaker_count) || 0,
    videoUrl,
    rawAudioUrl,
    cleanedAudioUrl
  };
}

function getConfirmedDeliverables(request, wf) {
  const fromWf = normalizeConfirmedDeliverables(wf?.confirmedDeliverables);
  if (fromWf) return fromWf;
  const fromReq = normalizeConfirmedDeliverables(request?.confirmedDeliverables);
  if (fromReq) return fromReq;
  if (
    request?.script ||
    request?.videoUrl ||
    request?.rawAudioUrl ||
    request?.cleanedAudioUrl ||
    request?.whisperSegments?.length ||
    request?.transcriptPlain ||
    Object.keys(normalizeScriptsBySpeakerMap(request?.scriptsBySpeaker)).length
  ) {
    return buildConfirmedDeliverablesSnapshot(request);
  }
  return null;
}

function persistConfirmedDeliverablesOnRequest(requestId, confirmed) {
  if (!requestId || !confirmed) return;
  try {
    const rows = JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]");
    const idx = rows.findIndex((r) => r.requestId === requestId);
    if (idx >= 0) {
      rows[idx].confirmedDeliverables = confirmed;
      rows[idx].updatedAt = new Date().toISOString();
      localStorage.setItem("wavrick_youtube_requests", JSON.stringify(rows));
      void persistYoutubeRequestToCloud(rows[idx]);
    }
  } catch {
    /* ignore */
  }
}

function formatWorkCaseVideoLabel(videoUrl) {
  if (!videoUrl) return "動画未設定";
  try {
    const url = new URL(videoUrl);
    const path = url.pathname.length > 28 ? `${url.pathname.slice(0, 28)}…` : url.pathname;
    return `${url.hostname}${path}`;
  } catch {
    return videoUrl.length > 48 ? `${videoUrl.slice(0, 48)}…` : videoUrl;
  }
}

function formatWorkRequestOptionLabel(request) {
  const wf = getWorkflows()[request.requestId];
  const status = wf?.status || request.status || REQUEST_STATUS_FLOW[0];
  const created = request.createdAt ? formatDateTime(request.createdAt).slice(0, 10) : "";
  const videoShort = formatWorkCaseVideoLabel(request.videoUrl || "");
  const idTail = (request.requestId || "—").slice(-10);
  return `[${status}] ${videoShort} (${idTail}${created ? ` · ${created}` : ""})`;
}

function resolveOpenRecruitSlotsFromCast(castAcceptance) {
  const Tx = getTransactionApi();
  const raw = Array.isArray(castAcceptance) ? castAcceptance : [];
  const slots = Tx ? Tx.normalizeSlots(raw) : raw;
  if (Tx?.getOpenRecruitSlots) {
    return Tx.getOpenRecruitSlots(slots);
  }
  return slots.filter((s) => {
    if (!s || s.mode === "pick" || s.talentId) return false;
    const mode = String(s.mode || "recruit");
    const status = String(s.status || "recruiting");
    return (
      (mode === "recruit" || mode === "omakase") &&
      (status === "recruiting" || status === "needs_reselection")
    );
  });
}

function mapOpenRecruitmentListingRow(row) {
  const Tx = getTransactionApi();
  const rawCast = Array.isArray(row.cast_acceptance)
    ? row.cast_acceptance
    : Array.isArray(row.castAcceptance)
      ? row.castAcceptance
      : [];
  const slots = Tx ? Tx.normalizeSlots(rawCast) : rawCast;
  const openSlots = resolveOpenRecruitSlotsFromCast(slots.length ? slots : rawCast);
  return {
    requestId: row.request_id || row.requestId || "",
    customerName: row.customer_name || row.customerName || row.name || "依頼案件",
    customerEmail: (
      row.customer_email ||
      row.customerEmail ||
      row.email ||
      ""
    )
      .toLowerCase()
      .trim(),
    videoUrl: row.video_url || row.videoUrl || "",
    tone: row.tone || "",
    deadline: row.deadline || "",
    workflowStatus: row.workflow_status || row.workflowStatus || row.status || REQUEST_STATUS_FLOW[0],
    transactionPhase: row.transaction_phase || row.transactionPhase || "casting",
    castAcceptance: slots.length ? slots : rawCast,
    openSlots,
    script: row.script || "",
    quoteBreakdown:
      row.quote_breakdown && typeof row.quote_breakdown === "object"
        ? row.quote_breakdown
        : row.quoteBreakdown && typeof row.quoteBreakdown === "object"
          ? row.quoteBreakdown
          : null,
    castSlots: Array.isArray(row.cast_slots)
      ? row.cast_slots
      : Array.isArray(row.castSlots)
        ? row.castSlots
        : [],
    scriptsBySpeaker: normalizeScriptsBySpeakerMap(
      row.scripts_by_speaker || row.scriptsBySpeaker || {}
    ),
    createdAt: row.request_created_at || row.createdAt || "",
    updatedAt: row.workflow_updated_at || row.updatedAt || ""
  };
}

function enrichRecruitmentCaseFromRequest(item, request) {
  if (!request) return item;
  const castSlots = getCastSlotsForRequest(request);
  return {
    ...item,
    customerEmail: (request.email || item.customerEmail || "").toLowerCase().trim(),
    scriptLanguage: request.scriptLanguage || item.scriptLanguage || "ja",
    script: item.script || request.script || "",
    castSlots: castSlots.length ? castSlots : item.castSlots || [],
    scriptsBySpeaker: normalizeScriptsBySpeakerMap(request.scriptsBySpeaker || item.scriptsBySpeaker)
  };
}

async function enrichRecruitmentCasesWithRequestData(cases) {
  // リロード直後は JWT なしでも一覧を出せるよう、enrich はローカルのみ参照する
  const rows = await getMergedYoutubeRequests({ localOnly: true });
  const byId = new Map(rows.map((row) => [row.requestId, row]));
  return cases.map((item) => enrichRecruitmentCaseFromRequest(item, byId.get(item.requestId)));
}

function getRecruitmentCastSlots(item) {
  if (item.castAcceptance?.length) return item.castAcceptance;
  if (item.castSlots?.length) return item.castSlots;
  return getCastSlotsForRequest({ script: item.script, castSlots: item.castSlots });
}

function getRecruitmentOfferPrefs(item, speakerIndex) {
  const idx = Number(speakerIndex);
  if (!idx) return null;
  const slots = item?.castAcceptance?.length
    ? item.castAcceptance
    : item?.castSlots || [];
  const slot = slots.find((s) => Number(s.speakerIndex) === idx);
  const raw =
    slot?.recruitPrefs ||
    item?.omakaseCriteria?.[String(idx)] ||
    item?.omakaseCriteria?.[idx] ||
    null;
  if (!raw || typeof raw !== "object") return null;
  return normalizeWorkRecruitPrefs(raw);
}

function getRecruitmentSpeakerQuote(item, speakerIndex) {
  const P = getPricingApi();
  const idx = Number(speakerIndex);
  const savedLines = Array.isArray(item?.quoteBreakdown?.lines)
    ? item.quoteBreakdown.lines
    : Array.isArray(item?.quoteBreakdown?.speakers)
      ? item.quoteBreakdown.speakers
      : [];
  const saved = savedLines.find((s) => Number(s.speakerIndex) === idx);
  let line = null;
  if (saved && P) {
    const billableSeconds = Number(saved.billableSeconds) || 0;
    const rawSeconds = Number(saved.rawSec != null ? saved.rawSec : saved.rawSeconds) || 0;
    const subtotalUsd = Number(saved.subtotalUsd);
    if (Number.isFinite(subtotalUsd) && (billableSeconds > 0 || rawSeconds > 0 || subtotalUsd > 0)) {
      line = {
        speakerIndex: idx,
        rawSeconds,
        billableSeconds: billableSeconds || Math.max(1, Math.ceil(rawSeconds)),
        subtotalUsd,
        minimumApplied: Boolean(saved.minimumApplied)
      };
    }
  }
  if (!line) {
    const script = String(item?.script || "").trim();
    if (!P || !script) return null;
    const castSlots = getRecruitmentCastSlots(item);
    const quote = buildQuoteForCastAndScript(castSlots, script);
    if (!quote?.speakers?.length) return null;
    line = quote.speakers.find((s) => Number(s.speakerIndex) === idx) || null;
  }
  if (!line || !P) return line;

  // 顧客が設定した募集単価があればそれで小計を出し直す
  const prefs = getRecruitmentOfferPrefs(item, idx);
  const rate = Number(prefs?.pricePerMinute);
  if (Number.isFinite(rate) && rate > 0 && line.billableSeconds > 0) {
    let subtotalUsd = Math.round((line.billableSeconds / 60) * rate * 100) / 100;
    const minSlot = Number(P.MIN_SLOT_ORDER_USD) || 20;
    let minimumApplied = false;
    if (subtotalUsd < minSlot) {
      subtotalUsd = minSlot;
      minimumApplied = true;
    }
    return {
      ...line,
      pricePerMinute: rate,
      subtotalUsd,
      minimumApplied
    };
  }
  return line;
}

function formatRecruitmentSpeakerMetrics(item, speakerIndex) {
  const P = getPricingApi();
  const line = getRecruitmentSpeakerQuote(item, speakerIndex);
  if (!line || !P) {
    return { durationLabel: "—", subtotalLabel: "—" };
  }
  return {
    durationLabel: P.formatSpeakerQuoteDuration(line.rawSeconds, line.billableSeconds),
    subtotalLabel: P.formatUsd(line.subtotalUsd) + (line.minimumApplied ? " (最低価格)" : "")
  };
}

function buildRecruitmentYoutubeUrlHtml(videoUrl) {
  const url = String(videoUrl || "").trim();
  if (!url) {
    return `<p class="section-desc">${escapeHtml(t("recruitments.youtube_empty"))}</p>`;
  }
  return `<p class="recruitment-youtube-url"><a href="${escapeAttr(url)}" target="_blank" rel="noreferrer">${escapeHtml(url)}</a></p>`;
}

function isRecruitmentSlotClosed(slot) {
  if (!slot) return true;
  if (slot.mode === "pick") return true;
  if (slot.talentId) return true;
  const Tx = getTransactionApi();
  if (!Tx) return false;
  const open = Tx.getOpenRecruitSlots?.([slot]) || [];
  return open.length === 0;
}

function getRecruitmentSlotModeLabel(slot) {
  if (!slot) return "";
  if (slot.mode === "pick") return t("recruitments.slot_mode_pick");
  if (isRecruitmentSlotClosed(slot)) return t("recruitments.slot_mode_closed");
  return t("recruitments.slot_mode_open");
}

function countRecruitmentSlotApplicants(slot) {
  const Tx = getTransactionApi();
  const appliedStatus = Tx?.APP_STATUS?.applied || "applied";
  return (slot.applications || []).filter((a) => a.status === appliedStatus).length;
}

function findRecruitmentListingCase(requestId) {
  const id = String(requestId || "").trim();
  if (!id) return null;
  return recruitmentsPageCases.find((row) => String(row.requestId || "").trim() === id) || null;
}

function resolveRequestForRecruitmentApply(requestId, rows) {
  const id = String(requestId || "").trim();
  if (!id) return null;
  const fromRows = (rows || []).find((row) => {
    const rid = String(row.requestId || "").trim();
    const rowId = String(row.rowId || row.id || "").trim();
    return rid === id || rowId === id;
  });
  if (fromRows) return fromRows;
  const listing = findRecruitmentListingCase(id);
  if (!listing) return null;
  // 募集一覧 RPC には載るが youtube_requests 行を声優が引けない／ID 不一致のとき用
  return {
    requestId: id,
    name: listing.customerName || "依頼案件",
    email: listing.customerEmail || "",
    videoUrl: listing.videoUrl || "",
    tone: listing.tone || "",
    deadline: listing.deadline || "",
    status: listing.workflowStatus || REQUEST_STATUS_FLOW[0],
    script: listing.script || "",
    castSlots: listing.castSlots || [],
    scriptsBySpeaker: listing.scriptsBySpeaker || {},
    createdAt: listing.createdAt || "",
    updatedAt: listing.updatedAt || ""
  };
}

function seedWorkflowFromRecruitmentListing(requestId, current, listing) {
  if (!listing) return current;
  if (!Array.isArray(listing.castAcceptance) || !listing.castAcceptance.length) return current;
  const Tx = getTransactionApi();
  const Sync = globalThis.WavrickWorkflowSync;
  const localSlots = Array.isArray(current?.castAcceptance) ? current.castAcceptance : [];
  let castAcceptance = listing.castAcceptance;
  if (localSlots.length && Sync?.mergeCastAcceptance) {
    // Start from cloud listing (source of open recruit), then fold local progress
    // so stale local cannot hide a still-open recruit frame.
    castAcceptance = Sync.mergeCastAcceptance(localSlots, listing.castAcceptance);
    if (Tx) {
      castAcceptance = castAcceptance.map((slot) => {
        const fromListing = listing.castAcceptance.find(
          (s) => Number(s.speakerIndex) === Number(slot.speakerIndex)
        );
        if (!fromListing) return slot;
        const listingOpen =
          fromListing.mode === "recruit" &&
          (fromListing.status === Tx.SLOT_STATUS.recruiting ||
            fromListing.status === Tx.SLOT_STATUS.needs_reselection) &&
          !fromListing.talentId;
        if (!listingOpen) return slot;
        const localStatus = String(slot.status || "");
        // 顧客選定・受諾・辞退は募集一覧の古いスナップショットで潰さない
        if (
          localStatus === Tx.SLOT_STATUS.pending_acceptance ||
          localStatus === Tx.SLOT_STATUS.accepted ||
          localStatus === Tx.SLOT_STATUS.declined ||
          String(slot.talentId || "").trim()
        ) {
          return slot;
        }
        const apps = [
          ...(Array.isArray(slot.applications) ? slot.applications : []),
          ...(Array.isArray(fromListing.applications) ? fromListing.applications : [])
        ];
        const seen = new Set();
        const applications = apps.filter((a) => {
          const key = String(a?.talentId || "")
            .toLowerCase()
            .trim()
            .replace(/^voice:/, "");
          if (!key || seen.has(key)) return false;
          seen.add(key);
          return true;
        });
        return {
          ...slot,
          mode: "recruit",
          status: fromListing.status,
          talentId: "",
          displayName: "",
          offerSentAt: null,
          applications
        };
      });
    }
  }
  return {
    ...current,
    requestId,
    status: listing.workflowStatus || current.status,
    transactionPhase: listing.transactionPhase || current.transactionPhase || "casting",
    castAcceptance,
    updatedAt: listing.updatedAt || current.updatedAt
  };
}

async function patchRemoteWorkflowCastFields(requestId, wf, aliasKeys = []) {
  if (!isSupabaseEnabled() || !requestId || !wf) return { ok: true, skipped: true };
  initSupabaseClient();
  if (!supabaseClient) return { ok: true, skipped: true };
  const keys = [...new Set([requestId, ...aliasKeys].map((k) => String(k || "").trim()).filter(Boolean))];
  let lastError = null;
  let updated = false;
  for (const key of keys) {
    let remotePhase = "";
    let remotePayment = "";
    let remotePaymentMode = "";
    let remoteProvisionalAt = null;
    const { data: existing } = await supabaseClient
      .from(TABLES.requestWorkflows)
      .select("transaction_phase,paymentstatus,payment_mode,provisional_payment_at")
      .eq("requestid", key)
      .maybeSingle();
    if (existing) {
      remotePhase = String(existing.transaction_phase || "");
      remotePayment = String(existing.paymentstatus || "");
      remotePaymentMode = String(existing.payment_mode || "");
      remoteProvisionalAt = existing.provisional_payment_at || null;
    }

    const localPhase = wf.transactionPhase || "casting";
    const resolvedPhase =
      workflowPhaseRank(remotePhase) > workflowPhaseRank(localPhase) ? remotePhase : localPhase;

    const patchPayload = {
      cast_acceptance: wf.castAcceptance || [],
      transaction_phase: resolvedPhase,
      status: wf.status || REQUEST_STATUS_FLOW[0],
      updated_at: wf.updatedAt || new Date().toISOString()
    };

    // キャンセル交渉も必ず載せる（cast だけ patch して cancel が落ちる事故を防ぐ）
    if (wf.cancelNegotiation && typeof wf.cancelNegotiation === "object") {
      patchPayload.cancel_negotiation = wf.cancelNegotiation;
    }

    const remotePaid = remotePayment === "paid" || remotePayment === "paid_provisional";
    const localPaid = isWorkflowPaymentCleared(wf);
    if (remotePaid) {
      patchPayload.paymentstatus = remotePayment;
      if (remotePaymentMode) patchPayload.payment_mode = remotePaymentMode;
      if (remoteProvisionalAt) patchPayload.provisional_payment_at = remoteProvisionalAt;
    } else if (localPaid && wf.paymentStatus) {
      patchPayload.paymentstatus = wf.paymentStatus;
      if (wf.paymentMode) patchPayload.payment_mode = wf.paymentMode;
      if (wf.provisionalPaymentAt) patchPayload.provisional_payment_at = wf.provisionalPaymentAt;
    }

    const { data, error } = await supabaseClient
      .from(TABLES.requestWorkflows)
      .update(patchPayload)
      .eq("requestid", key)
      .select("requestid,cancel_negotiation");
    if (error) {
      lastError = error;
      continue;
    }
    if (Array.isArray(data) && data.length) updated = true;
  }
  if (updated) {
    void signalWorkdataChangedSafe({ requestId });
    return { ok: true };
  }
  return { ok: false, error: lastError || { message: "workflow_update_empty" } };
}

async function updateWorkflowForRequest(requestId, mutator) {
  // Prefer local + listing for cast/apply. Full remote request list is slow and
  // can leave the UI looking frozen after tapping 応募.
  let rows = await getMergedYoutubeRequests({ localOnly: true });
  const listing = findRecruitmentListingCase(requestId);
  let request = resolveRequestForRecruitmentApply(requestId, rows);
  if (!request) {
    rows = await getMergedYoutubeRequests();
    request = resolveRequestForRecruitmentApply(requestId, rows);
  }
  if (!request) return { ok: false, error: "案件が見つかりません。" };
  let current = getWorkflowForRequest(requestId, request.status, request);
  current = seedWorkflowFromRecruitmentListing(requestId, current, listing);
  const priorSnapshot = {
    cancelNegotiation: current?.cancelNegotiation
      ? { ...current.cancelNegotiation }
      : null
  };
  const next = maybeAdvanceTransactionPhase(mutator({ ...current }), request);
  next.requestId = request.requestId || requestId;
  next.updatedAt = new Date().toISOString();
  const cancelStatus = String(next?.cancelNegotiation?.status || "");
  const cancelChanged =
    JSON.stringify(priorSnapshot.cancelNegotiation || null) !==
    JSON.stringify(next.cancelNegotiation || null);
  // キャンセル交渉がこの更新で変わったときだけ強制書込（別操作で古い pending を再送しない）
  const forceCancelFields =
    cancelChanged &&
    (cancelStatus === "pending_talent" ||
      cancelStatus === "disputed" ||
      cancelStatus === "resolved");
  // ローカルは requestId / rowId 両方に保存（顧客案件管理で応募者を見えるようにする）
  saveWorkflowAliases(request, next, { syncRemote: false });

  let remote = { ok: true, skipped: true };
  if (isSupabaseEnabled()) {
    initSupabaseClient();
    const Sync = globalThis.WavrickWorkflowSync;
    if (Sync?.persistWorkflow && supabaseClient) {
      remote = await Sync.persistWorkflow(next, request, {
        client: supabaseClient,
        touchUpdatedAt: true,
        forceCancelFields
      });
    } else {
      const aliasKeys = listRequestWorkflowAliasKeys(request);
      remote = await patchRemoteWorkflowCastFields(requestId, next, aliasKeys);
    }
    if (!remote?.ok && !remote?.skipped) {
      console.warn("[wavrick] updateWorkflowForRequest remote failed", remote.error);
      // クラウド失敗時はローカルのキャンセル交渉を巻き戻し（顧客だけ「申告済み」に見えないように）
      if (forceCancelFields) {
        const rolled = {
          ...next,
          cancelNegotiation: priorSnapshot.cancelNegotiation
        };
        saveWorkflowAliases(request, rolled, { syncRemote: false });
      }
      return {
        ok: false,
        error:
          typeof remote.error === "string"
            ? remote.error
            : remote.error?.message || "クラウドへの選定・応募同期に失敗しました。再試行してください。",
        request,
        workflow: next,
        remoteOk: false
      };
    }
    if (remote?.workflow) {
      // Keep payment etc. from healed remote while preserving just-written cast / cancel
      const cast = next.castAcceptance;
      const cancelNeg = next.cancelNegotiation;
      Object.assign(next, remote.workflow);
      if (Array.isArray(cast)) {
        next.castAcceptance =
          Sync?.mergeCastAcceptance?.(remote.workflow.castAcceptance, cast) || cast;
      }
      if (cancelNeg && typeof cancelNeg === "object") {
        const remoteCn = remote.workflow?.cancelNegotiation;
        const localReq = Date.parse(cancelNeg.requestedAt || 0) || 0;
        const remoteReq = Date.parse(remoteCn?.requestedAt || 0) || 0;
        // いま書いた新しいキャンセル交渉を、古い resolved マージで消さない
        if (
          forceCancelFields &&
          localReq &&
          (!remoteReq || localReq >= remoteReq) &&
          (String(cancelNeg.status || "") === "pending_talent" ||
            String(cancelNeg.status || "") === "disputed" ||
            String(cancelNeg.status || "") === "resolved")
        ) {
          next.cancelNegotiation = { ...cancelNeg };
        } else {
          next.cancelNegotiation =
            typeof Sync?.mergeCancelNegotiation === "function"
              ? Sync.mergeCancelNegotiation(remoteCn, cancelNeg)
              : cancelNeg;
        }
      }
      saveWorkflowAliases(request, next, { syncRemote: false });
    }
    // Sync.persistWorkflow / patchRemoteWorkflowCastFields が signal 済み。描画だけ。
    // forceDetail で開いている案件詳細も必ず受諾/選定状態を再描画する。
    paintWorkdataUpdated({
      requestId: next.requestId || requestId,
      forceDetail: true
    });
  }

  const caseIdx = recruitmentsPageCases.findIndex((row) => row.requestId === requestId);
  if (caseIdx >= 0) {
    const Tx = getTransactionApi();
    const slots = Tx ? Tx.normalizeSlots(next.castAcceptance || []) : next.castAcceptance || [];
    recruitmentsPageCases[caseIdx] = enrichRecruitmentCaseFromRequest(
      {
        ...recruitmentsPageCases[caseIdx],
        castAcceptance: slots,
        openSlots: Tx ? Tx.getOpenRecruitSlots(slots) : []
      },
      request
    );
  }
  return { ok: true, request, workflow: next, remoteOk: remote.ok !== false };
}

function buildOpenRecruitmentCaseFromRequest(request, wf) {
  const Tx = getTransactionApi();
  const castAcceptance = wf?.castAcceptance?.length ? wf.castAcceptance : getCastSlotsForRequest(request);
  const slots = Tx && castAcceptance?.length ? Tx.normalizeSlots(castAcceptance) : castAcceptance || [];
  const openSlots = Tx ? Tx.getOpenRecruitSlots(slots) : [];
  const base = {
    requestId: request.requestId || "",
    customerName: request.name || "依頼案件",
    customerEmail: (request.email || "").toLowerCase().trim(),
    videoUrl: request.videoUrl || "",
    tone: request.tone || "",
    deadline: request.deadline || "",
    workflowStatus: wf?.status || request.status || REQUEST_STATUS_FLOW[0],
    transactionPhase: wf?.transactionPhase || "casting",
    castAcceptance: slots,
    openSlots,
    script: request.script || "",
    castSlots: getCastSlotsForRequest(request),
    scriptsBySpeaker: normalizeScriptsBySpeakerMap(request.scriptsBySpeaker),
    createdAt: request.createdAt || "",
    updatedAt: wf?.updatedAt || request.createdAt || ""
  };
  return enrichRecruitmentCaseFromRequest(base, request);
}

function isRecruitmentCaseStillOpen(request, wf) {
  const Tx = getTransactionApi();
  if (!Tx) return false;
  const status = wf?.status || request?.status || "";
  if (status === "完了" || status === "キャンセル") return false;
  if (wf?.transactionPhase === Tx.TRANSACTION_PHASE.cancelled) return false;
  const phase = wf?.transactionPhase || Tx.TRANSACTION_PHASE.casting;
  if (![Tx.TRANSACTION_PHASE.draft, Tx.TRANSACTION_PHASE.casting, Tx.TRANSACTION_PHASE.quoted].includes(phase)) {
    return false;
  }
  const castAcceptance = wf?.castAcceptance?.length ? wf.castAcceptance : getCastSlotsForRequest(request);
  if (!castAcceptance?.length) return false;
  const slots = Tx.normalizeSlots(castAcceptance);
  return Tx.hasOpenRecruitment(slots) && Tx.getOpenRecruitSlots(slots).length > 0;
}

function mergeRecruitmentCaseRows(remoteCases, localCases) {
  const map = new Map();
  const touch = (row) => {
    if (!row?.requestId) return;
    const openSlots = resolveOpenRecruitSlotsFromCast(row.castAcceptance || row.openSlots || []);
    if (!openSlots.length) return;
    const normalized = { ...row, openSlots };
    const prev = map.get(normalized.requestId);
    const rowTs = new Date(normalized.updatedAt || normalized.createdAt || 0).getTime();
    const prevTs = prev ? new Date(prev.updatedAt || prev.createdAt || 0).getTime() : -1;
    if (!prev || rowTs >= prevTs) map.set(normalized.requestId, normalized);
  };
  for (const row of remoteCases || []) touch(row);
  for (const row of localCases || []) touch(row);
  return [...map.values()].sort(
    (a, b) => new Date(b.updatedAt || b.createdAt) - new Date(a.updatedAt || a.createdAt)
  );
}

function filterRecruitmentCasesForViewer(cases, session) {
  const viewerEmail = (session?.email || "").toLowerCase().trim();
  let rows = (cases || [])
    .map((item) => {
      const openSlots = resolveOpenRecruitSlotsFromCast(item.castAcceptance || item.openSlots || []);
      const ownerEmail = (item.customerEmail || "").toLowerCase().trim();
      return {
        ...item,
        openSlots,
        // 顧客も自分の公開募集を一覧で確認できるようにする（以前は案件管理のみ）
        isOwnRecruitment: Boolean(viewerEmail && ownerEmail && ownerEmail === viewerEmail)
      };
    })
    .filter((item) => item.openSlots.length > 0);
  if (!session) return rows;
  const B = getTalentBlocksApi();
  if (sessionHasRole(session, "voice") && B) {
    const talentId = resolveVoiceTalentIdForSession(
      session.role === "voice" ? session : { ...session, role: "voice" }
    );
    if (talentId) {
      rows = rows.filter((item) => !B.isBlockedBetween(item.customerEmail || "", talentId));
    }
  }
  return rows;
}

async function getOpenRecruitmentCasesFromLocal() {
  const rows = await getMergedYoutubeRequests({ localOnly: true });
  const Tx = getTransactionApi();
  if (!Tx) return [];
  const cases = [];
  for (const request of rows) {
    const wf = getWorkflowForRequest(request.requestId, request.status);
    if (!isRecruitmentCaseStillOpen(request, wf)) continue;
    const castAcceptance = wf?.castAcceptance?.length ? wf.castAcceptance : getCastSlotsForRequest(request);
    const wfForBuild = {
      ...wf,
      castAcceptance: wf?.castAcceptance?.length ? wf.castAcceptance : Tx.normalizeSlots(castAcceptance)
    };
    const item = buildOpenRecruitmentCaseFromRequest(request, wfForBuild);
    if (!item.openSlots?.length) continue;
    cases.push(item);
  }
  return cases.sort((a, b) => new Date(b.updatedAt || b.createdAt) - new Date(a.updatedAt || a.createdAt));
}

/**
 * 公開募集一覧は SECURITY DEFINER + GRANT TO anon。
 * supabase-js のユーザ JWT が壊れている／未復元だと PostgREST が 401 (PGRST301) を返し、
 * anon で呼べる RPC まで失敗する。必ず anon key だけで叩く。
 */
async function fetchOpenRecruitmentCasesRemote() {
  const cfg = getStoredSupabaseConfig();
  if (!cfg?.supabaseUrl || !cfg?.supabaseAnonKey) {
    return { ok: false, rows: [], reason: "disabled" };
  }
  const endpoint = `${String(cfg.supabaseUrl).replace(/\/+$/, "")}/rest/v1/rpc/get_open_recruitment_listings`;
  try {
    const response = await fetch(endpoint, {
      method: "POST",
      headers: {
        apikey: cfg.supabaseAnonKey,
        Authorization: `Bearer ${cfg.supabaseAnonKey}`,
        "Content-Type": "application/json",
        Prefer: "return=representation"
      },
      body: "{}"
    });
    const payload = await response.json().catch(() => null);
    if (!response.ok) {
      const error = payload && typeof payload === "object" ? payload : { message: `http_${response.status}` };
      console.warn("[wavrick] get_open_recruitment_listings failed", error);
      return { ok: false, rows: [], reason: "error", error, status: response.status };
    }
    if (!Array.isArray(payload)) return { ok: false, rows: [], reason: "invalid_payload" };
    const rows = payload
      .map(mapOpenRecruitmentListingRow)
      .filter((item) => item.requestId && Array.isArray(item.openSlots) && item.openSlots.length > 0);
    return { ok: true, rows };
  } catch (error) {
    console.warn("[wavrick] get_open_recruitment_listings network failed", error);
    return { ok: false, rows: [], reason: "network", error };
  }
}

async function fetchOpenRecruitmentCases() {
  // Listing RPC is SECURITY DEFINER (works without JWT). Do not block on work hydrate.
  void hydrateRemoteWorkData().catch((error) => {
    console.warn("[wavrick] recruitment side-hydrate skipped", error);
  });
  const remoteResult = await fetchOpenRecruitmentCasesRemote();
  const remote = remoteResult?.ok ? remoteResult.rows || [] : [];
  let local = [];
  try {
    local = await getOpenRecruitmentCasesFromLocal();
  } catch (error) {
    console.warn("[wavrick] local recruitment cases failed", error);
  }
  const merged = mergeRecruitmentCaseRows(remote, local);
  const enriched = await enrichRecruitmentCasesWithRequestData(merged);
  const cases = filterRecruitmentCasesForViewer(enriched, getCurrentSession());
  return {
    cases,
    remoteOk: Boolean(remoteResult?.ok),
    remoteReason: remoteResult?.reason || null,
    remoteCount: remote.length
  };
}

function setRecruitmentsMessage(text, status) {
  const applyMessage = (el) => {
    if (!el) return;
    el.textContent = text || "";
    el.classList.remove("ok", "err");
    if (status) el.classList.add(status);
    if (el.id === "recruitmentSpeakerApplyMessage") {
      el.hidden = !text;
    }
  };
  applyMessage(document.getElementById("recruitmentsMessage"));
  applyMessage(document.getElementById("recruitmentSpeakerApplyMessage"));
}
globalThis.setRecruitmentsMessage = setRecruitmentsMessage;

function renderRecruitmentSpeakerRows(item, { clickable = false, requestId = "" } = {}) {
  const Tx = getTransactionApi();
  const slots = item.castAcceptance?.length ? item.castAcceptance : [];
  const openSlots = slots.filter((slot) => !isRecruitmentSlotClosed(slot));
  if (!openSlots.length) {
    return `<p class="section-desc">${escapeHtml(t("recruitments.no_slots"))}</p>`;
  }

  return `<div class="cast-acceptance-list">${openSlots
    .map((slot) => {
      const appCount = countRecruitmentSlotApplicants(slot);
      const metrics = formatRecruitmentSpeakerMetrics(item, slot.speakerIndex);
      const modeLabel = getRecruitmentSlotModeLabel(slot);
      const statusLabel = Tx ? Tx.getCustomerSlotLabel(slot, slots) : modeLabel;
      const rowClass = [
        "cast-acceptance-row",
        "recruitment-slot-row",
        clickable ? "recruitment-slot-row--clickable" : ""
      ]
        .filter(Boolean)
        .join(" ");
      const attrs = clickable
        ? ` data-recruitment-speaker="${escapeAttr(String(slot.speakerIndex))}" data-recruitment-id="${escapeAttr(requestId || item.requestId || "")}" tabindex="0" role="button"`
        : "";
      const applicantLabel =
        appCount > 0
          ? t("recruitments.applicants_count", { count: appCount })
          : t("recruitments.accepting");
      return `<div class="${rowClass}"${attrs} aria-label="${escapeAttr(t("recruitments.speaker_row_aria", { index: slot.speakerIndex }))}">
        <span class="cast-acceptance-speaker">${escapeHtml(t("recruitments.speaker_label", { index: slot.speakerIndex }))}</span>
        <div class="recruitment-slot-main">
          <span class="cast-acceptance-name">${escapeHtml(statusLabel)}</span>
          <span class="recruitment-slot-mode">${escapeHtml(modeLabel)}</span>
        </div>
        <span class="recruitment-slot-metrics">
          <span>${escapeHtml(t("recruitments.speech_short", { duration: metrics.durationLabel }))}</span>
          <span>${escapeHtml(t("recruitments.subtotal_short", { amount: metrics.subtotalLabel }))}</span>
        </span>
        <span class="cast-acceptance-status">${escapeHtml(applicantLabel)}</span>
      </div>`;
    })
    .join("")}</div>`;
}

function bindRecruitmentSpeakerRowClicks(container, onOpenSpeaker) {
  if (!container) return;
  container.querySelectorAll("[data-recruitment-speaker]").forEach((node) => {
    const openSpeaker = () => {
      const rid = node.getAttribute("data-recruitment-id");
      const speakerIndex = Number(node.getAttribute("data-recruitment-speaker"));
      if (rid && speakerIndex) onOpenSpeaker(rid, speakerIndex);
    };
    node.addEventListener("click", openSpeaker);
    node.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        openSpeaker();
      }
    });
  });
}

function buildRecruitmentSpeakerApplyAction(item, slot, session) {
  const Tx = getTransactionApi();
  const talentId = session?.role === "voice" ? resolveVoiceTalentIdForSession(session) : "";
  const closed = isRecruitmentSlotClosed(slot);
  const applied = talentId && Tx?.voiceHasAppliedToSlot(slot, talentId);
  const canApply = talentId && Tx?.canTalentApplyToSlot(slot, talentId);

  if (closed) {
    return `<div class="hero-actions recruitment-detail-actions">
      <span class="recruitment-slot-closed-badge">${escapeHtml(t("recruitments.closed_badge"))}</span>
      <p class="section-desc">${slot.mode === "pick" ? escapeHtml(t("recruitments.apply_closed_pick")) : escapeHtml(t("recruitments.apply_closed_selected"))}</p>
    </div>`;
  }
  if (applied) {
    return `<div class="hero-actions recruitment-detail-actions">
      <span class="cast-acceptance-status">${escapeHtml(t("recruitments.applied"))}</span>
      <button type="button" class="btn-ghost" data-go="work">${escapeHtml(t("recruitments.view_in_work"))}</button>
    </div>`;
  }
  if (session?.role === "voice" && canApply) {
    return `<div class="hero-actions recruitment-detail-actions">
      <button type="button" class="btn-red" id="recruitmentSpeakerApplyBtn" data-request-id="${escapeAttr(item.requestId)}" data-speaker-index="${slot.speakerIndex}">${escapeHtml(t("recruitments.apply_btn"))}</button>
    </div>`;
  }
  if (session) {
    return `<p class="section-desc">${escapeHtml(t("recruitments.login_voice_hint"))}</p>
      <div class="hero-actions recruitment-detail-actions">
        <button type="button" class="btn-red" data-go="login">${escapeHtml(t("recruitments.login_voice_btn"))}</button>
      </div>`;
  }
  return `<p class="section-desc">${escapeHtml(t("recruitments.login_apply_hint"))}</p>
    <div class="hero-actions recruitment-detail-actions">
      <button type="button" class="btn-red" data-go="login">${escapeHtml(t("recruitments.login_apply_btn"))}</button>
      <button type="button" class="btn-ghost" data-go="voice">${escapeHtml(t("recruitments.register_voice_btn"))}</button>
    </div>`;
}

function renderRecruitmentsList(cases) {
  const grid = document.getElementById("recruitmentsGrid");
  const empty = document.getElementById("recruitmentsEmpty");
  const countEl = document.getElementById("recruitmentsCount");
  if (!grid || !empty) return;

  recruitmentsPageCases = cases;
  if (countEl) countEl.textContent = cases.length ? t("recruitments.count", { count: cases.length }) : "";

  if (!cases.length) {
    grid.innerHTML = "";
    empty.classList.remove("hidden");
    return;
  }

  empty.classList.add("hidden");
  grid.innerHTML = cases
    .map((item) => {
      const slotCount = item.openSlots?.length || 0;
      const updated = item.updatedAt ? formatDateTime(item.updatedAt) : "";
      const ownBadge = item.isOwnRecruitment
        ? `<span class="recruitment-card-badge recruitment-card-badge-own">${escapeHtml(t("recruitments.badge_own"))}</span>`
        : "";
      return `<article class="recruitment-card" data-recruitment-id="${escapeAttr(item.requestId)}" tabindex="0" role="button" aria-label="${escapeAttr(t("recruitments.card_aria", { name: item.customerName }))}">
        <div class="recruitment-card-head">
          <h3 class="recruitment-card-title">${escapeHtml(item.customerName)}</h3>
          <span class="recruitment-card-badges">
            ${ownBadge}
            <span class="recruitment-card-badge">${escapeHtml(t("recruitments.badge_open", { count: slotCount }))}</span>
          </span>
        </div>
        <p class="recruitment-card-video">${
          item.videoUrl
            ? `<a href="${escapeAttr(item.videoUrl)}" target="_blank" rel="noreferrer" data-recruitment-video-link="1">${escapeHtml(item.videoUrl)}</a>`
            : escapeHtml(t("recruitments.unset"))
        }</p>
        <div class="recruitment-card-meta">
          ${renderScriptLanguageMetaHtml(item.scriptLanguage || "ja", "recruitments.script_language")}
          ${item.tone ? `<span>${escapeHtml(t("recruitments.meta_tone"))}: ${escapeHtml(item.tone)}</span>` : ""}
          ${item.deadline ? `<span>${escapeHtml(t("recruitments.meta_deadline"))}: ${escapeHtml(item.deadline)}</span>` : ""}
          ${updated ? `<span>${escapeHtml(t("recruitments.meta_updated"))}: ${escapeHtml(updated)}</span>` : ""}
        </div>
        <button type="button" class="btn-ghost btn-sm recruitment-card-detail-btn" data-recruitment-id="${escapeAttr(item.requestId)}">${escapeHtml(t("recruitments.view_detail"))}</button>
      </article>`;
    })
    .join("");

  grid.querySelectorAll("[data-recruitment-id]").forEach((node) => {
    const openDetail = () => {
      const requestId = node.getAttribute("data-recruitment-id");
      if (requestId) showRecruitmentDetail(requestId);
    };
    if (node.classList.contains("recruitment-card-detail-btn")) {
      node.addEventListener("click", (event) => {
        event.stopPropagation();
        openDetail();
      });
      return;
    }
    node.querySelectorAll("[data-recruitment-video-link]").forEach((link) => {
      link.addEventListener("click", (event) => event.stopPropagation());
    });
    node.addEventListener("click", openDetail);
    node.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        openDetail();
      }
    });
  });
}

function showRecruitmentDetail(requestId, options = {}) {
  const listView = document.getElementById("recruitmentsListView");
  const detailView = document.getElementById("recruitmentsDetailView");
  const speakerView = document.getElementById("recruitmentsSpeakerDetailView");
  const panel = document.getElementById("recruitmentsDetailPanel");
  if (!listView || !detailView || !panel) return;

  recruitmentsCurrentRequestId = requestId;
  recruitmentsCurrentSpeakerIndex = 0;

  const item = recruitmentsPageCases.find((row) => row.requestId === requestId);
  if (!item) {
    setRecruitmentsMessage(t("recruitments.not_found"), "err");
    return;
  }

  const P = getPricingApi();
  const pricingNote = P
    ? t("recruitments.pricing_platform", {
        perMin: P.formatUsd(P.MIN_PRICE_PER_MINUTE_USD),
        minSlot: P.formatUsd(P.MIN_SLOT_ORDER_USD)
      })
    : t("recruitments.pricing_platform", { perMin: "$15", minSlot: "$20" });

  panel.innerHTML = `
    <h3 class="recruitment-detail-title">${escapeHtml(item.customerName)}</h3>
    <div class="work-case-header-meta recruitment-detail-meta">
      <div><strong>${escapeHtml(t("recruitments.case_id"))}:</strong> ${escapeHtml(item.requestId)}</div>
      <div><strong>${escapeHtml(t("recruitments.video"))}:</strong> ${
        item.videoUrl
          ? `<a href="${escapeAttr(item.videoUrl)}" target="_blank" rel="noreferrer">${escapeHtml(item.videoUrl)}</a>`
          : escapeHtml(t("recruitments.unset"))
      }</div>
      ${item.tone ? `<div><strong>${escapeHtml(t("recruitments.meta_tone"))}:</strong> ${escapeHtml(item.tone)}</div>` : ""}
      <div><strong>${escapeHtml(t("recruitments.script_language"))}:</strong> ${escapeHtml(formatScriptLanguageDisplay(item.scriptLanguage || "ja"))}</div>
      ${item.deadline ? `<div><strong>${escapeHtml(t("recruitments.meta_deadline"))}:</strong> ${escapeHtml(item.deadline)}</div>` : ""}
      <div><strong>${escapeHtml(t("recruitments.status"))}:</strong> ${escapeHtml(translateWorkflowStatus(item.workflowStatus))}</div>
      <div><strong>${escapeHtml(t("recruitments.price_guide"))}:</strong> ${escapeHtml(pricingNote)}</div>
    </div>
    <h4 class="cast-subtitle">${escapeHtml(t("recruitments.speaker_slots_title"))}</h4>
    <p class="section-desc">${escapeHtml(t("recruitments.speaker_slots_desc"))}</p>
    ${renderRecruitmentSpeakerRows(item, { clickable: true, requestId })}
  `;

  bindRecruitmentSpeakerRowClicks(panel, showRecruitmentSpeakerDetail);

  listView.classList.add("hidden");
  speakerView?.classList.add("hidden");
  detailView.classList.remove("hidden");
  if (!options.skipNavBack) {
    globalThis.WavrickNavBack?.push?.(() => {
      showRecruitmentsListView({ skipNavBack: true });
    });
    globalThis.WavrickNavBack?.bindSwipeBack?.(detailView, () => {
      globalThis.WavrickNavBack?.pop?.();
    });
  }
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function showRecruitmentSpeakerDetail(requestId, speakerIndex, options = {}) {
  const caseView = document.getElementById("recruitmentsDetailView");
  const speakerView = document.getElementById("recruitmentsSpeakerDetailView");
  const panel = document.getElementById("recruitmentsSpeakerDetailPanel");
  if (!caseView || !speakerView || !panel) return;

  recruitmentsCurrentRequestId = requestId;
  recruitmentsCurrentSpeakerIndex = Number(speakerIndex);

  const item = recruitmentsPageCases.find((row) => row.requestId === requestId);
  const slot = item?.castAcceptance?.find((s) => Number(s.speakerIndex) === Number(speakerIndex));
  if (!item || !slot) {
    setRecruitmentsMessage(t("recruitments.slot_not_found"), "err");
    return;
  }

  const session = getCurrentSession();
  const metrics = formatRecruitmentSpeakerMetrics(item, speakerIndex);
  const appCount = countRecruitmentSlotApplicants(slot);
  const P = getPricingApi();
  const voicePayout =
    P && metrics.subtotalLabel !== "—"
      ? (() => {
          const line = getRecruitmentSpeakerQuote(item, speakerIndex);
          return line ? P.formatUsd(line.subtotalUsd * P.VOICE_PAYOUT_RATE) : "";
        })()
      : "";
  const offerPrefs = getRecruitmentOfferPrefs(item, speakerIndex);
  const offerMeta = offerPrefs
    ? `<div><strong>${escapeHtml(t("work.open_recruit_price") || "単価")}:</strong> ${escapeHtml(
        P ? P.formatUsd(offerPrefs.pricePerMinute) : `$${offerPrefs.pricePerMinute}`
      )}/分</div>
      ${
        offerPrefs.additionalRetakePrice > 0
          ? `<div><strong>${escapeHtml(t("work.open_recruit_retake") || "追加リテイク料")}:</strong> ${escapeHtml(
              P ? P.formatUsd(offerPrefs.additionalRetakePrice) : `$${offerPrefs.additionalRetakePrice}`
            )}/回</div>`
          : ""
      }
      ${
        offerPrefs.gender
          ? `<div><strong>${escapeHtml(t("work.open_recruit_gender") || "性別")}:</strong> ${escapeHtml(
              offerPrefs.gender === "male"
                ? t("work.open_recruit_gender_male") || "男性"
                : offerPrefs.gender === "female"
                  ? t("work.open_recruit_gender_female") || "女性"
                  : offerPrefs.gender
            )}</div>`
          : ""
      }
      ${
        offerPrefs.attributes
          ? `<div><strong>${escapeHtml(t("work.open_recruit_attributes") || "希望属性")}:</strong> ${escapeHtml(
              offerPrefs.attributes
            )}</div>`
          : ""
      }`
    : "";
  const applicantDisplay =
    appCount > 0
      ? t("recruitments.applicants_n", { count: appCount })
      : t("recruitments.no_applicants");

  panel.innerHTML = `
    <h3 class="recruitment-detail-title">${escapeHtml(t("recruitments.speaker_detail_title", { name: item.customerName, index: speakerIndex }))}</h3>
    <div class="work-case-header-meta recruitment-detail-meta">
      <div><strong>${escapeHtml(t("recruitments.case_id"))}:</strong> ${escapeHtml(item.requestId)}</div>
      <div><strong>${escapeHtml(t("recruitments.slot_status"))}:</strong> ${escapeHtml(getRecruitmentSlotModeLabel(slot))}</div>
      <div><strong>${escapeHtml(t("recruitments.speech_time"))}:</strong> ${escapeHtml(metrics.durationLabel)}</div>
      <div><strong>${escapeHtml(t("recruitments.subtotal"))}:</strong> ${escapeHtml(metrics.subtotalLabel)}</div>
      ${voicePayout ? `<div><strong>${escapeHtml(t("recruitments.voice_payout"))}:</strong> ${escapeHtml(voicePayout)}</div>` : ""}
      ${offerMeta}
      <div><strong>${escapeHtml(t("recruitments.applicant_count"))}:</strong> ${escapeHtml(applicantDisplay)}</div>
    </div>
    <h4 class="cast-subtitle">${escapeHtml(t("recruitments.youtube_section_title"))}</h4>
    <p class="section-desc">${escapeHtml(t("recruitments.youtube_section_desc"))}</p>
    ${buildRecruitmentYoutubeUrlHtml(item.videoUrl)}
    <p id="recruitmentSpeakerApplyMessage" class="message recruitments-apply-inline" hidden aria-live="polite"></p>
    ${buildRecruitmentSpeakerApplyAction(item, slot, session)}
  `;

  panel.querySelectorAll("[data-go]").forEach((node) => {
    node.addEventListener("click", (event) => {
      event.preventDefault();
      if (node.getAttribute("data-go") === "work") {
        setWorkSelectedRequestId(requestId);
      }
      showPage(node.getAttribute("data-go"));
    });
  });

  caseView.classList.add("hidden");
  speakerView.classList.remove("hidden");
  if (!options.skipNavBack) {
    globalThis.WavrickNavBack?.push?.(() => {
      showRecruitmentDetail(requestId, { skipNavBack: true });
    });
    globalThis.WavrickNavBack?.bindSwipeBack?.(speakerView, () => {
      globalThis.WavrickNavBack?.pop?.();
    });
  }
  window.scrollTo({ top: 0, behavior: "smooth" });
}

async function applyToRecruitmentSlot(requestId, speakerIndex) {
  const applyBtn = document.getElementById("recruitmentSpeakerApplyBtn");
  const prevLabel = applyBtn?.textContent || "";
  const setBusy = (busy, label) => {
    if (!applyBtn) return;
    applyBtn.disabled = Boolean(busy);
    if (label) applyBtn.textContent = label;
  };

  try {
    setBusy(true, t("recruitments.applying"));
    setRecruitmentsMessage(t("recruitments.applying"), "");

    const session = getCurrentSession();
    const Tx = getTransactionApi();
    const talentId = resolveVoiceTalentIdForSession(session);
    if (session?.role !== "voice" || !talentId || !Tx) {
      setRecruitmentsMessage("応募するには声優としてログインしてください。", "err");
      return;
    }
    if (globalThis.WavrickAccountRestriction?.isSessionSuspended?.(session)) {
      setRecruitmentsMessage(t("account.restriction_block_new_work"), "err");
      return;
    }

    // 一覧 RPC の案件を優先。全件クラウド取得は遅い／JWT 待ちで無反応に見えるため避ける。
    const listing = findRecruitmentListingCase(requestId);
    const localRows = await getMergedYoutubeRequests({ localOnly: true });
    let request = resolveRequestForRecruitmentApply(requestId, localRows);
    if (!request && listing) {
      request = resolveRequestForRecruitmentApply(requestId, []);
    }
    if (!request) {
      setRecruitmentsMessage("案件が見つかりません。一覧を更新してから再度お試しください。", "err");
      return;
    }

    const customerEmail = (request?.email || listing?.customerEmail || "").toLowerCase().trim();
    const B = getTalentBlocksApi();
    if (customerEmail && B?.isBlockedBetween(customerEmail, talentId)) {
      setRecruitmentsMessage("この顧客とはブロック関係のため応募できません。", "err");
      return;
    }

    const profile = resolveVoiceProfileByTalentId(talentId);
    const displayName = profile?.displayName || session?.name || talentId;
    let applyOk = false;
    let applyError = "";
    const result = await updateWorkflowForRequest(requestId, (innerWf) => {
      const applied = Tx.applyTalentApplication(
        innerWf.castAcceptance || [],
        speakerIndex,
        talentId,
        displayName
      );
      if (!applied.ok) {
        applyError = applied.error || "応募に失敗しました。";
        return innerWf;
      }
      applyOk = true;
      innerWf.castAcceptance = applied.slots;
      return maybeAdvanceTransactionPhase(innerWf, request);
    });

    if (!result.ok) {
      setRecruitmentsMessage(result.error || "応募に失敗しました。", "err");
      return;
    }
    if (!applyOk) {
      setRecruitmentsMessage(applyError || "この枠には応募できません。", "err");
      return;
    }
    if (result.remoteOk === false) {
      setRecruitmentsMessage(
        "応募の保存に失敗しました。通信状況を確認して再度お試しください。",
        "err"
      );
      return;
    }

    pushCaseNotification(t("work.notify_speaker_applied", { speaker: speakerIndex }), requestId, {
      to: "customer",
      kind: "customer",
      category: "case"
    });
    setRecruitmentsMessage(`話者${speakerIndex} に応募しました。`, "ok");
    showRecruitmentSpeakerDetail(requestId, speakerIndex);
  } catch (err) {
    console.warn("[wavrick] applyToRecruitmentSlot failed", err);
    setRecruitmentsMessage(
      err instanceof Error ? err.message : "応募に失敗しました。",
      "err"
    );
  } finally {
    setBusy(false, prevLabel);
    document.getElementById("recruitmentSpeakerApplyMessage")?.scrollIntoView?.({
      block: "nearest",
      behavior: "smooth"
    });
  }
}

function showRecruitmentsListView(options = {}) {
  document.getElementById("recruitmentsListView")?.classList.remove("hidden");
  document.getElementById("recruitmentsDetailView")?.classList.add("hidden");
  document.getElementById("recruitmentsSpeakerDetailView")?.classList.add("hidden");
  recruitmentsCurrentRequestId = "";
  recruitmentsCurrentSpeakerIndex = 0;
  void options;
}

function showRecruitmentsCaseView() {
  document.getElementById("recruitmentsListView")?.classList.add("hidden");
  document.getElementById("recruitmentsDetailView")?.classList.remove("hidden");
  document.getElementById("recruitmentsSpeakerDetailView")?.classList.add("hidden");
}

let recruitmentsRefreshGeneration = 0;

async function refreshRecruitmentsPage(options = {}) {
  if (_wavrickDeferRecruitmentsCloudLoad && !options.force) {
    return { ok: false, reason: "deferred" };
  }
  const generation = ++recruitmentsRefreshGeneration;
  const previousCases = Array.isArray(recruitmentsPageCases) ? recruitmentsPageCases.slice() : [];
  setRecruitmentsMessage("読み込み中…", "");
  showRecruitmentsListView();
  try {
    const session = getCurrentSession();
    // 一覧 RPC は anon。JWT 復元待ちで遅延させない（壊れた JWT でも取得できる）。
    const fetched = await fetchOpenRecruitmentCases();
    const cases = Array.isArray(fetched?.cases) ? fetched.cases : Array.isArray(fetched) ? fetched : [];
    const remoteOk = fetched?.remoteOk !== false;
    if (generation !== recruitmentsRefreshGeneration) {
      return { ok: false, reason: "superseded" };
    }
    // 失敗時に成功済みの一覧を空で上書きしない
    if (!cases.length && !remoteOk && previousCases.length) {
      renderRecruitmentsList(previousCases);
      setRecruitmentsMessage("募集案件の再取得に失敗しました。表示中の一覧は前回の結果です。", "err");
      return {
        ok: false,
        count: previousCases.length,
        remoteOk: false,
        remoteReason: fetched?.remoteReason || "error",
        remoteCount: fetched?.remoteCount || 0,
        keptPrevious: true
      };
    }
    renderRecruitmentsList(cases);
    if (cases.length) {
      setRecruitmentsMessage("", "");
    } else if (!remoteOk) {
      setRecruitmentsMessage("募集案件の取得に失敗しました。しばらくしてから「更新」を試してください。", "err");
    } else {
      setRecruitmentsMessage(t("recruitments.empty") || "現在、公開中の募集案件はありません。", "ok");
    }
    return {
      ok: remoteOk || cases.length > 0,
      count: cases.length,
      remoteOk,
      remoteReason: fetched?.remoteReason || null,
      remoteCount: fetched?.remoteCount || 0
    };
  } catch {
    if (generation !== recruitmentsRefreshGeneration) {
      return { ok: false, reason: "superseded" };
    }
    if (previousCases.length) {
      renderRecruitmentsList(previousCases);
      setRecruitmentsMessage("募集案件の取得に失敗しました。表示中の一覧は前回の結果です。", "err");
      return { ok: false, reason: "error", keptPrevious: true, count: previousCases.length };
    }
    setRecruitmentsMessage("募集案件の取得に失敗しました。", "err");
    renderRecruitmentsList([]);
    return { ok: false, reason: "error" };
  }
}

function bindRecruitmentsPage() {
  if (isRecruitmentsPageBound) return;
  isRecruitmentsPageBound = true;

  document.getElementById("recruitmentsRefreshBtn")?.addEventListener("click", () => {
    void refreshRecruitmentsPage();
  });
  document.getElementById("recruitmentsBackToListBtn")?.addEventListener("click", () => {
    globalThis.WavrickNavBack?.pop?.();
    window.scrollTo({ top: 0, behavior: "smooth" });
  });
  document.getElementById("recruitmentsBackToCaseBtn")?.addEventListener("click", () => {
    globalThis.WavrickNavBack?.pop?.();
    window.scrollTo({ top: 0, behavior: "smooth" });
  });
  // Backup: delegated click so apply still works if per-button bind is lost after re-render.
  document.getElementById("page-recruitments")?.addEventListener("click", (event) => {
    const btn = event.target?.closest?.("#recruitmentSpeakerApplyBtn");
    if (!btn || btn.disabled) return;
    event.preventDefault();
    const requestId = btn.getAttribute("data-request-id") || recruitmentsCurrentRequestId;
    const speakerIndex = Number(
      btn.getAttribute("data-speaker-index") || recruitmentsCurrentSpeakerIndex || 0
    );
    if (!requestId || !speakerIndex) return;
    void applyToRecruitmentSlot(requestId, speakerIndex);
  });
}

function syncWorkRoleVisibility(session) {
  const roles = getSessionRoles(session);
  const isAdmin = roles.includes("admin") || session?.role === "admin";
  const isVoice = isAdmin || roles.includes("voice");
  const isCustomer = isAdmin || roles.includes("customer");
  // Elements may list multiple roles (e.g. work-role-voice work-role-admin). Show if ANY matches.
  document.querySelectorAll(".work-role-voice").forEach((el) => {
    const show =
      isVoice ||
      (el.classList.contains("work-role-admin") && isAdmin) ||
      (el.classList.contains("work-role-customer") && isCustomer);
    el.classList.toggle("hidden", !show);
  });
  document.querySelectorAll(".work-role-customer").forEach((el) => {
    if (el.classList.contains("work-role-voice")) return;
    const allowAdmin = el.classList.contains("work-role-admin");
    const show = isCustomer || (allowAdmin && isAdmin);
    el.classList.toggle("hidden", !show);
  });
  document.querySelectorAll(".work-role-admin").forEach((el) => {
    if (el.classList.contains("work-role-customer") || el.classList.contains("work-role-voice")) return;
    el.classList.toggle("hidden", !isAdmin);
  });
  const subtitle = document.getElementById("workPageSubtitle");
  if (subtitle) {
    const hasCustomer = roles.includes("customer");
    const hasVoice = roles.includes("voice");
    if (isAdmin) {
      subtitle.textContent = t("work.subtitle_admin");
    } else if (hasCustomer && hasVoice) {
      subtitle.textContent = t("work.subtitle_both");
    } else if (hasVoice) {
      subtitle.textContent = t("work.subtitle_voice");
    } else if (hasCustomer) {
      subtitle.textContent = t("work.subtitle_customer");
    } else {
      subtitle.textContent = t("work.subtitle_guest");
    }
  }
}

function getAssignedVoiceContactsForRequest(request, wf) {
  const slots = wf?.castAcceptance?.length ? wf.castAcceptance : getCastSlotsForRequest(request);
  const Tx = getTransactionApi();
  const seen = new Set();
  const contacts = [];
  for (const slot of slots) {
    if (!slot?.talentId) continue;
    const tid = String(slot.talentId);
    if (seen.has(tid)) continue;
    seen.add(tid);
    const profile = resolveVoiceProfileByTalentId(tid);
    const email = (profile?.email || tid.replace(/^voice:/, "")).trim();
    contacts.push({
      talentId: tid,
      speakerIndex: slot.speakerIndex,
      displayName: profile?.displayName || slot.displayName || email || tid,
      email: email.includes("@") ? email : ""
    });
  }
  if (!contacts.length && Tx) {
    for (const slot of slots) {
      for (const app of slot.applications || []) {
        if (app.status !== Tx.APP_STATUS.selected && app.status !== Tx.APP_STATUS.accepted) continue;
        const tid = String(app.talentId || "");
        if (!tid || seen.has(tid)) continue;
        seen.add(tid);
        const profile = resolveVoiceProfileByTalentId(tid);
        const email = (profile?.email || tid.replace(/^voice:/, "")).trim();
        contacts.push({
          talentId: tid,
          speakerIndex: slot.speakerIndex,
          displayName: profile?.displayName || app.displayName || email || tid,
          email: email.includes("@") ? email : ""
        });
      }
    }
  }
  return contacts;
}

function getCustomerScriptMailParticipant(request) {
  return {
    key: `customer:${(request?.email || "").toLowerCase().trim()}`,
    role: "customer",
    talentId: "",
    displayName: request?.name || request?.email || "顧客",
    email: (request?.email || "").trim()
  };
}

function getCaseScriptMailParticipants(request, wf) {
  return {
    customer: getCustomerScriptMailParticipant(request),
    voices: getAssignedVoiceContactsForRequest(request, wf)
  };
}

function voiceIsInvolvedInScriptMailCase(request, wf, talentId) {
  if (!talentId) return false;
  const Tx = getTransactionApi();
  const slots = wf?.castAcceptance?.length ? wf.castAcceptance : getCastSlotsForRequest(request);
  if (Tx?.voiceIsInvolvedInCase(slots, talentId)) return true;
  return getVoiceSpeakerSlotsForRequest(request, talentId).length > 0;
}

function canSeeScriptMailMessage(msg, session, request, myTalentId) {
  if (msg.kind !== "script_revision") return false;
  const scope = msg.recipientScope || "all";
  if (scope === "all") return true;
  const role = session?.role || "";
  if (role === "admin") return true;
  if (role === "customer") {
    if (msg.senderRole === "customer") return true;
    if (msg.recipientRole === "customer") return true;
    return false;
  }
  if (role === "voice" && myTalentId) {
    if (msg.senderTalentId === myTalentId) return true;
    if (msg.recipientRole === "voice" && msg.recipientTalentId === myTalentId) return true;
    return false;
  }
  return false;
}

function formatScriptMailRecipientLabel(msg, request, voices) {
  if ((msg.recipientScope || "all") === "all") return "全体";
  if (msg.recipientRole === "customer") {
    return getCustomerScriptMailParticipant(request).displayName;
  }
  const voice = voices.find((v) => v.talentId === msg.recipientTalentId);
  if (voice) return `${voice.displayName}（話者${voice.speakerIndex}）`;
  return msg.recipientTalentId || "個人";
}

function buildScriptMailRecipientOptions(session, request, wf, myTalentId) {
  const { customer, voices } = getCaseScriptMailParticipants(request, wf);
  const options = [];
  if (session?.role === "customer") {
    for (const voice of voices) {
      options.push({
        value: `voice:${voice.talentId}`,
        role: "voice",
        talentId: voice.talentId,
        label: `${voice.displayName}（話者${voice.speakerIndex}）`
      });
    }
  } else if (session?.role === "voice") {
    options.push({
      value: `customer:${customer.key}`,
      role: "customer",
      talentId: "",
      label: `${customer.displayName}（顧客）`
    });
    for (const voice of voices) {
      if (voice.talentId === myTalentId) continue;
      options.push({
        value: `voice:${voice.talentId}`,
        role: "voice",
        talentId: voice.talentId,
        label: `${voice.displayName}（話者${voice.speakerIndex}）`
      });
    }
  } else if (session?.role === "admin") {
    options.push({
      value: `customer:${customer.key}`,
      role: "customer",
      talentId: "",
      label: `${customer.displayName}（顧客）`
    });
    for (const voice of voices) {
      options.push({
        value: `voice:${voice.talentId}`,
        role: "voice",
        talentId: voice.talentId,
        label: `${voice.displayName}（話者${voice.speakerIndex}）`
      });
    }
  }
  return options;
}

function parseScriptMailRecipientValue(raw) {
  const value = String(raw || "");
  if (value.startsWith("customer:")) {
    return { recipientRole: "customer", recipientTalentId: "" };
  }
  if (value.startsWith("voice:")) {
    return { recipientRole: "voice", recipientTalentId: value.slice(6) };
  }
  return { recipientRole: "", recipientTalentId: "" };
}

function buildScriptMailExternalUrl(request, recipient, messageText) {
  if (!recipient?.email) return "";
  const subject = encodeURIComponent(`【WAVRICK】台本・タイムコード連絡 — ${request.requestId || "案件"}`);
  const body = encodeURIComponent(
    `案件 ${request.requestId || ""} の台本・タイムコードに関する連絡です。\n\n` +
      `動画: ${request.videoUrl || "—"}\n\n` +
      `${messageText}\n\n---\nWAVRICK 案件管理より`
  );
  return `mailto:${encodeURIComponent(recipient.email)}?subject=${subject}&body=${body}`;
}

function syncWorkScriptMailComposerUi(session, request, wf) {
  const scopeEl = document.getElementById("workScriptMailScope");
  const recipientField = document.getElementById("workScriptMailRecipientField");
  const recipientEl = document.getElementById("workScriptMailRecipient");
  const externalBtn = document.getElementById("workOpenScriptMailExternalBtn");
  if (!scopeEl || !recipientEl) return;

  const myTalentId = session?.role === "voice" ? resolveVoiceTalentIdForSession(session) : "";
  const voices = getAssignedVoiceContactsForRequest(request, wf);
  const options = buildScriptMailRecipientOptions(session, request, wf, myTalentId);
  const isIndividual = scopeEl.value === "individual";

  recipientField?.classList.toggle("hidden", !isIndividual);
  recipientEl.innerHTML = options
    .map((opt) => `<option value="${escapeAttr(opt.value)}">${escapeHtml(opt.label)}</option>`)
    .join("");

  const composer = document.getElementById("workScriptMailComposer");
  if (composer) {
    composer.classList.toggle("hidden", isIndividual && !options.length);
  }

  if (externalBtn) {
    let showExternal = false;
    let mailto = "";
    if (isIndividual && recipientEl.value) {
      const parsed = parseScriptMailRecipientValue(recipientEl.value);
      const text = document.getElementById("workScriptMailInput")?.value?.trim() || "";
      if (parsed.recipientRole === "customer") {
        const customer = getCustomerScriptMailParticipant(request);
        if (customer.email && text) {
          mailto = buildScriptMailExternalUrl(request, customer, text);
          showExternal = Boolean(mailto);
        }
      } else if (parsed.recipientRole === "voice") {
        const voice = voices.find((v) => v.talentId === parsed.recipientTalentId);
        if (voice?.email && text) {
          mailto = buildScriptMailExternalUrl(request, voice, text);
          showExternal = Boolean(mailto);
        }
      }
    }
    externalBtn.classList.toggle("hidden", !showExternal);
    externalBtn.dataset.mailto = mailto || "";
  }
}

function renderScriptMailThreadHtml(messages, session, request, wf, myTalentId) {
  const voices = getAssignedVoiceContactsForRequest(request, wf);
  const visible = (messages || [])
    .filter((m) => m.kind === "script_revision" && canSeeScriptMailMessage(m, session, request, myTalentId))
    .sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));

  if (!visible.length) {
    return `<p class="section-desc">まだメールはありません。台本・タイムコードの修正連絡を送ってください。</p>`;
  }

  return visible
    .map((m) => {
      const scopeLabel = formatScriptMailRecipientLabel(m, request, voices);
      const scopeBadge =
        (m.recipientScope || "all") === "all"
          ? `<span class="work-script-mail-badge work-script-mail-badge--all">全体</span>`
          : `<span class="work-script-mail-badge work-script-mail-badge--direct">個人 → ${escapeHtml(scopeLabel)}</span>`;
      const roleLabel =
        m.senderRole === "voice" ? "声優" : m.senderRole === "customer" ? "顧客" : "";
      return `<article class="work-script-mail-item">
        <header class="work-script-mail-item-head">
          <strong>${escapeHtml(m.sender)}</strong>
          ${roleLabel ? `<span class="work-script-mail-role">${escapeHtml(roleLabel)}</span>` : ""}
          ${scopeBadge}
          <time class="work-script-mail-time">${escapeHtml(formatDateTime(m.createdAt))}</time>
        </header>
        <p class="work-script-mail-body">${escapeHtml(m.text)}</p>
      </article>`;
    })
    .join("");
}

function renderWorkScriptMailCard(request, session, wf) {
  const card = document.getElementById("workScriptRevisionCard");
  const threadEl = document.getElementById("workScriptMailThread");
  if (!card || !threadEl) return;

  const role = session?.role || "";
  const myTalentId = role === "voice" ? resolveVoiceTalentIdForSession(session) : "";
  const voices = getAssignedVoiceContactsForRequest(request, wf);
  const canUse =
    role === "admin" ||
    role === "customer" ||
    (role === "voice" && voiceIsInvolvedInScriptMailCase(request, wf, myTalentId));

  if (!canUse) {
    card.classList.add("hidden");
    return;
  }
  card.classList.remove("hidden");

  threadEl.innerHTML = renderScriptMailThreadHtml(wf.messages || [], session, request, wf, myTalentId);
  syncWorkScriptMailComposerUi(session, request, wf);
  syncWorkCancelledMessagingUi(wf);

  const composer = document.getElementById("workScriptMailComposer");
  if (composer) {
    const blocked = role === "customer" && !voices.length;
    composer.classList.toggle("hidden", blocked);
    if (blocked && !threadEl.querySelector(".work-script-mail-blocked-note")) {
      threadEl.insertAdjacentHTML(
        "beforeend",
        `<p class="section-desc work-script-mail-blocked-note">担当声優が確定すると、全体・個人宛にメールを送れます。</p>`
      );
    }
  }

  threadEl.scrollTop = threadEl.scrollHeight;
}

async function sendWorkScriptMailMessage(request, session, wf) {
  const text = document.getElementById("workScriptMailInput")?.value?.trim() || "";
  const scope = document.getElementById("workScriptMailScope")?.value || "all";
  const recipientRaw = document.getElementById("workScriptMailRecipient")?.value || "";

  if (!text) {
    setMessage("workMessage", "メール本文を入力してください。", "err");
    return null;
  }

  const myTalentId = session?.role === "voice" ? resolveVoiceTalentIdForSession(session) : "";
  const voices = getAssignedVoiceContactsForRequest(request, wf);

  if (scope === "individual") {
    const options = buildScriptMailRecipientOptions(session, request, wf, myTalentId);
    if (!options.length) {
      setMessage("workMessage", "送信できる宛先がありません。", "err");
      return null;
    }
  } else if (session?.role === "customer" && !voices.length) {
    setMessage("workMessage", "担当声優が確定していないため、全体送信できません。", "err");
    return null;
  }

  let recipientRole = "";
  let recipientTalentId = "";
  if (scope === "individual") {
    const parsed = parseScriptMailRecipientValue(recipientRaw);
    recipientRole = parsed.recipientRole;
    recipientTalentId = parsed.recipientTalentId;
    if (!recipientRole) {
      setMessage("workMessage", "宛先を選んでください。", "err");
      return null;
    }
  }

  const senderName =
    session?.role === "customer"
      ? request.name || session.displayName || "顧客"
      : session?.role === "voice"
        ? resolveVoiceProfileByTalentId(myTalentId)?.displayName || session.displayName || "声優"
        : session?.displayName || "ユーザー";

  const message = {
    id: newWorkflowEntryId("msg"),
    sender: senderName,
    text,
    kind: "script_revision",
    createdAt: new Date().toISOString(),
    senderRole: session?.role === "voice" ? "voice" : session?.role === "customer" ? "customer" : "admin",
    senderTalentId: session?.role === "voice" ? myTalentId : "",
    recipientScope: scope === "individual" ? "individual" : "all",
    recipientRole: scope === "individual" ? recipientRole : "",
    recipientTalentId: scope === "individual" ? recipientTalentId : ""
  };

  return message;
}

function showWorkMainView() {
  document.getElementById("workMainView")?.classList.remove("hidden");
  document.getElementById("workDeliverableDetailView")?.classList.add("hidden");
}

function isWorkCaseDetailOpen() {
  const detail = document.getElementById("workCaseDetailView");
  return Boolean(detail && !detail.classList.contains("hidden"));
}

/** 案件管理で「詳細を維持／開く」べきか（一覧表示中はロックだけでは詳細に戻さない） */
function shouldKeepWorkCaseDetailOpen() {
  return _workCaseOpenInFlight > 0 || isWorkCaseDetailOpen();
}

function workRequestIdsMatch(a, b, request = null) {
  const left = String(a || "").trim();
  const right = String(b || "").trim();
  if (!left || !right) return false;
  if (left === right) return true;
  if (!request || typeof request !== "object") return false;
  const ids = [request.requestId, request.rowId, request.id]
    .map((x) => String(x || "").trim())
    .filter(Boolean);
  return ids.includes(left) && ids.includes(right);
}

function closeWorkCaseSwitcher() {
  const switcher = document.getElementById("workCaseSwitcher");
  if (!switcher) return;
  switcher.classList.add("hidden");
  switcher.hidden = true;
  const btn = document.getElementById("workCaseIdSwitchBtn");
  if (btn) btn.setAttribute("aria-expanded", "false");
}

function openWorkCaseSwitcher() {
  const switcher = document.getElementById("workCaseSwitcher");
  if (!switcher) return;
  switcher.classList.remove("hidden");
  switcher.hidden = false;
  const btn = document.getElementById("workCaseIdSwitchBtn");
  if (btn) btn.setAttribute("aria-expanded", "true");
  const select = document.getElementById("workRequestSelect");
  try {
    select?.focus?.();
  } catch {
    /* ignore */
  }
}

function toggleWorkCaseSwitcher() {
  const switcher = document.getElementById("workCaseSwitcher");
  if (!switcher || switcher.classList.contains("hidden") || switcher.hidden) {
    openWorkCaseSwitcher();
  } else {
    closeWorkCaseSwitcher();
  }
}

function showWorkCaseListView(options = {}) {
  const listView = document.getElementById("workCaseListView");
  const detailView = document.getElementById("workCaseDetailView");
  closeWorkCaseSwitcher();
  if (options.clearOpenLock) {
    clearWorkCaseOpenLock();
  }
  listView?.classList.remove("hidden");
  detailView?.classList.add("hidden");
  if (!options.skipNavBack) {
    /* list is root of work page — no push */
  }
  if (options.scrollTop !== false) {
    window.scrollTo({ top: 0, behavior: options.instant ? "instant" : "smooth" });
  }
}

function showWorkCaseDetailView(options = {}) {
  const listView = document.getElementById("workCaseListView");
  const detailView = document.getElementById("workCaseDetailView");
  if (!listView || !detailView) return;
  closeWorkCaseSwitcher();
  listView.classList.add("hidden");
  detailView.classList.remove("hidden");
  document.getElementById("workCaseEmpty")?.classList.add("hidden");
  document.getElementById("workCasePanel")?.classList.remove("hidden");
  if (!options.skipNavBack) {
    globalThis.WavrickNavBack?.push?.(() => {
      showWorkCaseListView({ skipNavBack: true, clearOpenLock: true });
    });
    globalThis.WavrickNavBack?.bindSwipeBack?.(detailView, () => {
      globalThis.WavrickNavBack?.pop?.();
    });
  }
  if (options.scrollTop !== false) {
    window.scrollTo({ top: 0, behavior: options.instant ? "instant" : "smooth" });
  }
}

function showWorkDeliverableDetailView() {
  document.getElementById("workMainView")?.classList.add("hidden");
  const detailView = document.getElementById("workDeliverableDetailView");
  detailView?.classList.remove("hidden");
  globalThis.WavrickNavBack?.push?.(showWorkMainView);
  if (detailView) {
    globalThis.WavrickNavBack?.bindSwipeBack?.(detailView, () => {
      globalThis.WavrickNavBack?.pop?.();
    });
  }
}

function renderWorkDeliverableDetailPanel(request, session) {
  const panel = document.getElementById("workDeliverableDetailPanel");
  if (!panel || !request) return;
  const wf = getWorkflowForRequest(request.requestId, request.status);
  const confirmed = getConfirmedDeliverables(request, wf);
  const confirmedAt = confirmed?.confirmedAt ? formatDateTime(confirmed.confirmedAt) : "—";
  const transcript = confirmed?.transcriptPlain || "";
  const scriptFull = confirmed?.scriptFull || "";
  const castSlots = confirmed?.castSlots?.length ? confirmed.castSlots : getCastSlotsForRequest(request);
  const speakerCount = confirmed?.speakerCount || castSlots.length || 0;
  let perSpeakerHtml = "";
  if (speakerCount > 0 && confirmed?.scriptsBySpeaker) {
    const parts = [];
    for (let i = 1; i <= speakerCount; i++) {
      const body = resolveRecordScriptForSpeaker(scriptFull, i, castSlots, confirmed.scriptsBySpeaker);
      if (!body.trim()) continue;
      const slot = castSlots.find((s) => Number(s.speakerIndex) === i);
      const castLabel =
        slot?.mode === "recruit" || slot?.mode === "omakase"
          ? "募集枠"
          : slot?.displayName || slot?.talentId || "—";
      parts.push(`<h4 class="cast-subtitle">話者${i}（${escapeHtml(castLabel)}）</h4>
        <pre class="work-deliverable-readonly">${escapeHtml(body.trim())}</pre>`);
    }
    if (parts.length) perSpeakerHtml = parts.join("");
  }

  panel.innerHTML = `
    <h3 class="work-deliverable-title">${escapeHtml(request.name || "依頼案件")} — 確定版</h3>
    <p class="section-desc work-deliverable-notice">このページの内容は<strong>確定版</strong>です。ここからは編集できません。変更が必要な場合は案件管理画面の「メールを送信」から担当声優へ連絡してください。</p>
    <div class="work-case-header-meta work-deliverable-meta">
      <div><strong>案件ID:</strong> ${escapeHtml(request.requestId || "—")}</div>
      <div><strong>確定日時:</strong> ${escapeHtml(confirmedAt)}</div>
      <div><strong>動画:</strong> ${
        request.videoUrl
          ? `<a href="${escapeAttr(request.videoUrl)}" target="_blank" rel="noreferrer">${escapeHtml(request.videoUrl)}</a>`
          : "未設定"
      }</div>
    </div>
    <h4 class="cast-subtitle">書き起こし（確定版）</h4>
    ${
      transcript
        ? `<pre class="work-deliverable-readonly work-deliverable-transcript">${escapeHtml(transcript)}</pre>`
        : `<p class="section-desc">書き起こしデータがありません。</p>`
    }
    <h4 class="cast-subtitle">台本（話者振り分け済み・確定版）</h4>
    ${
      scriptFull
        ? perSpeakerHtml ||
          `<pre class="work-deliverable-readonly">${escapeHtml(scriptFull)}</pre>`
        : `<p class="section-desc">台本データがありません。</p>`
    }
    ${
      session?.role === "customer" || session?.role === "admin"
        ? `<div class="hero-actions work-action-row">
            <button type="button" class="btn-ghost" id="workDeliverableBackBtn">案件管理に戻る</button>
            <button type="button" class="btn-red" id="workDeliverableRevisionBtn">メールを送信</button>
          </div>`
        : `<div class="hero-actions work-action-row">
            <button type="button" class="btn-ghost" id="workDeliverableBackBtn">案件管理に戻る</button>
          </div>`
    }
  `;

  panel.querySelector("#workDeliverableBackBtn")?.addEventListener("click", () => {
    globalThis.WavrickNavBack?.pop?.();
    window.scrollTo({ top: 0, behavior: "smooth" });
  });
  panel.querySelector("#workDeliverableRevisionBtn")?.addEventListener("click", () => {
    globalThis.WavrickNavBack?.pop?.();
    document.getElementById("workScriptRevisionCard")?.scrollIntoView({ behavior: "smooth", block: "start" });
    document.getElementById("workScriptMailInput")?.focus();
  });
}

function openWorkDeliverableDetail(requestId) {
  void (async () => {
    let req = findLocalWorkRequestByAnyId(requestId);
    if (!req) {
      req = await softAwait(resolveWorkRequestByAnyId(requestId), WORK_OPEN_RESOLVE_TIMEOUT_MS, "deliverable_resolve");
    }
    if (!req) {
      setMessage("workMessage", "案件が見つかりません。", "err");
      return;
    }
    const session = getCurrentSession();
    renderWorkDeliverableDetailPanel(req, session);
    showWorkDeliverableDetailView();
    window.scrollTo({ top: 0, behavior: "smooth" });
  })();
}

function matchWorkRequestByAnyId(row, requestId) {
  const id = String(requestId || "").trim();
  if (!row || !id) return false;
  return row.requestId === id || row.rowId === id || String(row.id || "") === id;
}

function findLocalWorkRequestByAnyId(requestId) {
  const id = String(requestId || "").trim();
  if (!id) return null;
  let rows = [];
  try {
    rows = JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]");
  } catch {
    rows = [];
  }
  const direct = (Array.isArray(rows) ? rows : []).find((r) => matchWorkRequestByAnyId(r, id));
  if (direct) return direct;

  const { wf } = findStoredWorkflow(id);
  if (wf?.castAcceptance?.length || wf?.status) {
    return buildRequestStubFromWorkflow(id, wf);
  }

  const fromListing = resolveRequestForRecruitmentApply(id, rows);
  if (fromListing) return fromListing;

  return null;
}

async function loadWorkRequestForOpen(requestId, options = {}) {
  const id = String(requestId || "").trim();
  const onProgress =
    typeof options.onProgress === "function" ? options.onProgress : () => {};

  onProgress("local");
  let request = findLocalWorkRequestByAnyId(id);
  if (request) {
    workOpenTrace("open-hit-local", { id, requestId: request.requestId });
    return { request, source: "local" };
  }

  if (isSupabaseEnabled()) {
    onProgress("auth");
    await softAwait(ensureSupabaseAuthForLocalSession(), WORK_OPEN_AUTH_TIMEOUT_MS, "open_auth");
  }

  onProgress("remote");
  request = await softAwait(
    resolveWorkRequestByAnyId(id),
    WORK_OPEN_RESOLVE_TIMEOUT_MS,
    "open_resolve"
  );
  if (request) {
    return { request, source: "remote" };
  }

  request = findLocalWorkRequestByAnyId(id);
  if (request) {
    return { request, source: "local_after_remote" };
  }

  return { request: null, source: "miss" };
}

async function openWorkCaseById(requestId, options = {}) {
  const session = getCurrentSession();
  if (!requestId) {
    setMessage("workMessage", "案件IDが空のため開けませんでした。", "err");
    return;
  }
  if (!session) {
    setMessage("workMessage", "案件を開くにはログインが必要です。", "err");
    return;
  }

  // 先にロック（showPage → hydrate が別案件IDで上書きするのを防ぐ）
  const openGeneration = ++_workCaseOpenGeneration;
  const isStaleOpen = () => openGeneration !== _workCaseOpenGeneration;
  setWorkCaseOpenLock(requestId);
  _workCaseOpenInFlight += 1;
  if (typeof globalThis !== "undefined") globalThis._workCaseOpenInFlight = _workCaseOpenInFlight;
  workOpenTrace("open-start", {
    requestId,
    role: session.role,
    email: session.email,
    generation: openGeneration
  });

  // select を先に目標IDへ寄せる — 同期 refresh が innerHTML 直後に先頭（キャンセル等）へ飛ばないようにする
  const selectEarly = document.getElementById("workRequestSelect");
  if (selectEarly) {
    const hasOption = [...selectEarly.options].some((o) => o.value === requestId);
    if (!hasOption) {
      const opt = document.createElement("option");
      opt.value = requestId;
      opt.textContent = String(requestId);
      selectEarly.appendChild(opt);
    }
    selectEarly.value = requestId;
  }

  const pageWorkEarly = document.getElementById("page-work");
  const alreadyOnWork = pageWorkEarly?.classList.contains("active");
  if (!alreadyOnWork) {
    showPage("work");
  }

  // await 前に詳細シェルを出す — 同期 refresh が一覧へ戻す競合を防ぐ
  document.getElementById("workCaseEmpty")?.classList.add("hidden");
  document.getElementById("workCasePanel")?.classList.remove("hidden");
  showWorkCaseDetailView({
    skipNavBack: options.skipNavBack === true || isWorkCaseDetailOpen(),
    scrollTop: true,
    instant: !alreadyOnWork
  });
  // 直前に別案件（特にキャンセル）を見ていた場合の残表示を消す
  const cancelledBanner = document.getElementById("workCancelledBanner");
  if (cancelledBanner) {
    cancelledBanner.classList.add("hidden");
    cancelledBanner.hidden = true;
  }
  const cancelPendingBanner = document.getElementById("workCancelPendingBanner");
  if (cancelPendingBanner) {
    cancelPendingBanner.classList.add("hidden");
    cancelPendingBanner.hidden = true;
  }
  const headerHost = document.getElementById("workCaseHeader");
  if (headerHost) {
    headerHost.innerHTML = `<div class="section-desc">${escapeHtml(
      String(requestId)
    )} を読み込んでいます…</div>`;
  }
  setMessage("workDetailMessage", "案件を読み込んでいます…", null);

  try {
    const loaded = await loadWorkRequestForOpen(requestId, {
      onProgress(step) {
        if (isStaleOpen()) return;
        if (step === "local") {
          setMessage("workDetailMessage", "保存済みデータを確認しています…", null);
        } else if (step === "auth") {
          setMessage("workDetailMessage", "クラウドログインを確認しています…", null);
        } else if (step === "remote") {
          setMessage("workDetailMessage", "クラウドから案件データを取得しています…", null);
        }
      }
    });
    if (isStaleOpen()) return;
    const request = loaded.request;

    if (!request) {
      if (isStaleOpen()) return;
      clearWorkCaseOpenLock();
      showWorkCaseListView({ skipNavBack: true, scrollTop: false, clearOpenLock: true });
      const jwtOk = isSupabaseEnabled() ? await hasValidSupabaseAuthSession() : true;
      workOpenTrace("open-failed", {
        requestId,
        role: session.role,
        email: session.email,
        jwtOk,
        source: loaded.source,
        talentId: session.role === "voice" ? resolveVoiceTalentIdForSession(session) : ""
      });
      setMessage(
        "workMessage",
        jwtOk
          ? `案件（${String(requestId).slice(0, 12)}…）を開けませんでした。クラウド上に案件データが見つかりません。「一覧を更新」後にもう一度試すか、再ログインしてください。`
          : "クラウド同期用のログインが切れているため案件を開けません。一度ログアウトして再ログインしてください。",
        "err"
      );
      setMessage("workDetailMessage", "", null);
      return;
    }

    if (!sessionCanAccessWorkRequest(session, request)) {
      if (isStaleOpen()) return;
      clearWorkCaseOpenLock();
      showWorkCaseListView({ skipNavBack: true, scrollTop: false, clearOpenLock: true });
      workOpenTrace("open-denied", {
        requestId,
        role: session.role,
        email: session.email,
        ownerEmail: request.email || ""
      });
      const voiceTalentId = sessionHasRole(session, "voice")
        ? resolveVoiceTalentIdForSession(
            session.role === "voice" ? session : { ...session, role: "voice" }
          )
        : "";
      const declinedCancelled =
        Boolean(voiceTalentId) && voiceHasDeclinedRequest(request, voiceTalentId);
      setMessage(
        "workMessage",
        declinedCancelled
          ? t("work.case_cancelled") || "この案件はキャンセルされました"
          : "この案件を表示する権限がありません。ご自身の案件のみ案件管理に表示されます。",
        "err"
      );
      setMessage("workDetailMessage", "", null);
      return;
    }

    if (isStaleOpen()) return;
    setWorkCaseOpenLock(request.requestId);
    let rows = await getVisibleRequestsForCurrentSession({ localOnly: true });
    if (isStaleOpen()) return;
    if (!rows.some((r) => r.requestId === request.requestId)) {
      rows = [request, ...rows];
    }

    const select = document.getElementById("workRequestSelect");
    if (select) {
      const hasOption = [...select.options].some((o) => o.value === request.requestId);
      if (!hasOption) {
        const opt = document.createElement("option");
        opt.value = request.requestId;
        opt.textContent = formatWorkRequestOptionLabel(request);
        select.appendChild(opt);
      }
      select.value = request.requestId;
    }

    let renderedRequest = request;
    try {
      if (isStaleOpen()) return;
      renderWorkDetails(renderedRequest, session);
      renderWorkNotifications(renderedRequest.requestId);
      await softAwait(
        refreshWorkPendingDeliveryHint(renderedRequest.requestId),
        WORK_OPEN_POST_RENDER_TIMEOUT_MS,
        "open_pending_hint"
      );
      await softAwait(
        applyPendingMixToDeliveryInput(renderedRequest.requestId),
        WORK_OPEN_POST_RENDER_TIMEOUT_MS,
        "open_pending_mix"
      );
    } catch (err) {
      if (isStaleOpen()) return;
      console.warn("[wavrick] openWorkCaseById render failed", err);
      setMessage(
        "workDetailMessage",
        err instanceof Error ? err.message : "案件の表示中にエラーが発生しました。",
        "err"
      );
    }

    if (isStaleOpen()) return;
    renderWorkCaseCards(rows.length ? rows : [renderedRequest], renderedRequest.requestId, session);
    if (!isWorkCaseDetailOpen()) {
      showWorkCaseDetailView({ skipNavBack: true, scrollTop: false });
    }

    const pendingApplicants = countPendingRecruitApplicants(
      getWorkflowForRequest(renderedRequest.requestId, renderedRequest.status, renderedRequest)
    );
    const scrollToSelect = options.scrollToSelect === true || pendingApplicants > 0;

    setMessage(
      "workMessage",
      scrollToSelect
        ? "案件を開きました。下の「取引・キャスティング（応募者の選定）」から声優を選んでください。"
        : `案件「${formatWorkCaseVideoLabel(renderedRequest.videoUrl || "") || renderedRequest.name || renderedRequest.requestId}」を開きました。`,
      "ok"
    );
    setMessage(
      "workDetailMessage",
      scrollToSelect
        ? "下の「取引・キャスティング（応募者の選定）」から声優を選んでください。"
        : "",
      scrollToSelect ? "ok" : null
    );

    if (scrollToSelect) {
      requestAnimationFrame(() => {
        setTimeout(() => {
          if (isStaleOpen()) return;
          const scrollTarget =
            document.getElementById("workTransactionCard") ||
            document.getElementById("workCastAcceptanceList");
          scrollTarget?.scrollIntoView({ behavior: "smooth", block: "start" });
        }, alreadyOnWork ? 40 : 100);
      });
    }

    // ローカル表示後にクラウドで補完（失敗しても画面は維持）
    if (
      isSupabaseEnabled() &&
      (requestNeedsMediaEnrichment(renderedRequest) || !String(renderedRequest.script || "").trim())
    ) {
      void softAwait(
        enrichRequestRowFromRemote(renderedRequest),
        WORK_OPEN_ENRICH_TIMEOUT_MS,
        "open_enrich"
      ).then((enriched) => {
        if (!enriched || isStaleOpen() || !isWorkCaseDetailOpen()) return;
        const currentId = String(document.getElementById("workRequestSelect")?.value || "").trim();
        if (currentId && currentId !== enriched.requestId) return;
        renderWorkDetails(enriched, session);
        renderWorkNotifications(enriched.requestId);
      });
    }

    // 一覧キャッシュをバックグラウンド更新（オープンをブロックしない）
    void getVisibleRequestsForCurrentSession()
      .then((freshRows) => {
        if (!freshRows.length || isStaleOpen() || !isWorkCaseDetailOpen()) return;
        const openId = String(document.getElementById("workRequestSelect")?.value || "").trim();
        renderWorkCaseCards(freshRows, openId, session);
      })
      .catch((err) => {
        console.warn("[wavrick] openWorkCaseById background refresh failed", err);
      });
  } catch (err) {
    if (isStaleOpen()) return;
    console.warn("[wavrick] openWorkCaseById failed", err);
    clearWorkCaseOpenLock();
    if (!findLocalWorkRequestByAnyId(requestId)) {
      showWorkCaseListView({ skipNavBack: true, scrollTop: false, clearOpenLock: true });
    }
    setMessage(
      "workMessage",
      "案件の読み込みに失敗しました。「一覧を更新」を試すか、再ログインしてください。",
      "err"
    );
    setMessage(
      "workDetailMessage",
      err instanceof Error ? err.message : "案件の読み込みに失敗しました。",
      "err"
    );
  } finally {
    _workCaseOpenInFlight = Math.max(0, _workCaseOpenInFlight - 1);
    if (typeof globalThis !== "undefined") globalThis._workCaseOpenInFlight = _workCaseOpenInFlight;
  }
}

function renderWorkCaseCards(visibleRows, selectedRequestId, session) {
  const host = document.getElementById("workCaseCards");
  if (!host) return;
  if (session?.role !== "customer" && session?.role !== "admin" && session?.role !== "voice") {
    host.classList.add("hidden");
    host.innerHTML = "";
    return;
  }
  if (!visibleRows.length) {
    host.innerHTML = "";
    host.classList.add("hidden");
    return;
  }
  host.classList.remove("hidden");
  const talentId = sessionHasRole(session, "voice")
    ? resolveVoiceTalentIdForSession(
        session.role === "voice" ? session : { ...session, role: "voice" }
      )
    : "";
  const rowsForCards = sortVisibleWorkRowsForSession(visibleRows, session);
  host.innerHTML = rowsForCards
    .map((request) => {
      const wf = getWorkflowForRequest(request.requestId, request.status, request);
      const status = wf?.status || request.status || REQUEST_STATUS_FLOW[0];
      const cancelled = isWorkflowCancelled(wf) || String(status || "").trim() === "キャンセル";
      const isActive = request.requestId === selectedRequestId;
      const videoLabel = formatWorkCaseVideoLabel(request.videoUrl || "");
      const created = request.createdAt ? formatDateTime(request.createdAt).slice(0, 10) : "";
      const deadline = request.deadline ? `納期 ${escapeHtml(request.deadline)}` : "";
      const pendingApplicants = countPendingRecruitApplicants(wf);
      const pendingInvite = Boolean(talentId && voiceHasPendingInviteOnRequest(request, talentId));
      const mySlot = talentId ? getVoiceSlotForWorkCard(request, talentId) : null;
      const Tx = getTransactionApi();
      const castSummary = talentId
        ? pendingInvite
          ? escapeHtml(t("work.cast_pending_invite") || "依頼あり — 受けるか選択してください")
          : mySlot
            ? `話者${mySlot.speakerIndex} — ${escapeHtml(
                Tx?.slotStatusLabel?.(mySlot.status) || mySlot.status || "担当"
              )}`
            : requestOwnedByCustomerEmail(request, session?.email)
              ? "依頼した案件"
              : "関連案件"
        : pendingApplicants > 0
          ? `応募 ${pendingApplicants} 人 — 選定してください`
          : request.selectedTalentName
            ? escapeHtml(request.selectedTalentName.slice(0, 80))
            : "キャスティング中";
      const isOwnRequest = requestOwnedByCustomerEmail(request, session?.email);
      let selectBadge;
      if (cancelled) {
        selectBadge = `<span class="work-case-badge is-cancelled">${escapeHtml(cancelledStatusLabel())}</span>`;
      } else if (pendingInvite) {
        selectBadge = `<span class="work-case-badge work-case-badge--pending-invite">${escapeHtml(
          t("work.badge_pending_invite") || "回答待ち"
        )}</span>`;
      } else if (isOwnRequest || (!talentId && sessionHasRole(session, "customer"))) {
        selectBadge =
          pendingApplicants > 0
            ? `<span class="work-case-badge work-case-badge--select">要選定 ${pendingApplicants}</span>`
            : `<span class="work-case-badge is-active">${escapeHtml(status)}</span>`;
      } else {
        selectBadge = `<span class="work-case-badge is-active">${escapeHtml(status)}</span>`;
      }
      const openLabel = pendingInvite
        ? t("work.open_pending_invite") || "回答する"
        : isOwnRequest && pendingApplicants > 0
          ? "応募者を選定する"
          : "この案件を開く";
      return `<article class="work-case-card${isActive ? " is-active" : ""}${
        pendingInvite ? " is-pending-invite" : ""
      }${pendingApplicants > 0 && isOwnRequest && !pendingInvite ? " needs-select" : ""}" data-work-case-id="${escapeAttr(request.requestId)}">
        <div class="work-case-card-head">
          ${selectBadge}
          ${created ? `<span class="work-case-card-date">${escapeHtml(created)}</span>` : ""}
        </div>
        <h3 class="work-case-card-video">${escapeHtml(videoLabel)}</h3>
        <p class="work-case-card-id">ID: ${escapeHtml((request.requestId || "").slice(-12))}</p>
        <p class="work-case-card-cast">${castSummary}</p>
        ${deadline ? `<p class="work-case-card-deadline">${deadline}</p>` : ""}
        <div class="hero-actions work-case-card-actions">
          <button type="button" class="btn-red btn-sm work-case-open-btn" data-work-case-id="${escapeAttr(request.requestId)}">${escapeHtml(openLabel)}</button>
          ${
            !pendingInvite &&
            (isOwnRequest || sessionHasRole(session, "customer") || sessionHasRole(session, "admin"))
              ? `<button type="button" class="btn-ghost btn-sm work-case-detail-btn" data-work-deliverable-id="${escapeAttr(request.requestId)}">確定版</button>`
              : ""
          }
        </div>
      </article>`;
    })
    .join("");

}

function handleWorkCaseListClick(event) {
  const openBtn = event.target.closest(".work-case-open-btn");
  if (openBtn) {
    event.preventDefault();
    event.stopPropagation();
    const requestId = openBtn.getAttribute("data-work-case-id");
    if (requestId) {
      void openWorkCaseById(requestId, {
        scrollToSelect: openBtn.textContent?.includes("選定")
      });
    }
    return;
  }
  const detailBtn = event.target.closest(".work-case-detail-btn");
  if (detailBtn) {
    event.preventDefault();
    event.stopPropagation();
    const requestId = detailBtn.getAttribute("data-work-deliverable-id");
    if (requestId) openWorkDeliverableDetail(requestId);
    return;
  }
  const card = event.target.closest(".work-case-card");
  if (card && !event.target.closest("button, a")) {
    const requestId = card.getAttribute("data-work-case-id");
    if (requestId) void openWorkCaseById(requestId);
  }
}

function getQuoteSpeakerLines(quote) {
  if (Array.isArray(quote?.speakers)) return quote.speakers;
  if (Array.isArray(quote?.lines)) return quote.lines;
  return [];
}

function resolveRequestQuoteBreakdown(request, wf, castSlots) {
  const saved =
    wf?.quoteBreakdown && typeof wf.quoteBreakdown === "object"
      ? wf.quoteBreakdown
      : request?.quoteBreakdown && typeof request.quoteBreakdown === "object"
        ? request.quoteBreakdown
        : null;
  if (getQuoteSpeakerLines(saved).length) return saved;
  return buildQuoteForCastAndScript(castSlots || [], String(request?.script || ""));
}

function buildVoiceQuoteSummary(request, wf, talentId, voiceSlots) {
  const P = getPricingApi();
  if (!P || !talentId || !voiceSlots?.length) return null;
  const speakerIndices = new Set(
    voiceSlots.map((slot) => Number(slot?.speakerIndex)).filter((idx) => idx > 0)
  );
  if (!speakerIndices.size) return null;
  const castSlots = getWorkflowCastSlots(request, wf);
  const quote = resolveRequestQuoteBreakdown(request, wf, castSlots);
  const lines = getQuoteSpeakerLines(quote).filter((line) =>
    speakerIndices.has(Number(line?.speakerIndex))
  );
  if (!lines.length) return null;
  return {
    speakerIndices: [...speakerIndices].sort((a, b) => a - b),
    rawSeconds: lines.reduce(
      (sum, line) => sum + (Number(line?.rawSeconds ?? line?.rawSec) || 0),
      0
    ),
    billableSeconds: lines.reduce(
      (sum, line) => sum + (Number(line?.billableSeconds) || 0),
      0
    ),
    subtotalUsd: lines.reduce((sum, line) => sum + (Number(line?.subtotalUsd) || 0), 0),
    minimumApplied: lines.some((line) => Boolean(line?.minimumApplied))
  };
}

function renderWorkCaseHeader(request, session) {
  const host = document.getElementById("workCaseHeader");
  if (!host || !request) return;
  const wf = maybeAdvanceTransactionPhase(
    { ...getWorkflowForRequest(request.requestId, request.status, request) },
    request
  );
  const viewingAsVoice =
    sessionHasRole(session, "voice") &&
    !sessionHasRole(session, "admin") &&
    !requestOwnedByCustomerEmail(request, session?.email);
  const talentId = viewingAsVoice
    ? resolveVoiceTalentIdForSession(
        session.role === "voice" ? session : { ...session, role: "voice" }
      )
    : "";
  const wfSlots = wf.castAcceptance?.length ? wf.castAcceptance : getCastSlotsForRequest(request);
  const Tx = getTransactionApi();
  const slots = viewingAsVoice ? getVoiceSpeakerSlotsForRequest(request, talentId) : [];
  let slotLabel = slots.length
    ? slots.map((s) => `話者${s.speakerIndex}`).join("・")
    : request.selectedTalentName || "担当";
  if (session?.role === "customer" && Tx && wfSlots.length) {
    slotLabel = wfSlots.map((s) => `話者${s.speakerIndex}: ${Tx.getCustomerSlotLabel(s, wfSlots)}`).join(" / ");
  }
  if (viewingAsVoice && Tx && talentId && wfSlots.length) {
    const onHold = Tx.isTransactionOnHoldForVoice(wfSlots, talentId);
    if (onHold) slotLabel = "取引保留中";
  }
  const statusLabel = wf.status || REQUEST_STATUS_FLOW[0];
  const cancelled = isWorkflowCancelled(wf);
  const badges = [
    `<span class="work-case-badge ${cancelled ? "is-cancelled" : "is-active"}">${escapeHtml(
      cancelled ? cancelledStatusLabel() : statusLabel
    )}</span>`,
    `<span class="work-case-badge">${escapeHtml(slotLabel)}</span>`
  ];
  const pendingApplicants =
    session?.role === "customer" ? countPendingRecruitApplicants(wf) : 0;
  if (pendingApplicants > 0) {
    badges.push(
      `<span class="work-case-badge work-case-badge--select">要選定 ${pendingApplicants}人</span>`
    );
  }
  if (request.deadline) badges.push(`<span class="work-case-badge">納期 ${escapeHtml(request.deadline)}</span>`);
  const P = getPricingApi();
  const quoteUsd = wf.quoteAmountUsd ?? request.quoteAmountUsd;
  const voiceQuote = viewingAsVoice
    ? buildVoiceQuoteSummary(request, wf, talentId, slots)
    : null;
  const quoteLine = viewingAsVoice
    ? voiceQuote
      ? `<div><strong>担当 speaker:</strong> ${escapeHtml(
          voiceQuote.speakerIndices.map((idx) => `話者${idx}`).join("・")
        )}</div>
        <div><strong>タイムコード合計:</strong> ${escapeHtml(
          P.formatSpeakerQuoteDuration(voiceQuote.rawSeconds, voiceQuote.billableSeconds)
        )}</div>
        <div><strong>見積（担当分）:</strong> ${escapeHtml(
          P.formatUsd(voiceQuote.subtotalUsd)
        )}${voiceQuote.minimumApplied ? "（最低価格適用）" : ""}</div>`
      : ""
    : quoteUsd != null && P
      ? `<div><strong>見積（USD）:</strong> ${escapeHtml(P.formatUsd(quoteUsd))}${
          wf.billableSeconds ? ` / 課金枠 ${escapeHtml(P.formatBillableDuration(wf.billableSeconds))}` : ""
        }</div>`
      : wf.quoteAmount
        ? `<div><strong>見積:</strong> ${escapeHtml(wf.quoteAmount)}</div>`
        : "";
  const selectHint =
    pendingApplicants > 0
      ? `<p class="work-case-select-hint">応募者の選定はすぐ下の「取引・キャスティング（応募者の選定）」から行えます。</p>`
      : "";
  const caseId = String(request.requestId || "").trim();
  host.innerHTML = `
    <div class="work-case-header-top">
      <p class="work-case-header-title">${escapeHtml(formatWorkCaseVideoLabel(request.videoUrl || "") || request.name || "依頼案件")}</p>
      ${
        session?.role === "customer" || session?.role === "admin"
          ? `<button type="button" class="btn-ghost btn-sm work-case-header-detail-btn" id="workOpenDeliverableDetailBtn">詳細（確定版）</button>`
          : ""
      }
    </div>
    <div class="work-case-header-meta">
      <div><strong>案件名:</strong> ${escapeHtml(request.name || "依頼案件")}</div>
      <div class="work-case-id-row">
        <strong>案件ID:</strong>
        <button type="button" id="workCaseIdSwitchBtn" class="work-case-id-btn" aria-haspopup="listbox" aria-expanded="false" title="${escapeAttr(t("work.switch_case_hint") || "クリックして案件を切り替え")}">${escapeHtml(caseId || "—")}</button>
        <span class="work-case-id-hint">${escapeHtml(t("work.switch_case_hint") || "クリックで切替")}</span>
      </div>
      <div><strong>顧客:</strong> ${escapeHtml(request.name || "—")}（${escapeHtml(request.email || "—")}）</div>
      <div><strong>動画:</strong> ${
        request.videoUrl
          ? `<a href="${escapeAttr(request.videoUrl)}" target="_blank" rel="noreferrer">${escapeHtml(request.videoUrl)}</a>`
          : "未設定"
      }</div>
      ${request.tone ? `<div><strong>トーン:</strong> ${escapeHtml(request.tone)}</div>` : ""}
      ${quoteLine}
    </div>
    <div class="work-case-badge-row">${badges.join("")}</div>
    ${selectHint}
  `;
  host.querySelector("#workOpenDeliverableDetailBtn")?.addEventListener("click", () => {
    if (request.requestId) openWorkDeliverableDetail(request.requestId);
  });
  host.querySelector("#workCaseIdSwitchBtn")?.addEventListener("click", (event) => {
    event.preventDefault();
    toggleWorkCaseSwitcher();
  });
}

function syncWorkRetakeComposer(request, wf) {
  const lock = document.getElementById("workRetakePaymentLock");
  const paidBtn = document.getElementById("markRetakePaidBtn");
  const payBar = document.getElementById("workRetakePayBar");
  const P = getPricingApi();
  if (!lock || !P || !request) return;
  const session = getCurrentSession();
  const slots = getWorkflowCastSlots(request, wf);
  const fee = P.computePaidRetakeFeeUsd(slots, resolveVoiceProfileByTalentId);
  const used = P.countRevisionSessions(wf.messages);
  const needsPay = used >= P.FREE_RETAKE_LIMIT && wf.retakePaymentStatus !== "paid";
  const canPay =
    session?.role === "customer" || session?.role === "admin";
  if (needsPay && canPay) {
    lock.classList.remove("hidden");
    payBar?.classList.remove("hidden");
    if (isAdminTestRequest(request, session)) {
      lock.textContent = `無料のリテイク依頼は${P.FREE_RETAKE_LIMIT}回までです。次の1回は ${P.formatUsd(fee)}（運営テスト: 仮決済で完了できます）。`;
      if (paidBtn) {
        paidBtn.classList.remove("hidden");
        paidBtn.textContent =
          t("work.admin_retake_provisional_pay") || "リテイク仮決済する（テスト）";
      }
    } else {
      lock.textContent = `無料のリテイク依頼は${P.FREE_RETAKE_LIMIT}回までです。次の1回は ${P.formatUsd(fee)} の決済が必要です（リテイクは顧客用収録ページから送信します）。`;
      if (paidBtn) {
        paidBtn.classList.remove("hidden");
        paidBtn.textContent = t("work.retake_pay_checkout") || "リテイク料金を決済する";
      }
    }
  } else {
    lock.classList.add("hidden");
    payBar?.classList.add("hidden");
    if (paidBtn) paidBtn.classList.add("hidden");
  }
}

function renderWorkStatusTimeline(status, wf = null) {
  const wrap = document.getElementById("workStatusTimeline");
  if (!wrap) return;
  const statusNote = document.getElementById("workCancelledStatusNote");
  const cancelled = isWorkflowCancelled(wf) || String(status || "").trim() === "キャンセル";
  if (statusNote) {
    statusNote.classList.toggle("hidden", !cancelled);
    statusNote.hidden = !cancelled;
    if (cancelled) statusNote.textContent = cancelledCaseMessage();
  }
  if (cancelled) {
    wrap.classList.add("is-cancelled");
    wrap.innerHTML = `<span class="status-pill status-pill--cancelled">${escapeHtml(cancelledStatusLabel())}</span>`;
    return;
  }
  wrap.classList.remove("is-cancelled");
  const activeIndex = REQUEST_STATUS_FLOW.indexOf(status);
  wrap.innerHTML = REQUEST_STATUS_FLOW
    .map((label, idx) => `<span class="status-pill ${idx <= activeIndex ? "done" : ""}">${escapeHtml(label)}</span>`)
    .join("");
}

function syncWorkRecordPaymentLock(request, wf, session) {
  const lock = document.getElementById("workRecordPaymentLock");
  const openBtn = document.getElementById("workOpenRecordWorkspaceBtn");
  const customerBtn = document.getElementById("workOpenCustomerRecordWorkspaceBtn");
  const cancelled = isWorkflowCancelled(wf);
  // キャンセル済み以外は常に操作可能（決済未完了ならクリック時に注意を表示）
  if (openBtn) openBtn.disabled = cancelled;
  if (customerBtn) customerBtn.disabled = cancelled;
  if (!lock) return;
  if (cancelled) {
    lock.classList.remove("hidden");
    lock.textContent = cancelledCaseMessage();
    return;
  }
  const voiceAccepted =
    session?.role === "voice" && isRecordingUnlocked(wf, request, session);
  const unpaid =
    voiceAccepted &&
    !isOpsTestCase(request, wf, session) &&
    !isWorkflowPaymentCleared(wf, request, session);
  lock.classList.toggle("hidden", !unpaid);
  if (unpaid) {
    const hint = t("work.record_unpaid_hint");
    lock.textContent =
      hint && hint !== "work.record_unpaid_hint"
        ? hint
        : "決済完了前です。収録ページは開けますが、納品は決済後のみ可能です。キャンセル時も声優への送金はありません。";
  } else {
    lock.textContent = "";
  }
}

function syncWorkCancelledMessagingUi(wf) {
  const cancelled = isWorkflowCancelled(wf);
  const chatInput = document.getElementById("workChatInput");
  const chatSendBtn = document.getElementById("sendWorkChatBtn");
  const chatNote = document.getElementById("workChatCancelledNote");
  if (chatInput) chatInput.disabled = cancelled;
  if (chatSendBtn) chatSendBtn.disabled = cancelled;
  if (chatNote) {
    chatNote.classList.toggle("hidden", !cancelled);
    chatNote.hidden = !cancelled;
    if (cancelled) {
      const msg = t("work.chat_send_blocked_cancelled");
      chatNote.textContent =
        msg && msg !== "work.chat_send_blocked_cancelled"
          ? msg
          : "キャンセルされた案件ではメッセージを送信できません。過去のやり取りは閲覧できます。";
    }
  }

  const mailInput = document.getElementById("workScriptMailInput");
  const mailSendBtn = document.getElementById("workSendScriptMailBtn");
  const mailScope = document.getElementById("workScriptMailScope");
  const mailRecipient = document.getElementById("workScriptMailRecipient");
  const mailExternalBtn = document.getElementById("workOpenScriptMailExternalBtn");
  if (mailInput) mailInput.disabled = cancelled;
  if (mailSendBtn) mailSendBtn.disabled = cancelled;
  if (mailScope) mailScope.disabled = cancelled;
  if (mailRecipient) mailRecipient.disabled = cancelled;
  if (mailExternalBtn && cancelled) mailExternalBtn.classList.add("hidden");
}

function syncWorkCancelledBanner(wf) {
  const banner = document.getElementById("workCancelledBanner");
  if (!banner) return;
  const cancelled = isWorkflowCancelled(wf);
  // 顧客・声優どちらでも表示（role クラス無し）
  banner.classList.remove("work-role-customer", "work-role-admin", "work-role-voice");
  banner.classList.toggle("hidden", !cancelled);
  banner.hidden = !cancelled;
  if (!cancelled) return;
  const title = banner.querySelector(".work-cancelled-banner-title");
  const desc = banner.querySelector(".work-cancelled-banner-desc");
  if (title) title.textContent = cancelledCaseMessage();
  if (desc) {
    const msg = t("work.case_cancelled_hint");
    desc.textContent =
      msg && msg !== "work.case_cancelled_hint"
        ? msg
        : "収録ページは開けず、取引メッセージの送信もできません。過去のメッセージは閲覧できます。";
  }
}

function cancelReasonLabel(code) {
  const c = String(code || "").toUpperCase();
  if (c === "A") return t("work.cancel_reason_a") || "理由 A";
  if (c === "B") return t("work.cancel_reason_b") || "理由 B";
  return c || "-";
}

function syncWorkCancelPendingBanner(wf) {
  const banner = document.getElementById("workCancelPendingBanner");
  if (!banner) return;
  const Tx = getTransactionApi();
  // 全体バナーは案件全体キャンセルのみ。声優ごとのキャンセルはキャスティング行に出す。
  const showTransactionBanner = (() => {
    if (isWorkflowCancelled(wf)) return false;
    if (typeof Tx?.isTransactionCancelPending === "function") {
      return Boolean(Tx.isTransactionCancelPending(wf));
    }
    if (!Tx?.isCancelPending?.(wf)) return false;
    const cn = Tx.getCancelNegotiation?.(wf);
    return Tx.getCancelScope?.(cn) !== (Tx.CANCEL_SCOPE?.talent_slot || "talent_slot");
  })();
  banner.classList.toggle("hidden", !showTransactionBanner);
  banner.hidden = !showTransactionBanner;
  if (!showTransactionBanner) return;
  const cn = Tx.getCancelNegotiation(wf);
  const desc = document.getElementById("workCancelPendingDesc");
  if (!desc) return;
  if (Tx.isCancelDisputed?.(wf)) {
    desc.textContent =
      t("work.cancel_disputed_hint") ||
      "声優がキャンセルに了承しませんでした。運営が判断します。";
  } else {
    const reason = cancelReasonLabel(cn?.reasonCode);
    const detail = String(cn?.reasonDetail || "").trim();
    desc.textContent = `${t("work.cancel_pending_hint") || "声優の了承待ちです。"}\n${reason}${
      detail ? ` — ${detail}` : ""
    }`;
  }
}

function renderWorkCancelTalentCard(request, session, wf) {
  const card = document.getElementById("workCancelTalentCard");
  if (!card) return;
  const Tx = getTransactionApi();
  const talentId = resolveVoiceTalentIdForSession(session);
  const email = String(session?.email || "")
    .toLowerCase()
    .trim();
  const needs =
    session?.role === "voice" &&
    !isWorkflowCancelled(wf) &&
    (Boolean(Tx?.talentNeedsCancelResponse?.(wf, talentId)) ||
      Boolean(email && Tx?.talentNeedsCancelResponse?.(wf, email)));
  card.classList.toggle("hidden", !needs);
  card.hidden = !needs;
  if (!needs) return;
  const cn = Tx.getCancelNegotiation(wf);
  const scope = Tx.getCancelScope?.(cn) || Tx.CANCEL_SCOPE?.transaction || "transaction";
  const titleEl = card.querySelector("h3");
  if (titleEl) {
    titleEl.textContent =
      scope === (Tx.CANCEL_SCOPE?.talent_slot || "talent_slot")
        ? t("work.cancel_talent_slot_response_title") ||
          "この枠のキャンセル依頼への回答"
        : t("work.cancel_talent_title") || "案件キャンセル依頼への回答";
  }
  const reasonEl = document.getElementById("workCancelTalentReason");
  const detailEl = document.getElementById("workCancelTalentDetail");
  if (reasonEl) {
    reasonEl.textContent = `${t("work.cancel_reason_label") || "理由"}: ${cancelReasonLabel(cn?.reasonCode)}`;
  }
  if (detailEl) {
    const detail = String(cn?.reasonDetail || "").trim();
    if (scope === (Tx.CANCEL_SCOPE?.talent_slot || "talent_slot")) {
      const targetSpeaker =
        Number(Tx.getCancelTargetSpeakerIndex?.(cn) || cn?.targetSpeakerIndex || 0) || 0;
      const speaker = (wf.castAcceptance || []).find((s) => {
        if (targetSpeaker >= 1 && Number(s.speakerIndex) !== targetSpeaker) return false;
        if (Tx.talentIdsMatch?.(s?.talentId, cn?.targetTalentId)) return true;
        return String(s?.talentId || "") === String(cn?.targetTalentId || "");
      });
      const speakerLabel =
        targetSpeaker >= 1
          ? `話者${targetSpeaker}`
          : speaker
            ? `話者${speaker.speakerIndex}`
            : t("work.slot_cancel_this_talent") || "この声優枠";
      detailEl.textContent = `${speakerLabel} — ${detail}`;
    } else {
      detailEl.textContent = detail;
    }
  }
  const noteEl = document.getElementById("workCancelTalentNoReason");
  // 同期再描画で理由入力・エラーを消さない（了承しない送信不能の主因だった）
  if (noteEl && !noteEl.dataset.boundCancelNote) {
    noteEl.dataset.boundCancelNote = "1";
    noteEl.addEventListener("input", () => {
      noteEl.dataset.keep = String(noteEl.value || "").trim() ? "1" : "";
    });
    noteEl.addEventListener("focus", () => {
      noteEl.dataset.keep = "1";
    });
  }
}

function mapTalentCancelDecisionError(errorKey) {
  const key = String(errorKey || "").trim();
  if (key === "missing_note") {
    return t("work.cancel_talent_no_reason_required") || "了承しない理由を記入してください。";
  }
  if (key === "already_responded") {
    return t("work.cancel_already_responded") || "すでに回答済みです。";
  }
  if (key === "not_pending") {
    return t("work.cancel_not_pending") || "回答待ちのキャンセル依頼がありません。";
  }
  if (key === "not_required" || key === "missing_talent") {
    return t("work.cancel_not_required") || "このキャンセル依頼の回答対象ではありません。";
  }
  return t("work.cancel_request_failed") || "回答を保存できませんでした。";
}

/** 制作進行〜取引完了前（返金できない可能性の警告対象） */
function isCancelDuringProductionWindow(wf) {
  if (!wf || isWorkflowCancelled(wf)) return false;
  if (String(wf.status || "").trim() === "完了") return false;
  const phase = String(wf.transactionPhase || "").trim();
  const Tx = getTransactionApi();
  if (phase === (Tx?.TRANSACTION_PHASE?.in_production || "in_production")) return true;
  const status = String(wf.status || "").trim();
  return status === "進行中" || status === "納品" || status === "検収";
}

