let _workOpenRecruitContext = null;

function normalizeWorkRecruitPrefs(raw) {
  const Tx = getTransactionApi();
  if (Tx?.normalizeRecruitPrefs) return Tx.normalizeRecruitPrefs(raw);
  const MIN = 15;
  const price = Number(raw?.pricePerMinute);
  const retake = Number(raw?.additionalRetakePrice);
  return {
    pricePerMinute: Number.isFinite(price) ? Math.max(MIN, price) : MIN,
    additionalRetakePrice: Number.isFinite(retake) ? Math.max(0, retake) : 0,
    gender: String(raw?.gender || "").trim(),
    attributes: String(raw?.attributes || "").trim(),
    language: String(raw?.language || "ja").trim() || "ja"
  };
}

function estimateWorkRecruitQuote(request, speakerIndex, pricePerMinute) {
  const P = getPricingApi();
  const idx = Number(speakerIndex) || 0;
  const rate = Math.max(15, Number(pricePerMinute) || 15);
  if (!P || !idx) {
    return { durationLabel: "—", subtotalLabel: "—", rate };
  }
  const line = getRecruitmentSpeakerQuote(
    {
      script: request?.script || "",
      castSlots: request?.castSlots || [],
      quoteBreakdown: request?.quoteBreakdown || null
    },
    idx
  );
  // Prefer billable seconds from saved/platform quote, reprice with customer rate
  const billableSeconds = Number(line?.billableSeconds) || 0;
  const rawSeconds = Number(line?.rawSeconds) || billableSeconds;
  const minutes = billableSeconds / 60;
  let subtotalUsd = Math.round(minutes * rate * 100) / 100;
  const minSlot = Number(P.MIN_SLOT_ORDER_USD) || 20;
  let minimumApplied = false;
  if (billableSeconds > 0 && subtotalUsd < minSlot) {
    subtotalUsd = minSlot;
    minimumApplied = true;
  }
  return {
    durationLabel:
      billableSeconds > 0
        ? P.formatSpeakerQuoteDuration(rawSeconds, billableSeconds)
        : "—",
    subtotalLabel:
      billableSeconds > 0
        ? P.formatUsd(subtotalUsd) + (minimumApplied ? " (最低価格)" : "")
        : "—",
    rate,
    billableSeconds,
    subtotalUsd
  };
}

function refreshWorkOpenRecruitQuotePreview() {
  const quoteEl = document.getElementById("workOpenRecruitQuote");
  if (!quoteEl || !_workOpenRecruitContext) return;
  const price = Number(document.getElementById("workOpenRecruitPrice")?.value);
  const est = estimateWorkRecruitQuote(
    _workOpenRecruitContext.request,
    _workOpenRecruitContext.speakerIndex,
    price
  );
  const P = getPricingApi();
  quoteEl.innerHTML = `
    <strong>${escapeHtml(
      t("work.open_recruit_quote_title", {
        speaker: _workOpenRecruitContext.speakerIndex
      }) || `話者${_workOpenRecruitContext.speakerIndex} の見積プレビュー`
    )}</strong>
    <span>${escapeHtml(
      t("work.open_recruit_quote_line", {
        duration: est.durationLabel,
        subtotal: est.subtotalLabel,
        rate: P ? P.formatUsd(est.rate) : `$${est.rate}`
      }) ||
        `発話 ${est.durationLabel} ／ 小計 ${est.subtotalLabel}（単価 $${est.rate}/分）`
    )}</span>
  `;
}

function openWorkOpenRecruitModal(request, speakerIndex, wf) {
  const modal = document.getElementById("workOpenRecruitModal");
  if (!modal || !request || !speakerIndex) return;
  const Tx = getTransactionApi();
  const slot = (wf?.castAcceptance || []).find(
    (s) => Number(s.speakerIndex) === Number(speakerIndex)
  );
  const existing = normalizeWorkRecruitPrefs(
    slot?.recruitPrefs ||
      wf?.omakaseCriteria?.[String(speakerIndex)] ||
      wf?.omakaseCriteria?.[speakerIndex] ||
      {}
  );
  const scriptLang = String(
    request.scriptLanguage || existing.language || "ja"
  ).trim() || "ja";
  const prefs = normalizeWorkRecruitPrefs({ ...existing, language: scriptLang });

  _workOpenRecruitContext = {
    requestId: request.requestId || request.rowId || "",
    speakerIndex: Number(speakerIndex),
    request
  };

  const priceEl = document.getElementById("workOpenRecruitPrice");
  const retakeEl = document.getElementById("workOpenRecruitRetake");
  const genderEl = document.getElementById("workOpenRecruitGender");
  const langEl = document.getElementById("workOpenRecruitLanguage");
  const attrEl = document.getElementById("workOpenRecruitAttributes");
  if (priceEl) priceEl.value = String(prefs.pricePerMinute);
  if (retakeEl) retakeEl.value = String(prefs.additionalRetakePrice);
  if (genderEl) genderEl.value = prefs.gender || "";
  if (langEl) {
    langEl.value =
      typeof formatScriptLanguageDisplay === "function"
        ? formatScriptLanguageDisplay(scriptLang)
        : scriptLang;
    langEl.dataset.langCode = scriptLang;
  }
  if (attrEl) attrEl.value = prefs.attributes || "";
  setMessage("workOpenRecruitModalMessage", "", "");
  refreshWorkOpenRecruitQuotePreview();

  modal.classList.remove("hidden");
  modal.hidden = false;
  modal.setAttribute("aria-hidden", "false");
  priceEl?.focus();
}

function closeWorkOpenRecruitModal() {
  const modal = document.getElementById("workOpenRecruitModal");
  if (!modal) return;
  modal.classList.add("hidden");
  modal.hidden = true;
  modal.setAttribute("aria-hidden", "true");
  _workOpenRecruitContext = null;
}

async function submitWorkOpenRecruitModal() {
  const ctx = _workOpenRecruitContext;
  const Tx = getTransactionApi();
  if (!ctx?.requestId || !Tx) {
    setMessage("workOpenRecruitModalMessage", "対象案件がありません。", "err");
    return;
  }
  const langCode =
    document.getElementById("workOpenRecruitLanguage")?.dataset?.langCode ||
    ctx.request?.scriptLanguage ||
    "ja";
  const prefs = normalizeWorkRecruitPrefs({
    pricePerMinute: document.getElementById("workOpenRecruitPrice")?.value,
    additionalRetakePrice: document.getElementById("workOpenRecruitRetake")?.value,
    gender: document.getElementById("workOpenRecruitGender")?.value,
    attributes: document.getElementById("workOpenRecruitAttributes")?.value,
    language: langCode
  });
  if (prefs.pricePerMinute < 15) {
    setMessage(
      "workOpenRecruitModalMessage",
      t("work.open_recruit_price_invalid") || "単価は $15/分 以上で入力してください。",
      "err"
    );
    return;
  }

  const submitBtn = document.getElementById("workOpenRecruitSubmitBtn");
  const prev = submitBtn?.textContent;
  if (submitBtn) {
    submitBtn.disabled = true;
    submitBtn.textContent = t("common.sending") || "送信中...";
  }
  setMessage("workOpenRecruitModalMessage", t("common.sending") || "送信中...", null);

  let openError = "";
  let result;
  try {
    result = await updateWorkflowForRequest(ctx.requestId, (innerWf) => {
      const opened = Tx.applyCustomerOpenRecruitFromDeclined(
        innerWf.castAcceptance || [],
        ctx.speakerIndex,
        { recruitPrefs: prefs }
      );
      if (!opened.ok) {
        openError = opened.error || "募集の開始に失敗しました。";
        return innerWf;
      }
      innerWf.castAcceptance = opened.slots;
      const criteria =
        innerWf.omakaseCriteria && typeof innerWf.omakaseCriteria === "object"
          ? { ...innerWf.omakaseCriteria }
          : {};
      criteria[String(ctx.speakerIndex)] = {
        pricePerMinute: prefs.pricePerMinute,
        additionalRetakePrice: prefs.additionalRetakePrice,
        gender: prefs.gender,
        attributes: prefs.attributes,
        language: prefs.language
      };
      innerWf.omakaseCriteria = criteria;
      return maybeAdvanceTransactionPhase(innerWf, ctx.request);
    });
  } catch (err) {
    console.warn("[wavrick] open recruit with prefs failed", err);
    setMessage(
      "workOpenRecruitModalMessage",
      err instanceof Error ? err.message : "募集の開始に失敗しました。",
      "err"
    );
    if (submitBtn) {
      submitBtn.disabled = false;
      submitBtn.textContent = prev || t("work.open_recruit_submit") || "この条件で募集を開始";
    }
    return;
  }

  if (!result?.ok) {
    setMessage(
      "workOpenRecruitModalMessage",
      result?.error || "募集の開始に失敗しました。",
      "err"
    );
    if (submitBtn) {
      submitBtn.disabled = false;
      submitBtn.textContent = prev || t("work.open_recruit_submit") || "この条件で募集を開始";
    }
    return;
  }
  if (openError) {
    setMessage("workOpenRecruitModalMessage", openError, "err");
    if (submitBtn) {
      submitBtn.disabled = false;
      submitBtn.textContent = prev || t("work.open_recruit_submit") || "この条件で募集を開始";
    }
    return;
  }

  const updatedWf = result.workflow || getWorkflowForRequest(ctx.requestId);
  const rows = JSON.parse(localStorage.getItem("wavrick_youtube_requests") || "[]");
  const reqIdx = rows.findIndex(
    (r) =>
      r.requestId === ctx.requestId ||
      r.rowId === ctx.requestId ||
      String(r.id || "") === String(ctx.requestId)
  );
  if (reqIdx >= 0) {
    syncRequestTalentIdsFromCastAcceptance(rows[reqIdx], updatedWf?.castAcceptance || []);
    rows[reqIdx].updatedAt = new Date().toISOString();
    localStorage.setItem("wavrick_youtube_requests", JSON.stringify(rows));
    void persistYoutubeRequestToCloud(rows[reqIdx]);
  }

  pushCaseNotification(
    t("work.notify_recruit_opened_after_decline") ||
      `話者${ctx.speakerIndex} の募集を開始しました`,
    ctx.requestId,
    {
      to: "participants",
      kind: "customer",
      category: "case",
      request: ctx.request
    }
  );

  closeWorkOpenRecruitModal();
  setMessage(
    "workMessage",
    t("work.open_recruit_done") || "募集を開始しました。",
    "ok"
  );
  if (typeof showToast === "function") {
    showToast(t("work.open_recruit_done") || "募集を開始しました。", "success", 3500);
  }
  signalWorkdataChangedSafe({
    requestId: ctx.requestId,
    skipLocalHydrate: true,
    force: true,
    forceDetail: true
  });
  try {
    const refreshed = await resolveWorkRequestByAnyId(ctx.requestId);
    const sess = getCurrentSession();
    if (refreshed && typeof renderWorkDetails === "function") {
      renderWorkDetails(refreshed, sess);
    }
  } catch {
    /* ignore */
  }
}

function bindWorkOpenRecruitModal() {
  if (bindWorkOpenRecruitModal.bound) return;
  bindWorkOpenRecruitModal.bound = true;
  document.querySelectorAll("[data-close-work-open-recruit-modal]").forEach((el) => {
    el.addEventListener("click", () => closeWorkOpenRecruitModal());
  });
  document.getElementById("workOpenRecruitSubmitBtn")?.addEventListener("click", () => {
    void submitWorkOpenRecruitModal();
  });
  document.getElementById("workOpenRecruitPrice")?.addEventListener("input", () => {
    refreshWorkOpenRecruitQuotePreview();
  });
}

async function logCaseCancelEvent(payload) {
  try {
    const result = await window.WavrickCaseCancelEvents?.submitCancelEvent?.(payload);
    if (result && result.ok === false) {
      console.warn("[wavrick] case cancel event not saved", result.error);
    }
  } catch (err) {
    console.warn("[wavrick] case cancel event failed", err);
  }
}

