  document.getElementById("workSendScriptMailBtn")?.addEventListener("click", async () => {
    const session = getCurrentSession();
    if (!session || (session.role !== "customer" && session.role !== "voice" && session.role !== "admin")) {
      return;
    }
    const request = await findCurrentRequest();
    if (!request) {
      setMessage("workMessage", "対象案件がありません。", "err");
      return;
    }
    const wf = getWorkflowForRequest(request.requestId, request.status);
    if (isWorkflowCancelled(wf)) {
      setMessage(
        "workMessage",
        t("work.chat_send_blocked_cancelled") ||
          "キャンセルされた案件ではメッセージを送信できません。過去のやり取りは閲覧できます。",
        "err"
      );
      syncWorkCancelledMessagingUi(wf);
      return;
    }
    const message = await sendWorkScriptMailMessage(request, session, wf);
    if (!message) return;

    const req = await updateWorkflow((innerWf) => {
      innerWf.messages = [...(innerWf.messages || []), message];
      return innerWf;
    });
    if (!req) return;

    const scopeLabel =
      message.recipientScope === "all" ? t("work.script_scope_all") : t("work.script_scope_individual");
    const scriptNoteText = t("work.notify_script_note", { scope: scopeLabel });
    if (message.recipientScope === "individual" && message.recipientRole === "customer") {
      pushCaseNotification(scriptNoteText, req.requestId, {
        to: "customer",
        kind: notificationKindForSession(session),
        category: "case",
        request: req,
        workflow: wf
      });
    } else if (message.recipientScope === "individual" && message.recipientTalentId) {
      pushCaseNotification(scriptNoteText, req.requestId, {
        to: "voice",
        talentId: message.recipientTalentId,
        kind: notificationKindForSession(session),
        category: "case",
        request: req,
        workflow: wf
      });
    } else {
      pushCaseNotification(scriptNoteText, req.requestId, {
        to: "participants",
        kind: notificationKindForSession(session),
        category: "case",
        request: req,
        workflow: wf
      });
    }
    setMessage("workMessage", "メールを送信しました。", "ok");
    const input = document.getElementById("workScriptMailInput");
    if (input) input.value = "";
    const sessionAfter = getCurrentSession();
    const wfAfter = getWorkflowForRequest(request.requestId, request.status);
    renderWorkScriptMailCard(request, sessionAfter, wfAfter);
  });

